function resolveTextSelectionNode(
  moveTarget: MoveTarget,
  selectedPanel: string | null,
) {
  const panelNode =
    selectedPanel === "head2"
      ? "headline2"
      : selectedPanel === "social"
        ? "socialHandle"
        : selectedPanel === "timeLabel"
          ? "time"
          : selectedPanel;
  if (panelNode && TEXT_SELECTION_NODE_IDS.has(panelNode)) return panelNode;
  const moveNode = moveTarget;
  return moveNode && TEXT_SELECTION_NODE_IDS.has(moveNode) ? moveNode : null;
}

const TEMPLATE_LABEL_PANEL_KEYS = ["presenter", "date", "leftRail", "rightRail", "social", "price", "compliance"] as const;
type TemplateLabelPanelKey = (typeof TEMPLATE_LABEL_PANEL_KEYS)[number];

function isTemplateLabelPanelKey(value: string | null | undefined): value is TemplateLabelPanelKey {
  return TEMPLATE_LABEL_PANEL_KEYS.includes(value as TemplateLabelPanelKey);
}

function resolveTemplateCanvasSelectionPanel(
  key: string,
  target: EventTarget | null
) {
  const panelKey = key === "headline2" ? "head2" : key;
  if (panelKey !== "time") return panelKey;
  const element =
    typeof Element !== "undefined" && target instanceof Element ? target : null;
  return element?.closest('[data-node="timeLabel"]') ? "timeLabel" : "time";
}

function resolveCoordinateReaderTarget(
  moveTarget: MoveTarget,
  selectedPanel: string | null
) {
  if (selectedPanel && COORDINATE_READER_TARGETS.has(selectedPanel)) {
    return selectedPanel === "head2" ? "headline2" : selectedPanel;
  }
  return moveTarget;
}





