// ——— Template variant resolver (square/story with fallbacks) ———
function getVariant(tpl: TemplateSpec, fmt: Format) {
  const withFormats = tpl as TemplateWithFormats;
  // prefer explicit format, then square fallback, then base
  return withFormats.formats?.[fmt]
      ?? withFormats.formats?.square
      ?? tpl.base
      ?? null;
}

// Keep recipe recognition at module scope because both the native canvas
// renderer and the editor workflow need the same provenance check. Matching
// the direction, stored recipe, or composition pattern also keeps restored
// projects working if one incidental metadata field is absent.
function isCocoFashionClubVerticalVariant(value: unknown): boolean {
  const variant = (value ?? {}) as Record<string, any>;
  return (
    variant.cocoCampaignDirectionId === "fashion-club-vertical" ||
    variant.cocoVisualRecipeId === "fashion-club-vertical" ||
    variant.cocoCompositionSystem?.patternId === "fashion-club-vertical"
  );
}

function isCocoLadiesCssEditorialVariant(value: unknown): boolean {
  const variant = (value ?? {}) as Record<string, any>;
  return (
    variant.cocoVisualRecipeId === LADIES_CSS_EDITORIAL_RECIPE.id ||
    variant.cocoCompositionSystem?.patternId ===
      LADIES_CSS_EDITORIAL_RECIPE.runtime.compositionPattern
  );
}

function isCocoRushNightVariant(value: unknown): boolean {
  const variant = (value ?? {}) as Record<string, any>;
  return (
    variant.cocoVisualRecipeId === RUSH_NIGHT_RECIPE.id ||
    variant.cocoCompositionSystem?.patternId ===
      RUSH_NIGHT_RECIPE.runtime.compositionPattern
  );
}

function isCocoNeonNightShiftVariant(value: unknown): boolean {
  const variant = (value ?? {}) as Record<string, any>;
  return (
    variant.cocoVisualRecipeId === NEON_NIGHT_SHIFT_RECIPE.id ||
    variant.cocoCompositionSystem?.patternId ===
      NEON_NIGHT_SHIFT_RECIPE.runtime.compositionPattern
  );
}

function isCocoGlowInTheDarkVariant(value: unknown): boolean {
  const variant = (value ?? {}) as Record<string, any>;
  return (
    variant.cocoVisualRecipeId === GLOW_IN_THE_DARK_RECIPE.id ||
    variant.cocoCompositionSystem?.patternId ===
      GLOW_IN_THE_DARK_RECIPE.runtime.compositionPattern
  );
}

function isCocoRecipeSubjectAsset(value: unknown): boolean {
  const asset = (value ?? {}) as Record<string, any>;
  return (
    asset.cocoCompiledObjectId === "subject" ||
    asset.cocoAssetRole === "subject" ||
    String(asset.id || "").startsWith("coco_recipe_subject_") ||
    Boolean(asset.cocoSubjectLayoutId) ||
    (Boolean(asset.isExtracted) && !asset.isLogo && !asset.isSticker)
  );
}

function hasCocoSemanticTimeObject(value: unknown): boolean {
  const semanticObjects = (value as Record<string, any> | null | undefined)
    ?.cocoCssCompiler?.semanticObjects;
  return Boolean(
    semanticObjects &&
      Object.values(semanticObjects).some(
        (entry: any) => entry?.semanticRole === "time",
      ),
  );
}

function isMaterializedCocoVisualRecipeVariant(value: unknown): boolean {
  // Canvas ownership is separate from permission to offer a recipe in Coco.
  // An unregistered CSS compilation must never trigger generic template search.
  return hasCocoCompiledCanvas(value) || Boolean(getMaterializedCocoVisualRecipe(value));
}

type CocoMaterializedRecipeRuntime = {
  authority?: {
    layout?: { genericTemplateMayOverride?: boolean };
    palette?: { generatedPaletteMayOverride?: boolean };
  };
};

function materializedCocoRecipeBlocksGenericLayout(value: unknown): boolean {
  if (hasCocoCompiledCanvas(value)) return true;
  const recipe = getMaterializedCocoVisualRecipe(value) as
    | { runtime?: CocoMaterializedRecipeRuntime }
    | undefined;
  return Boolean(
    recipe?.runtime?.authority?.layout?.genericTemplateMayOverride === false
  );
}

function materializedCocoRecipeBlocksGeneratedPalette(value: unknown): boolean {
  const recipe = getMaterializedCocoVisualRecipe(value) as
    | { runtime?: CocoMaterializedRecipeRuntime }
    | undefined;
  return Boolean(
    recipe?.runtime?.authority?.palette?.generatedPaletteMayOverride === false
  );
}

