async function blobToDataURL(b: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(String(r.result || ''));
    r.onerror = reject;
    r.readAsDataURL(b);
  });
}

const MOBILE_MAX_IMAGE = 2400;
const DESKTOP_MAX_IMAGE = 2200;

type DownscaleOutputType = "image/png" | "image/jpeg" | "image/webp";

function getRuntimeMaxImageDimension() {
  if (typeof window === "undefined") return DESKTOP_MAX_IMAGE;
  const ua = typeof navigator === "undefined" ? "" : navigator.userAgent;
  const isMobileRuntime =
    window.innerWidth < 768 || /iPhone|iPad|Android/i.test(ua);
  return isMobileRuntime ? MOBILE_MAX_IMAGE : DESKTOP_MAX_IMAGE;
}

/** Ensure the given families are actually loaded before we rasterize. */
function waitForExportTimeout(ms: number): Promise<void> {
  if (ms <= 0) return Promise.resolve();
  return new Promise((resolve) => {
    if (typeof window !== "undefined") {
      window.setTimeout(resolve, ms);
      return;
    }
    setTimeout(resolve, ms);
  });
}

async function waitForExportPromise<T>(
  promise: Promise<T> | undefined | null,
  timeoutMs: number
): Promise<T | undefined> {
  if (!promise || typeof (promise as any).then !== "function") return undefined;
  return Promise.race([
    promise.catch(() => undefined),
    waitForExportTimeout(timeoutMs).then(() => undefined),
  ]);
}

async function fetchExportResource(
  input: RequestInfo | URL,
  init?: RequestInit,
  timeoutMs = 3500
) {
  const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
  const timeout = controller && typeof window !== "undefined"
    ? window.setTimeout(() => controller.abort(), timeoutMs)
    : null;
  try {
    return await fetch(input, {
      ...init,
      signal: controller?.signal ?? init?.signal,
    });
  } finally {
    if (timeout !== null) window.clearTimeout(timeout);
  }
}

async function blobToDataURLForExport(blob: Blob, timeoutMs = 2500) {
  const dataUrl = await waitForExportPromise(blobToDataURL(blob), timeoutMs);
  if (!dataUrl) throw new Error("blob data url timed out");
  return dataUrl;
}

async function waitForFamilies(
  families: (string | undefined)[],
  timeoutMs = 7000
): Promise<void> {
  const used = Array.from(new Set(families.filter(Boolean) as string[]));
  const deadline = Date.now() + timeoutMs;

  // First, wait for any pending font loads globally.
  await waitForExportPromise((document as any).fonts?.ready, Math.min(timeoutMs, 1500));

  // Then explicitly request each family at a few representative sizes/weights.
  for (const fam of used) {
    const faces = [
      `400 16px "${fam}"`,
      `700 32px "${fam}"`,
      `900 48px "${fam}"`,
    ];
    for (const desc of faces) {
      try {
        const p = (document as any).fonts?.load
          ? (document as any).fonts.load(desc)
          : Promise.resolve();
        // Simple timeout guard so we don't hang forever
        const remaining = Math.max(0, deadline - Date.now());
        await waitForExportPromise(p, Math.min(remaining, 1500));
      } catch {}
    }
  }
}

/** Export pre-flight: force browser to realize/load requested font families. */
async function forceFontRender(families: (string | undefined)[]): Promise<void> {
  const uniq = Array.from(new Set(families.filter(Boolean) as string[]));
  await waitForExportPromise((document as any).fonts?.ready, 1500);
  await Promise.all(
    uniq.map(async (f) => {
      try {
        await waitForExportPromise((document as any).fonts?.load?.(`16px "${f}"`), 1200);
      } catch {}
    })
  );
}

function normalizeFontFamilyName(raw: string): string {
  return String(raw || "").trim().replace(/^['"]|['"]$/g, "").toLowerCase();
}

function guessFontFormat(url: string): string {
  const clean = url.split("?")[0].toLowerCase();
  if (clean.endsWith(".woff2")) return "woff2";
  if (clean.endsWith(".woff")) return "woff";
  if (clean.endsWith(".otf")) return "opentype";
  return "truetype";
}

function hslToRgb(h: number, s: number, l: number): [number, number, number] {
  const hue = ((h % 360) + 360) % 360;
  const sat = Math.max(0, Math.min(1, s));
  const light = Math.max(0, Math.min(1, l));
  const c = (1 - Math.abs(2 * light - 1)) * sat;
  const x = c * (1 - Math.abs(((hue / 60) % 2) - 1));
  const m = light - c / 2;

  let r = 0;
  let g = 0;
  let b = 0;

  if (hue < 60) [r, g, b] = [c, x, 0];
  else if (hue < 120) [r, g, b] = [x, c, 0];
  else if (hue < 180) [r, g, b] = [0, c, x];
  else if (hue < 240) [r, g, b] = [0, x, c];
  else if (hue < 300) [r, g, b] = [x, 0, c];
  else [r, g, b] = [c, 0, x];

  return [
    Math.round((r + m) * 255),
    Math.round((g + m) * 255),
    Math.round((b + m) * 255),
  ];
}

type TemplateBackgroundPaletteSample = {
  rgb: LightingRgb;
  hex: string;
  count: number;
  h: number;
  s: number;
  l: number;
  lum: number;
};

const templateBackgroundPaletteCache = new Map<string, Palette>();

function rgbToHslForTemplatePalette(color: LightingRgb) {
  const rn = color.r / 255;
  const gn = color.g / 255;
  const bn = color.b / 255;
  const max = Math.max(rn, gn, bn);
  const min = Math.min(rn, gn, bn);
  const d = max - min;
  const l = (max + min) / 2;
  let h = 0;
  let s = 0;

  if (d) {
    s = d / (1 - Math.abs(2 * l - 1));
    if (max === rn) h = ((gn - bn) / d) % 6;
    else if (max === gn) h = (bn - rn) / d + 2;
    else h = (rn - gn) / d + 4;
    h *= 60;
    if (h < 0) h += 360;
  }

  return {
    h,
    s: Math.max(0, Math.min(1, s)),
    l: Math.max(0, Math.min(1, l)),
  };
}

function normalizePaletteHexString(hex: string, fallback = "#FFFFFF") {
  const value = String(hex || "").trim();
  if (!/^#[0-9a-f]{6}$/i.test(value)) return fallback;
  return value.toUpperCase();
}

function paletteHexFromRgb(color: LightingRgb) {
  return rgbToHex(color).toUpperCase();
}

function paletteHexFromHsl(h: number, s: number, l: number) {
  const [r, g, b] = hslToRgb(h, s, l);
  return paletteHexFromRgb({ r, g, b });
}

function hueDistance(a: number, b: number) {
  const diff = Math.abs((((a - b) % 360) + 540) % 360 - 180);
  return Math.min(180, diff);
}

function rgbDistance(a: LightingRgb, b: LightingRgb) {
  const dr = a.r - b.r;
  const dg = a.g - b.g;
  const db = a.b - b.b;
  return Math.sqrt(dr * dr + dg * dg + db * db);
}

function pickTemplatePaletteSample(
  samples: TemplateBackgroundPaletteSample[],
  predicate: (sample: TemplateBackgroundPaletteSample) => boolean,
  score: (sample: TemplateBackgroundPaletteSample) => number
) {
  let winner: TemplateBackgroundPaletteSample | null = null;
  let bestScore = -Infinity;
  for (const sample of samples) {
    if (!predicate(sample)) continue;
    const nextScore = score(sample);
    if (nextScore > bestScore) {
      bestScore = nextScore;
      winner = sample;
    }
  }
  return winner;
}

function resolveTemplateBackgroundPaletteSource(tpl: TemplateSpec, fmt: Format) {
  const variant: any = tpl.formats?.[fmt] ?? tpl.formats?.square ?? tpl.base ?? {};
  const candidates = [
    variant.backgroundUrl,
    variant.bgUploadUrl,
    variant.bgUrl,
    tpl.preview,
  ];
  return String(candidates.find((candidate) => typeof candidate === "string" && candidate.trim()) || "").trim();
}

async function analyzeTemplateBackgroundPalette(src: string): Promise<Palette | null> {
  const raw = String(src || "").trim();
  if (!raw || typeof window === "undefined" || typeof document === "undefined") return null;

  let cacheKey = raw;
  try {
    cacheKey = new URL(raw, window.location.href).toString();
  } catch {}

  const cached = templateBackgroundPaletteCache.get(cacheKey);
  if (cached) return { ...cached };

  try {
    const img = await new Promise<HTMLImageElement>((resolve, reject) => {
      const node = new Image();
      node.crossOrigin = "anonymous";
      node.decoding = "async";
      node.onload = () => resolve(node);
      node.onerror = () => reject(new Error("Failed to load template background for palette analysis."));
      node.src = cacheKey;
    });

    const naturalWidth = img.naturalWidth || img.width || 1;
    const naturalHeight = img.naturalHeight || img.height || 1;
    const maxSide = 180;
    const scale = Math.min(1, maxSide / Math.max(naturalWidth, naturalHeight));
    const width = Math.max(1, Math.round(naturalWidth * scale));
    const height = Math.max(1, Math.round(naturalHeight * scale));
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d", { willReadFrequently: true });
    if (!ctx) return null;

    ctx.drawImage(img, 0, 0, width, height);
    const data = ctx.getImageData(0, 0, width, height).data;
    const buckets = new Map<string, { r: number; g: number; b: number; count: number }>();

    for (let i = 0; i < data.length; i += 4) {
      const alpha = data[i + 3];
      if (alpha < 180) continue;

      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      const key = `${Math.round(r / 24) * 24},${Math.round(g / 24) * 24},${Math.round(b / 24) * 24}`;
      const bucket = buckets.get(key);
      if (bucket) {
        bucket.r += r;
        bucket.g += g;
        bucket.b += b;
        bucket.count += 1;
      } else {
        buckets.set(key, { r, g, b, count: 1 });
      }
    }

    const samples = Array.from(buckets.values())
      .map((bucket) => {
        const rgb = {
          r: Math.round(bucket.r / bucket.count),
          g: Math.round(bucket.g / bucket.count),
          b: Math.round(bucket.b / bucket.count),
        };
        const hsl = rgbToHslForTemplatePalette(rgb);
        return {
          rgb,
          hex: paletteHexFromRgb(rgb),
          count: bucket.count,
          h: hsl.h,
          s: hsl.s,
          l: hsl.l,
          lum: luminanceOfRgb(rgb),
        };
      })
      .sort((a, b) => b.count - a.count);

    if (!samples.length) return null;

    const directedPalette = createDirectedPalette(
      samples.map((sample) => ({
        hex: sample.hex,
        h: sample.h,
        s: sample.s,
        l: sample.l,
        weight: sample.count,
      }))
    );
    const baseHex = directedPalette.atmosphericColor?.hex || directedPalette.dominant.hex;
    const luxuryHex = directedPalette.luxuryColor?.hex || directedPalette.support.hex;
    const energyHex = directedPalette.energyColor?.hex || directedPalette.accent.hex;
    const neutralHex = directedPalette.readabilityColor?.hex || directedPalette.support.hex;
    const shadowHex = directedPalette.shadowColor?.hex || darkenHex(baseHex, 45);

    const palette: Palette = {
      bgFrom: baseHex,
      bgTo: shadowHex,
      secondary: baseHex,
      primary: luxuryHex,
      neutral: neutralHex,
      accent: energyHex,
    };
    templateBackgroundPaletteCache.set(cacheKey, { ...palette });
    return palette;
  } catch {
    return null;
  }
}

const tintedTextureCache = new Map<string, string>();
const canvasTintCache = new Map<string, string>();

type CanvasPreloadJob = {
  key: string;
  src: string;
  label: string;
  kind?: "image" | "tintedTexture";
  hue?: number;
};

type CanvasPreloadQueueStep = {
  job: CanvasPreloadJob;
  index: number;
  total: number;
  done: number;
  errors: number;
  phase: "start" | "done";
};

const CANVAS_PRELOAD_PROBLEM_COPY = [
  "Solving: make the event clear in the first three seconds.",
  "Solving: keep post and story versions matched without rebuilding twice.",
  "Solving: protect mobile memory by loading one premium layer at a time.",
  "Solving: keep the date, venue, price, and social details export-ready.",
  "Solving: prepare the design so edits stay responsive after load.",
];

function stablePreloadHash(value: string) {
  if (value.length > 2048) {
    value = `${value.slice(0, 768)}:${value.length}:${value.slice(-768)}`;
  }
  let hash = 2166136261;
  for (let i = 0; i < value.length; i += 1) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
}

function canPreloadCanvasSource(src?: string | null) {
  const value = String(src || "").trim();
  return !!value && !value.startsWith("about:") && !value.startsWith("javascript:");
}

function buildCanvasPreloadKey(src: string, kind: CanvasPreloadJob["kind"] = "image", hue = 0) {
  return `${kind}:${stablePreloadHash(src)}:${Math.round(Number(hue) || 0)}`;
}

function waitForCanvasPreloadFrame() {
  if (typeof window === "undefined") return Promise.resolve();
  return new Promise<void>((resolve) => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      window.clearTimeout(timeout);
      resolve();
    };
    const timeout = window.setTimeout(finish, 80);
    window.requestAnimationFrame(() => {
      finish();
    });
  });
}

function waitForCanvasPreloadPause(ms: number) {
  if (!ms || typeof window === "undefined") return Promise.resolve();
  return new Promise<void>((resolve) => {
    window.setTimeout(resolve, ms);
  });
}

async function loadCanvasPreloadImage(src: string): Promise<HTMLImageElement> {
  if (!canPreloadCanvasSource(src)) throw new Error("Missing image source");
  const img = new Image();
  if (!src.startsWith("data:") && !src.startsWith("blob:")) {
    img.crossOrigin = "anonymous";
  }
  img.decoding = "async";
  img.loading = "eager";
  await new Promise<void>((resolve, reject) => {
    const timeout = typeof window !== "undefined"
      ? window.setTimeout(() => {
          cleanup();
          reject(new Error("Image preload timed out"));
        }, 7000)
      : null;
    const cleanup = () => {
      if (timeout !== null) window.clearTimeout(timeout);
      img.onload = null;
      img.onerror = null;
    };
    img.onload = () => {
      cleanup();
      resolve();
    };
    img.onerror = () => {
      cleanup();
      reject(new Error("Image failed to preload"));
    };
    img.src = src;
    if (img.complete && img.naturalWidth > 0 && img.naturalHeight > 0) {
      cleanup();
      resolve();
    }
  });
  if ((img as any).decode) {
    try {
      await waitForExportPromise((img as any).decode(), 1500);
    } catch {
      // The onload path already proved the browser has the image.
    }
  }
  return img;
}

async function waitForHtmlImageElement(img: HTMLImageElement) {
  if (!img) throw new Error("Missing image element");
  if (img.complete && (!img.naturalWidth || !img.naturalHeight)) {
    throw new Error("Image failed to load");
  }
  if (!(img.complete && img.naturalWidth > 0 && img.naturalHeight > 0)) {
    await new Promise<void>((resolve, reject) => {
      const timeout = window.setTimeout(() => {
        cleanup();
        reject(new Error("Image load timed out"));
      }, 8000);
      const cleanup = () => {
        window.clearTimeout(timeout);
        img.removeEventListener("load", onLoad);
        img.removeEventListener("error", onError);
      };
      const onLoad = () => {
        cleanup();
        resolve();
      };
      const onError = () => {
        cleanup();
        reject(new Error("Image failed to load"));
      };
      img.addEventListener("load", onLoad, { once: true });
      img.addEventListener("error", onError, { once: true });
    });
  }
  if ((img as any).decode) {
    try {
      await waitForExportPromise((img as any).decode(), 1500);
    } catch {
      // A loaded image can still throw on decode in Safari. Keep the loaded image.
    }
  }
  if (!(img.complete && img.naturalWidth > 0 && img.naturalHeight > 0)) {
    throw new Error("Image did not decode");
  }
}

async function preloadCanvasImageUrl(src?: string | null) {
  if (!canPreloadCanvasSource(src)) return true;
  try {
    await loadCanvasPreloadImage(String(src));
    return true;
  } catch {
    return false;
  }
}

async function bakeTintedTextureSource(src: string, hue: number) {
  if (!src || !hue) {
    await preloadCanvasImageUrl(src);
    return src;
  }

  const cacheKey = `${src}|${Math.round(hue)}`;
  const cached = tintedTextureCache.get(cacheKey);
  if (cached) return cached;

  const img = await loadCanvasPreloadImage(src);
  try {
    const canvas = document.createElement("canvas");
    canvas.width = img.naturalWidth || img.width;
    canvas.height = img.naturalHeight || img.height;
    const ctx = canvas.getContext("2d", { willReadFrequently: true });
    if (!ctx || !canvas.width || !canvas.height) return src;

    ctx.drawImage(img, 0, 0);
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;
    const [tr, tg, tb] = hslToRgb(hue, 1, 0.5);

    for (let i = 0; i < data.length; i += 4) {
      const alpha = data[i + 3];
      if (alpha === 0) continue;

      const luminance =
        (0.2126 * data[i] + 0.7152 * data[i + 1] + 0.0722 * data[i + 2]) / 255;
      const boosted = Math.max(0, Math.min(1, luminance * 1.15 + 0.05));

      data[i] = Math.round(tr * boosted);
      data[i + 1] = Math.round(tg * boosted);
      data[i + 2] = Math.round(tb * boosted);
    }

    ctx.putImageData(imageData, 0, 0);
    const tinted = canvas.toDataURL("image/png");
    tintedTextureCache.set(cacheKey, tinted);
    return tinted;
  } catch {
    return src;
  }
}

function applyCssHueRotatePixel(
  r: number,
  g: number,
  b: number,
  degrees: number
) {
  const rad = (degrees * Math.PI) / 180;
  const cos = Math.cos(rad);
  const sin = Math.sin(rad);
  const nr =
    (0.213 + cos * 0.787 - sin * 0.213) * r +
    (0.715 - cos * 0.715 - sin * 0.715) * g +
    (0.072 - cos * 0.072 + sin * 0.928) * b;
  const ng =
    (0.213 - cos * 0.213 + sin * 0.143) * r +
    (0.715 + cos * 0.285 + sin * 0.14) * g +
    (0.072 - cos * 0.072 - sin * 0.283) * b;
  const nb =
    (0.213 - cos * 0.213 - sin * 0.787) * r +
    (0.715 - cos * 0.715 + sin * 0.715) * g +
    (0.072 + cos * 0.928 + sin * 0.072) * b;

  return [
    Math.max(0, Math.min(255, Math.round(nr))),
    Math.max(0, Math.min(255, Math.round(ng))),
    Math.max(0, Math.min(255, Math.round(nb))),
  ] as const;
}

async function bakeCanvasTintSource(
  src: string,
  hue: number,
  mode: "hue" | "colorize" = "hue"
) {
  if (!src || !hue) {
    await preloadCanvasImageUrl(src);
    return src;
  }

  const cacheKey = `${src}|${mode}|${Math.round(hue)}`;
  const cached = canvasTintCache.get(cacheKey);
  if (cached) return cached;

  const img = await loadCanvasPreloadImage(src);
  try {
    const canvas = document.createElement("canvas");
    canvas.width = img.naturalWidth || img.width;
    canvas.height = img.naturalHeight || img.height;
    const ctx = canvas.getContext("2d", { willReadFrequently: true });
    if (!ctx || !canvas.width || !canvas.height) return src;

    ctx.drawImage(img, 0, 0);
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;
    const target = mode === "colorize" ? hslToRgb(hue, 1, 0.5) : null;

    for (let i = 0; i < data.length; i += 4) {
      if (data[i + 3] === 0) continue;

      if (target) {
        const luminance =
          (0.2126 * data[i] + 0.7152 * data[i + 1] + 0.0722 * data[i + 2]) / 255;
        const boosted = Math.max(0, Math.min(1, luminance * 1.15 + 0.05));
        data[i] = Math.round(target[0] * boosted);
        data[i + 1] = Math.round(target[1] * boosted);
        data[i + 2] = Math.round(target[2] * boosted);
      } else {
        const [r, g, b] = applyCssHueRotatePixel(data[i], data[i + 1], data[i + 2], hue);
        data[i] = r;
        data[i + 1] = g;
        data[i + 2] = b;
      }
    }

    ctx.putImageData(imageData, 0, 0);
    const tinted = canvas.toDataURL("image/png");
    canvasTintCache.set(cacheKey, tinted);
    return tinted;
  } catch {
    return src;
  }
}

function applyExportCssColorFilterToCanvas(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  filterCss?: string
) {
  try {
    const ops: { name: string; value: number }[] = [];
    const re = /([a-z-]+)\(([^()]*)\)/gi;
    let match: RegExpExecArray | null;
    while ((match = re.exec(String(filterCss || "")))) {
      const name = match[1].toLowerCase();
      const rawValue = String(match[2] || "").trim();
      const numeric = rawValue.match(/^([-+]?\d*\.?\d+)(%|deg|rad|turn)?$/i);
      if (!numeric) continue;

      const number = Number(numeric[1]);
      const unit = String(numeric[2] || "").toLowerCase();
      if (!Number.isFinite(number)) continue;

      let value = number;
      if (name === "hue-rotate") {
        if (unit === "rad") value = number * (180 / Math.PI);
        else if (unit === "turn") value = number * 360;
      } else if (unit === "%") {
        value = number / 100;
      }

      if (
        name === "brightness" ||
        name === "contrast" ||
        name === "saturate" ||
        name === "hue-rotate"
      ) {
        ops.push({ name, value });
      }
    }
    if (!ops.length) return false;

    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const clampChannel = (value: number) =>
      Math.max(0, Math.min(255, Math.round(value * 255)));

    for (let i = 0; i < data.length; i += 4) {
      let r = data[i] / 255;
      let g = data[i + 1] / 255;
      let b = data[i + 2] / 255;

      for (const op of ops) {
        if (op.name === "brightness") {
          r *= Math.max(0, op.value);
          g *= Math.max(0, op.value);
          b *= Math.max(0, op.value);
        } else if (op.name === "contrast") {
          const amount = Math.max(0, op.value);
          r = (r - 0.5) * amount + 0.5;
          g = (g - 0.5) * amount + 0.5;
          b = (b - 0.5) * amount + 0.5;
        } else if (op.name === "saturate") {
          const amount = Math.max(0, op.value);
          const lr = 0.213 * r + 0.715 * g + 0.072 * b;
          r = lr + (r - lr) * amount;
          g = lr + (g - lr) * amount;
          b = lr + (b - lr) * amount;
        } else if (op.name === "hue-rotate") {
          const rotated = applyCssHueRotatePixel(r * 255, g * 255, b * 255, op.value);
          r = rotated[0] / 255;
          g = rotated[1] / 255;
          b = rotated[2] / 255;
        }
      }

      data[i] = clampChannel(r);
      data[i + 1] = clampChannel(g);
      data[i + 2] = clampChannel(b);
    }

    ctx.putImageData(imageData, 0, 0);
    return true;
  } catch {
    return false;
  }
}

async function preloadCanvasJobsSequentially(
  jobs: CanvasPreloadJob[],
  opts: {
    onStep?: (step: CanvasPreloadQueueStep) => void;
    pauseMs?: number;
    shouldCancel?: () => boolean;
  } = {}
) {
  let errors = 0;
  const total = jobs.length;

  for (let index = 0; index < jobs.length; index += 1) {
    if (opts.shouldCancel?.()) break;
    const job = jobs[index];
    opts.onStep?.({ job, index, total, done: index, errors, phase: "start" });

    const ok =
      job.kind === "tintedTexture"
        ? await bakeTintedTextureSource(job.src, Number(job.hue || 0)).then(() => true).catch(() => false)
        : await preloadCanvasImageUrl(job.src);
    if (!ok) errors += 1;

    opts.onStep?.({ job, index, total, done: index + 1, errors, phase: "done" });
    await waitForCanvasPreloadFrame();
    await waitForCanvasPreloadPause(opts.pauseMs ?? 0);
  }

  return { errors };
}

type CocoRendererFaceZone = {
  x: number;
  y: number;
  width: number;
  height: number;
  align?: "left" | "center" | "right";
};

function resolveCocoRendererFaceZone(
  state: ReturnType<typeof useFlyerState.getState>,
  format: "square" | "story",
  liveBackground?: {
    positionX: number;
    positionY: number;
    scale: number;
    rotation?: number;
  }
): CocoRendererFaceZone | null {
  const list = (((state as any).portraits?.[format] || []) as any[]).filter(
    (item) => !isRemovedTemplateAsset(item)
  );
  const isUsableExtractedSubject = (item: any) =>
    !!item?.isExtracted &&
    !item?.isLogo &&
    !item?.isFlare &&
    !!item?.cocoSubjectBounds?.face;
  // Match the canvas guide's canonical cutout selection exactly. A generated
  // hero can legitimately carry `isBrandFace`; that tag must not disqualify
  // the visible person whose mask and face bounds are being rendered.
  const isVisibleMaskedSubject = (item: any) =>
    !!item?.isExtracted &&
    !!item?.cocoSubjectBounds?.maskDataUrl &&
    !!item?.cocoSubjectBounds?.face;
  // The visible extracted subject is authoritative. A native scene may also
  // retain an older recipe subject entry; choosing that first freezes the face
  // rectangle while the user moves the cutout that is actually on the canvas.
  const subjectItem =
    list.find(isVisibleMaskedSubject) ??
    list.find(isUsableExtractedSubject) ??
    list.find(
      (item) =>
        String(item?.id || "").startsWith("coco_recipe_subject_") &&
        !!item?.cocoSubjectBounds?.face
    );
  const sessionVariant = (state as any).session?.[format];
  const backgroundOnlyHero = Boolean(sessionVariant?.cocoBackgroundOnlyHero);
  const subjectBounds = (subjectItem?.cocoSubjectBounds ?? sessionVariant?.cocoSubjectBounds) as
    | CanvasSubjectBoundsInput
    | undefined;
  const canonicalBackgroundFace = sessionVariant?.cocoHeroImageFace as
    | {
        x: number;
        y: number;
        width: number;
        height: number;
        imageWidth: number;
        imageHeight: number;
      }
    | undefined;
  // A single-photo canvas has exactly one subject authority: the analyzed
  // background image. Winning-template assets may still carry portrait-like
  // metadata, but they are styling/decorative imports and must never replace
  // the uploaded photo's face rectangle.
  if (
    backgroundOnlyHero &&
    liveBackground &&
    canonicalBackgroundFace &&
    Number(canonicalBackgroundFace.imageWidth) > 0 &&
    Number(canonicalBackgroundFace.imageHeight) > 0
  ) {
    const sourceWidth = Number(canonicalBackgroundFace.imageWidth);
    const sourceHeight = Number(canonicalBackgroundFace.imageHeight);
    const model = buildCanvasSubjectModel({
      bounds: {
        width: sourceWidth,
        height: sourceHeight,
        alpha: { x: 0, y: 0, width: sourceWidth, height: sourceHeight },
        face: {
          x: canonicalBackgroundFace.x,
          y: canonicalBackgroundFace.y,
          width: canonicalBackgroundFace.width,
          height: canonicalBackgroundFace.height,
        },
      },
      canvas: { width: 540, height: format === "story" ? 960 : 540 },
      transform: {
        kind: "background",
        backgroundPositionX: liveBackground.positionX,
        backgroundPositionY: liveBackground.positionY,
        backgroundScale: liveBackground.scale,
        rotationDeg: liveBackground.rotation,
      },
    });
    if (model.faceBounds) return canvasRectToPercent(model.faceBounds, model.canvas);
  }
  if (
    !backgroundOnlyHero &&
    subjectItem &&
    subjectBounds?.face &&
    Number(subjectBounds.width) > 0 &&
    Number(subjectBounds.height) > 0
  ) {
    const model = buildCanvasSubjectModel({
      bounds: subjectBounds,
      canvas: { width: 540, height: format === "story" ? 960 : 540 },
      transform: {
        kind: "cutout",
        centerXPct: Number(subjectItem.x ?? 50),
        centerYPct: Number(subjectItem.y ?? 50),
        scale: Math.max(0.001, Number(subjectItem.scale ?? 1)),
        rotationDeg: Number(subjectItem.rotation ?? 0),
      },
    });
    if (model.faceBounds) return canvasRectToPercent(model.faceBounds, model.canvas);
  }
  if (
    !backgroundOnlyHero &&
    !subjectItem &&
    liveBackground &&
    canonicalBackgroundFace &&
    Number(canonicalBackgroundFace.imageWidth) > 0 &&
    Number(canonicalBackgroundFace.imageHeight) > 0
  ) {
    const sourceWidth = Number(canonicalBackgroundFace.imageWidth);
    const sourceHeight = Number(canonicalBackgroundFace.imageHeight);
    const model = buildCanvasSubjectModel({
      bounds: {
        width: sourceWidth,
        height: sourceHeight,
        alpha: { x: 0, y: 0, width: sourceWidth, height: sourceHeight },
        face: {
          x: canonicalBackgroundFace.x,
          y: canonicalBackgroundFace.y,
          width: canonicalBackgroundFace.width,
          height: canonicalBackgroundFace.height,
        },
      },
      canvas: { width: 540, height: format === "story" ? 960 : 540 },
      transform: {
        kind: "background",
        backgroundPositionX: liveBackground.positionX,
        backgroundPositionY: liveBackground.positionY,
        backgroundScale: liveBackground.scale,
        rotationDeg: liveBackground.rotation,
      },
    });
    if (model.faceBounds) return canvasRectToPercent(model.faceBounds, model.canvas);
  }
  // Compatibility fallback for older background canvases that predate the
  // canonical hero-face record. New canvases never derive face geometry from
  // the segmentation result.
  if (
    backgroundOnlyHero &&
    !subjectItem &&
    liveBackground &&
    subjectBounds?.face &&
    Number(subjectBounds.width) > 0 &&
    Number(subjectBounds.height) > 0
  ) {
    const model = buildCanvasSubjectModel({
      bounds: subjectBounds,
      canvas: { width: 540, height: format === "story" ? 960 : 540 },
      transform: {
        kind: "background",
        backgroundPositionX: liveBackground.positionX,
        backgroundPositionY: liveBackground.positionY,
        backgroundScale: liveBackground.scale,
        rotationDeg: liveBackground.rotation,
      },
    });
    if (model.faceBounds) {
      return canvasRectToPercent(model.faceBounds, model.canvas);
    }
  }
  const value = subjectItem?.cocoSubjectFaceFitZone ?? sessionVariant?.cocoHeroImageFit?.faceRect;
  const x = Number(value?.x);
  const y = Number(value?.y);
  const width = Number(value?.width);
  const height = Number(value?.height);
  if (![x, y, width, height].every(Number.isFinite) || width <= 0 || height <= 0) return null;
  return {
    x: Math.max(0, Math.min(100, x)),
    y: Math.max(0, Math.min(100, y)),
    width: Math.max(1, Math.min(100, width)),
    height: Math.max(1, Math.min(100, height)),
    align: value?.align,
  };
}

function resolveCocoNativeVariantFaceZone(
  variant: Partial<TemplateBase>,
  format: Format
): CocoRendererFaceZone | null {
  const assets = [
    ...((((variant as any).emojiList ?? []) as any[])),
    ...((((variant as any).portraits ?? []) as any[])),
  ];
  const subjectModel = assets.find((item) => (item as any)?.cocoCanvasSubjectModel?.faceBounds)
    ?.cocoCanvasSubjectModel;
  if (subjectModel?.faceBounds && subjectModel?.canvas) {
    return canvasRectToPercent(subjectModel.faceBounds, subjectModel.canvas);
  }

  const bounds = (variant as any).cocoSubjectBounds as CanvasSubjectBoundsInput | undefined;
  if (
    bounds?.face &&
    Number(bounds.width) > 0 &&
    Number(bounds.height) > 0
  ) {
    const model = buildCanvasSubjectModel({
      bounds,
      canvas: { width: 540, height: format === "story" ? 960 : 540 },
      transform: {
        kind: "background",
        backgroundPositionX: Number((variant as any).bgPosX ?? 50),
        backgroundPositionY: Number((variant as any).bgPosY ?? 50),
        backgroundScale: Math.max(0.01, Number((variant as any).bgScale ?? 1)),
        rotationDeg: Number((variant as any).bgRotate ?? 0),
      },
    });
    if (model.faceBounds) return canvasRectToPercent(model.faceBounds, model.canvas);
  }

  // A template face target is not a detection. For a background-only hero
  // with no measured face, expose no native face zone at all; otherwise later
  // layout changes can mistake the recipe target for a real person.
  if ((variant as any).cocoBackgroundOnlyHero && !(variant as any).cocoHeroImageFace) {
    return null;
  }

  const fallback =
    (variant as any).cocoHeroImageFit?.faceRect ??
    (variant as any).subjectFaceRect;
  const x = Number(fallback?.x);
  const y = Number(fallback?.y);
  const width = Number(fallback?.width);
  const height = Number(fallback?.height);
  return [x, y, width, height].every(Number.isFinite) && width > 0 && height > 0
    ? { x, y, width, height, align: fallback?.align }
    : null;
}

function applyCocoNativeFaceAvoidance(
  source: Partial<TemplateBase>,
  faceZone: CocoRendererFaceZone | null,
  format: Format
): Partial<TemplateBase> {
  if (!faceZone) return source;
  if (
    Number((source as any).cocoCenterLayoutVersion ?? 0) >= 1 &&
    (source as any).cocoSubjectLayoutId === "subject-center"
  ) {
    return source;
  }
  // Center-authority v6 already derives every semantic content zone from the
  // live protected face and subject envelope. Running the legacy lockup
  // shifter afterward replaces those authoritative coordinates (most visibly
  // pushing the event name below the face), so the text appears beside the
  // debug zones instead of inside them. Side layouts still need this fallback;
  // a completed center layout does not.
  if (
    Number((source as any).cocoCenterAuthorityVersion ?? 0) >= 7 &&
    (source as any).cocoSubjectLayoutId === "subject-center" &&
    (source as any).cocoCenterZones
  ) {
    return source;
  }
  const storedBase = ((source as any).cocoNativeFaceAvoidanceBase ?? null) as
    | Record<string, unknown>
    | null;
  const base = storedBase ?? {
    headX: source.headX,
    headY: source.headY,
    headlineSize: source.headlineSize,
    head2X: source.head2X,
    head2Y: source.head2Y,
    head2Size: source.head2Size,
    head2ColWidth: source.head2ColWidth,
    presenterX: source.presenterX,
    presenterY: source.presenterY,
    presenterWidth: source.presenterWidth,
    presenterSize: source.presenterSize,
    subtagY: source.subtagY,
    detailsY: source.detailsY,
    details2Y: source.details2Y,
    priceY: source.priceY,
    complianceY: (source as any).complianceY,
  };
  const headlineY = Number(base.headY);
  const headlineSize = Number(base.headlineSize);
  if (!Number.isFinite(headlineY) || !Number.isFinite(headlineSize) || headlineSize <= 0) {
    return source;
  }

  const lineCount = Math.max(
    1,
    String(source.headline ?? "")
      .split(/\r?\n/)
      .filter((line) => line.trim()).length
  );
  const lineHeight = Math.max(0.55, Number((source as any).headlineHeight ?? source.lineHeight ?? 1));
  const canvasHeight = format === "story" ? 960 : 540;
  const headlineHeight = Math.max(4, (headlineSize * lineCount * lineHeight / canvasHeight) * 100);
  const faceBottom = Number(faceZone.y) + Number(faceZone.height);
  const faceRight = Number(faceZone.x) + Number(faceZone.width);
  const protectionGap = Math.max(3.5, Number(faceZone.height) * 0.14);
  const presenterSize = Math.max(0, Number(base.presenterSize ?? source.presenterSize ?? 0));
  const presenterLineHeight = Math.max(0.6, Number(source.presenterLineHeight ?? 0.8));
  const presenterHeight = presenterSize > 0
    ? Math.max(1.25, (presenterSize * presenterLineHeight / canvasHeight) * 100)
    : 0;
  const basePresenterY = Number(base.presenterY);
  const headlineX = Number(base.headX ?? source.headX ?? 0);
  const headlineWidth = Math.max(
    8,
    Math.min(100, Number(source.textColWidth ?? (source as any).mainTitleRect?.width ?? 58))
  );
  const headlineOverlapsExpandedFace =
    headlineX < faceRight + protectionGap &&
    headlineX + headlineWidth > Number(faceZone.x) - protectionGap &&
    headlineY < faceBottom + protectionGap &&
    headlineY + headlineHeight > Number(faceZone.y) - protectionGap;
  const presenterY = headlineOverlapsExpandedFace && Number.isFinite(basePresenterY)
    ? Math.max(basePresenterY, faceBottom + protectionGap)
    : basePresenterY;
  const presenterToHeadlineGap = presenterHeight > 0 ? 2.75 : 0;
  const desiredHeadlineY = headlineOverlapsExpandedFace
    ? Math.max(
        headlineY,
        faceBottom + protectionGap,
        Number.isFinite(presenterY)
          ? presenterY + presenterHeight + presenterToHeadlineGap
          : headlineY
      )
    : headlineY;

  const headlineBottom = headlineY + headlineHeight;
  const lockupMinY = headlineY - 8;
  const lockupMaxY = headlineBottom + 10;
  const followingRoleYs = [
    base.detailsY,
    base.details2Y,
    base.priceY,
    base.complianceY,
    base.subtagY,
  ]
    .map(Number)
    .filter((value) => Number.isFinite(value) && value > headlineY + headlineHeight * 0.7);
  const nextRoleY = followingRoleYs.length ? Math.min(...followingRoleYs) : 96;
  const maximumHeadlineBottom = Math.max(desiredHeadlineY + 4, nextRoleY - 3.25);
  const availableHeadlineHeight = Math.max(4, maximumHeadlineBottom - desiredHeadlineY);
  const headlineScale = headlineOverlapsExpandedFace
    ? Math.max(0.68, Math.min(1, availableHeadlineHeight / headlineHeight))
    : 1;
  const adjustedHeadlineSize = Math.round(headlineSize * headlineScale * 10) / 10;
  // The face boundary is absolute. Capping this shift left the title sitting
  // across the face whenever a reference began unusually high on the canvas.
  // The reference controls style; the detected face controls how far the
  // title lockup must move.
  const shift = headlineOverlapsExpandedFace
    ? Math.max(0, desiredHeadlineY - headlineY)
    : 0;

  const shiftNearbyY = (value: unknown) => {
    const y = Number(value);
    return Number.isFinite(y) && y >= lockupMinY && y <= lockupMaxY ? y + shift : value;
  };
  const shiftRect = (value: unknown) => {
    if (!value || typeof value !== "object") return value;
    const rect = value as Record<string, unknown>;
    const y = Number(rect.y);
    return Number.isFinite(y) ? { ...rect, y: y + shift } : value;
  };
  const shiftAssets = (value: unknown) =>
    Array.isArray(value)
      ? value.map((item) => {
          const y = Number(item?.y);
          return Number.isFinite(y) && y >= headlineY - 2 && y <= lockupMaxY
            ? { ...item, y: y + shift }
            : item;
        })
      : value;

  const head2X = Number(base.head2X);
  const head2Y = Number(base.head2Y);
  const head2Size = Number(base.head2Size);
  const head2LineCount = Math.max(
    1,
    String(source.head2line ?? "")
      .split(/\r?\n/)
      .filter((line) => line.trim()).length
  );
  const head2LineHeight = Math.max(0.65, Number(source.head2LineHeight ?? 0.95));
  const head2Height = Number.isFinite(head2Size) && head2Size > 0
    ? Math.max(2, (head2Size * head2LineCount * head2LineHeight / canvasHeight) * 100)
    : 0;
  const configuredHead2Width = Number(
    base.head2ColWidth ?? (source as any).scriptRect?.width ?? source.textColWidth ?? 34
  );
  const head2Width = Math.max(8, Math.min(92, configuredHead2Width));
  const horizontalGap = Math.max(3.25, Number(faceZone.width) * 0.12);
  const canvasMargin = 4;
  const overlapsExpandedFace =
    Number.isFinite(head2X) &&
    Number.isFinite(head2Y) &&
    head2Height > 0 &&
    head2X < faceRight + horizontalGap &&
    head2X + head2Width > Number(faceZone.x) - horizontalGap &&
    head2Y < faceBottom + protectionGap &&
    head2Y + head2Height > Number(faceZone.y) - protectionGap;
  let adjustedHead2X = head2X;
  let adjustedHead2Y = head2Y;
  let adjustedHead2Size = head2Size;
  let adjustedHead2Width = head2Width;
  if (overlapsExpandedFace) {
    const leftWidth = Math.max(0, Number(faceZone.x) - horizontalGap - canvasMargin);
    const rightStart = Math.min(96, faceRight + horizontalGap);
    const rightWidth = Math.max(0, 100 - canvasMargin - rightStart);
    const preferLeft = head2X + head2Width / 2 <= Number(faceZone.x) + Number(faceZone.width) / 2;
    const side = preferLeft
      ? leftWidth >= Math.min(14, head2Width * 0.55) ? "left" : "right"
      : rightWidth >= Math.min(14, head2Width * 0.55) ? "right" : "left";
    const availableWidth = side === "left" ? leftWidth : rightWidth;
    adjustedHead2Width = Math.max(8, Math.min(head2Width, availableWidth));
    adjustedHead2X = side === "left"
      ? Math.max(canvasMargin, Number(faceZone.x) - horizontalGap - adjustedHead2Width)
      : rightStart;
    if (Number.isFinite(head2Size) && adjustedHead2Width < head2Width) {
      adjustedHead2Size = Math.max(10, head2Size * (adjustedHead2Width / head2Width));
    }
    // Preserve the reference's vertical rhythm when a clean side pocket exists.
    // Otherwise put the reduced accent immediately above the protected face.
    if (availableWidth < 8) {
      adjustedHead2Y = Math.max(canvasMargin, Number(faceZone.y) - protectionGap - head2Height);
    }
  }

  return {
    ...source,
    headY: headlineY + shift,
    headlineSize: adjustedHeadlineSize,
    headSize: adjustedHeadlineSize,
    head2X: adjustedHead2X,
    head2Y: adjustedHead2Y,
    head2Size: adjustedHead2Size,
    head2SizePx: adjustedHead2Size,
    head2ColWidth: adjustedHead2Width,
    presenterY: Number.isFinite(presenterY) ? presenterY : shiftNearbyY(source.presenterY) as number,
    leftRailY: shiftNearbyY((source as any).leftRailY) as number,
    rightRailY: shiftNearbyY((source as any).rightRailY) as number,
    detailsY: shiftNearbyY(source.detailsY) as number,
    details2Y: shiftNearbyY(source.details2Y) as number,
    venueY: shiftNearbyY(source.venueY) as number,
    mainTitleRect: shiftRect((source as any).mainTitleRect) as any,
    scriptRect: shiftRect((source as any).scriptRect) as any,
    emojiList: shiftAssets((source as any).emojiList) as any,
    portraits: shiftAssets((source as any).portraits) as any,
    ...({
      cocoNativeFaceAvoidanceShift: shift,
      cocoNativeFaceZone: { ...faceZone },
      cocoNativeFaceAvoidanceBase: base,
      cocoNativeFaceReflow: {
        headlineScale,
        headlineY: headlineY + shift,
        presenterY,
        head2X: adjustedHead2X,
        head2Y: adjustedHead2Y,
        head2Size: adjustedHead2Size,
      },
    } as any),
  };
}

function fitCocoCenterHeadlineSize(
  value: unknown,
  text: unknown,
  zone: { width: number; height: number } | null | undefined,
  format: Format,
  lineHeight: unknown
) {
  const requested = Number(value);
  if (!Number.isFinite(requested) || requested <= 0 || !zone) return value;
  const lines = String(text ?? "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
  const lineCount = Math.max(1, lines.length);
  const longestLine = Math.max(1, ...lines.map((line) => line.length));
  const canvasWidth = 540;
  const canvasHeight = format === "story" ? 960 : 540;
  const resolvedLineHeight = Math.max(0.7, Number(lineHeight ?? 0.9));
  const heightLimit = (zone.height / 100) * canvasHeight / (lineCount * resolvedLineHeight);
  const widthLimit = (zone.width / 100) * canvasWidth / (longestLine * 0.62);
  return Math.max(12, Math.round(Math.min(requested, heightLimit, widthLimit) * 10) / 10);
}

const COCO_LIVE_GUIDE_ROLES = [
  "headline",
  "headline2",
  "presenter",
  "date",
  "price",
  "details",
  "details2",
  "venue",
  "subtag",
  "compliance",
  "leftRail",
  "rightRail",
  "socialHandle",
  "qr",
] as const;

type CocoLiveNativeZone = { role: string; rect: CocoRendererFaceZone };

function CocoLiveNativeZoneGuides({
  enabled,
  measurementKey,
  onZones,
  visible = enabled,
}: {
  enabled: boolean;
  measurementKey: string;
  onZones?: (measurementKey: string, zones: CocoLiveNativeZone[]) => void;
  visible?: boolean;
}) {
  const [zones, setZones] = React.useState<CocoLiveNativeZone[]>([]);
  const signatureRef = React.useRef("");
  const anchorRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    if (!enabled) {
      signatureRef.current = "";
      setZones([]);
      onZones?.(measurementKey, []);
      return;
    }
    // A new format/layout needs its own readiness handoff even when the
    // painted rectangles happen to be numerically identical.
    signatureRef.current = "";
    let frame = 0;
    let resizeObserver: ResizeObserver | null = null;
    let mutationObserver: MutationObserver | null = null;
    const measure = () => {
      frame = 0;
      const root = anchorRef.current?.closest<HTMLElement>("#portrait-layer-root");
      if (!root) return;
      const artboard = root.closest<HTMLElement>("#artboard") ?? root.parentElement;
      if (!artboard) return;
      const rootRect = root.getBoundingClientRect();
      if (rootRect.width <= 0 || rootRect.height <= 0) return;
      const next = COCO_LIVE_GUIDE_ROLES.flatMap((role) => {
        const candidates = Array.from(
          artboard.querySelectorAll<HTMLElement>(`[data-node="${role}"]`)
        );
        const node = candidates.find((candidate) => {
          const rect = candidate.getBoundingClientRect();
          return (
            rect.width > 0 &&
            rect.height > 0 &&
            rect.right > rootRect.left &&
            rect.left < rootRect.right &&
            rect.bottom > rootRect.top &&
            rect.top < rootRect.bottom
          );
        });
        if (!node) return [];
        const rect = node.getBoundingClientRect();
        const x = ((rect.left - rootRect.left) / rootRect.width) * 100;
        const y = ((rect.top - rootRect.top) / rootRect.height) * 100;
        const left = Math.max(0, Math.min(100, x));
        const top = Math.max(0, Math.min(100, y));
        const width = Math.max(
          0.5,
          Math.min(100 - left, (rect.width / rootRect.width) * 100)
        );
        const height = Math.max(
          0.5,
          Math.min(100 - top, (rect.height / rootRect.height) * 100)
        );
        return [{ role, rect: { x: left, y: top, width, height } }];
      });
      const signature = JSON.stringify(
        next.map(({ role, rect }) => [
          role,
          rect.x.toFixed(2),
          rect.y.toFixed(2),
          rect.width.toFixed(2),
          rect.height.toFixed(2),
        ])
      );
      if (signature !== signatureRef.current) {
        signatureRef.current = signature;
        setZones(next);
        onZones?.(measurementKey, next);
      }
    };
    const scheduleMeasure = () => {
      if (!frame) frame = window.requestAnimationFrame(measure);
    };
    scheduleMeasure();
    const root = anchorRef.current?.closest<HTMLElement>("#portrait-layer-root");
    const artboard = root?.closest<HTMLElement>("#artboard") ?? root?.parentElement;
    if (artboard) {
      resizeObserver = new ResizeObserver(scheduleMeasure);
      resizeObserver.observe(artboard);
      COCO_LIVE_GUIDE_ROLES.forEach((role) => {
        artboard
          .querySelectorAll<HTMLElement>(`[data-node="${role}"]`)
          .forEach((node) => resizeObserver?.observe(node));
      });
      mutationObserver = new MutationObserver((records) => {
        if (
          records.some(
            (record) =>
              !(record.target as Element).closest?.('[data-coco-debug-layout-zones="true"]')
          )
        ) {
          scheduleMeasure();
        }
      });
      mutationObserver.observe(artboard, {
        attributes: true,
        childList: true,
        characterData: true,
        subtree: true,
      });
    }
    window.addEventListener("resize", scheduleMeasure);
    return () => {
      if (frame) window.cancelAnimationFrame(frame);
      resizeObserver?.disconnect();
      mutationObserver?.disconnect();
      window.removeEventListener("resize", scheduleMeasure);
    };
  }, [enabled, measurementKey, onZones]);

  if (!enabled) return null;
  return (
    <>
      <span
        ref={anchorRef}
        data-nonexport="true"
        data-coco-live-native-zone-anchor={measurementKey}
        hidden
      />
      {visible && zones.length > 0 ? (
        <div
          data-nonexport="true"
          data-coco-debug-layout-zones="true"
          data-coco-debug-layout-source="live-native"
          className="pointer-events-none absolute inset-0"
          style={{ zIndex: 1188 }}
        >
          {zones.map(({ role, rect }, index) => {
        const hue = (index * 47 + 184) % 360;
        const color = `hsl(${hue} 96% 62%)`;
        return (
          <div
            key={`coco-live-native-zone-${role}`}
            data-coco-debug-layout-zone={role}
            style={{
              position: "absolute",
              left: `${rect.x}%`,
              top: `${rect.y}%`,
              width: `${rect.width}%`,
              height: `${rect.height}%`,
              border: `1.5px dashed ${color}`,
              background: `hsl(${hue} 96% 62% / 0.035)`,
            }}
          >
            <span
              style={{
                position: "absolute",
                left: 3,
                top: rect.y < 3 ? 3 : -20,
                maxWidth: "calc(100% - 6px)",
                overflow: "hidden",
                padding: "2px 5px",
                borderRadius: 4,
                background: "rgba(8, 12, 20, 0.86)",
                color,
                fontSize: 9,
                fontWeight: 850,
                letterSpacing: "0.06em",
                lineHeight: 1.35,
                textOverflow: "ellipsis",
                textTransform: "uppercase",
                whiteSpace: "nowrap",
              }}
            >
              {role}
            </span>
          </div>
        );
          })}
        </div>
      ) : null}
    </>
  );
}

type CocoRendererZoneMap = CocoReferenceZoneMap & {
  headlineAuthority?: "image-safe-zone";
};

function patchCocoCompositionZones(
  composition: CocoCompositionSystem | null | undefined,
  zones: CocoRendererZoneMap | null | undefined,
  referenceLayoutId?: string | null
): CocoCompositionSystem | null {
  if (!composition) return null;
  if (!zones) return composition;
  if (referenceLayoutId?.startsWith("template:")) {
    return buildAuthoritativeReferenceComposition({
      base: composition,
      layoutId: referenceLayoutId,
      zones,
    });
  }
  // The image analyzer's headline candidates are deliberately at least 70%
  // of the canvas. Once it has selected one, render every selected role as
  // an independent zone. Leaving a non-center composition in its legacy
  // single textColumn would measure the title against the safe zone but then
  // draw it somewhere else as part of the old flowing stack.
  if (zones.headlineAuthority === "image-safe-zone") {
    return buildAuthoritativeReferenceComposition({
      base: composition,
      layoutId: "image-safe-zone",
      zones,
    });
  }
  const zoneForBlock = (block: CocoCompositionSystem["blocks"][number]) => {
    if (block.role === "headline") return zones.headline;
    if (block.role === "accent") return zones.script;
    if (block.role === "badge") return zones.price;
    if (block.role === "dateTime") return zones.date;
    if (block.role === "venue") return zones.venue;
    if (block.role === "footer" && block.source === "presenter") return zones.presenter;
    if (block.role === "footer" && block.source === "compliance") return zones.compliance;
    return undefined;
  };
  const patchBlock = (block: CocoCompositionSystem["blocks"][number]) => {
    const zone = zoneForBlock(block);
    return zone ? { ...block, rect: { ...zone, align: zone.align ?? block.align } } : block;
  };
  const blocks = composition.blocks.map(patchBlock);
  return {
    ...composition,
    blocks,
    allBlocks: composition.allBlocks.map(patchBlock),
  };
}

function TintedTextureImage({
  src,
  hue,
  tintMode = "colorize",
  fallbackFilter,
  style,
  ...imgProps
}: {
  src: string;
  hue: number;
  tintMode?: "hue" | "colorize";
  fallbackFilter?: string;
  style: React.CSSProperties;
} & React.ImgHTMLAttributes<HTMLImageElement>) {
  const requestKey = `${stablePreloadHash(src)}:${src.length}:${Math.round(Number(hue) || 0)}:${tintMode}:${fallbackFilter ?? ""}`;
  const [resolved, setResolved] = React.useState<{
    filter?: string;
    key: string;
    src: string;
  }>(() => ({
    filter: !src || !hue ? undefined : fallbackFilter,
    key: requestKey,
    src,
  }));

  React.useEffect(() => {
    let cancelled = false;

    if (!src || !hue) {
      setResolved((previous) =>
        previous.key === requestKey && previous.src === src && previous.filter === undefined
          ? previous
          : { filter: undefined, key: requestKey, src }
      );
      return () => {
        cancelled = true;
      };
    }

    const bakePromise =
      tintMode === "colorize"
        ? bakeTintedTextureSource(src, hue)
        : bakeCanvasTintSource(src, hue, "hue");

    void bakePromise
      .then((nextSrc) => {
        if (!cancelled) {
          const bakedSrc = nextSrc || src;
          const bakedFilter = nextSrc && nextSrc !== src ? undefined : fallbackFilter;
          setResolved((previous) =>
            previous.key === requestKey &&
            previous.src === bakedSrc &&
            previous.filter === bakedFilter
              ? previous
              : { filter: bakedFilter, key: requestKey, src: bakedSrc }
          );
        }
      })
      .catch(() => {
        if (!cancelled) {
          setResolved((previous) =>
            previous.key === requestKey &&
            previous.src === src &&
            previous.filter === fallbackFilter
              ? previous
              : { filter: fallbackFilter, key: requestKey, src }
          );
        }
      });

    return () => {
      cancelled = true;
    };
  }, [fallbackFilter, hue, requestKey, src, tintMode]);

  const displaySrc = resolved.key === requestKey ? resolved.src : src;
  const displayFilter = resolved.key === requestKey
    ? resolved.filter
    : !src || !hue
      ? undefined
      : fallbackFilter;

  const mergedStyle =
    displayFilter && displayFilter !== "none"
      ? { ...style, filter: displayFilter, WebkitFilter: displayFilter }
      : style;

  return (
    <img
      {...imgProps}
      src={displaySrc}
      alt={imgProps.alt ?? ""}
      draggable={false}
      style={mergedStyle}
    />
  );
}

async function inlineCssUrlsToData(css: string): Promise<string> {
  if (!css) return css;
  const urlMatches = Array.from(css.matchAll(/url\((['"]?)(.*?)\1\)/g));
  if (!urlMatches.length) return css;

  let nextCss = css;
  const cache = new Map<string, string>();

  for (const match of urlMatches) {
    const rawUrl = String(match[2] || "").trim();
    if (!rawUrl || rawUrl.startsWith("data:")) continue;

    const absUrl = rawUrl.startsWith("http")
      ? rawUrl
      : new URL(rawUrl, window.location.href).toString();
    if (!cache.has(absUrl)) {
      try {
        const res = await fetch(absUrl, { mode: "cors", credentials: "omit", cache: "no-store" });
        if (!res.ok) throw new Error(`font fetch failed: ${res.status}`);
        const dataUrl = await blobToDataURL(await res.blob());
        cache.set(absUrl, dataUrl);
      } catch {
        cache.set(absUrl, rawUrl);
      }
    }
    const embedded = cache.get(absUrl) || rawUrl;
    nextCss = nextCss.split(rawUrl).join(embedded);
  }

  return nextCss;
}

async function buildLocalFontEmbedCss(families: string[]): Promise<string> {
  const uniq = Array.from(new Set(families.filter(Boolean)));
  if (!uniq.length) return "";

  const rules: string[] = [];
  const byNormalized = new Map<string, string>(
    Object.keys(FONT_FILE_MAP).map((k) => [normalizeFontFamilyName(k), FONT_FILE_MAP[k]])
  );

  for (const family of uniq) {
    const normalized = normalizeFontFamilyName(family);
    const fallbackAlias = normalized === "birch" ? "brich" : normalized === "brich" ? "birch" : normalized;
    const srcPath = byNormalized.get(normalized) || byNormalized.get(fallbackAlias);
    if (!srcPath) continue;
    // Match the composite face in globals.css in standalone PNG/SVG exports.
    // Brigends' bundled demo uses placeholder artwork for digits/currency.
    const faces = [{ path: srcPath, unicodeRange: "" }];
    if (normalized === normalizeFontFamilyName("Brigends Expanded")) faces.push({
      path: FONT_FILE_MAP["LEMONMILK-Bold"],
      unicodeRange: "U+0023-0026, U+0030-0039, U+003F-0040, U+00A2-00A3, U+00A9, U+20A3-20A4, U+20A7, U+20AC, U+2116",
    });
    for (const face of faces) {
      try {
        const srcUrl = new URL(face.path, window.location.origin).toString();
        const res = await fetch(srcUrl, { credentials: "omit", cache: "no-store" });
        if (!res.ok) continue;
        const dataUrl = await blobToDataURL(await res.blob());
        rules.push(
          `@font-face{font-family:"${family}";src:url("${dataUrl}") format("${guessFontFormat(face.path)}");font-style:normal;font-weight:100 900;font-display:swap;${face.unicodeRange ? `unicode-range:${face.unicodeRange};` : ""}}`
        );
      } catch {
        // best effort
      }
    }
  }

  return rules.join("\n");
}

// ===== CLIENT REMOVE-BG (module scope) =====
function dataURLToBlob(dataURL: string): Blob {
  function blobToDataURL(b: Blob): Promise<string> {
  return new Promise((res) => {
    const fr = new FileReader();
    fr.onload = () => res(String(fr.result));
    fr.readAsDataURL(b);
  });
}

  const [head, b64] = dataURL.split(',');
  const mime = head.match(/data:(.*);base64/)?.[1] || 'image/png';
  const bin = atob(b64);
  const u8 = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return new Blob([u8], { type: mime });
}

/** Sends the image to /api/remove-bg and returns a transparent PNG dataURL */
async function removePortraitBackgroundFromURL(url: string): Promise<string> {
  const blob = url.startsWith('data:')
    ? dataURLToBlob(url)
    : await (await fetch(url, { cache: 'no-store' })).blob();

  const fd = new FormData();
  fd.append('image', blob, 'image.png');

  const r = await fetch('/api/remove-bg', { method: 'POST', body: fd });
  if (!r.ok) throw new Error(await r.text());

  const out = await r.blob();
  return await new Promise<string>((res) => {
    const fr = new FileReader();
    fr.onload = () => res(String(fr.result));
    fr.readAsDataURL(out);
  });
}
