function canonicalizeTemplateTags(tags: string[]): string[] {
  const out = new Set<string>();
  for (const raw of tags || []) {
    const key = String(raw || "").trim().toLowerCase();
    if (!key) continue;
    out.add(TAG_CANONICAL_MAP[key] || raw);
  }
  return Array.from(out);
}

function buildTemplatePreviewSrcSet(preview: string | null | undefined) {
  const src = typeof preview === "string" ? preview : "";
  if (!src.startsWith("/template-previews/900/")) return undefined;
  return `${src.replace("/template-previews/900/", "/template-previews/720/")} 720w, ${src} 900w`;
}

function getGalleryRevealBatchSize() {
  if (typeof window === "undefined") return 4;
  return window.matchMedia("(max-width: 767px)").matches ? 4 : 12;
}

/* ===== TEMPLATE GALLERY (UPDATED) ===== */
/* ===== TEMPLATE GALLERY (LOCAL, SELF-CONTAINED) ===== */
const TemplateGalleryPanel = React.memo(({
  items,
  onApply,
  format,
  isOpen,   // 👈 NEW PROP
  onToggle,  // 👈 NEW PROP
  limitedTemplateNotice,
}: {
  items: TemplateSpec[];
  onApply: (tpl: TemplateSpec, opts?: { targetFormat?: Format }) => void;
  format: Format;
  isOpen?: boolean;
  onToggle?: () => void;
  limitedTemplateNotice?: string;
}) => {
  const INITIAL_VISIBLE_TEMPLATES = 4;
  const [q, setQ] = React.useState('');
  const deferredQ = React.useDeferredValue(q);
  const [searchFocused, setSearchFocused] = React.useState(false);
  const [visibleCount, setVisibleCount] = React.useState(INITIAL_VISIBLE_TEMPLATES);
  const [pendingTemplateId, setPendingTemplateId] = React.useState<string | null>(null);

  const itemsWithTags = React.useMemo(
    () => items.map((t) => ({ ...t, normalizedTags: canonicalizeTemplateTags(t.tags) })),
    [items]
  );

  const searchableTags = React.useMemo(() => {
    const s = new Set<string>();
    itemsWithTags.forEach((t) => t.normalizedTags.forEach((x) => s.add(x)));

    const ordered = TAG_ORDER.filter((x) => s.has(x));
    const extra = Array.from(s).filter((x) => !TAG_ORDER_SET.has(x)).sort();
    return [...ordered, ...extra];
  }, [itemsWithTags]);

  const filtered = React.useMemo(() => {
    const query = deferredQ.trim().toLowerCase();
    return itemsWithTags.filter((t) => {
      if (!query) return true;
      return (
        t.label.toLowerCase().includes(query) ||
        t.normalizedTags.some((x) => x.toLowerCase().includes(query))
      );
    });
  }, [itemsWithTags, deferredQ]);

  const searchSuggestions = React.useMemo(() => {
    const query = q.trim().toLowerCase();
    if (!query) return [];

    const suggestions: Array<{ label: string; kind: "Template" | "Style" }> = [];
    const seen = new Set<string>();
    const addSuggestion = (label: string, kind: "Template" | "Style") => {
      const value = String(label || "").trim();
      const key = value.toLowerCase();
      if (!value || seen.has(key)) return;
      seen.add(key);
      suggestions.push({ label: value, kind });
    };

    itemsWithTags
      .filter((t) => t.label.toLowerCase().includes(query))
      .sort((a, b) => {
        const aStarts = a.label.toLowerCase().startsWith(query) ? 0 : 1;
        const bStarts = b.label.toLowerCase().startsWith(query) ? 0 : 1;
        return aStarts - bStarts || a.label.localeCompare(b.label);
      })
      .slice(0, 5)
      .forEach((t) => addSuggestion(t.label, "Template"));

    searchableTags
      .filter((x) => x.toLowerCase().includes(query))
      .sort((a, b) => {
        const aStarts = a.toLowerCase().startsWith(query) ? 0 : 1;
        const bStarts = b.toLowerCase().startsWith(query) ? 0 : 1;
        return aStarts - bStarts || a.localeCompare(b);
      })
      .slice(0, 4)
      .forEach((x) => addSuggestion(x, "Style"));

    return suggestions.slice(0, 6);
  }, [itemsWithTags, q, searchableTags]);

  React.useEffect(() => {
    setVisibleCount(INITIAL_VISIBLE_TEMPLATES);
  }, [deferredQ, INITIAL_VISIBLE_TEMPLATES]);

  const visible = React.useMemo(
    () => filtered.slice(0, visibleCount),
    [filtered, visibleCount]
  );

  return (
    <Collapsible
      title="Template Gallery"
      storageKey="p:templates"
      isOpen={isOpen}     // 👈 PASS TO COLLAPSIBLE
      onToggle={onToggle} // 👈 PASS TO COLLAPSIBLE
      titleClassName={isOpen ? "text-amber-400" : ""}
      right={
        <div className="relative">
          <input
            type="text"
            placeholder="Search..."
            value={q}
            onChange={(e) => setQ(e.target.value)}
            onFocus={() => setSearchFocused(true)}
            onBlur={() => window.setTimeout(() => setSearchFocused(false), 120)}
            className="px-2 py-1 rounded-md text-xs border border-neutral-700 bg-neutral-900/80"
            style={{ width: 140 }}
          />
          {searchFocused && q.trim() && searchSuggestions.length > 0 && (
            <div className="absolute right-0 top-[calc(100%+6px)] z-50 w-[220px] overflow-hidden rounded-md border border-neutral-700 bg-neutral-950/95 shadow-[0_16px_40px_rgba(0,0,0,0.45)]">
              {searchSuggestions.map((suggestion) => (
                <button
                  key={`${suggestion.kind}-${suggestion.label}`}
                  type="button"
                  onMouseDown={(event) => {
                    event.preventDefault();
                    setQ(suggestion.label);
                    setSearchFocused(false);
                  }}
                  className="flex w-full items-center justify-between gap-3 px-3 py-2 text-left text-[12px] text-neutral-100 hover:bg-white/10"
                >
                  <span className="min-w-0 truncate">{suggestion.label}</span>
                  <span className="shrink-0 text-[9px] uppercase tracking-[0.12em] text-neutral-500">
                    {suggestion.kind}
                  </span>
                </button>
              ))}
            </div>
          )}
        </div>
      }
    >
      {limitedTemplateNotice && (
        <div className="mb-3 rounded-lg border border-cyan-300/20 bg-cyan-300/[0.07] px-3 py-2 text-[11px] leading-5 text-cyan-50/80">
          {limitedTemplateNotice}
        </div>
      )}

      <div className="grid grid-cols-2 gap-3">
        {visible.map(t => (
          <div
            key={t.id}
            className="rounded-lg overflow-hidden border border-neutral-700 bg-neutral-900/60"
          >
            <div className="relative">
              <img
                src={t.preview}
                alt={t.label}
                className="w-full h-[120px] object-cover block"
                width={360}
                height={360}
                loading="lazy"
                decoding="async"
                srcSet={buildTemplatePreviewSrcSet(t.preview)}
                sizes="(max-width: 767px) 45vw, 180px"
                fetchPriority="low"
                draggable={false}
              />
            </div>

            <div className="p-2 flex items-center justify-between gap-2">
              <div className="text-[12px] font-semibold">{t.label}</div>
              <button
                type="button"
                className="text-[12px] px-2 py-1 rounded-md border border-indigo-400/40 bg-indigo-600/20 hover:bg-indigo-600/30 focus-ring"
                disabled={pendingTemplateId === t.id}
                onClick={() => {
                  flushSync(() => {
                    setPendingTemplateId(t.id);
                  });
                  runAfterPaintAndYield(() => {
                    try {
                      onApply(t, { targetFormat: format });
                    } finally {
                      setPendingTemplateId(null);
                    }
                  });
                }}
              >
                {pendingTemplateId === t.id ? "Applying..." : "Apply"}
              </button>
            </div>
          </div>
        ))}
      </div>
      {filtered.length > visibleCount && (
        <div className="mt-3 grid place-items-center">
          <button
            type="button"
            className="rounded-lg border border-amber-300/25 bg-amber-300/10 px-3 py-1 text-xs text-amber-100 hover:bg-amber-300/15"
            onClick={() =>
              setVisibleCount((current) =>
                Math.min(filtered.length, current + getGalleryRevealBatchSize())
              )
            }
          >
            <span className="inline-flex items-center gap-1 animate-pulse [animation-duration:4.2s] [animation-timing-function:ease-in-out]">
              View more templates
              <span aria-hidden="true">↓</span>
            </span>
          </button>
        </div>
      )}
    </Collapsible>
  );
});
TemplateGalleryPanel.displayName = 'TemplateGalleryPanel';

const BackgroundGalleryPanel = React.memo(({
  items,
  onApply,
  isOpen,
  onToggle,
}: {
  items: ReadonlyArray<{
    id: string;
    name: string;
    src: string;
  }>;
  onApply: (src: string) => void;
  isOpen?: boolean;
  onToggle?: () => void;
}) => {
  const INITIAL_VISIBLE_BACKGROUNDS = 4;
  const [visibleCount, setVisibleCount] = React.useState(INITIAL_VISIBLE_BACKGROUNDS);
  const [pendingBackgroundId, setPendingBackgroundId] = React.useState<string | null>(null);
  const visible = React.useMemo(
    () => items.slice(0, visibleCount),
    [items, visibleCount]
  );

  React.useEffect(() => {
    setVisibleCount(INITIAL_VISIBLE_BACKGROUNDS);
  }, [items]);

  return (
    <Collapsible
      title="Backgrounds"
      storageKey="p:dj-backgrounds"
      isOpen={isOpen}
      onToggle={onToggle}
      titleClassName={isOpen ? "text-amber-400" : ""}
    >
      <div className="grid grid-cols-2 gap-3">
        {visible.map((background) => (
          <div
            key={background.id}
            className="overflow-hidden rounded-lg border border-neutral-700 bg-neutral-900/60"
          >
            <img
              src={background.src}
              alt={background.name}
              className="block h-[120px] w-full object-cover"
              width={360}
              height={360}
              loading="lazy"
              decoding="async"
              fetchPriority="low"
              draggable={false}
            />
            <div className="flex items-center justify-between gap-2 p-2">
              <div className="text-[12px] font-semibold">{background.name}</div>
              <button
                type="button"
                className="rounded-md border border-indigo-400/40 bg-indigo-600/20 px-2 py-1 text-[12px] hover:bg-indigo-600/30 focus-ring"
                disabled={pendingBackgroundId === background.id}
                onClick={() => {
                  flushSync(() => {
                    setPendingBackgroundId(background.id);
                  });
                  runAfterPaintAndYield(() => {
                    try {
                      onApply(background.src);
                    } finally {
                      setPendingBackgroundId(null);
                    }
                  });
                }}
              >
                {pendingBackgroundId === background.id ? "Applying..." : "Apply"}
              </button>
            </div>
          </div>
        ))}
      </div>
      {items.length > visibleCount && (
        <div className="mt-3 grid place-items-center">
          <button
            type="button"
            className="rounded-lg border border-amber-300/25 bg-amber-300/10 px-3 py-1 text-xs text-amber-100 hover:bg-amber-300/15"
            onClick={() =>
              setVisibleCount((current) =>
                Math.min(items.length, current + getGalleryRevealBatchSize())
              )
            }
          >
            <span className="inline-flex items-center gap-1 animate-pulse [animation-duration:4.2s] [animation-timing-function:ease-in-out]">
              View more backgrounds
              <span aria-hidden="true">↓</span>
            </span>
          </button>
        </div>
      )}
    </Collapsible>
  );
});
BackgroundGalleryPanel.displayName = 'BackgroundGalleryPanel';


type Align = 'left' | 'center' | 'right';
type TextSide = 'left' | 'right';
type GenStyle = 'urban' | 'neon' | 'vintage' | 'tropical';



// add this near your other types
type Palette = {
  bgFrom: string;
  bgTo: string;
  primary?: string;
  secondary?: string;
  accent?: string;
  neutral?: string;
};
type PaletteRole = "base" | "primary" | "secondary" | "accent" | "neutral";
type MobileBgFloatPage = "adjust" | "layout" | "palette";
type GeneratedSceneBuilderPaletteOption = {
  id: string;
  label: string;
  palette: Palette;
};

type GeneratedSceneBuilderPaletteCycle = {
  key: string;
  palettes: GeneratedSceneBuilderPaletteOption[];
  index: number;
};

function resolveMobileBgFloatPalette(source?: Partial<Palette> | null): Palette {
  const base = normalizePaletteHexString(
    String(source?.secondary || source?.bgFrom || "#101015"),
    "#101015"
  );
  const primary = normalizePaletteHexString(
    String(source?.primary || source?.bgTo || "#F3DFC1"),
    "#F3DFC1"
  );
  return {
    bgFrom: base,
    bgTo: normalizePaletteHexString(String(source?.bgTo || darken(base, 0.35)), darken(base, 0.35)),
    secondary: base,
    primary,
    accent: normalizePaletteHexString(String(source?.accent || "#D21F3C"), "#D21F3C"),
    neutral: normalizePaletteHexString(String(source?.neutral || lighten(primary, 0.45)), lighten(primary, 0.45)),
  };
}

function pickSeparatedMobileBgHue(avoid: number[], candidates: number[]) {
  return candidates
    .map((hue) => ({
      hue: ((hue % 360) + 360) % 360,
      score: avoid.reduce((sum, current) => sum + hueDistance(hue, current), 0),
    }))
    .sort((a, b) => b.score - a.score)[0]?.hue ?? candidates[0] ?? 250;
}

function paletteHexFromPercentHsl(h: number, s: number, l: number) {
  return paletteHexFromHsl(h, Math.max(0, Math.min(100, s)) / 100, Math.max(0, Math.min(100, l)) / 100);
}

const GENERATED_SCENE_BUILDER_PALETTE_RECIPES = [
  { id: "image-echo", label: "Image Echo", rotation: 0, luxury: 32, energy: 165, bgS: 58, luxuryS: 54, bgL: 8, luxuryL: 76, energyL: 60 },
  { id: "analog-glow", label: "Analog Glow", rotation: -30, luxury: 28, energy: -120, bgS: 54, luxuryS: 46, bgL: 7, luxuryL: 80, energyL: 62 },
  { id: "electric-opposite", label: "Electric Opposite", rotation: 30, luxury: -24, energy: 180, bgS: 64, luxuryS: 38, bgL: 8, luxuryL: 84, energyL: 58 },
  { id: "split-warm", label: "Split Warm", rotation: 72, luxury: 36, energy: 150, bgS: 62, luxuryS: 60, bgL: 9, luxuryL: 74, energyL: 60 },
  { id: "split-cool", label: "Split Cool", rotation: 114, luxury: -36, energy: 210, bgS: 66, luxuryS: 44, bgL: 7, luxuryL: 80, energyL: 60 },
  { id: "triad-pulse", label: "Triad Pulse", rotation: 162, luxury: 120, energy: 240, bgS: 60, luxuryS: 64, bgL: 8, luxuryL: 72, energyL: 62 },
  { id: "jewel-shift", label: "Jewel Shift", rotation: 222, luxury: 42, energy: 162, bgS: 68, luxuryS: 58, bgL: 8, luxuryL: 76, energyL: 58 },
  { id: "aurora-shift", label: "Aurora Shift", rotation: 294, luxury: -30, energy: 210, bgS: 64, luxuryS: 50, bgL: 7, luxuryL: 82, energyL: 61 },
] as const;

function liftGeneratedPaletteColor(
  hue: number,
  saturation: number,
  initialLightness: number,
  background: string,
  minimumContrast: number
) {
  const lightnessSteps = Array.from(
    new Set([
      initialLightness,
      ...[68, 72, 76, 82, 88, 94, 97].filter(
        (lightness) => lightness > initialLightness
      ),
    ])
  );
  for (const lightness of lightnessSteps) {
    const candidate = paletteHexFromPercentHsl(hue, saturation, lightness);
    if (contrastRatio(candidate, background) >= minimumContrast) return candidate;
  }
  return "#FFFFFF";
}

function buildGeneratedSceneBuilderPaletteCycle(
  source?: Partial<Palette> | null
): GeneratedSceneBuilderPaletteOption[] {
  const scenePalette = resolveMobileBgFloatPalette(source);
  const baseHsl = rgbToHslForTemplatePalette(hexToRgb(scenePalette.secondary));
  const accentHsl = rgbToHslForTemplatePalette(hexToRgb(scenePalette.accent));
  const primaryHsl = rgbToHslForTemplatePalette(hexToRgb(scenePalette.primary));
  const anchorHue =
    baseHsl.s >= 0.12
      ? baseHsl.h
      : accentHsl.s >= 0.2
      ? accentHsl.h
      : primaryHsl.s >= 0.2
      ? primaryHsl.h
      : 252;
  const sourceBaseSaturation = Math.min(76, Math.max(0, baseHsl.s * 100));

  return GENERATED_SCENE_BUILDER_PALETTE_RECIPES.map((recipe) => {
    const atmosphereHue = normalizeHueDegrees(anchorHue + recipe.rotation);
    const luxuryHue = normalizeHueDegrees(atmosphereHue + recipe.luxury);
    const energyHue = normalizeHueDegrees(atmosphereHue + recipe.energy);
    const baseSaturation = Math.min(76, Math.max(recipe.bgS, sourceBaseSaturation + 12));
    const base = paletteHexFromPercentHsl(atmosphereHue, baseSaturation, recipe.bgL);
    const shadow = paletteHexFromPercentHsl(
      atmosphereHue + 8,
      Math.min(82, baseSaturation + 8),
      recipe.bgL <= 7 ? 3 : 4
    );
    const primary = liftGeneratedPaletteColor(
      luxuryHue,
      recipe.luxuryS,
      recipe.luxuryL,
      base,
      4.5
    );
    const neutral = liftGeneratedPaletteColor(luxuryHue, 16, 94, base, 6.2);
    const accent = liftGeneratedPaletteColor(energyHue, 94, recipe.energyL, base, 4.5);

    return {
      id: recipe.id,
      label: recipe.label,
      palette: {
        bgFrom: base,
        bgTo: shadow,
        secondary: base,
        primary,
        neutral,
        accent,
      },
    };
  });
}

function generatedSceneBuilderPaletteCycleKey(
  templateId: string,
  format: Format,
  source: string
) {
  return `${templateId || "template"}:${format}:${stablePreloadHash(source)}`;
}

function buildMobileBgFloatRecommendedPalettes(source?: Partial<Palette> | null) {
  const scenePalette = resolveMobileBgFloatPalette(source);
  const baseHsl = rgbToHslForTemplatePalette(hexToRgb(scenePalette.secondary));
  const primaryHsl = rgbToHslForTemplatePalette(hexToRgb(scenePalette.primary));
  const baseSat = baseHsl.s * 100;
  const primarySat = primaryHsl.s * 100;
  const warmHue = baseSat < 12 ? 330 : baseHsl.h;
  const luxuryHue = primarySat > 18 ? primaryHsl.h : 43;
  const coolHue = (warmHue + 190) % 360;
  const warmEnergyHue = pickSeparatedMobileBgHue(
    [warmHue, luxuryHue],
    [(warmHue + 165) % 360, 250, 196, 344]
  );
  const coolEnergyHue = pickSeparatedMobileBgHue(
    [coolHue, warmEnergyHue, luxuryHue],
    [344, 196, 250, 31]
  );

  const warmBase = paletteHexFromPercentHsl(warmHue, Math.max(baseSat + 16, 42), 8);
  const warmShadow = paletteHexFromPercentHsl(warmHue, Math.max(baseSat + 20, 48), 4);
  const warmLuxury = paletteHexFromPercentHsl(luxuryHue, Math.max(primarySat + 20, 68), 70);
  const coolBase = paletteHexFromPercentHsl(coolHue, 58, 7);
  const coolShadow = paletteHexFromPercentHsl(coolHue, 64, 3);

  return [
    {
      id: "warm-luxury-energy",
      label: "Warm Luxury",
      palette: {
        ...scenePalette,
        bgFrom: warmBase,
        bgTo: warmShadow,
        secondary: warmBase,
        primary: warmLuxury,
        neutral: paletteHexFromPercentHsl(luxuryHue, 34, 93),
        accent: paletteHexFromPercentHsl(warmEnergyHue, 92, 58),
      },
    },
    {
      id: "cool-electric-contrast",
      label: "Cool Electric",
      palette: {
        ...scenePalette,
        bgFrom: coolBase,
        bgTo: coolShadow,
        secondary: coolBase,
        primary: paletteHexFromPercentHsl(coolHue, 20, 94),
        neutral: paletteHexFromPercentHsl(coolHue, 18, 88),
        accent: paletteHexFromPercentHsl(coolEnergyHue, 94, 60),
      },
    },
  ];
}

function normalizeGlassGlowColor(value: string, fallback: string) {
  const normalized = normalizePaletteHexString(value, fallback);
  const hsl = rgbToHslForTemplatePalette(hexToRgb(normalized));
  const isWashedWarm = hsl.l > 0.62 && hsl.h >= 28 && hsl.h <= 74;
  const isFlatNeutral = hsl.s < 0.08 && hsl.l > 0.72;
  return isWashedWarm || isFlatNeutral ? fallback : normalized;
}

function resolveGlassPaletteColors(source: Partial<Palette> | null | undefined) {
  const paletteSource = source || {};
  const primary = normalizeGlassGlowColor(
    String(paletteSource.primary || paletteSource.accent || paletteSource.bgTo || HEADLINE_GLASS_DEFAULTS.primaryColor),
    HEADLINE_GLASS_DEFAULTS.primaryColor
  );
  let secondary = normalizeGlassGlowColor(
    String(paletteSource.accent || paletteSource.neutral || paletteSource.primary || HEADLINE_GLASS_DEFAULTS.secondaryColor),
    HEADLINE_GLASS_DEFAULTS.secondaryColor
  );
  if (rgbDistance(hexToRgb(primary), hexToRgb(secondary)) < 34) {
    secondary = normalizeGlassGlowColor(
      String(paletteSource.bgTo || paletteSource.secondary || HEADLINE_GLASS_DEFAULTS.secondaryColor),
      HEADLINE_GLASS_DEFAULTS.secondaryColor
    );
  }
  const neutral = normalizePaletteHexString(String(paletteSource.neutral || ""), "");
  const neutralHsl = neutral ? rgbToHslForTemplatePalette(hexToRgb(neutral)) : null;
  const neutralIsCoolLight =
    !!neutral &&
    luminanceOfRgb(hexToRgb(neutral)) > 145 &&
    (!neutralHsl || neutralHsl.s < 0.08 || (neutralHsl.h >= 155 && neutralHsl.h <= 300));
  const highlightColor = neutralIsCoolLight ? neutral : HEADLINE_GLASS_DEFAULTS.highlightColor;

  return {
    primaryColor: primary,
    secondaryColor: secondary,
    highlightColor,
    edgeColor: primary,
  };
}

function resolveKineticPaletteColors(source: Partial<Palette> | null | undefined) {
  return resolveKineticPaletteColorsFromPreset(source, {
    normalizePaletteHexString,
    normalizeGlassGlowColor,
    hexToRgb,
    rgbDistance,
  });
}

function resolvePure3dPaletteColors(source: Partial<Palette> | null | undefined) {
  return resolveFlat3dPaletteColors(source, {
    normalizePaletteHexString,
    normalizeGlassGlowColor,
    darkenHex,
    lightenHex,
  });
}

function resolveGoldBlockPaletteColors(source: Partial<Palette> | null | undefined) {
  return resolveGoldBlockPaletteColorsFromPreset(source, {
    normalizePaletteHexString,
    darkenHex,
    lightenHex,
  });
}

function resolveQuantumPaletteColors(source: Partial<Palette> | null | undefined) {
  const paletteSource = source || {};
  return {
    cyanColor: normalizeGlassGlowColor(
      String(paletteSource.accent || paletteSource.primary || HEADLINE_QUANTUM_DEFAULTS.cyanColor),
      HEADLINE_QUANTUM_DEFAULTS.cyanColor
    ),
    blueColor: normalizeGlassGlowColor(
      String(paletteSource.primary || paletteSource.bgTo || HEADLINE_QUANTUM_DEFAULTS.blueColor),
      HEADLINE_QUANTUM_DEFAULTS.blueColor
    ),
    highlightColor: normalizePaletteHexString(
      String((paletteSource as any).highlight || paletteSource.neutral || HEADLINE_QUANTUM_DEFAULTS.highlightColor),
      HEADLINE_QUANTUM_DEFAULTS.highlightColor
    ),
    purpleColor: normalizeGlassGlowColor(
      String(paletteSource.secondary || paletteSource.bgTo || HEADLINE_QUANTUM_DEFAULTS.purpleColor),
      HEADLINE_QUANTUM_DEFAULTS.purpleColor
    ),
    magentaColor: normalizeGlassGlowColor(
      String(paletteSource.accent || HEADLINE_QUANTUM_DEFAULTS.magentaColor),
      HEADLINE_QUANTUM_DEFAULTS.magentaColor
    ),
  };
}

function resolveDashStrokePaletteColors(source: Partial<Palette> | null | undefined) {
  return resolveStrokePaletteColorsFromPreset(source, {
    normalizeGlassGlowColor,
  });
}

function resolveRetroEngravedPaletteColors(source: Partial<Palette> | null | undefined) {
  const paletteSource = source || {};
  const faceColor = normalizePaletteHexString(
    String(paletteSource.primary || paletteSource.accent || paletteSource.bgTo || HEADLINE_RETRO_ENGRAVED_DEFAULTS.faceColor),
    HEADLINE_RETRO_ENGRAVED_DEFAULTS.faceColor
  );
  const raisedColor = normalizePaletteHexString(
    String(paletteSource.neutral || paletteSource.bgFrom || HEADLINE_RETRO_ENGRAVED_DEFAULTS.paperColor),
    HEADLINE_RETRO_ENGRAVED_DEFAULTS.paperColor
  );
  let shadowColor = normalizePaletteHexString(
    String(paletteSource.bgTo || paletteSource.secondary || paletteSource.primary || HEADLINE_RETRO_ENGRAVED_DEFAULTS.faceColor),
    HEADLINE_RETRO_ENGRAVED_DEFAULTS.faceColor
  );
  if (rgbDistance(hexToRgb(faceColor), hexToRgb(shadowColor)) < 28) {
    shadowColor = darkenHex(faceColor, 28);
  }

  return {
    faceColor,
    raisedColor,
    borderColor: shadowColor,
    shadowColor,
  };
}

function hueFromPaletteColor(hex: string | undefined | null) {
  const normalized = normalizePaletteHexString(String(hex || ""), "");
  if (!normalized) return null;
  const hsl = rgbToHslForTemplatePalette(hexToRgb(normalized));
  if (hsl.s < 0.06) return null;
  return hsl.h;
}

function normalizeHueDegrees(value: number) {
  return ((value % 360) + 360) % 360;
}

function toSignedHueDegrees(value: number) {
  const normalized = normalizeHueDegrees(value);
  return normalized > 180 ? normalized - 360 : normalized;
}

function resolveBackgroundSourceHue(src: string | null | undefined) {
  const source = String(src || "").toLowerCase();
  if (/(edm_tunnel|fire|flame|pyro|co2|stage)/.test(source)) return 24;
  return 0;
}

function resolveBackgroundTreatmentHue(src: string | null | undefined, palette: Palette) {
  const hues = [
    hueFromPaletteColor(palette.secondary),
    hueFromPaletteColor(palette.bgFrom),
    hueFromPaletteColor(palette.bgTo),
    hueFromPaletteColor(palette.primary),
    hueFromPaletteColor(palette.accent),
  ].filter((hue): hue is number => typeof hue === "number" && Number.isFinite(hue));

  if (hues.length) return hues[0];

  const source = String(src || "").toLowerCase();
  if (/(edm_tunnel|fire|flame|pyro|co2|stage)/.test(source)) return 24;

  return 220;
}

// hue-rotate() applies to the whole uploaded photo, including any person in
// it, with no subject/skin masking. resolveBackgroundSourceHue() can't
// actually measure a photo's real dominant hue (it only pattern-matches a
// few filenames), so the "delta" below is effectively the palette's raw hue.
// Un-clamped, this can rotate the full color wheel and turn skin tones and
// backgrounds into unrelated colors. Clamping keeps the mood nudge subtle
// enough to never invert a photo's real colors.
const MAX_PALETTE_HUE_ROTATION_DEG = 20;

function paletteHueToSliderValue(palette: Palette, src: string | null | undefined) {
  const targetHue = resolveBackgroundTreatmentHue("", palette);
  const sourceHue = resolveBackgroundSourceHue(src);
  const rawHue = toSignedHueDegrees(targetHue - sourceHue);
  const clampedHue = Math.max(
    -MAX_PALETTE_HUE_ROTATION_DEG,
    Math.min(MAX_PALETTE_HUE_ROTATION_DEG, rawHue)
  );
  return Math.round(clampedHue);
}

function optionalPaletteHex(value: unknown) {
  return normalizePaletteHexString(String(value || ""), "") || undefined;
}

function resolveOriginalTemplatePalette(source: Partial<Palette>, variant?: any): Palette {
  const primary =
    optionalPaletteHex(source.primary) ??
    optionalPaletteHex(variant?.textFx?.color) ??
    optionalPaletteHex(variant?.headColor) ??
    optionalPaletteHex(variant?.details2Color) ??
    "#F3DFC1";
  const secondary =
    optionalPaletteHex(source.secondary) ??
    optionalPaletteHex(source.bgFrom) ??
    optionalPaletteHex(variant?.subtagBgColor) ??
    optionalPaletteHex(variant?.headExtrudeColor) ??
    "#0B0B0D";
  const accent =
    optionalPaletteHex(source.accent) ??
    optionalPaletteHex(variant?.details2Color) ??
    optionalPaletteHex(variant?.head2Fx?.color) ??
    optionalPaletteHex(variant?.head2Color) ??
    primary;
  const neutral =
    optionalPaletteHex(source.neutral) ??
    optionalPaletteHex(variant?.bodyColor) ??
    optionalPaletteHex(variant?.venueColor) ??
    primary;
  const bgFrom = optionalPaletteHex(source.bgFrom) ?? secondary;
  const bgTo =
    optionalPaletteHex(source.bgTo) ??
    optionalPaletteHex(variant?.headExtrudeColor) ??
    "#121216";

  return {
    bgFrom,
    bgTo,
    primary,
    secondary,
    accent,
    neutral,
  };
}

function cloneTemplateAssetSessionList<T extends { id?: unknown }>(
  items: readonly T[] | undefined
) {
  return Array.isArray(items)
    ? items
        .filter((item) => !isRemovedTemplateAsset(item))
        .map((item) => normalizeRuntimeAssetRecord({ ...item }))
    : undefined;
}

function cloneTemplateSessionVariant(source: Partial<TemplateBase> | undefined): Partial<TemplateBase> {
  const base = source ?? {};
  return {
    ...base,
    palette: base.palette ? { ...base.palette } : undefined,
    textFx: base.textFx ? { ...base.textFx } : undefined,
    head2Fx: base.head2Fx ? { ...base.head2Fx } : undefined,
    textLayerOffset: base.textLayerOffset ? { ...base.textLayerOffset } : undefined,
    subjectVisibleRect: base.subjectVisibleRect ? { ...base.subjectVisibleRect } : undefined,
    subjectSideVisibleRect: base.subjectSideVisibleRect ? { ...base.subjectSideVisibleRect } : undefined,
    subjectFaceRect: base.subjectFaceRect ? { ...base.subjectFaceRect } : undefined,
    subjectSideFaceRect: base.subjectSideFaceRect ? { ...base.subjectSideFaceRect } : undefined,
    cocoCompositionMap: base.cocoCompositionMap,
    cocoCompositionSystem: (base as any).cocoCompositionSystem,
    cocoRenderPlan: (base as any).cocoRenderPlan,
    cocoTypographyStack: (base as any).cocoTypographyStack,
    cocoTextReferenceTemplateId: base.cocoTextReferenceTemplateId,
    cocoTextReferenceScore: base.cocoTextReferenceScore,
    mainTitleRect: base.mainTitleRect ? { ...base.mainTitleRect } : undefined,
    ghostTitleRect: base.ghostTitleRect ? { ...base.ghostTitleRect } : undefined,
    scriptRect: base.scriptRect ? { ...base.scriptRect } : undefined,
    leftMetaRect: base.leftMetaRect ? { ...base.leftMetaRect } : undefined,
    rightMetaRect: base.rightMetaRect ? { ...base.rightMetaRect } : undefined,
    priceRect: base.priceRect ? { ...base.priceRect } : undefined,
    footerRect: base.footerRect ? { ...base.footerRect } : undefined,
    textZones: base.textZones
      ? Object.fromEntries(
          Object.entries(base.textZones).map(([key, zone]) => [key, { ...zone }])
        )
      : undefined,
    emojiList: cloneTemplateAssetSessionList(base.emojiList),
    emojis: cloneTemplateAssetSessionList(base.emojis),
  };
}

type TextFx = {
  skewAxis?: "x" | "y"; // Missing in older saves: preserve their horizontal shear.
  compiledGradientEdited?: boolean;
  uppercase: boolean;
  bold: boolean;
  italic: boolean;
  underline: boolean;
  alpha: number;
  tracking: number;
  texture?: string;


  // headline fill & gradient
  gradient: boolean;   // when true, gradient overrides fill color
  gradFrom: string;
  gradMid?: string;
  gradTo: string;
  color: string;       // <— NEW: solid fill color when gradient is OFF

  // outline & effects
  strokeWidth: number;
  strokeColor: string;
  shadow: number;
  glow: number;
  glowColor?: string;
  shadowColor?: string;
  shadowBlur?: number;
  shadowOffsetX?: number;
  shadowOffsetY?: number;

  // NEW: enable/disable the drop shadow completely
  shadowEnabled: boolean;   // <— ADD THIS LINE
};

type GlitchNoiseBlock = {
  topPct: number;
  leftPct: number;
  widthPct: number;
  heightPct: number;
  offsetX: number;
  offsetY: number;
  opacity: number;
};

type HalftoneHeadlineSvgProps = {
  text: string;
  align: Align;
  fontFamily: string;
  fontSize: number;
  lineHeight: number;
  letterSpacingEm: number;
  fontStyle?: React.CSSProperties["fontStyle"];
  color: string;
  accentColor: string;
  shadowColor: string;
  shadowOffsetX: number;
  shadowOffsetY: number;
  depthLayers?: number;
  depthStepX?: number;
  depthStepY?: number;
  alpha: number;
  dotSpacing?: number;
  maxDot?: number;
  minDot?: number;
  minDotScale?: number;
  maxDotScale?: number;
  fadeTop?: number;
  fadeBottom?: number;
  strokeWidth?: number;
  strokeColor?: string;
  shadowBlur?: number;
  glow?: number;
  glowColor?: string;
  highlightColor?: string;
  highlightOffset?: number;
  blendMode?: string;
  effectFilter?: string;
  hitTest?: boolean;
  onBoundsChange?: (bounds: { width: number; height: number }) => void;
};

function escapeSvgAttr(value: string) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function svgBackgroundImage(svg: string) {
  return `url("data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}")`;
}

function clampFiniteNumber(value: unknown, fallback: number, min: number, max: number) {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.max(min, Math.min(max, n));
}

let headlinePaintMeasureCanvas: HTMLCanvasElement | null = null;

function getHeadlinePaintMeasureContext() {
  if (typeof document === "undefined") return null;
  if (!headlinePaintMeasureCanvas) {
    headlinePaintMeasureCanvas = document.createElement("canvas");
  }
  return headlinePaintMeasureCanvas.getContext("2d");
}

function buildHeadlineMeasureFont(
  fontStyle: React.CSSProperties["fontStyle"],
  fontWeight: number | string,
  fontSize: number,
  fontFamily: string
) {
  const family = String(fontFamily || "LEMONMILK-Bold")
    .split(",")
    .map((part) => {
      const name = part.trim().replace(/^['"]|['"]$/g, "");
      return name.includes(" ") ? `"${name.replaceAll('"', "")}"` : name;
    })
    .join(", ");
  return `${fontStyle || "normal"} ${fontWeight || 900} ${fontSize}px ${family}`;
}

function estimateHeadlineInlineGlyphBleed({
  fontSize,
  italic,
}: {
  fontSize: number;
  italic: boolean;
}) {
  const safeFontSize = Math.max(1, Number(fontSize) || 72);
  return Math.ceil(italic ? safeFontSize * 0.14 : safeFontSize * 0.025);
}

function measureHeadlineInlineGlyphBleed({
  text,
  fontFamily,
  fontSize,
  fontWeight,
  fontStyle,
  letterSpacingEm,
}: {
  text: string;
  fontFamily: string;
  fontSize: number;
  fontWeight: number | string;
  fontStyle: React.CSSProperties["fontStyle"];
  letterSpacingEm: number;
}) {
  const safeFontSize = Math.max(1, Number(fontSize) || 72);
  const fallback = estimateHeadlineInlineGlyphBleed({
    fontSize: safeFontSize,
    italic: fontStyle === "italic",
  });
  const ctx = getHeadlinePaintMeasureContext();
  if (!ctx) return fallback;

  ctx.font = buildHeadlineMeasureFont(fontStyle, fontWeight, safeFontSize, fontFamily);
  const trackingPx = (Number.isFinite(letterSpacingEm) ? letterSpacingEm : 0) * safeFontSize;
  const lines = String(text || "").split("\n");
  let leftBleed = 0;
  let rightBleed = 0;

  lines.forEach((line) => {
    const chars = Array.from(line || " ");
    let cursor = 0;
    let minX = 0;
    let maxX = 0;

    chars.forEach((char, index) => {
      const metrics = ctx.measureText(char || " ");
      const advance = Number.isFinite(metrics.width) ? metrics.width : 0;
      const glyphLeft =
        cursor - (Number.isFinite(metrics.actualBoundingBoxLeft) ? metrics.actualBoundingBoxLeft : 0);
      const glyphRight =
        cursor +
        (Number.isFinite(metrics.actualBoundingBoxRight)
          ? metrics.actualBoundingBoxRight
          : advance);
      minX = Math.min(minX, glyphLeft);
      maxX = Math.max(maxX, glyphRight);
      cursor += advance + (index < chars.length - 1 ? trackingPx : 0);
    });

    leftBleed = Math.max(leftBleed, Math.max(0, -minX));
    rightBleed = Math.max(rightBleed, Math.max(0, maxX - cursor));
  });

  return Math.ceil(Math.max(fallback, leftBleed, rightBleed));
}

function measureHalftoneHeadlineBounds({
  text,
  fontSize,
  lineHeight,
  letterSpacingEm,
}: {
  text: string;
  fontSize: number;
  lineHeight: number;
  letterSpacingEm: number;
}) {
  const safeText = String(text || "").trim() ? String(text) : "HEADLINE";
  const lines = safeText.split("\n");
  const safeFontSize = Math.max(8, Number(fontSize) || 72);
  const rawLineHeight = Number(lineHeight);
  const safeLineHeight = Math.max(
    0,
    Math.min(1.4, Number.isFinite(rawLineHeight) ? rawLineHeight : 0.84)
  );
  const letterSpacing = Number.isFinite(letterSpacingEm) ? letterSpacingEm : -0.075;
  const letterSpacingPx = letterSpacing * safeFontSize;
  const lineStep = safeFontSize * safeLineHeight;
  const lineCount = Math.max(1, lines.length);
  const textBlockHeight =
    safeFontSize + Math.max(0, lineCount - 1) * safeFontSize * safeLineHeight;
  const visualPad = Math.max(8, Math.min(18, safeFontSize * 0.055));
  const estimatedLineWidth = (line: string) => {
    const count = Math.max(1, line.length);
    const base = count * safeFontSize * 0.9;
    const tracking = letterSpacingPx * Math.max(0, count - 1);
    return Math.max(safeFontSize, base + tracking);
  };
  const textWidth = Math.max(...lines.map(estimatedLineWidth));

  return {
    lines,
    safeFontSize,
    safeLineHeight,
    letterSpacing,
    lineStep,
    textBlockHeight,
    textWidth,
    visualPad,
    width: Math.ceil(textWidth + visualPad * 2),
    height: Math.ceil(textBlockHeight + visualPad * 2),
  };
}

const HalftoneHeadlineSvg = React.memo(function HalftoneHeadlineSvg({
  text,
  align,
  fontFamily,
  fontSize,
  lineHeight,
  letterSpacingEm,
  fontStyle = "normal",
  color,
  accentColor,
  shadowColor,
  shadowOffsetX,
  shadowOffsetY,
  depthLayers = 0,
  depthStepX = 0,
  depthStepY = 0,
  alpha,
  dotSpacing = HEADLINE_HALFTONE_DEFAULTS.dotSpacing,
  maxDot = 7.8,
  minDot = 1.2,
  minDotScale = HEADLINE_HALFTONE_DEFAULTS.minDotScale,
  maxDotScale = HEADLINE_HALFTONE_DEFAULTS.maxDotScale,
  fadeTop = HEADLINE_HALFTONE_DEFAULTS.fadeTop,
  fadeBottom = HEADLINE_HALFTONE_DEFAULTS.fadeBottom,
  strokeWidth = 0,
  strokeColor = "#ffffff",
  shadowBlur = 0,
  glow = 0,
  glowColor = "transparent",
  highlightColor = "transparent",
  highlightOffset = 0,
  blendMode = "source-over",
  effectFilter = "none",
  hitTest = false,
  onBoundsChange,
}: HalftoneHeadlineSvgProps) {
  const measureTextRef = React.useRef<SVGTextElement | null>(null);
  const measureFrameRef = React.useRef<number | null>(null);
  const [measuredTextBounds, setMeasuredTextBounds] = React.useState<{
    key: string;
    anchorX: number;
    x: number;
    y: number;
    width: number;
    height: number;
  } | null>(null);
  const reactId = React.useId().replace(/:/g, "");
  const maskId = `halftone-text-mask-${reactId}`;
  const gradientId = `halftone-text-gradient-${reactId}`;
  const shadowFilterId = `halftone-shadow-${reactId}`;
  const glowFilterId = `halftone-glow-${reactId}`;
  const measureKey = [
    text,
    fontFamily,
    fontSize,
    lineHeight,
    letterSpacingEm,
    fontStyle,
    align,
  ].join("|");
  const {
    lines,
    safeFontSize,
    letterSpacing,
    lineStep,
    textBlockHeight,
    textWidth,
    visualPad,
  } = measureHalftoneHeadlineBounds({
    text,
    fontSize,
    lineHeight,
    letterSpacingEm,
  });
  const activeTextBounds = measuredTextBounds?.key === measureKey ? measuredTextBounds : null;
  const width = Math.ceil((activeTextBounds?.width ?? textWidth) + visualPad * 2);
  const height = Math.ceil((activeTextBounds?.height ?? textBlockHeight) + visualPad * 2);
  const viewBoxX = activeTextBounds ? activeTextBounds.x - visualPad : 0;
  const viewBoxY = activeTextBounds ? activeTextBounds.y - visualPad : 0;
  const safeMinDot = clampFiniteNumber(minDot, 1.2, 0, 14);
  const safeMaxDot = Math.max(safeMinDot, Math.min(14, Number(maxDot) || 7.8));
  const fallbackTextX = align === "left" ? 0 : align === "right" ? width : width / 2;
  const textX = activeTextBounds?.anchorX ?? fallbackTextX;
  const textAnchor = align === "left" ? "start" : align === "right" ? "end" : "middle";
  const firstLineY = Math.max(safeFontSize * 0.5, lineStep * 0.5);
  const dotFieldLeft = viewBoxX;
  const dotFieldTop = viewBoxY;
  const dotFieldWidth = width;
  const dotFieldHeight = height;
  const alphaValue = Number(alpha);
  const textOpacity = Math.max(0, Math.min(1, Number.isFinite(alphaValue) ? alphaValue : 1));
  const safeDotSpacing = clampFiniteNumber(dotSpacing, HEADLINE_HALFTONE_DEFAULTS.dotSpacing, 4, 28);
  const dotCols = Math.max(12, Math.ceil(width / safeDotSpacing));
  const dotRows = Math.max(8, Math.ceil(dotFieldHeight / safeDotSpacing));
  const safeMinDotScale = clampFiniteNumber(minDotScale, HEADLINE_HALFTONE_DEFAULTS.minDotScale, 0.05, 1);
  const safeMaxDotScale = Math.max(
    safeMinDotScale,
    clampFiniteNumber(maxDotScale, HEADLINE_HALFTONE_DEFAULTS.maxDotScale, 0.05, 1.5)
  );
  const safeFadeTop = clampFiniteNumber(fadeTop, HEADLINE_HALFTONE_DEFAULTS.fadeTop, 0, 1.5);
  const safeFadeBottom = clampFiniteNumber(fadeBottom, HEADLINE_HALFTONE_DEFAULTS.fadeBottom, 0, 1.5);
  const safeStrokeWidth = Math.max(0, Number(strokeWidth) || 0);
  const safeShadowBlur = Math.max(0, Number(shadowBlur) || 0);
  const safeGlow = Math.max(0, Number(glow) || 0);
  const safeHighlightOffset = Number.isFinite(Number(highlightOffset)) ? Number(highlightOffset) : 0;
  const safeDepthLayers = Math.max(0, Math.min(18, Math.round(Number(depthLayers) || 0)));
  const safeDepthStepX = Number.isFinite(Number(depthStepX)) ? Number(depthStepX) : 0;
  const safeDepthStepY = Number.isFinite(Number(depthStepY)) ? Number(depthStepY) : 0;
  const fillPaint = accentColor && accentColor !== color ? `url(#${gradientId})` : color;
  const svgBlendMode = blendMode && blendMode !== "source-over" ? blendMode : "normal";
  const svgFilter = effectFilter && effectFilter !== "none" ? effectFilter : undefined;
  const shadowVisible =
    !!shadowColor &&
    shadowColor !== "transparent" &&
    (shadowOffsetX !== 0 || shadowOffsetY !== 0 || safeShadowBlur > 0);
  const glowVisible = !!glowColor && glowColor !== "transparent" && safeGlow > 0;
  const highlightVisible = !!highlightColor && highlightColor !== "transparent" && safeHighlightOffset !== 0;

  const reportMeasuredTextBounds = React.useCallback(() => {
    const node = measureTextRef.current;
    if (!node) return;

    let bbox: DOMRect | SVGRect | null = null;
    try {
      bbox = node.getBBox();
    } catch {
      bbox = null;
    }
    if (!bbox || !Number.isFinite(bbox.width) || !Number.isFinite(bbox.height)) return;

    const nextX = Number(bbox.x) || 0;
    const nextY = Number(bbox.y) || 0;
    const nextTextWidth = Math.max(1, bbox.width);
    const nextTextHeight = Math.max(1, bbox.height);
    const nextWidth = Math.ceil(nextTextWidth + visualPad * 2);
    const nextHeight = Math.ceil(nextTextHeight + visualPad * 2);

    setMeasuredTextBounds((prev) =>
      prev?.key === measureKey &&
      Math.abs(prev.anchorX - textX) < 0.5 &&
      Math.abs(prev.x - nextX) < 0.5 &&
      Math.abs(prev.y - nextY) < 0.5 &&
      Math.abs(prev.width - nextTextWidth) < 0.5 &&
      Math.abs(prev.height - nextTextHeight) < 0.5
        ? prev
        : {
            key: measureKey,
            anchorX: textX,
            x: nextX,
            y: nextY,
            width: nextTextWidth,
            height: nextTextHeight,
          }
    );
    onBoundsChange?.({ width: nextWidth, height: nextHeight });
  }, [measureKey, onBoundsChange, textX, visualPad]);

  React.useLayoutEffect(() => {
    if (measureFrameRef.current !== null) {
      window.cancelAnimationFrame(measureFrameRef.current);
    }
    measureFrameRef.current = window.requestAnimationFrame(() => {
      measureFrameRef.current = null;
      reportMeasuredTextBounds();
    });

    const fontsReady = typeof document !== "undefined" ? (document as any).fonts?.ready : null;
    if (fontsReady && typeof fontsReady.then === "function") {
      fontsReady.then(reportMeasuredTextBounds).catch(() => {});
    }

    return () => {
      if (measureFrameRef.current !== null) {
        window.cancelAnimationFrame(measureFrameRef.current);
        measureFrameRef.current = null;
      }
    };
  }, [reportMeasuredTextBounds]);

  const dotPath = React.useMemo(() => {
    const commands: string[] = [];

    for (let y = 0; y < dotRows; y++) {
      for (let x = 0; x < dotCols; x++) {
        const px = dotFieldLeft + ((x + 0.5) / dotCols) * dotFieldWidth;
        const py = dotFieldTop + ((y + 0.5) / dotRows) * dotFieldHeight;
        const horizontalT = dotCols > 1 ? 1 - x / (dotCols - 1) : 1;
        const verticalT = dotRows > 1 ? y / (dotRows - 1) : 1;
        const horizontalScale = safeMinDotScale + (safeMaxDotScale - safeMinDotScale) * horizontalT;
        const verticalScale = safeFadeTop + (safeFadeBottom - safeFadeTop) * verticalT;
        const dotScale = Math.max(
          safeMinDotScale,
          Math.min(safeMaxDotScale, horizontalScale * verticalScale)
        );
        const r = Math.max(safeMinDot, safeMaxDot * dotScale);
        const d = (r * 2).toFixed(2);

        commands.push(
          `M${(px - r).toFixed(2)},${py.toFixed(2)}a${r.toFixed(2)},${r.toFixed(2)} 0 1,0 ${d},0a${r.toFixed(2)},${r.toFixed(2)} 0 1,0 -${d},0`
        );
      }
    }

    return commands.join(" ");
  }, [
    dotCols,
    dotFieldLeft,
    dotFieldHeight,
    dotFieldTop,
    dotFieldWidth,
    dotRows,
    safeFadeBottom,
    safeFadeTop,
    safeMaxDot,
    safeMaxDotScale,
    safeMinDot,
    safeMinDotScale,
    width,
  ]);

  const renderSvgText = (
    fill: string,
    extraProps: React.SVGProps<SVGTextElement> & { key?: React.Key } = {},
    textRef?: React.Ref<SVGTextElement>
  ) => {
    const { key, ...textProps } = extraProps;

    return (
      <text
        key={key}
        ref={textRef}
        x={textX}
        textAnchor={textAnchor}
        dominantBaseline="middle"
        fontFamily={fontFamily}
        fontSize={safeFontSize}
        fontWeight={900}
        fontStyle={fontStyle}
        letterSpacing={`${letterSpacing}em`}
        fill={fill}
        {...textProps}
      >
        {lines.map((line, idx) => (
          <tspan key={`line-${idx}`} x={textX} y={firstLineY + idx * lineStep}>
            {line || " "}
          </tspan>
        ))}
      </text>
    );
  };

  return (
    <svg
      viewBox={`${viewBoxX} ${viewBoxY} ${width} ${height}`}
      preserveAspectRatio="xMinYMin meet"
      width={width}
      height={height}
      className="pointer-events-none block select-none overflow-visible"
      style={{
        opacity: textOpacity,
        overflow: "visible",
      }}
      aria-hidden="true"
    >
      <defs>
        <linearGradient id={gradientId} x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor={color} />
          <stop offset="100%" stopColor={accentColor || color} />
        </linearGradient>
        <filter id={shadowFilterId} x="-35%" y="-35%" width="170%" height="190%">
          <feDropShadow
            dx={shadowOffsetX}
            dy={shadowOffsetY}
            stdDeviation={safeShadowBlur / 2}
            floodColor={shadowColor}
            floodOpacity={1}
          />
        </filter>
        <filter id={glowFilterId} x="-35%" y="-35%" width="170%" height="190%">
          <feDropShadow
            dx={0}
            dy={0}
            stdDeviation={safeGlow / 2.8}
            floodColor={glowColor}
            floodOpacity={1}
          />
        </filter>
        <mask id={maskId} maskUnits="userSpaceOnUse" x={viewBoxX} y={viewBoxY} width={width} height={height}>
          <rect x={viewBoxX} y={viewBoxY} width={width} height={height} fill="black" />
          {renderSvgText("white")}
        </mask>
      </defs>

      {shadowVisible &&
        renderSvgText(shadowColor, {
          transform: `translate(${shadowOffsetX} ${shadowOffsetY})`,
          filter: safeShadowBlur > 0 ? `url(#${shadowFilterId})` : undefined,
        })}
      {safeDepthLayers > 0 &&
        Array.from({ length: safeDepthLayers }, (_, index) => {
          const layer = safeDepthLayers - index;
          return renderSvgText(shadowColor, {
            key: `depth-${layer}`,
            transform: `translate(${(safeDepthStepX * layer).toFixed(2)} ${(safeDepthStepY * layer).toFixed(2)})`,
            opacity: 0.2 + 0.45 * (layer / safeDepthLayers),
          });
        })}
      {glowVisible &&
        renderSvgText("none", {
          stroke: glowColor,
          strokeWidth: Math.max(safeStrokeWidth, safeGlow * 0.18),
          filter: `url(#${glowFilterId})`,
          opacity: 0.75,
          paintOrder: "stroke fill",
        })}

      <g
        mask={`url(#${maskId})`}
        style={{
          mixBlendMode: svgBlendMode as React.CSSProperties["mixBlendMode"],
          filter: svgFilter,
        }}
      >
        <path d={dotPath} fill={fillPaint} />
        {highlightVisible && (
          <path
            d={dotPath}
            fill={highlightColor}
            opacity={0.24}
            transform={`translate(${safeHighlightOffset} ${safeHighlightOffset})`}
          />
        )}
      </g>
      {safeStrokeWidth > 0 &&
        renderSvgText("none", {
          stroke: strokeColor,
          strokeWidth: safeStrokeWidth,
          paintOrder: "stroke fill",
          vectorEffect: "non-scaling-stroke",
        })}
      {hitTest && (
        renderSvgText("rgba(0,0,0,0.001)", {
          stroke: "rgba(0,0,0,0.001)",
          strokeWidth: Math.max(8, safeFontSize * 0.055, safeStrokeWidth),
          paintOrder: "stroke fill",
          style: {
            cursor: "grab",
            pointerEvents: "visiblePainted",
            userSelect: "none",
          },
        })
      )}
      {renderSvgText(
        "transparent",
        {
          opacity: 0,
          pointerEvents: "none",
        },
        measureTextRef
      )}
    </svg>
  );
});

