type TextPixelHitLayerProps = {
  text: string;
  active?: boolean;
  align?: Align;
  fontFamily?: string;
  fontSize: number;
  fontWeight?: number;
  fontStyle?: React.CSSProperties["fontStyle"];
  lineHeight?: number;
  letterSpacing?: string;
  uppercase?: boolean;
  doubleBreaks?: boolean;
  strokeWidth?: number;
  hitPadding?: number;
  wrapWidth?: number;
  cursor?: React.CSSProperties["cursor"];
  perGlyph?: boolean;
  clipToGlyphs?: boolean;
  styledRuns?: CocoResolvedTextRun[] | null;
};

type StyledTextHitRun = {
  fontFamily: string;
  fontSize: number;
  fontStyle: React.CSSProperties["fontStyle"];
  fontWeight: string | number;
  text: string;
  width: number;
};

function StyledTextPixelHitLayer({
  align,
  cursor,
  fontFamily,
  fontSize,
  fontStyle,
  fontWeight,
  letterSpacing,
  lineHeight,
  runs,
  strokeWidth,
  uppercase,
}: {
  align: Align;
  cursor: React.CSSProperties["cursor"];
  fontFamily: string;
  fontSize: number;
  fontStyle: React.CSSProperties["fontStyle"];
  fontWeight: string | number;
  letterSpacing: string;
  lineHeight: number;
  runs: CocoResolvedTextRun[];
  strokeWidth: number;
  uppercase: boolean;
}) {
  const context = getHeadlinePaintMeasureContext();
  const letterSpacingValue = String(letterSpacing || "0").trim();
  const measureRun = (
    text: string,
    runFontSize: number,
    runFontFamily: string,
    runFontWeight: string | number,
    runFontStyle: React.CSSProperties["fontStyle"],
  ) => {
    const numericSpacing = Number.parseFloat(letterSpacingValue);
    const spacingPx = Number.isFinite(numericSpacing)
      ? letterSpacingValue.endsWith("em")
        ? numericSpacing * runFontSize
        : numericSpacing
      : 0;
    const chars = Array.from(text || " ");
    if (!context) {
      return chars.length * runFontSize * 0.58 + Math.max(0, chars.length - 1) * spacingPx;
    }
    context.font = buildHeadlineMeasureFont(
      runFontStyle,
      Number(runFontWeight) || 400,
      runFontSize,
      runFontFamily,
    );
    return chars.reduce(
      (width, character, index) =>
        width + context.measureText(character).width + (index < chars.length - 1 ? spacingPx : 0),
      0,
    );
  };

  const lines: StyledTextHitRun[][] = [[]];
  runs.forEach((run) => {
    const parts = String(run.text ?? "").replace(/\r\n?/g, "\n").split("\n");
    parts.forEach((part, partIndex) => {
      const runFontSize = Math.max(1, Number(run.fontSizePx ?? fontSize) || fontSize);
      const runFontFamily = String(run.fontFamily || fontFamily);
      const runFontWeight = run.fontWeight ?? fontWeight;
      const runFontStyle = (run.fontStyle || fontStyle) as React.CSSProperties["fontStyle"];
      const displayText = uppercase ? part.toUpperCase() : part;
      lines.at(-1)!.push({
        fontFamily: runFontFamily,
        fontSize: runFontSize,
        fontStyle: runFontStyle,
        fontWeight: runFontWeight,
        text: displayText,
        width: measureRun(displayText, runFontSize, runFontFamily, runFontWeight, runFontStyle),
      });
      if (partIndex < parts.length - 1) lines.push([]);
    });
    if (run.breakAfter) lines.push([]);
  });
  while (lines.length > 1 && lines.at(-1)!.length === 0) lines.pop();

  const lineMetrics = lines.map((line) => {
    const maxFontSize = Math.max(1, ...line.map((run) => run.fontSize));
    return {
      baseline: maxFontSize * 0.82,
      height: maxFontSize * lineHeight,
      width: line.reduce((sum, run) => sum + run.width, 0),
    };
  });
  const pad = 2;
  const measuredWidth = Math.max(1, ...lineMetrics.map((line) => line.width));
  const width = measuredWidth + pad * 2;
  const height = Math.max(1, lineMetrics.reduce((sum, line) => sum + line.height, 0)) + pad * 2;
  const left =
    align === "right"
      ? `calc(100% - ${width}px)`
      : align === "center"
        ? `calc(50% - ${width / 2}px)`
        : "0px";
  const interactionStrokeWidth = Math.max(0.75, Math.min(3, Number(strokeWidth) || 0));
  let lineTop = pad;

  return (
    <svg
      data-text-glyph-box="true"
      data-styled-text-hit-box="true"
      data-nonexport="true"
      aria-hidden="true"
      focusable="false"
      className="absolute top-0 overflow-visible"
      width={width}
      height={height}
      style={{
        left,
        width: `${width}px`,
        height: `${height}px`,
        filter: "none",
        pointerEvents: "none",
        textShadow: "none",
        zIndex: 1000,
      }}
    >
      {lines.flatMap((line, lineIndex) => {
        const metrics = lineMetrics[lineIndex];
        const lineStart =
          align === "right"
            ? width - pad - metrics.width
            : align === "center"
              ? (width - metrics.width) / 2
              : pad;
        const baselineY = lineTop + metrics.baseline;
        let runX = lineStart;
        const rendered = line.map((run, runIndex) => {
          const x = runX;
          runX += run.width;
          const painted = /\S/.test(run.text);
          return (
            <text
              key={`styled-text-hit-${lineIndex}-${runIndex}`}
              data-text-hit-run={`${lineIndex}:${runIndex}`}
              data-text-hit-surface={painted ? "true" : undefined}
              x={x}
              y={baselineY}
              dominantBaseline="alphabetic"
              fontFamily={run.fontFamily}
              fontSize={run.fontSize}
              fontWeight={run.fontWeight}
              fontStyle={run.fontStyle}
              letterSpacing={letterSpacing}
              fill="#000"
              fillOpacity={0.001}
              stroke="#000"
              strokeOpacity={0.001}
              strokeWidth={interactionStrokeWidth}
              paintOrder="stroke fill"
              style={{
                cursor,
                filter: "none",
                pointerEvents: painted ? "visiblePainted" : "none",
                textShadow: "none",
                userSelect: "none",
              }}
            >
              {run.text || " "}
            </text>
          );
        });
        lineTop += metrics.height;
        return rendered;
      })}
    </svg>
  );
}

function TextPixelHitLayer({
  text,
  align = "left",
  fontFamily = "LEMONMILK-Regular",
  fontSize,
  fontWeight = 700,
  fontStyle = "normal",
  lineHeight = 1,
  letterSpacing = "0em",
  uppercase = false,
  doubleBreaks = false,
  strokeWidth = 2,
  hitPadding,
  wrapWidth,
  cursor = "grab",
  perGlyph = false,
  clipToGlyphs = false,
  styledRuns,
}: TextPixelHitLayerProps) {
  const safeFontSize = Math.max(1, Number(fontSize) || 12);
  const safeLineHeight = Math.max(0.05, Number(lineHeight) || 1);
  if (styledRuns?.length) {
    return (
      <StyledTextPixelHitLayer
        align={align}
        cursor={cursor}
        fontFamily={fontFamily}
        fontSize={safeFontSize}
        fontStyle={fontStyle}
        fontWeight={fontWeight}
        letterSpacing={letterSpacing}
        lineHeight={safeLineHeight}
        runs={styledRuns}
        strokeWidth={strokeWidth}
        uppercase={uppercase}
      />
    );
  }
  const lineAdvance = safeFontSize * safeLineHeight * (doubleBreaks ? 2 : 1);
  const parseLetterSpacingPx = () => {
    const value = String(letterSpacing || "0").trim();
    if (!value) return 0;
    const numeric = Number.parseFloat(value);
    if (!Number.isFinite(numeric)) return 0;
    return value.endsWith("em") ? numeric * safeFontSize : numeric;
  };
  const letterSpacingPx = parseLetterSpacingPx();
  const measureLine = (line: string) => {
    const measured = line || " ";
    const context = getHeadlinePaintMeasureContext();
    if (!context) {
      return measured.length * safeFontSize * 0.58 + Math.max(0, measured.length - 1) * letterSpacingPx;
    }
    context.font = buildHeadlineMeasureFont(fontStyle, fontWeight, safeFontSize, fontFamily);
    let width = 0;
    const chars = Array.from(measured);
    chars.forEach((char, index) => {
      width += context.measureText(char).width;
      if (index < chars.length - 1) width += letterSpacingPx;
    });
    return width;
  };
  const sourceLines = String(text || "").replace(/\r\n?/g, "\n").split("\n");
  const safeWrapWidth = Math.max(0, Number(wrapWidth) || 0);
  const wrapLine = (line: string) => {
    if (!safeWrapWidth || measureLine(line) <= safeWrapWidth) return [line];
    const words = line.split(/(\s+)/).filter(Boolean);
    const wrapped: string[] = [];
    let current = "";
    words.forEach((word) => {
      const candidate = `${current}${word}`;
      if (current.trim() && measureLine(candidate) > safeWrapWidth) {
        wrapped.push(current.trimEnd());
        current = word.trimStart();
      } else {
        current = candidate;
      }
    });
    if (current || !wrapped.length) wrapped.push(current.trimEnd());
    return wrapped;
  };
  const displayLines = sourceLines.flatMap(wrapLine).map((line) =>
    uppercase ? line.toUpperCase() : line
  );
  const measuredWidth = Math.max(1, ...displayLines.map(measureLine));
  const requestedPad = Math.max(0, Number(hitPadding) || 0);
  const strokePad = Math.max(1, Math.abs(Number(strokeWidth) || 0) * 0.75);
  const pad = Math.max(1, Math.min(strokePad, 2), Math.min(requestedPad, 2));
  const width = measuredWidth + pad * 2;
  const height = pad * 2 + safeFontSize * 1.25 + Math.max(0, displayLines.length - 1) * lineAdvance;
  const interactionStrokeWidth = Math.max(0.75, Math.min(3, Number(strokeWidth) || 0));
  const left =
    align === "right"
      ? `calc(100% - ${width}px)`
      : align === "center"
      ? `calc(50% - ${width / 2}px)`
      : "0px";
  const x = align === "right" ? width - pad : align === "center" ? width / 2 : pad;
  const textAnchor = align === "right" ? "end" : align === "center" ? "middle" : "start";
  const renderGlyphTspans = (interactive: boolean) => {
    let glyphIndex = 0;
    return displayLines.flatMap((line, lineIndex) =>
      Array.from(line || " ").map((glyph, lineGlyphIndex) => {
        const currentGlyphIndex = glyphIndex++;
        const whitespace = /\s/.test(glyph);
        return (
          <tspan
            key={`${interactive ? "text-hit" : "text-select"}-${lineIndex}-${currentGlyphIndex}`}
            x={lineGlyphIndex === 0 ? x : undefined}
            dy={lineGlyphIndex === 0 ? (lineIndex === 0 ? 0 : lineAdvance) : undefined}
            {...(interactive
              ? {
                  "data-text-glyph-character": glyph,
                  "data-text-glyph-index": currentGlyphIndex,
                  "data-text-hit-surface": whitespace ? undefined : "true",
                }
              : {})}
            style={interactive ? { pointerEvents: whitespace ? "none" : "visiblePainted" } : undefined}
          >
            {glyph}
          </tspan>
        );
      })
    );
  };

  const inkContext = clipToGlyphs ? getHeadlinePaintMeasureContext() : null;
  if (inkContext) inkContext.font = buildHeadlineMeasureFont(fontStyle, fontWeight, safeFontSize, fontFamily);
  const inkBounds = inkContext ? displayLines.map((line, index) => {
    const metrics = inkContext.measureText(line || " ");
    const baseline = pad + safeFontSize * .82 + index * lineAdvance;
    return { top: baseline - metrics.actualBoundingBoxAscent, bottom: baseline + metrics.actualBoundingBoxDescent };
  }) : [];

  return (
    <svg
      data-text-glyph-box="true"
      data-nonexport="true"
      aria-hidden="true"
      focusable="false"
      className="absolute top-0 overflow-visible"
      width={width}
      height={height}
      style={{
        left,
        width: `${width}px`,
        height: `${height}px`,
	    // This SVG is interaction geometry only. Text effects inherit by
	    // default, which caused the transparent hit glyphs above the real text
	    // to paint a second drop shadow in front of the visible letters.
	    filter: "none",
	    textShadow: "none",
        pointerEvents: "none",
        zIndex: 1000,
        clipPath: inkBounds.length
          ? `inset(${Math.min(...inkBounds.map(b => b.top)) - 1}px -10000px ${height - Math.max(...inkBounds.map(b => b.bottom)) - 1}px -10000px)`
          : undefined,
      }}
    >
      <text
        data-text-hit-surface={perGlyph ? undefined : "true"}
        x={x}
        y={pad + safeFontSize * 0.82}
        textAnchor={textAnchor}
        dominantBaseline="alphabetic"
        fontFamily={fontFamily}
        fontSize={safeFontSize}
        fontWeight={fontWeight}
        fontStyle={fontStyle}
        letterSpacing={letterSpacing}
        fill="#000"
        fillOpacity={0.001}
        stroke="#000"
        strokeOpacity={0.001}
        strokeWidth={interactionStrokeWidth}
        paintOrder="stroke fill"
        style={{
          cursor,
	      filter: "none",
          pointerEvents: perGlyph ? "none" : "visiblePainted",
	      textShadow: "none",
          userSelect: "none",
        }}
      >
        {perGlyph
          ? renderGlyphTspans(true)
          : displayLines.map((line, index) => (
              <tspan data-text-hit-surface="true" key={`text-hit-${index}`} x={x} dy={index === 0 ? 0 : lineAdvance}>
                {line || " "}
              </tspan>
            ))}
      </text>
    </svg>
  );
}

type TextObjectSelectionRect = {
  left: number;
  top: number;
  width: number;
  height: number;
};

function TextObjectSelectionBox({
  nodeId,
  rootRef,
}: {
  nodeId: string | null;
  rootRef: React.RefObject<HTMLDivElement | null>;
}) {
  const [rect, setRect] = React.useState<TextObjectSelectionRect | null>(null);

  React.useLayoutEffect(() => {
    if (!nodeId) {
      setRect(null);
      return;
    }

    let frame = 0;
    const update = () => {
      const root = rootRef.current;
      if (!root) {
        setRect(null);
        frame = window.requestAnimationFrame(update);
        return;
      }
      const compiledTarget = Array.from(
        root.querySelectorAll<HTMLElement>(
          '[data-coco-compiled-document="true"] [data-node]',
        ),
      ).find((element) => element.dataset.node === nodeId);
      const target =
        compiledTarget ??
        (canvasRefs[nodeId as keyof typeof canvasRefs] as HTMLElement | null);
      if (!target || !target.isConnected) {
        setRect(null);
        frame = window.requestAnimationFrame(update);
        return;
      }

      const rootBounds = root.getBoundingClientRect();
      const scaleX = rootBounds.width / Math.max(1, root.offsetWidth);
      const scaleY = rootBounds.height / Math.max(1, root.offsetHeight);
      const textBounds: DOMRect[] = [];
      const walker = document.createTreeWalker(target, NodeFilter.SHOW_TEXT);
      let textNode = walker.nextNode();
      while (textNode) {
        const parent = textNode.parentElement;
        if (
          textNode.textContent?.trim() &&
          parent &&
          !parent.closest('[data-nonexport="true"]')
        ) {
          const style = window.getComputedStyle(parent);
          if (style.display !== "none" && style.visibility !== "hidden") {
            const range = document.createRange();
            range.selectNodeContents(textNode);
            textBounds.push(
              ...Array.from(range.getClientRects()).filter(
                (bounds) => bounds.width > 0 && bounds.height > 0,
              ),
            );
          }
        }
        textNode = walker.nextNode();
      }
      const glyphBounds = Array.from(
        target.querySelectorAll<SVGElement>('[data-text-glyph-box="true"]'),
      )
        .map((element) => element.getBoundingClientRect())
        .filter((bounds) => bounds.width > 0 && bounds.height > 0);
      const bounds = textBounds.length
        ? textBounds
        : glyphBounds.length
          ? glyphBounds
          : [target.getBoundingClientRect()];
      const left = Math.min(...bounds.map((item) => item.left));
      const top = Math.min(...bounds.map((item) => item.top));
      const right = Math.max(...bounds.map((item) => item.right));
      const bottom = Math.max(...bounds.map((item) => item.bottom));
      const padding = 2;
      const next = {
        left: (left - rootBounds.left) / scaleX - padding,
        top: (top - rootBounds.top) / scaleY - padding,
        width: (right - left) / scaleX + padding * 2,
        height: (bottom - top) / scaleY + padding * 2,
      };
      setRect((previous) =>
        previous &&
        Math.abs(previous.left - next.left) < 0.25 &&
        Math.abs(previous.top - next.top) < 0.25 &&
        Math.abs(previous.width - next.width) < 0.25 &&
        Math.abs(previous.height - next.height) < 0.25
          ? previous
          : next,
      );
      frame = window.requestAnimationFrame(update);
    };

    update();
    return () => window.cancelAnimationFrame(frame);
  }, [nodeId, rootRef]);

  if (!nodeId || !rect) return null;
  return (
    <div
      data-text-object-selection-box={nodeId}
      data-nonexport="true"
      aria-hidden="true"
      className="absolute pointer-events-none"
      style={{
        left: rect.left,
        top: rect.top,
        width: rect.width,
        height: rect.height,
        border: "1px solid #fff",
        boxSizing: "border-box",
        zIndex: 2000,
      }}
    />
  );
}

type SecondaryTextLockupProps = {
  align: Align;
  children: React.ReactNode;
  gapPx?: number;
  node?: string;
  style?: React.CSSProperties;
};

function SecondaryTextLockup({
  align,
  children,
  gapPx = 5,
  node,
  style,
}: SecondaryTextLockupProps) {
  return (
    <div
      data-secondary-lockup={node}
      style={{
        alignItems:
          align === "right" ? "flex-end" : align === "center" ? "center" : "flex-start",
        display: "flex",
        flexDirection: "column",
        gap: `${gapPx}px`,
        maxWidth: "100%",
        width: "max-content",
        ...style,
      }}
    >
      {children}
    </div>
  );
}

