const COCO_CANVAS_LAYER_STEP = 8;
const COCO_CANVAS_LAYER_MIN = -120;
const COCO_CANVAS_LAYER_MAX = 180;
const COCO_COMPILED_LAYER_BASE = 500;
const COCO_RUNTIME_PRICE_LAYER_ID = "@runtime/price";
const COCO_RUNTIME_QR_LAYER_ID = "@runtime/qr";
const CSS_MIN_VISIBLE_ALPHA = 12 / 255;
const splitCssPaintLayers = (value: string) => {
  const layers: string[] = [];
  let depth = 0;
  let start = 0;
  for (let index = 0; index < value.length; index += 1) {
    const char = value[index];
    if (char === "(") depth += 1;
    else if (char === ")") depth = Math.max(0, depth - 1);
    else if (char === "," && depth === 0) {
      layers.push(value.slice(start, index).trim());
      start = index + 1;
    }
  }
  layers.push(value.slice(start).trim());
  return layers.filter(Boolean);
};
const cssLinearGradientStopsForSvg = (value: string) => {
  const source = String(value || "");
  const marker = source.search(/(?:repeating-)?linear-gradient\(/i);
  if (marker < 0) return [] as Array<{ color: string; offset: string }>;
  const open = source.indexOf("(", marker);
  let depth = 0;
  let close = -1;
  for (let index = open; index < source.length; index += 1) {
    if (source[index] === "(") depth += 1;
    else if (source[index] === ")") {
      depth -= 1;
      if (depth === 0) {
        close = index;
        break;
      }
    }
  }
  if (open < 0 || close < 0) return [] as Array<{ color: string; offset: string }>;
  const parts = splitCssPaintLayers(source.slice(open + 1, close));
  const rawStops = parts
    .map((part) => {
      const match = part.match(
        /^((?:rgba?|hsla?)\([^)]*\)|#[0-9a-f]{3,8}|[a-z]+)(?:\s+(.+))?$/i,
      );
      if (!match) return null;
      const explicitOffset = match[2]?.match(/(-?(?:\d+\.?\d*|\.\d+))%/);
      return {
        color: match[1],
        explicitOffset: explicitOffset ? Number(explicitOffset[1]) : null,
      };
    })
    .filter((stop): stop is { color: string; explicitOffset: number | null } => Boolean(stop));
  if (rawStops.length < 2) return [] as Array<{ color: string; offset: string }>;
  return rawStops.map((stop, index) => ({
    color: stop.color,
    offset: `${Math.max(
      0,
      Math.min(
        100,
        stop.explicitOffset ?? (index / Math.max(1, rawStops.length - 1)) * 100,
      ),
    )}%`,
  }));
};
const cssPaintHasInvisibleStop = (value: string) => {
  if (/\btransparent\b/i.test(value)) return true;
  for (const match of value.matchAll(/(?:rgba|hsla)\(([^)]*)\)/gi)) {
    const body = match[1];
    const alphaMatch = body.match(/(?:,|\/)\s*(-?(?:\d+\.?\d*|\.\d+))(%)?\s*$/);
    if (!alphaMatch) continue;
    const alpha = Number(alphaMatch[1]) / (alphaMatch[2] ? 100 : 1);
    if (!Number.isFinite(alpha) || alpha < CSS_MIN_VISIBLE_ALPHA) return true;
  }
  return false;
};
const cssBackgroundPaintsEntireBox = (style: CSSStyleDeclaration) => {
  const opacity = Number.parseFloat(style.opacity || "1");
  if (Number.isFinite(opacity) && opacity < CSS_MIN_VISIBLE_ALPHA) return false;
  if (style.maskImage && style.maskImage !== "none") return false;
  const blendMode = String(style.mixBlendMode || "normal").toLowerCase();
  if (blendMode !== "normal") return false;

  const backgroundColor = String(style.backgroundColor || "").trim();
  if (
    backgroundColor &&
    backgroundColor !== "transparent" &&
    !cssPaintHasInvisibleStop(backgroundColor)
  ) return true;

  return splitCssPaintLayers(String(style.backgroundImage || "none")).some(
    (layer) =>
      /(?:repeating-)?(?:linear|radial|conic)-gradient\(/i.test(layer) &&
      !cssPaintHasInvisibleStop(layer),
  );
};
const finiteCocoLayerZ = (value: unknown, fallback = 0) => {
  const number = Number(value);
  return Number.isFinite(number) ? number : fallback;
};
const authoredCocoLayerZ = (object: any) =>
  finiteCocoLayerZ(
    object?.stacking?.effectiveZIndex,
    finiteCocoLayerZ(object?.stacking?.zIndex),
  );
const nudgeCocoLayerZ = (value: unknown, direction: "up" | "down") =>
  Math.max(
    COCO_CANVAS_LAYER_MIN,
    Math.min(
      COCO_CANVAS_LAYER_MAX,
      finiteCocoLayerZ(value) +
        (direction === "up" ? COCO_CANVAS_LAYER_STEP : -COCO_CANVAS_LAYER_STEP),
    ),
  );
