function cocoCenterSocialPlatform(item: any): string | null {
  const explicit = String(item?.socialPlatform || "").trim().toLowerCase();
  if (explicit) return explicit === "twitter" ? "x" : explicit;
  const identity = [item?.id, item?.editorGraphicId, item?.label]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
  if (/instagram/.test(identity)) return "instagram";
  if (/tiktok/.test(identity)) return "tiktok";
  if (/(^|[_\s])x($|[_\s])|twitter/.test(identity)) return "x";
  if (/whatsapp/.test(identity)) return "whatsapp";
  if (/facebook/.test(identity)) return "facebook";
  if (/youtube/.test(identity)) return "youtube";
  return null;
}

function isCocoCenterSocialPortrait(item: any): boolean {
  const platform = cocoCenterSocialPlatform(item);
  // Social Media UI also has optional non-footer stickers. Only the six
  // supported platform icons participate in the center-stack lockup.
  const isSupportedPlatform = Boolean(platform && COCO_CENTER_SOCIAL_PLATFORM_TO_GRAPHIC[platform]);
  return Boolean(
    item?.isSocialIcon ||
      COCO_CENTER_SOCIAL_REQUIRED_ID_PATTERN.test(String(item?.id || ""))
  ) && isSupportedPlatform;
}
