function resolveCocoPriceBadgeWidthPct(scale: number, centerStack: boolean) {
  const scaledWidth = Math.min(30, 12 * Math.max(0.1, Number(scale) || 1));
  return centerStack
    ? Math.max(
        COCO_CENTER_FOOTER_BADGE_MIN_DIAMETER_PX /
          COCO_CENTER_FOOTER_REFERENCE_WIDTH_PX *
          100,
        scaledWidth
      )
    : Math.max(6, scaledWidth);
}

function measureCocoPriceBadgeLine(
  line: string,
  fontSize: number,
  fontFamily: string
) {
  const context = getHeadlinePaintMeasureContext();
  if (!context) return 0;
  context.font = buildHeadlineMeasureFont("normal", 900, fontSize, fontFamily);
  const metrics = context.measureText(line || " ");
  const paintedWidth =
    Number(metrics.actualBoundingBoxLeft || 0) +
    Number(metrics.actualBoundingBoxRight || 0);
  return Math.max(Number(metrics.width || 0), paintedWidth);
}

function resolveCocoPriceBadgeFontSize({
  diameterPx,
  fontFamily,
  lineHeight,
  requestedSize,
  text,
}: {
  diameterPx: number;
  fontFamily: string;
  lineHeight: number;
  requestedSize: number;
  text: string;
}) {
  return fitCocoPriceBadgeFontSize({
    diameterPx,
    fontFamily,
    lineHeight,
    requestedSize,
    text,
    measureLineWidth: (line, size) =>
      measureCocoPriceBadgeLine(line, size, fontFamily),
  });
}
