function withoutInterFlyerFont(font: unknown, fallback: string) {
  const raw = typeof font === "string" ? font.trim() : "";
  if (!raw) return fallback;
  const families = raw
    .split(",")
    .map((family) => family.trim())
    .filter((family) => {
      const unquoted = family.replace(/^['"]|['"]$/g, "");
      return !/^inter$/i.test(unquoted);
    });
  return families.length ? families.join(", ") : fallback;
}

function normalizeCocoFontName(font: unknown) {
  return typeof font === "string" ? font.trim() : "";
}

function isReadableCocoSupportFont(font: unknown) {
  const name = normalizeCocoFontName(font);
  if (!name) return false;
  if (COCO_MODULE_DECORATIVE_SUPPORT_FONTS.has(name)) return false;
  if (COCO_MODULE_DECORATIVE_SUPPORT_FONT_PATTERN.test(name)) return false;
  return COCO_MODULE_READABLE_SUPPORT_FONTS.has(name);
}

function uniqueCocoSupportFonts(fonts: Array<string | undefined | null>) {
  const seen = new Set<string>();
  return fonts
    .map(normalizeCocoFontName)
    .filter((font) => {
      if (!font || seen.has(font)) return false;
      seen.add(font);
      return true;
    });
}

function pickReadableCocoSupportFont(
  preferred: unknown,
  candidates: Array<string | undefined | null>,
  fallback = "Bebas Neue"
) {
  const ordered = uniqueCocoSupportFonts([
    normalizeCocoFontName(preferred),
    ...candidates,
    fallback,
    ...COCO_MODULE_BODY_COPY_FONTS,
  ]);
  return ordered.find(isReadableCocoSupportFont) ?? fallback;
}

function sanitizeCocoSupportFont(
  font: unknown,
  role: CocoSupportFontRole,
  candidates: Array<string | undefined | null> = []
) {
  if (isReadableCocoSupportFont(font)) return normalizeCocoFontName(font);
  return pickReadableCocoSupportFont(
    font,
    [...candidates, ...COCO_MODULE_SUPPORT_ROLE_OPTIONS[role]],
    COCO_MODULE_SUPPORT_FALLBACKS[role]
  );
}

function sanitizeCocoCssSupportFontFamily(
  font: unknown,
  role: CocoSupportFontRole,
  candidates: Array<string | undefined | null> = []
) {
  const raw = normalizeCocoFontName(font);
  const primary = raw.split(",")[0]?.trim().replace(/^['"]|['"]$/g, "");
  return sanitizeCocoSupportFont(primary || raw, role, candidates);
}

function cssFontFamilyStack(families: string[]) {
  const seen = new Set<string>();
  return families
    .map((family) => normalizeCocoFontName(family))
    .filter((family) => {
      const key = family.toLowerCase();
      if (!family || seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .map((family) => {
      if (/^(serif|sans-serif|monospace|system-ui|ui-sans-serif)$/i.test(family)) return family;
      const escaped = family.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
      return `"${escaped}"`;
    })
    .join(", ");
}

function cocoSupportFontStack(
  font: unknown,
  role: CocoSupportFontRole,
  candidates: Array<string | undefined | null> = []
) {
  const safe = sanitizeCocoSupportFont(font, role, candidates);
  return cssFontFamilyStack([safe, "LEMONMILK-Regular", "BebasNeue-Regular", "Arial", "sans-serif"]);
}
