const IMPORTED_DESIGN_BG_URL_FIXUPS = new Map<string, string>([
  ["/template-previews/720/la-lux.webp", "/templates/la-lux.jpg"],
  ["/template-previews/900/la-lux.webp", "/templates/la-lux.jpg"],
  ["/samples/optimized/la-luxe.png", "/templates/la-lux.jpg"],
  ["/template-previews/720/karaokee.webp", "/templates/karaokee.jpg"],
  ["/template-previews/900/karaokee.webp", "/templates/karaokee.jpg"],
  ["/samples/optimized/karaoke.png", "/templates/karaokee.jpg"],
  ["/template-previews/720/mardi_gras.webp", "/templates/mardi_gras.jpg"],
  ["/template-previews/900/mardi_gras.webp", "/templates/mardi_gras.jpg"],
  ["/samples/optimized/mardi-gras.png", "/templates/mardi_gras.jpg"],
]);

function normalizeImportedDesignBgUrl(value: unknown) {
  const raw = typeof value === "string" ? value.trim() : "";
  if (!raw) return value;

  let path = raw;
  try {
    path = new URL(raw, "https://nightlife-flyers.local").pathname;
  } catch {
    path = raw.split(/[?#]/)[0] || raw;
  }

  return IMPORTED_DESIGN_BG_URL_FIXUPS.get(path) ?? raw;
}

function normalizeDesignJson(design: any, currentFormat: string) {
  const targetFmt = design.format || design.targetFormat || currentFormat;
  const sessionRoot =
    design?.session && typeof design.session === "object" ? design.session : {};
  const sessionState =
    sessionRoot && typeof sessionRoot === "object" ? sessionRoot[targetFmt] ?? {} : {};
  const merged = {
    ...design,
    ...sessionState,
  };

  const normalizeCompiledKey = (value: unknown) =>
    String(value ?? "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "");

  const compiledObjectsForFormat = (fmt: Format) => {
    const variant = sessionRoot?.[fmt];
    const compiledDocument = variant?.cocoCompositionSystem?.compiledDocument;
    const objects = Array.isArray(compiledDocument?.objects)
      ? compiledDocument.objects
      : Array.isArray(variant?.cocoCssCompiler?.ir?.objects)
        ? variant.cocoCssCompiler.ir.objects
        : [];
    return objects.filter((object: any) => object?.kind !== "text");
  };

  const restoreCompiledAssetIdentity = (
    item: any,
    fmt: Format,
    key: "portraits" | "emojis",
  ) => {
    const normalized = key === "portraits" ? normalizeRuntimeAssetRecord(item) : item;
    if (normalized?.cocoCompiledObjectId) return normalized;

    const assetRole = normalizeCompiledKey(normalized?.cocoAssetRole);
    if (!assetRole) return normalized;
    const matches = compiledObjectsForFormat(fmt).filter((object: any) => {
      const objectKeys = [object?.id, object?.assetRole, object?.semanticRole]
        .map(normalizeCompiledKey)
        .filter(Boolean);
      return objectKeys.includes(assetRole);
    });
    return matches.length === 1
      ? { ...normalized, cocoCompiledObjectId: matches[0].id }
      : normalized;
  };

  const normalizeFormatItems = (
    items: any[],
    key: "portraits" | "emojis",
    fmt: Format,
  ) => items.map((item) => restoreCompiledAssetIdentity(item, fmt, key));

  const readSessionArray = (fmt: Format, key: "portraits" | "emojis") => {
    const bucket = sessionRoot?.[fmt]?.[key];
    return Array.isArray(bucket) ? normalizeFormatItems(bucket, key, fmt) : [];
  };

  const normalizeByFormatArray = (value: any, key: "portraits" | "emojis") => {
    if (value && typeof value === "object" && !Array.isArray(value)) {
      return {
        square: Array.isArray(value.square)
          ? normalizeFormatItems(value.square, key, "square")
          : readSessionArray("square", key),
        story: Array.isArray(value.story)
          ? normalizeFormatItems(value.story, key, "story")
          : readSessionArray("story", key),
      };
    }
    if (Array.isArray(value)) {
      return {
        square:
          targetFmt === "square" ? normalizeFormatItems(value, key, "square") : readSessionArray("square", key),
        story:
          targetFmt === "story" ? normalizeFormatItems(value, key, "story") : readSessionArray("story", key),
      };
    }
    return {
      square: readSessionArray("square", key),
      story: readSessionArray("story", key),
    };
  };

  const normalizeFormatToggle = (
    rootValue: any,
    sessionKey:
      | "head2Enabled"
      | "detailsEnabled"
      | "details2Enabled"
      | "subtagEnabled"
      | "venueEnabled"
      | "emojisEnabled",
    fallback = false
  ) => {
    if (rootValue && typeof rootValue === "object" && !Array.isArray(rootValue)) {
      return {
        square:
          typeof rootValue.square === "boolean"
            ? rootValue.square
            : typeof sessionRoot?.square?.[sessionKey] === "boolean"
            ? sessionRoot.square[sessionKey]
            : fallback,
        story:
          typeof rootValue.story === "boolean"
            ? rootValue.story
            : typeof sessionRoot?.story?.[sessionKey] === "boolean"
            ? sessionRoot.story[sessionKey]
            : fallback,
      };
    }
    return {
      square:
        targetFmt === "square" && typeof rootValue === "boolean"
          ? rootValue
          : typeof sessionRoot?.square?.[sessionKey] === "boolean"
          ? sessionRoot.square[sessionKey]
          : fallback,
      story:
        targetFmt === "story" && typeof rootValue === "boolean"
          ? rootValue
          : typeof sessionRoot?.story?.[sessionKey] === "boolean"
          ? sessionRoot.story[sessionKey]
          : fallback,
    };
  };

  // Flatten text styles if nested differently in older versions
  const headline = merged.headline ?? merged.text?.headline;
  const head2 = merged.head2 ?? merged.text?.head2 ?? merged.text?.headline2;
  const details = merged.details ?? merged.text?.details;
  const details2 = merged.details2 ?? merged.text?.details2;
  const venue = merged.venue ?? merged.text?.venue;
  const subtag = merged.subtag ?? merged.text?.subtag;

  const portraits = normalizeByFormatArray(
    design.portraits ?? design.portraitsByFormat ?? sessionState?.portraits,
    "portraits"
  );
  const emojis = normalizeByFormatArray(
    design.emojis ?? design.emojisByFormat ?? sessionState?.emojis,
    "emojis"
  );

  const headline2Enabled = normalizeFormatToggle(
    design.headline2Enabled,
    "head2Enabled",
    true
  );
  const detailsEnabled = normalizeFormatToggle(
    design.detailsEnabled,
    "detailsEnabled",
    true
  );
  const details2Enabled = normalizeFormatToggle(
    design.details2Enabled,
    "details2Enabled",
    false
  );
  const venueEnabled = normalizeFormatToggle(
    design.venueEnabled,
    "venueEnabled",
    true
  );
  const emojisEnabled = normalizeFormatToggle(
    design.emojisEnabled,
    "emojisEnabled",
    true
  );
  const subtagEnabled = normalizeFormatToggle(
    design.subtagEnabled,
    "subtagEnabled",
    true
  );

  const normalizeSessionBgUrl = (session: any) => {
    if (!session || typeof session !== "object") return session;
    const bgUrl = normalizeImportedDesignBgUrl(session.bgUrl);
    return bgUrl === session.bgUrl ? session : { ...session, bgUrl };
  };

  const normalizedSession = {
    square: {
      ...normalizeSessionBgUrl(
        sessionRoot?.square && typeof sessionRoot.square === "object"
          ? sessionRoot.square
          : {}
      ),
      portraits: portraits.square,
      emojis: emojis.square,
      detailsEnabled: detailsEnabled.square,
      subtagEnabled: subtagEnabled.square,
      details2Enabled: details2Enabled.square,
      head2Enabled: headline2Enabled.square,
      venueEnabled: venueEnabled.square,
      emojisEnabled: emojisEnabled.square,
    },
    story: {
      ...normalizeSessionBgUrl(
        sessionRoot?.story && typeof sessionRoot.story === "object"
          ? sessionRoot.story
          : {}
      ),
      portraits: portraits.story,
      emojis: emojis.story,
      detailsEnabled: detailsEnabled.story,
      subtagEnabled: subtagEnabled.story,
      details2Enabled: details2Enabled.story,
      head2Enabled: headline2Enabled.story,
      venueEnabled: venueEnabled.story,
      emojisEnabled: emojisEnabled.story,
    },
  };

  return {
    ...merged,
    format: targetFmt,
    headline,
    head2,
    details,
    details2,
    venue,
    subtag,
    head2SizePx: merged.head2SizePx ?? merged.head2Size,
    headManualPx: merged.headManualPx ?? merged.headlineSize ?? merged.headSize,
    headlineHidden: !!(merged.headlineHidden ?? false),
    portraits,
    emojis,
    detailsEnabled,
    headline2Enabled,
    details2Enabled,
    subtagEnabled,
    venueEnabled,
    emojisEnabled,
    session: normalizedSession,
    // Recipe-generated projects use the portable `backgroundUrl` field while
    // older editor saves use `bgUrl`. Preserve an explicitly empty recipe
    // background so loading a materialized .nflyer clears the previous
    // canvas image instead of leaving a stale starter background underneath
    // the recipe-owned assets.
    bgUrl: normalizeImportedDesignBgUrl(merged.bgUrl ?? merged.backgroundUrl),
    icons:
      Array.isArray(merged.icons)
        ? merged.icons
        : Array.isArray(sessionRoot?.[targetFmt]?.icons)
        ? sessionRoot[targetFmt].icons
        : [],
  };
}

// =========================================================
// ✅ DYNAMIC STUDIO GENERATORS (Compatibility Mode)
// =========================================================

// 1. Tint Helper
function getTintedColor(intensity: number, warmth: number) {
  const a = Math.max(0, Math.min(1, intensity));
  let r = 255, g = 255, b = 255;

  if (warmth > 0) {
    b = 255 - (warmth * 200); 
    g = 255 - (warmth * 60); 
  } else {
    r = 255 - (Math.abs(warmth) * 200);
    g = 255 - (Math.abs(warmth) * 30);
  }
  return `rgba(${Math.floor(r)},${Math.floor(g)},${Math.floor(b)},${a})`;
}

// 2. Generic Studio (Smart Overload: Handles old & new calls)
function buildStudioPlate(
  arg1: string | number, // preset (old) OR size (new)
  arg2: number,          // size (old) OR lighting (new)
  arg3: number = 1.0,    // contrast
  arg4: number = 0       // warmth
): HTMLCanvasElement {
  
  // 🧠 DETECT ARGUMENTS:
  let size: number, lighting = 1.0, contrast = 1.0, warmth = 0;

  if (typeof arg1 === 'string') {
    // Legacy Call: (preset, size) -> Use defaults
    size = arg2;
  } else {
    // New Call: (size, lighting, contrast, warmth)
    size = arg1;
    lighting = arg2;
    contrast = arg3;
    warmth = arg4;
  }

  const c = document.createElement("canvas");
  c.width = size; c.height = size;
  const ctx = c.getContext("2d")!;

  // Background
  const bgVal = Math.max(0, 40 - (contrast * 30));
  ctx.fillStyle = `rgb(${bgVal},${bgVal},${bgVal})`;
  ctx.fillRect(0, 0, size, size);

  const boost = (base: number) => Math.min(1, base * lighting);

  // Ambient
  const bg = ctx.createRadialGradient(size*0.35, size*0.25, size*0.05, size*0.5, size*0.5, size*0.9);
  bg.addColorStop(0, getTintedColor(boost(0.15), warmth));
  bg.addColorStop(1, "rgba(0,0,0,0)");
  ctx.globalCompositeOperation = "screen";
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, size, size);

  // Softbox 1
  ctx.save();
  ctx.translate(size*0.1, size*0.1);
  ctx.rotate(-10 * Math.PI / 180);
  ctx.fillStyle = getTintedColor(boost(0.75), warmth);
  ctx.fillRect(0, 0, size*0.85, size*0.14);
  ctx.restore();

  // Softbox 2
  ctx.save();
  ctx.translate(size*0.15, size*0.65);
  ctx.rotate(12 * Math.PI / 180);
  ctx.fillStyle = getTintedColor(boost(0.45), warmth);
  ctx.fillRect(0, 0, size*0.75, size*0.09);
  ctx.restore();

  return c;
}

// 3. Chrome Studio (Smart Overload)
function generateChromeStudioEnv(
  arg1: number, 
  arg2: number, 
  arg3: number = 1.0, 
  arg4: number = 0,
  isIce = false
): HTMLCanvasElement {
  
  // Note: Chrome studio didn't have a 'preset' arg before, so standard signature works.
  // We just add defaults to be safe.
  const size = arg1;
  const lighting = arg2;
  const contrast = arg3;
  const warmth = arg4;

  const c = document.createElement("canvas");
  c.width = size; c.height = size;
  const ctx = c.getContext("2d")!;

  ctx.fillStyle = "#000000";
  ctx.fillRect(0, 0, size, size);

  const effectiveWarmth = isIce ? (warmth === 0 ? -0.8 : warmth) : warmth;
  const blurAmount = Math.max(0, (2.5 - contrast) * 10);
  const boost = (base: number) => Math.min(1, base * lighting);

  ctx.filter = `blur(${blurAmount}px)`;
  ctx.globalCompositeOperation = "screen";

  const g = ctx.createLinearGradient(0, size*0.5, 0, size*0.6);
  g.addColorStop(0, "rgba(0,0,0,0)");
  g.addColorStop(0.5, getTintedColor(boost(0.9), effectiveWarmth));
  g.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, size*0.4, size, size*0.4);

  ctx.fillStyle = getTintedColor(boost(1.0), effectiveWarmth);
  ctx.fillRect(size*0.1, size*0.1, size*0.4, size*0.15);

  ctx.fillStyle = getTintedColor(boost(0.8), effectiveWarmth);
  ctx.fillRect(size*0.7, size*0.15, size*0.2, size*0.5);

  return c;
}










// 7. MASTER BUILDER (Orchestrator) — LOCKED: gold / silver / chrome ONLY
async function buildTiledReflectionPlateDataUrl(
  uploadUrlOrNull: string | null,
  size: number = 2048,
  presetId: string = "gold",
  lighting: number = 60,
  reflections: number = 60,
  warmth: number = 0
): Promise<string> {
  // Normalize Inputs
  const L = clamp(Number(lighting) || 60, 0, 100) / 100 * 2; // 0..2
  const R = clamp(Number(reflections) || 60, 0, 100) / 100;  // 0..1
  const W = clamp(Number(warmth) || 0, -1, 1);               // -1..1

  // ✅ Lock preset to gold/silver/chrome (anything else becomes gold)
  const preset = (() => {
    const p = String(presetId || "gold").toLowerCase();
    if (p === "silver") return "silver";
    if (p === "chrome") return "chrome";
    return "gold";
  })();

  // Helper: build the studio canvas for allowed presets only
  const buildStudio = (): HTMLCanvasElement => {
    if (preset === "chrome") return generateChromeStudioEnv(size, L, R, W);
    if (preset === "silver") return generateChromeStudioEnv(size, L, R, W);
    return buildStudioPlate(size, L, R, W);
  };

  const tuning =
    preset === "chrome"
      ? { tileFrac: 0.52, brightBoost: 0.45, contrastBoost: 1.2, studioAlpha: 0.22 }
      : preset === "silver"
      ? { tileFrac: 0.44, brightBoost: 0.28, contrastBoost: 0.85, studioAlpha: 0.4 }
      : { tileFrac: 0.32, brightBoost: 0.15, contrastBoost: 0.5, studioAlpha: 0.65 };

  // =========================================================
  // A) NO UPLOAD: return pure studio plate
  // =========================================================
  if (!uploadUrlOrNull) {
    const studioCanvas = buildStudio();
    return studioCanvas.toDataURL("image/jpeg", 0.95);
  }

  // =========================================================
  // B) UPLOAD: make upload a "reflection content" + overlay studio
  // =========================================================
  let img: HTMLImageElement | null = null;
  try {
    img = await loadImage(uploadUrlOrNull);
  } catch {
    // If the background fails to load (CORS or decode), fall back to studio only.
    const studioCanvas = buildStudio();
    return studioCanvas.toDataURL("image/jpeg", 0.95);
  }

  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;

  const ctx = canvas.getContext("2d")!;
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = "high";

  // 1) Always start with true black base
  ctx.filter = "none";
  ctx.globalCompositeOperation = "source-over";
  ctx.globalAlpha = 1;
  ctx.fillStyle = "#000000";
  ctx.fillRect(0, 0, size, size);

  // 2) Tile upload as "bonus reflections" (neutralized)
  const brightness = 0.95 + L * 0.55 + tuning.brightBoost;
  const contrast = 1.05 + R * 0.95 + tuning.contrastBoost;
  const saturate = preset === "gold" ? 0.35 : 0.2;
  const hue = W * 10;                  // subtle warmth/cool

  ctx.filter = `brightness(${brightness}) contrast(${contrast}) saturate(${saturate}) hue-rotate(${hue}deg)`;

  const iw = (img as any).naturalWidth || (img as any).width;
  const ih = (img as any).naturalHeight || (img as any).height;

  const s = Math.min(iw, ih);
  const sx = Math.floor((iw - s) / 2);
  const sy = Math.floor((ih - s) / 2);

  if (preset === "chrome") {
    const scale = Math.max(size / iw, size / ih);
    const dw = iw * scale;
    const dh = ih * scale;
    const dx = (size - dw) / 2;
    const dy = (size - dh) / 2;
    ctx.drawImage(img as any, 0, 0, iw, ih, dx, dy, dw, dh);
  } else {
    const tileSize = Math.max(256, Math.round(size * tuning.tileFrac));

    for (let y = -tileSize; y < size + tileSize; y += tileSize) {
      for (let x = -tileSize; x < size + tileSize; x += tileSize) {
        ctx.save();

        const mx = ((x / tileSize) | 0) % 2 !== 0;
        const my = ((y / tileSize) | 0) % 2 !== 0;

        ctx.translate(x + (mx ? tileSize : 0), y + (my ? tileSize : 0));
        ctx.scale(mx ? -1 : 1, my ? -1 : 1);

        ctx.drawImage(img as any, sx, sy, s, s, 0, 0, tileSize, tileSize);
        ctx.restore();
      }
    }
  }

  // 3) Overlay the studio (always consistent)
  ctx.filter = "none";
  ctx.globalCompositeOperation = "screen";
  ctx.globalAlpha = tuning.studioAlpha;

  const studio = buildStudio();
  ctx.drawImage(studio, 0, 0);

  // restore state
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
  ctx.filter = "none";

  return canvas.toDataURL("image/jpeg", 0.95);
}








function generateSilverStudioEnv(size: number = 2048): string {
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("No 2D context");

  // 1) charcoal base (NOT pure black)
  ctx.fillStyle = "#111111";
  ctx.fillRect(0, 0, size, size);

  // 2) subtle concrete-like texture (noise)
  const img = ctx.getImageData(0, 0, size, size);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (Math.random() * 22) | 0; // 0..21
    const v = 16 + n; // lift blacks slightly
    d[i] = v; d[i + 1] = v; d[i + 2] = v; d[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);

  // 3) wide softbox sweeps (broad, not sharp)
  const sweep = ctx.createLinearGradient(0, size * 0.25, size, size * 0.75);
  sweep.addColorStop(0.00, "rgba(255,255,255,0.00)");
  sweep.addColorStop(0.35, "rgba(255,255,255,0.10)");
  sweep.addColorStop(0.50, "rgba(255,255,255,0.18)");
  sweep.addColorStop(0.65, "rgba(255,255,255,0.10)");
  sweep.addColorStop(1.00, "rgba(255,255,255,0.00)");
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  ctx.fillStyle = sweep;
  ctx.fillRect(0, 0, size, size);
  ctx.restore();

  // 4) a couple soft rectangles (muted)
  const boxes = [
    { x: 0.10, y: 0.12, w: 0.40, h: 0.16, a: 0.22, r: -10 },
    { x: 0.55, y: 0.14, w: 0.34, h: 0.14, a: 0.18, r: 8 },
    { x: 0.18, y: 0.72, w: 0.36, h: 0.14, a: 0.14, r: 12 },
  ];

  ctx.save();
  ctx.globalCompositeOperation = "screen";
  for (const b of boxes) {
    ctx.save();
    ctx.globalAlpha = b.a;
    ctx.translate(size * b.x, size * b.y);
    ctx.rotate((b.r * Math.PI) / 180);

    const g = ctx.createLinearGradient(0, 0, size * b.w, size * b.h);
    g.addColorStop(0.0, "rgba(255,255,255,0.00)");
    g.addColorStop(0.5, "rgba(255,255,255,0.85)");
    g.addColorStop(1.0, "rgba(255,255,255,0.00)");

    ctx.fillStyle = g;
    ctx.fillRect(0, 0, size * b.w, size * b.h);
    ctx.restore();
  }
  ctx.restore();

  // 5) vignette (keeps “premium” center read)
  const vign = ctx.createRadialGradient(
    size * 0.5, size * 0.5, size * 0.10,
    size * 0.5, size * 0.5, size * 0.80
  );
  vign.addColorStop(0.0, "rgba(0,0,0,0.00)");
  vign.addColorStop(1.0, "rgba(0,0,0,0.70)");
  ctx.fillStyle = vign;
  ctx.fillRect(0, 0, size, size);

  // 6) slight blur to feel like a backdrop plate
  const blurPx = Math.max(2, Math.round(size * 0.0016)); // ~3px at 2048
  const tmp = document.createElement("canvas");
  tmp.width = size; tmp.height = size;
  const tctx = tmp.getContext("2d");
  if (!tctx) throw new Error("No 2D context");
  tctx.filter = `blur(${blurPx}px)`;
  tctx.drawImage(canvas, 0, 0);

  ctx.clearRect(0, 0, size, size);
  ctx.drawImage(tmp, 0, 0);

  return canvas.toDataURL("image/jpeg", 0.92);
}



function clamp(n: number, min: number, max: number) {
  return Math.max(min, Math.min(max, n));
}

async function loadImage(url: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    if (!url.startsWith('data:')) img.crossOrigin = "anonymous";
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`Failed to load image`));
    img.src = url;
  });
}

function makeCanvas(size: number) {
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("No 2D context");
  return { canvas, ctx };
}

async function compositeWrapFromMaps(
  baseUrl: string,
  edgeUrl: string,
  depthUrl: string,
  maskUrl: string,
  opts?: { depthAlpha?: number; edgeAlpha?: number }
) {
  const [baseImg, edgeImg, depthImg, maskImg] = await Promise.all([
    loadImage(baseUrl),
    loadImage(edgeUrl),
    loadImage(depthUrl),
    loadImage(maskUrl),
  ]);
  const size = Math.min(
    (baseImg as any).naturalWidth || (baseImg as any).width,
    (baseImg as any).naturalHeight || (baseImg as any).height
  );
  const { canvas, ctx } = makeCanvas(size);

  ctx.drawImage(baseImg, 0, 0, size, size);

  const { canvas: depthC, ctx: depthCtx } = makeCanvas(size);
  depthCtx.drawImage(depthImg, 0, 0, size, size);
  depthCtx.globalCompositeOperation = "destination-in";
  depthCtx.drawImage(maskImg, 0, 0, size, size);

  const { canvas: edgeC, ctx: edgeCtx } = makeCanvas(size);
  edgeCtx.drawImage(edgeImg, 0, 0, size, size);
  edgeCtx.globalCompositeOperation = "destination-in";
  edgeCtx.drawImage(maskImg, 0, 0, size, size);

  const depthAlpha = Math.max(0, Math.min(1, opts?.depthAlpha ?? 0.28));
  const edgeAlpha = Math.max(0, Math.min(1, opts?.edgeAlpha ?? 0.45));

  // Depth adds gentle shadowing
  ctx.save();
  ctx.globalCompositeOperation = "multiply";
  ctx.globalAlpha = depthAlpha;
  ctx.drawImage(depthC, 0, 0, size, size);
  ctx.restore();

  // Edge adds subtle highlight definition
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  ctx.globalAlpha = edgeAlpha;
  ctx.drawImage(edgeC, 0, 0, size, size);
  ctx.restore();

  return canvas.toDataURL("image/png");
}

async function compositeSilverStudio(
  baseUrl: string,
  edgeUrl: string,
  depthUrl: string,
  maskUrl: string
) {
  try {
    const [baseImg, edgeImg, depthImg, maskImg] = await Promise.all([
      loadImage(baseUrl),
      loadImage(edgeUrl),
      loadImage(depthUrl),
      loadImage(maskUrl),
    ]);
  const size = Math.min(
    (baseImg as any).naturalWidth || (baseImg as any).width,
    (baseImg as any).naturalHeight || (baseImg as any).height
  );
  const { canvas, ctx } = makeCanvas(size);

  ctx.drawImage(baseImg, 0, 0, size, size);
  ctx.globalCompositeOperation = "destination-in";
  ctx.drawImage(maskImg, 0, 0, size, size);
  ctx.globalCompositeOperation = "source-over";

  const { canvas: edgeC, ctx: edgeCtx } = makeCanvas(size);
  edgeCtx.drawImage(edgeImg, 0, 0, size, size);
  edgeCtx.globalCompositeOperation = "destination-in";
  edgeCtx.drawImage(maskImg, 0, 0, size, size);

  const { canvas: depthC, ctx: depthCtx } = makeCanvas(size);
  depthCtx.drawImage(depthImg, 0, 0, size, size);
  depthCtx.globalCompositeOperation = "destination-in";
  depthCtx.drawImage(maskImg, 0, 0, size, size);

  // Stronger bevel depth
  ctx.save();
  ctx.globalCompositeOperation = "multiply";
  ctx.globalAlpha = 0.35;
  ctx.drawImage(depthC, 0, 0, size, size);
  ctx.restore();

  // Specular highlights
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  ctx.globalAlpha = 0.55;
  ctx.filter = "contrast(2.0) brightness(1.35)";
  ctx.drawImage(depthC, 0, 0, size, size);
  ctx.filter = "none";
  ctx.restore();

  // Crisp edges for definition
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  ctx.globalAlpha = 0.65;
  ctx.filter = "blur(1px)";
  ctx.drawImage(edgeC, 0, 0, size, size);
  ctx.filter = "none";
  ctx.restore();

    return canvas.toDataURL("image/png");
  } catch {
    return baseUrl;
  }
}

// chrome now uses the standard AI render path (no custom composite)

// 1. Text Layout
function layoutWrappedText(opts: {
  ctx: CanvasRenderingContext2D;
  text: string;
  fontName: string;
  size: number;
  fontSize: number;
  padding: number;
  lineHeightMultiplier: number;
}) {
  const { ctx, text, fontName, size, fontSize, padding, lineHeightMultiplier } = opts;
  const maxTextWidth = size - padding * 2;

  ctx.font = `900 ${fontSize}px "${fontName}"`;
  ctx.textAlign = "center";
  ctx.textBaseline = "alphabetic";

  const paragraphs = text.toUpperCase().split("\n");
  const lines: string[] = [];

  for (const p of paragraphs) {
    const words = p.split(" ").filter(Boolean);
    if (words.length === 0) { lines.push(""); continue; }
    let current = words[0];
    for (let i = 1; i < words.length; i++) {
      const w = words[i];
      const test = `${current} ${w}`;
      const width = ctx.measureText(test).width;
      if (width <= maxTextWidth) current = test;
      else { lines.push(current); current = w; }
    }
    lines.push(current);
  }

  const m = ctx.measureText("Mg");
  const ascent = (m as any).actualBoundingBoxAscent ?? fontSize * 0.8;
  const descent = (m as any).actualBoundingBoxDescent ?? fontSize * 0.2;
  const fontPx = ascent + descent;
  const lh = clamp(Number(lineHeightMultiplier) || 1.0, 0.2, 1.6);
  const lineHeight = fontPx * lh;

  let widest = 0;
  for (const line of lines) widest = Math.max(widest, ctx.measureText(line).width);

  const blockHeight = lines.length * lineHeight;
  const startY = size / 2 - blockHeight / 2 + ascent;

  return { lines, widest, blockHeight, startY, ascent, lineHeight, maxTextWidth };
}

// 2. Draw Authority Mask
function drawMaskText(opts: {
  ctx: CanvasRenderingContext2D;
  text: string;
  fontName: string;
  size: number;
  lineHeightMultiplier: number;
  strokeFrac?: number;
}) {
  const { ctx, text, fontName, size, lineHeightMultiplier } = opts;
  const padding = Math.round(size * 0.08);
  const maxTotalHeight = size * 0.8;

  let fontSize = Math.round(size * 0.22);
  while (fontSize > 40) {
    const layout = layoutWrappedText({ ctx, text, fontName, size, fontSize, padding, lineHeightMultiplier });
    if (layout.blockHeight <= maxTotalHeight && layout.widest <= layout.maxTextWidth) break;
    fontSize -= Math.max(6, Math.round(size * 0.004));
  }

  ctx.globalCompositeOperation = "source-over";
  ctx.clearRect(0, 0, size, size);
  ctx.font = `900 ${fontSize}px "${fontName}"`;
  ctx.textAlign = "center";
  ctx.textBaseline = "alphabetic";
  ctx.lineJoin = "round";
  ctx.miterLimit = 2;

  const layout = layoutWrappedText({ ctx, text, fontName, size, fontSize, padding, lineHeightMultiplier });
  const strokeWidth = Math.max(6, Math.round(fontSize * (opts.strokeFrac ?? 0.06)));

  ctx.strokeStyle = "#ffffff";
  ctx.fillStyle = "#ffffff";
  ctx.lineWidth = strokeWidth;

  for (let i = 0; i < layout.lines.length; i++) {
    const line = layout.lines[i];
    const y = layout.startY + i * layout.lineHeight;
    ctx.strokeText(line, size / 2, y);
    ctx.fillText(line, size / 2, y);
  }
}

// 3. Pixel Tools
function thresholdToBinary(imgData: ImageData, t = 10) {
  const d = imgData.data;
  for (let i = 0; i < d.length; i += 4) {
    const on = d[i] > t ? 255 : 0;
    d[i] = on; d[i + 1] = on; d[i + 2] = on; d[i + 3] = 255;
  }
}

// 4. Master Orchestrator (BLACK SCREEN)
async function buildCinematicMaps(
  headline: string,
  fontName: string,
  textureUrl: string,
  wrapId: string,
  lineHeightMultiplier: number = 1.0,
  size: number = 2048,
  materialKey: string = "gold"
): Promise<{ base: string; edge: string; depth: string; mask: string }> {

  try { await (document as any).fonts?.load?.(`900 150px "${fontName}"`); } catch {}

  const textureImg = await loadImage(textureUrl);

  // A) Mask (White text on black)
  const { canvas: maskCanvas, ctx: maskCtx } = makeCanvas(size);
  drawMaskText({ ctx: maskCtx, text: headline, fontName, size, lineHeightMultiplier, strokeFrac: 0.04 });

  const maskData = maskCtx.getImageData(0, 0, size, size);
  thresholdToBinary(maskData, 10);
  maskCtx.putImageData(maskData, 0, 0);

  // B) Base - The "Poisoned" Black Void
  const { canvas: baseCanvas, ctx: baseCtx } = makeCanvas(size);
  
  // 1. Fill with Black
  baseCtx.fillStyle = "#000000";
  baseCtx.fillRect(0, 0, size, size);

  // 2. 🔥 POISON THE VOID: Invisible Dither
  // Alternates between Pure Black (#000000) and Almost Black (#010101)
  // This structure stops the AI from generating "fog" or "glow" in empty space.
  const baseImg = baseCtx.getImageData(0, 0, size, size);
  const d = baseImg.data;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const idx = (y * size + x) * 4;
      const val = (x % 2 === y % 2) ? 0 : 1; // 0 or 1
      d[idx] = val;     // R
      d[idx + 1] = val; // G
      d[idx + 2] = val; // B
      d[idx + 3] = 255; // Alpha
    }
  }
  baseCtx.putImageData(baseImg, 0, 0);

  // 3. 🔥 MOAT: Dark Gray Guard Ring (#111111)
  // Separates the object from the void so edges don't melt
  baseCtx.save();
  baseCtx.globalCompositeOperation = "source-over";
  baseCtx.filter = `blur(${size * 0.008}px)`; 
  baseCtx.drawImage(maskCanvas, 0, 0); 
  
  baseCtx.globalCompositeOperation = "source-in";
  baseCtx.fillStyle = "#111111"; // Dark Gray Guard
  baseCtx.fillRect(0, 0, size, size);
  baseCtx.restore();

  // 4. Draw the Textured Object
  const { canvas: objCanvas, ctx: objCtx } = makeCanvas(size);
  if (wrapId && wrapId !== "none") {
    drawWrapTexture(objCtx, textureImg, size, wrapId);
  } else {
    objCtx.drawImage(textureImg, 0, 0, size, size);
  }
  const bevelStrength =
    wrapId && wrapId !== "none"
      ? 0.65
      : materialKey === "chrome"
      ? 1.2
      : materialKey === "silver"
      ? 1.1
      : 1;
  bakeBevelInternal(objCtx, maskCanvas, size, bevelStrength);
  objCtx.globalCompositeOperation = "destination-in";
  objCtx.drawImage(maskCanvas, 0, 0);

  // Composite object onto Black Void
  baseCtx.globalCompositeOperation = "source-over";
  baseCtx.drawImage(objCanvas, 0, 0);

  // C) Maps
  const depth = buildDepthFromMask(maskCanvas, size);
  const edge = buildEdgeFromMask(maskCanvas, size);

  const mask = maskCanvas.toDataURL("image/png");
  return { base: baseCanvas.toDataURL("image/png"), edge, depth, mask };

}

function drawWrapTexture(
  ctx: CanvasRenderingContext2D,
  img: HTMLImageElement,
  size: number,
  wrapId: string
) {
  const tuning: Record<string, { tileFrac: number; smoothing?: boolean }> = {
    zebra: { tileFrac: 0.18, smoothing: false },
    tiger: { tileFrac: 0.24 },
    carbon_fiber: { tileFrac: 0.18 },
    snakeskin: { tileFrac: 0.22 },
    geometric: { tileFrac: 0.22 },
  };

  const cfg = tuning[wrapId] || tuning.geometric;
  const tileSize = Math.max(160, Math.round(size * cfg.tileFrac));
  const tile = document.createElement("canvas");
  tile.width = tileSize;
  tile.height = tileSize;
  const tctx = tile.getContext("2d")!;

  const iw = (img as any).naturalWidth || (img as any).width;
  const ih = (img as any).naturalHeight || (img as any).height;
  const s = Math.min(iw, ih);
  const sx = Math.floor((iw - s) / 2);
  const sy = Math.floor((ih - s) / 2);

  const scale = tileSize / Math.max(1, s);
  const smoothing = typeof cfg.smoothing === "boolean" ? cfg.smoothing : scale < 1;
  tctx.imageSmoothingEnabled = smoothing;
  tctx.imageSmoothingQuality = smoothing ? "high" : "low";

  tctx.drawImage(img, sx, sy, s, s, 0, 0, tileSize, tileSize);

  const pattern = ctx.createPattern(tile, "repeat");
  if (!pattern) return;
  ctx.save();
  ctx.fillStyle = pattern;
  ctx.fillRect(0, 0, size, size);
  ctx.restore();
}

// 5. Bevel Baker (Internal)
function bakeBevelInternal(
  targetCtx: CanvasRenderingContext2D,
  maskCanvas: HTMLCanvasElement,
  size: number,
  strength: number = 1
) {
  const { canvas: hiC, ctx: hiCtx } = makeCanvas(size);
  const { canvas: shC, ctx: shCtx } = makeCanvas(size);
  const s = clamp(strength, 0.4, 1.4);
  const blurPx = Math.max(4, Math.round(size * 0.004 * s));

  hiCtx.filter = `blur(${blurPx}px)`;
  hiCtx.drawImage(maskCanvas, -size*0.002, -size*0.002);
  
  shCtx.filter = `blur(${blurPx}px)`;
  shCtx.drawImage(maskCanvas, size*0.002, size*0.002);

  targetCtx.save();
  targetCtx.globalCompositeOperation = "screen";
  targetCtx.globalAlpha = 0.5 * s;
  targetCtx.drawImage(hiC, 0, 0); 
  targetCtx.globalCompositeOperation = "multiply";
  targetCtx.globalAlpha = 0.6 * s;
  targetCtx.drawImage(shC, 0, 0);
  targetCtx.restore();
}

// 6. Edge Map
function buildEdgeFromMask(maskCanvas: HTMLCanvasElement, size: number) {
  const { canvas: edgeCanvas, ctx: edgeCtx } = makeCanvas(size);
  const { canvas: b1, ctx: c1 } = makeCanvas(size);
  const { canvas: b2, ctx: c2 } = makeCanvas(size);

  c1.filter = `blur(${size * 0.004}px)`; c1.drawImage(maskCanvas, 0, 0);
  c2.filter = `blur(${size * 0.002}px)`; c2.drawImage(maskCanvas, 0, 0);

  edgeCtx.drawImage(b1, 0, 0);
  edgeCtx.globalCompositeOperation = "difference";
  edgeCtx.drawImage(b2, 0, 0);
  
  const d = edgeCtx.getImageData(0,0,size,size);
  thresholdToBinary(d, 15);
  edgeCtx.putImageData(d, 0, 0);

  return edgeCanvas.toDataURL("image/png");
}

function buildDepthFromMask(maskCanvas: HTMLCanvasElement, size: number) {
  const { canvas: dC, ctx: dCtx } = makeCanvas(size);
  dCtx.fillStyle = "black"; dCtx.fillRect(0,0,size,size);
  dCtx.filter = `blur(${size*0.01}px)`;
  dCtx.drawImage(maskCanvas, 0, 0);
  return dC.toDataURL("image/png");
}

async function downscaleDataUrlClient(
  dataUrl: string,
  targetSize: number = 1024,
  mime: "image/png" | "image/jpeg" = "image/png",
  jpegQuality: number = 0.95
): Promise<string> {
  return new Promise((resolve, reject) => {
    if (!dataUrl.startsWith("data:image")) return reject(new Error("Invalid Image Data"));
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = targetSize; canvas.height = targetSize;
      const ctx = canvas.getContext("2d");
      if(!ctx) return reject("No Context");
      ctx.fillStyle = "#000000"; ctx.fillRect(0,0,targetSize,targetSize); // Safety Black
      ctx.drawImage(img, 0, 0, targetSize, targetSize);
      resolve(canvas.toDataURL(mime, jpegQuality));
    };
    img.src = dataUrl;
  });
}

// =========================================================
// ✅ VOID REMOVAL TOOL: Removes black void + moat AFTER render
// =========================================================

function isNearVoid(r: number, g: number, b: number) {
  // covers #000000, #010101 dither, and very dark noise
  return r <= 8 && g <= 8 && b <= 8;
}

function isNearMoat(r: number, g: number, b: number) {
  // covers #111111 moat and slight variations
  return r <= 28 && g <= 28 && b <= 28;
}

function floodFillBackgroundToTransparent(imgData: ImageData) {
  const { width: w, height: h, data } = imgData;
  const visited = new Uint8Array(w * h);

  const id = (x: number, y: number) => y * w + x;
  const p4 = (i: number) => i * 4;

  // ✅ Estimate background color from MANY border samples (robust vs not-fully-black)
  const samples: [number, number, number][] = [];

  const take = (x: number, y: number) => {
    const p = p4(id(x, y));
    samples.push([data[p], data[p + 1], data[p + 2]]);
  };

  // sample every N pixels along the border
  const step = Math.max(1, Math.floor(Math.min(w, h) / 64));

  for (let x = 0; x < w; x += step) {
    take(x, 0);
    take(x, h - 1);
  }
  for (let y = 0; y < h; y += step) {
    take(0, y);
    take(w - 1, y);
  }

  // Use median per channel (more robust than average)
  const median = (arr: number[]) => {
    const a = arr.slice().sort((a, b) => a - b);
    return a[Math.floor(a.length / 2)] ?? 0;
  };

  const rs = samples.map((s) => s[0]);
  const gs = samples.map((s) => s[1]);
  const bs = samples.map((s) => s[2]);

  const bgR = median(rs);
  const bgG = median(gs);
  const bgB = median(bs);

  const dist2 = (r: number, g: number, b: number) => {
    const dr = r - bgR,
      dg = g - bgG,
      db = b - bgB;
    return dr * dr + dg * dg + db * db;
  };

  const isLowChroma = (r: number, g: number, b: number) => {
    const mx = Math.max(r, g, b);
    const mn = Math.min(r, g, b);
    return mx - mn <= 20; // gray-ish
  };

  const isBg = (x: number, y: number) => {
    const p = p4(id(x, y));
    const r = data[p],
      g = data[p + 1],
      b = data[p + 2];

    // treat void + moat as background
    if (isNearVoid(r, g, b) || isNearMoat(r, g, b)) return true;

    //Adjust this number
    // treat pixels close to border background color as background (handles ash-grey)
    return isLowChroma(r, g, b) && dist2(r, g, b) <= 6400;
  };

  const qx: number[] = [];
  const qy: number[] = [];

  const pushIf = (x: number, y: number) => {
    const i = id(x, y);
    if (visited[i]) return;
    if (!isBg(x, y)) return;
    visited[i] = 1;
    qx.push(x);
    qy.push(y);
  };

  // seed from all borders
  for (let x = 0; x < w; x++) {
    pushIf(x, 0);
    pushIf(x, h - 1);
  }
  for (let y = 0; y < h; y++) {
    pushIf(0, y);
    pushIf(w - 1, y);
  }

  // flood fill (4-neighborhood)
  while (qx.length) {
    const x = qx.pop()!;
    const y = qy.pop()!;
    const neighbors = [
      [x + 1, y],
      [x - 1, y],
      [x, y + 1],
      [x, y - 1],
    ] as const;

    for (const [nx, ny] of neighbors) {
      if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
      const ni = id(nx, ny);
      if (visited[ni]) continue;
      if (!isBg(nx, ny)) continue;
      visited[ni] = 1;
      qx.push(nx);
      qy.push(ny);
    }
  }

  // set flooded background to alpha=0
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = id(x, y);
      if (!visited[i]) continue;
      data[p4(i) + 3] = 0;
    }
  }

  return imgData;
}


function removeEnclosedBackgroundIslands(imgData: ImageData) {
  const { width: w, height: h, data } = imgData;
  const visited = new Uint8Array(w * h);

  const id = (x: number, y: number) => y * w + x;
  const p4 = (i: number) => i * 4;

  // Background test must match what you already consider background:
  // - near void
  // - near moat
  // - low-chroma close to corner bg
  // We reuse the corner-bg estimation here so it matches your ash-grey handling.
  const sampleCorner = (x: number, y: number) => {
    const p = p4(id(x, y));
    return [data[p], data[p + 1], data[p + 2]] as const;
  };

  const corners = [
    sampleCorner(0, 0),
    sampleCorner(w - 1, 0),
    sampleCorner(0, h - 1),
    sampleCorner(w - 1, h - 1),
  ];

  const bgSum = corners.reduce(
    (acc, c) => [acc[0] + c[0], acc[1] + c[1], acc[2] + c[2]] as const,
    [0, 0, 0] as const
  );

  const bgR = Math.round(bgSum[0] / corners.length);
  const bgG = Math.round(bgSum[1] / corners.length);
  const bgB = Math.round(bgSum[2] / corners.length);

  const dist2 = (r: number, g: number, b: number) => {
    const dr = r - bgR, dg = g - bgG, db = b - bgB;
    return dr * dr + dg * dg + db * db;
  };

  const isLowChroma = (r: number, g: number, b: number) => {
    const mx = Math.max(r, g, b);
    const mn = Math.min(r, g, b);
    return (mx - mn) <= 20;
  };

  const isBgPixel = (x: number, y: number) => {
    const p = p4(id(x, y));
    const r = data[p], g = data[p + 1], b = data[p + 2], a = data[p + 3];

    // Already transparent is background
    if (a === 0) return true;

    // Your background logic
    if (isNearVoid(r, g, b) || isNearMoat(r, g, b)) return true;

    // Ash-grey lifted background
    return isLowChroma(r, g, b) && dist2(r, g, b) <= 2500;
  };

  // Scan for remaining background-colored regions that are NOT transparent yet.
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const start = id(x, y);
      if (visited[start]) continue;

      // Only consider candidates that still look like background BUT are not already transparent
      const p = p4(start);
      if (data[p + 3] === 0) { visited[start] = 1; continue; }
      if (!isBgPixel(x, y)) { visited[start] = 1; continue; }

      // Flood-fill this region
      const qx: number[] = [x];
      const qy: number[] = [y];
      visited[start] = 1;

      let touchesBorder = false;
      const region: number[] = [];

      while (qx.length) {
        const cx = qx.pop()!;
        const cy = qy.pop()!;
        const ci = id(cx, cy);

        region.push(ci);

        if (cx === 0 || cy === 0 || cx === w - 1 || cy === h - 1) {
          touchesBorder = true;
        }

        const neighbors = [
          [cx + 1, cy],
          [cx - 1, cy],
          [cx, cy + 1],
          [cx, cy - 1],
        ] as const;

        for (const [nx, ny] of neighbors) {
          if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
          const ni = id(nx, ny);
          if (visited[ni]) continue;
          visited[ni] = 1;
          if (!isBgPixel(nx, ny)) continue;
          qx.push(nx); qy.push(ny);
        }
      }

      // ✅ If it does NOT touch the border, it’s an enclosed hole → make transparent
      if (!touchesBorder) {
        for (const i of region) {
          data[p4(i) + 3] = 0;
        }
      }
    }
  }

  return imgData;
}


// Alpha crop helper (used by removeVoidAndCropToPng)
function cropToAlpha(imgData: ImageData): string {
  const { width: w, height: h, data } = imgData;
  let minX = w, minY = h, maxX = -1, maxY = -1;

  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const a = data[(y * w + x) * 4 + 3];
      if (a === 0) continue;
      if (x < minX) minX = x;
      if (y < minY) minY = y;
      if (x > maxX) maxX = x;
      if (y > maxY) maxY = y;
    }
  }

  if (maxX < minX || maxY < minY) {
    const c = document.createElement("canvas");
    c.width = 1;
    c.height = 1;
    return c.toDataURL("image/png");
  }

  const cw = maxX - minX + 1;
  const ch = maxY - minY + 1;

  const srcCanvas = document.createElement("canvas");
  srcCanvas.width = w;
  srcCanvas.height = h;
  const sctx = srcCanvas.getContext("2d")!;
  sctx.putImageData(imgData, 0, 0);

  const outCanvas = document.createElement("canvas");
  outCanvas.width = cw;
  outCanvas.height = ch;
  const octx = outCanvas.getContext("2d")!;
  octx.drawImage(srcCanvas, minX, minY, cw, ch, 0, 0, cw, ch);

  return outCanvas.toDataURL("image/png");
}

// Alpha helpers (shared)
function erodeAlpha(imgData: ImageData, iterations = 1, alphaThreshold = 10): ImageData {
  const { width: w, height: h, data } = imgData;
  for (let it = 0; it < iterations; it++) {
    const copy = new Uint8ClampedArray(data);
    const aAt = (x: number, y: number) => copy[(y * w + x) * 4 + 3];
    for (let y = 1; y < h - 1; y++) {
      for (let x = 1; x < w - 1; x++) {
        const a = aAt(x, y);
        if (a <= alphaThreshold) continue;
        const n =
          aAt(x + 1, y) <= alphaThreshold ||
          aAt(x - 1, y) <= alphaThreshold ||
          aAt(x, y + 1) <= alphaThreshold ||
          aAt(x, y - 1) <= alphaThreshold;
        if (n) data[(y * w + x) * 4 + 3] = 0;
      }
    }
  }
  return imgData;
}

function featherAlpha(imgData: ImageData, radius = 1): ImageData {
  const { width: w, height: h, data } = imgData;
  for (let it = 0; it < radius; it++) {
    const prev = new Uint8ClampedArray(data);
    const aPrev = (x: number, y: number) => prev[(y * w + x) * 4 + 3];
    for (let y = 1; y < h - 1; y++) {
      for (let x = 1; x < w - 1; x++) {
        let sum = 0;
        sum += aPrev(x, y);
        sum += aPrev(x + 1, y);
        sum += aPrev(x - 1, y);
        sum += aPrev(x, y + 1);
        sum += aPrev(x, y - 1);
        sum += aPrev(x + 1, y + 1);
        sum += aPrev(x - 1, y - 1);
        sum += aPrev(x + 1, y - 1);
        sum += aPrev(x - 1, y + 1);
        data[(y * w + x) * 4 + 3] = Math.round(sum / 9);
      }
    }
  }
  return imgData;
}

async function removeVoidAndCropToPng(urlOrDataUrl: string): Promise<string> {
  const img = await loadImage(urlOrDataUrl);

  const canvas = document.createElement("canvas");
  canvas.width = img.naturalWidth || img.width;
  canvas.height = img.naturalHeight || img.height;

  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  if (!ctx) throw new Error("No canvas context for void removal");

  ctx.drawImage(img, 0, 0);

  const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);

// 1) Remove background (flood fill from borders)
let cleared = floodFillBackgroundToTransparent(imgData);

cleared = removeEnclosedBackgroundIslands(cleared);

// 2) 🔧 ERODE MATTE by 1px to kill halo artifacts
// Fix Edges For 3D Renders
// First Number Is Edge Pixels
// Second Number Is Alpha Threshold
// Kills Halo
cleared = erodeAlpha(cleared, 3, 10);

// restore smooth edge (anti-alias)
cleared = featherAlpha(cleared, 1);

ctx.putImageData(cleared, 0, 0);

// 3) Crop tightly to remaining opaque pixels
const finalData = ctx.getImageData(0, 0, canvas.width, canvas.height);
return cropToAlpha(finalData);

}

// =========================================================
// MATERIAL GUIDE PRESETS (SOURCE OF TRUTH)
// =========================================================
const MATERIAL_GUIDES = {
  gold: {
    exposureTarget: 160,
    liftBlacks: 12,
    microStrength: 12,
    softboxMainAlpha: 0.72,
    softboxSecondaryAlpha: 0.48,
    kickerAlpha: 0.34,
  },

  chrome: {
    // 🔥 CRITICAL DIFFERENCE
    exposureTarget: 185,   // chrome must start bright
    liftBlacks: 10,

    microStrength: 4,      // chrome is smooth
    softboxMainAlpha: 0.90, // strong mirror cue
    softboxSecondaryAlpha: 0.65,
    kickerAlpha: 0.45,
  },
} as const;


// 2. Blends optional user upload INTO the studio plate (reflection-only)
async function buildReflectionPlateDataUrl(
  preset: string,
  reflectionUrlOrNull: string | null,
  size: number
): Promise<string> {
  const plate = buildStudioPlate(preset, size);
  const ctx = makeReadCtx(plate);

  if (reflectionUrlOrNull) {
    const img = await loadImage(reflectionUrlOrNull);

    // draw upload as reflection content (desat + contrast-ish)
    const tmp = document.createElement("canvas");
    tmp.width = size; tmp.height = size;
    const tctx = makeReadCtx(tmp);

    tctx.drawImage(img, 0, 0, size, size);

    // desaturate + boost contrast (simple + fast)
    const d = tctx.getImageData(0, 0, size, size);
    const px = d.data;
    for (let i = 0; i < px.length; i += 4) {
      const r = px[i], g = px[i + 1], b = px[i + 2];
      const l = (0.2126 * r + 0.7152 * g + 0.0722 * b); // luma
      let v = (l - 128) * 1.35 + 128; // contrast
      v = Math.max(0, Math.min(255, v));
      px[i] = px[i + 1] = px[i + 2] = v;
      px[i + 3] = 255;
    }
    tctx.putImageData(d, 0, 0);

    // blend into plate gently
    ctx.save();
    ctx.globalCompositeOperation = "overlay";
    ctx.globalAlpha = preset === "silver" ? 0.55 : 0.35; // chrome wants more reflection content
    ctx.drawImage(tmp, 0, 0);
    ctx.restore();
  }

  return plate.toDataURL("image/jpeg", 0.92);
}

// Keep component identity stable across Page updates so font readiness and
// composition/critique guards survive commits back to the parent.
const COCO_CANDIDATE_COLORS: Record<string, string> = {
  headline: "rgba(250, 204, 21, 0.95)",
  accent: "rgba(34, 211, 238, 0.95)",
  details: "rgba(74, 222, 128, 0.95)",
  date: "rgba(251, 146, 60, 0.95)",
  price: "rgba(244, 114, 182, 0.95)",
  venue: "rgba(167, 139, 250, 0.95)",
  presenter: "rgba(96, 165, 250, 0.95)",
  compliance: "rgba(248, 113, 113, 0.95)",
};

function cocoHeadlineClearsFixedObstacles(
  role: CanvasTextCandidate["role"],
  rect: CanvasTextCandidate["rect"],
  obstacles: CocoHeadlineFixedObstacle[] | undefined
) {
  if (role !== "headline" || !obstacles?.length) return true;
  return obstacles.every((obstacle) => {
    const width = Math.max(
      0,
      Math.min(rect.x + rect.width, obstacle.x + obstacle.width) -
        Math.max(rect.x, obstacle.x)
    );
    const height = Math.max(
      0,
      Math.min(rect.y + rect.height, obstacle.y + obstacle.height) -
        Math.max(rect.y, obstacle.y)
    );
    const overlap =
      width * height /
      Math.max(1, Math.min(rect.width * rect.height, obstacle.width * obstacle.height));
    return overlap <= (obstacle.role === "accent" ? 0.24 : 0.08);
  });
}

function CocoCanvasCandidateDebug({
  background,
  commitEnabled,
  copy,
  debugVisible,
  enabled,
  fixedHeadlineObstacles,
  format,
  headlineOnly,
  layoutId,
  model,
  onComposition,
}: {
  background: {
    url: string | null;
    positionX: number;
    positionY: number;
    scale: number;
    rotation: number;
  };
  copy: Partial<
    Record<
      CanvasTextCandidate["role"],
      { text: string; style: CopyCapacityStyle }
    >
  >;
  commitEnabled: boolean;
  debugVisible: boolean;
  enabled: boolean;
  fixedHeadlineObstacles?: CocoHeadlineFixedObstacle[];
  format: "square" | "story";
  headlineOnly?: boolean;
  layoutId?: string | null;
  model: CanvasSubjectModel | null;
  onComposition?: (composition: CanvasCompositionResult) => void;
}) {
  const [candidates, setCandidates] = React.useState<
    Array<CanvasTextCandidate & { capacity?: CopyCapacityResult }>
  >([]);
  const [composition, setComposition] = React.useState<CanvasCompositionResult | null>(null);
  const [environmentCells, setEnvironmentCells] = React.useState<CanvasEnvironmentCell[]>([]);
  const [subjectCells, setSubjectCells] = React.useState<CanvasInteractionCell[]>([]);
  const [renderCritique, setRenderCritique] = React.useState<ReturnType<typeof critiqueRenderedComposition> | null>(null);
  const signatureRef = React.useRef("");
  const sourceSignatureRef = React.useRef("");
  const critiqueSceneSignatureRef = React.useRef("");
  const compositionRef = React.useRef<CanvasCompositionResult | null>(null);
  const critiqueAttemptsRef = React.useRef(0);
  const headlineFontSpec = copy.headline;
  const fixedHeadlineObstacleSignature = (fixedHeadlineObstacles ?? [])
    .map((rect) => `${rect.role}:${rect.x},${rect.y},${rect.width},${rect.height}`)
    .join("|");
  const headlineFontSignature = headlineFontSpec
    ? [
        layoutId ?? "",
        headlineFontSpec.text,
        headlineFontSpec.style.fontFamily,
        headlineFontSpec.style.fontWeight ?? 700,
        headlineFontSpec.style.fontStyle ?? "normal",
      ].join("|")
    : "";
  const [readyHeadlineFontSignature, setReadyHeadlineFontSignature] =
    React.useState("");

  React.useEffect(() => {
    if (!enabled || !headlineFontSpec || !headlineFontSignature) {
      setReadyHeadlineFontSignature("");
      return;
    }
    let cancelled = false;
    const fontSet = document.fonts;
    const descriptor = `${headlineFontSpec.style.fontStyle ?? "normal"} ${
      headlineFontSpec.style.fontWeight ?? 700
    } 64px ${headlineFontSpec.style.fontFamily}`;
    const sample = headlineFontSpec.text.trim() || "M";
    const primaryFamily = headlineFontSpec.style.fontFamily
      .split(",")[0]
      ?.trim()
      .replace(/^['"]|['"]$/g, "") ?? "";
    const normalizedPrimaryFamily = normalizeFontFamilyName(primaryFamily);
    const primaryIsDeclaredLocalFace = Object.keys(FONT_FILE_MAP).some(
      (family) => normalizeFontFamilyName(family) === normalizedPrimaryFamily
    );

    // Canvas measurements taken before custom faces settle produce a valid
    // looking, but wrong, one-line/two-line decision. Do not let those
    // fallback metrics become a saved Coco plan.
    if (!fontSet?.load) {
      setReadyHeadlineFontSignature(headlineFontSignature);
      return;
    }
    void fontSet.load(descriptor, sample)
      .then(async (loadedFaces) => {
        await fontSet.ready;
        if (cancelled) return;
        const primaryFaceLoaded = loadedFaces.some(
          (face) => normalizeFontFamilyName(face.family) === normalizedPrimaryFamily
        );
        if (primaryIsDeclaredLocalFace && !primaryFaceLoaded) {
          setReadyHeadlineFontSignature("");
          return;
        }
        setReadyHeadlineFontSignature(headlineFontSignature);
      })
      .catch(() => {
        // Do not persist a structural decision measured with an accidental
        // fallback face. The artboard can keep its existing title while the
        // requested font remains unavailable.
        if (!cancelled) setReadyHeadlineFontSignature("");
      });
    return () => {
      cancelled = true;
    };
  }, [enabled, headlineFontSignature]);

  React.useEffect(() => {
    if (!enabled || !model?.source.maskDataUrl) {
      setSubjectCells((current) => (current.length ? [] : current));
      return;
    }
    let cancelled = false;
    const image = new Image();
    image.onload = () => {
      if (cancelled) return;
      const width = Math.max(1, image.naturalWidth || model.source.maskWidth || 1);
      const height = Math.max(1, image.naturalHeight || model.source.maskHeight || 1);
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const context = canvas.getContext("2d", { willReadFrequently: true });
      if (!context) return;
      context.drawImage(image, 0, 0, width, height);
      const rgba = context.getImageData(0, 0, width, height).data;
      const alpha = new Uint8ClampedArray(width * height);
      for (let index = 0; index < alpha.length; index += 1) {
        alpha[index] = rgba[index * 4 + 3] ?? 0;
      }
      const interaction = buildSubjectInteractionMap({
        alpha,
        width,
        height,
        regions: model.regions,
        columns: 24,
        alphaThreshold: model.source.maskThreshold,
      });
      const cells = interaction.cells.map((cell) => {
        const canvasRect = canvasRectToPercent(
          transformCanvasSubjectRect(model, {
            x: cell.xPct / 100 * model.source.width,
            y: cell.yPct / 100 * model.source.height,
            width: cell.widthPct / 100 * model.source.width,
            height: cell.heightPct / 100 * model.source.height,
          }),
          model.canvas
        );
        return {
          ...cell,
          canvasX: canvasRect.x,
          canvasY: canvasRect.y,
          canvasWidth: canvasRect.width,
          canvasHeight: canvasRect.height,
        };
      });
      if (!cancelled) setSubjectCells(cells);
    };
    image.onerror = () => {
      if (!cancelled) {
        setSubjectCells((current) => (current.length ? [] : current));
      }
    };
    image.src = model.source.maskDataUrl;
    return () => {
      cancelled = true;
    };
  }, [enabled, model]);

  React.useEffect(() => {
    if (!enabled || !model || !background.url) {
      setEnvironmentCells((current) => (current.length ? [] : current));
      return;
    }
    let cancelled = false;
    const image = new Image();
    image.onload = () => {
      if (cancelled) return;
      const width = 240;
      const height = Math.max(1, Math.round(width * model.canvas.height / model.canvas.width));
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const context = canvas.getContext("2d", { willReadFrequently: true });
      if (!context) return;
      const coverScale = Math.max(width / image.naturalWidth, height / image.naturalHeight);
      const scale = coverScale * Math.max(0.01, background.scale);
      const drawnWidth = image.naturalWidth * scale;
      const drawnHeight = image.naturalHeight * scale;
      const x = (width - drawnWidth) * background.positionX / 100;
      const y = (height - drawnHeight) * background.positionY / 100;
      context.save();
      context.translate(x + drawnWidth / 2, y + drawnHeight / 2);
      context.rotate(background.rotation * Math.PI / 180);
      context.drawImage(
        image,
        -drawnWidth / 2,
        -drawnHeight / 2,
        drawnWidth,
        drawnHeight
      );
      context.restore();
      try {
        const rgba = context.getImageData(0, 0, width, height).data;
        const subjectBoundsPct = canvasRectToPercent(
          model.silhouetteBounds,
          model.canvas
        );
        const map = buildCanvasEnvironmentMap({
          rgba,
          width,
          height,
          columns: 24,
          subjectBoundsPct,
        });
        if (!cancelled) setEnvironmentCells(map.cells);
      } catch {
        if (!cancelled) {
          setEnvironmentCells((current) => (current.length ? [] : current));
        }
      }
    };
    image.onerror = () => {
      if (!cancelled) {
        setEnvironmentCells((current) => (current.length ? [] : current));
      }
    };
    image.src = background.url;
    return () => {
      cancelled = true;
    };
  }, [
    background.positionX,
    background.positionY,
    background.rotation,
    background.scale,
    background.url,
    enabled,
    model,
  ]);

  React.useEffect(() => {
    if (
      !enabled ||
      !model ||
      subjectCells.length === 0 ||
      readyHeadlineFontSignature !== headlineFontSignature
    ) {
      setCandidates((current) => (current.length ? [] : current));
      setComposition(null);
      compositionRef.current = null;
      signatureRef.current = "";
      sourceSignatureRef.current = "";
      critiqueSceneSignatureRef.current = "";
      return;
    }
      const subjectChecksum = subjectCells.reduce(
        (sum, cell, index) => sum +
          (index + 1) * cell.subjectCoverage *
          (cell.canvasX + cell.canvasY + cell.canvasWidth + cell.canvasHeight),
        0
      );
      const critiqueSceneSignature = [
        background.url,
        background.positionX,
        background.positionY,
        background.scale,
        background.rotation,
        subjectChecksum.toFixed(3),
        ...Object.entries(copy).map(([role, spec]) =>
          `${role}:${spec?.text ?? ""}:${spec?.style.fontFamily ?? ""}:${
            spec?.style.fontWeight ?? ""
          }:${spec?.style.fontStyle ?? ""}:${spec?.style.letterSpacingPx ?? ""}:${
            spec?.style.lineHeight ?? ""
          }`
        ),
      ].join("|");
      if (critiqueSceneSignature !== critiqueSceneSignatureRef.current) {
        critiqueSceneSignatureRef.current = critiqueSceneSignature;
        critiqueAttemptsRef.current = 0;
        setRenderCritique(null);
      }
      const dynamicCandidates = generateCanvasTextCandidates({
        cells: subjectCells,
        copyTextByRole: Object.fromEntries(
          Object.entries(copy).map(([role, spec]) => [role, spec?.text ?? ""])
        ),
        environmentCells,
        roles: headlineOnly
          ? ["headline"]
          : ["headline", "accent", "details", "date", "price", "venue", "presenter", "compliance"],
        maxPerRole: 8,
        coordinated: false,
      });
      const generated = dynamicCandidates.filter(
        (candidate) =>
          cocoHeadlineClearsFixedObstacles(
            candidate.role,
            candidate.rect,
            fixedHeadlineObstacles
          )
      );
      const measureCanvas = document.createElement("canvas");
      const measureContext = measureCanvas.getContext("2d");
      const measureCandidateRun = (
        text: string,
        size: number,
        style: CopyCapacityStyle,
        letterSpacingPx = Number(style.letterSpacingPx ?? 0)
      ) => {
        if (!measureContext) return { width: 0, ascent: 0, descent: 0 };
        measureContext.font = `${style.fontStyle ?? "normal"} ${
          style.fontWeight ?? 700
        } ${size}px ${style.fontFamily}`;
        const metrics = measureContext.measureText(text || " ");
        return {
          width:
            metrics.width +
            Math.max(0, Array.from(text || " ").length - 1) * letterSpacingPx,
          ascent: Number(metrics.actualBoundingBoxAscent) || size * 0.82,
          descent: Number(metrics.actualBoundingBoxDescent) || size * 0.22,
        };
      };
      const fitCandidate = (
        candidate: CanvasTextCandidate,
        rect = candidate.rect
      ) => {
        const spec = copy[candidate.role];
        if (!spec || !measureContext) return undefined;
        const candidateText = candidate.textVariant ?? spec.text;
        const candidateLineCount = candidateText.split(/\r?\n/).filter(Boolean).length;
        const candidateLineHeight = Number(
          candidate.referenceLineHeight ?? spec.style.lineHeight ?? 1
        );
        const effectiveLineHeight =
          candidate.role === "headline" &&
          candidateLineCount > 1 &&
          !candidate.referenceLayoutId?.startsWith("template:")
            ? Math.max(1.02, candidateLineHeight)
            : candidateLineHeight;
        return calculateCopyCapacity({
          role: candidate.role,
          text: candidateText,
          zone: {
            width: rect.width / 100 * model.canvas.width,
            height: rect.height / 100 * model.canvas.height,
          },
          style: {
            ...spec.style,
            fontFamily: candidate.referenceFontFamily ?? spec.style.fontFamily,
            lineHeight: effectiveLineHeight,
            letterSpacingPx: candidate.referenceLetterSpacing != null
              ? candidate.referenceLetterSpacing * Number(candidate.referenceFontSize ?? 24)
              : spec.style.letterSpacingPx,
            maxLines:
              candidate.role === "headline" && candidate.textVariant
                ? Math.max(1, candidate.textVariant.split(/\r?\n/).filter(Boolean).length)
                : candidate.referenceMaxLines ?? spec.style.maxLines,
            maxFontSize: candidate.referenceFontSize ?? spec.style.maxFontSize,
          },
          measure: (text, size, style) => measureCandidateRun(text, size, style),
        });
      };
      const resolveHeadlineCandidate = (
        candidate: CanvasTextCandidate
      ): { textVariant: string; capacity: CopyCapacityResult } | null => {
        const spec = copy.headline;
        if (!spec || !measureContext || candidate.rect.width < 70) return null;
        const fontFamily = candidate.referenceFontFamily ?? spec.style.fontFamily;
        const fontWeight = candidate.referenceFontWeight ?? spec.style.fontWeight ?? 900;
        const fontStyle = spec.style.fontStyle ?? "normal";
        const lineHeight = Math.max(
          0.8,
          Number(candidate.referenceLineHeight ?? spec.style.lineHeight ?? 1.05)
        );
        const zoneWidth = candidate.rect.width / 100 * model.canvas.width;
        const zoneHeight = candidate.rect.height / 100 * model.canvas.height;
        const usableWidth = Math.max(1, zoneWidth * COCO_HEADLINE_SAFE_WIDTH_FILL);
        const usableHeight = Math.max(1, zoneHeight * COCO_HEADLINE_SAFE_HEIGHT_FILL);
        const plan = resolveHeadlineLockup({
          text: spec.text,
          safeZone: {
            width: usableWidth,
            height: usableHeight,
            widthPct: candidate.rect.width,
          },
          minFontSize: Math.max(
            cocoHeadlineMinimumSize(format),
            Number(spec.style.minFontSize ?? cocoHeadlineMinimumSize(format))
          ),
          maxFontSize: Math.max(
            cocoHeadlineMinimumSize(format),
            Number(
              candidate.referenceFontSize ??
                spec.style.maxFontSize ??
                cocoHeadlineMaximumSize(format)
            )
          ),
          measurePaintBounds: (text, fontSize) => {
            const lines = text.split(/\r?\n/).filter(Boolean);
            const effectiveLineHeight =
              lines.length > 1 && !candidate.referenceLayoutId?.startsWith("template:")
                ? Math.max(1.02, lineHeight)
                : lineHeight;
            const letterSpacingPx = candidate.referenceLetterSpacing != null
              ? candidate.referenceLetterSpacing * fontSize
              : Number(spec.style.letterSpacingEm ?? 0) * fontSize +
                Number(spec.style.letterSpacingPx ?? 0);
            const strokeWidth = Math.max(0, Number(spec.style.strokeWidth ?? 0));
            const style: CopyCapacityStyle = {
              ...spec.style,
              fontFamily,
              fontWeight,
              fontStyle,
              lineHeight,
            };
            const runs = lines.map((line) =>
              measureCandidateRun(line, fontSize, style, letterSpacingPx)
            );
            if (!runs.length) return null;
            const lineWidths = runs.map((run) => run.width);
            return {
              width: Math.max(...lineWidths) + strokeWidth * 2,
              height:
                runs[0].ascent +
                runs[runs.length - 1].descent +
                Math.max(0, runs.length - 1) * fontSize * effectiveLineHeight +
                strokeWidth * 2,
              lineWidths,
            };
          },
        });
        if (!plan) return null;
        const widthUse = plan.bounds.width / usableWidth;
        const heightUse = plan.bounds.height / usableHeight;
        return {
          textVariant: plan.text,
          capacity: {
            role: "headline",
            fits: plan.fits,
            fontSize: plan.fontSize,
            lines: plan.lines,
            lineCount: plan.lineCount,
            textWidth: plan.bounds.width,
            textHeight: plan.bounds.height,
            occupancy: Math.min(1, widthUse * heightUse),
            breathingRoom: Math.max(0, 1 - Math.max(widthUse, heightUse)),
            ...(plan.fits ? {} : { reason: "below-minimum-size" as const }),
          },
        };
      };
      const next: Array<
        CanvasTextCandidate & { capacity?: CopyCapacityResult }
      > = generated.flatMap((candidate) => {
        if (candidate.role === "headline") {
          const resolved = resolveHeadlineCandidate(candidate);
          return resolved
            ? [{ ...candidate, textVariant: resolved.textVariant, capacity: resolved.capacity }]
            : [];
        }
        const capacity = fitCandidate(candidate);
        return [{ ...candidate, ...(capacity ? { capacity } : {}) }];
      });
      const sourceSignature = next
        .map(
          (candidate) =>
            `${candidate.id}:${candidate.score.toFixed(2)}:${candidate.subjectOverlap.toFixed(
              3
            )}:${candidate.capacity?.fontSize ?? 0}:${candidate.capacity?.fits ?? false}:${candidate.textVariant ?? ""}`
        )
        .join("|");
      if (sourceSignature !== sourceSignatureRef.current) {
        sourceSignatureRef.current = sourceSignature;
        setRenderCritique(null);
      }
      const signature = sourceSignature;
      if (signature !== signatureRef.current) {
        signatureRef.current = signature;
        const capacityChecked = next.filter(
          (candidate): candidate is CapacityCheckedCandidate =>
            Boolean(candidate.capacity)
        );
        const globalResolution = (() => {
              const selectedComposition = chooseCanvasComposition({
                candidates: capacityChecked,
                requiredRoles: capacityChecked
                  .filter((candidate) => candidate.capacity.fits)
                  .map((candidate) => candidate.role),
              });
              const resolved = resolveCompositionLockups({
                composition: selectedComposition,
                refit: (candidate, rect) => fitCandidate(candidate, rect) ?? candidate.capacity,
                validate: (candidate, rect) =>
                  evaluateCanvasRectInteraction({ role: candidate.role, rect, cells: subjectCells })
                    .interaction.allowed &&
                  cocoHeadlineClearsFixedObstacles(
                    candidate.role,
                    rect,
                    fixedHeadlineObstacles
                  ),
              });
              const resolvedComposition = rescoreCanvasComposition({
                placements: resolved.placements,
                rejectedCandidateCount: selectedComposition.rejectedCandidateCount,
              });
              const subjectWeight = subjectCells.reduce(
                (sum, cell) => sum + cell.subjectCoverage * cell.canvasWidth * cell.canvasHeight,
                0
              );
              const subjectCenterX = subjectWeight > 0
                ? subjectCells.reduce(
                    (sum, cell) => sum +
                      (cell.canvasX + cell.canvasWidth / 2) *
                      cell.subjectCoverage * cell.canvasWidth * cell.canvasHeight,
                    0
                  ) / subjectWeight
                : 50;
              return resolveGlobalComposition({
                composition: resolvedComposition,
                subjectCenterX,
                validate: (candidate, rect) =>
                  evaluateCanvasRectInteraction({ role: candidate.role, rect, cells: subjectCells })
                    .interaction.allowed &&
                  cocoHeadlineClearsFixedObstacles(
                    candidate.role,
                    rect,
                    fixedHeadlineObstacles
                  ),
                quality: (_candidate, rect) => {
                  const localCells = environmentCells.filter((cell) => {
                    const width = Math.max(0, Math.min(rect.x + rect.width, cell.x + cell.width) - Math.max(rect.x, cell.x));
                    const height = Math.max(0, Math.min(rect.y + rect.height, cell.y + cell.height) - Math.max(rect.y, cell.y));
                    return width * height > 0;
                  });
                  return localCells.length ? scoreEnvironmentCells(localCells).readability : 0.5;
                },
              });
            })();
        compositionRef.current = globalResolution.composition;
        setComposition(globalResolution.composition);
        setCandidates(globalResolution.composition.placements);
      }
      if (commitEnabled && compositionRef.current) {
        onComposition?.(compositionRef.current);
      }
  }, [
    background.positionX,
    background.positionY,
    background.rotation,
    background.scale,
    background.url,
    commitEnabled,
    copy,
    enabled,
    environmentCells,
    fixedHeadlineObstacles,
    fixedHeadlineObstacleSignature,
    format,
    headlineFontSignature,
    headlineOnly,
    layoutId,
    model,
    onComposition,
    readyHeadlineFontSignature,
    subjectCells,
  ]);

  React.useEffect(() => {
    if (!enabled || !commitEnabled || !composition?.placements.length || !model) return;
    let cancelled = false;
    const inspect = () => {
      if (cancelled) return;
      const nodes = Array.from(
        document.querySelectorAll<HTMLElement>('[data-node="cocoTypographyZoneText"]')
      );
      const evidence = nodes.flatMap((node) => {
        const source = node.dataset.ownedSources?.split(",")[0];
        const role = source === "script" ? "accent" : source;
        const placement = composition.placements.find((candidate) => candidate.role === role);
        const child = node.firstElementChild as HTMLElement | null;
        const canvas = node.offsetParent as HTMLElement | null;
        if (!placement || !child || !canvas) return [];
        const canvasRect = canvas.getBoundingClientRect();
        const childRect = child.getBoundingClientRect();
        const range = document.createRange();
        range.selectNodeContents(child);
        const inkRect = range.getBoundingClientRect();
        range.detach();
        if (canvasRect.width <= 0 || canvasRect.height <= 0) return [];
        return [{
          allocatedRect: placement.rect,
          candidateId: placement.id,
          role: placement.role,
          rect: {
            x: (inkRect.left - canvasRect.left) / canvasRect.width * 100,
            y: (inkRect.top - canvasRect.top) / canvasRect.height * 100,
            width: inkRect.width / canvasRect.width * 100,
            height: inkRect.height / canvasRect.height * 100,
          },
          overflowX: Math.max(0, child.scrollWidth - child.clientWidth),
          overflowY: Math.max(0, childRect.bottom - node.getBoundingClientRect().bottom),
        }];
      });
      if (!evidence.length) return;
      const critique = critiqueRenderedComposition({
        zones: evidence,
        faceRect: model.faceBounds ? canvasRectToPercent(model.faceBounds, model.canvas) : null,
        subjectCells,
      });
      setRenderCritique(critique);
      if (critique.passed || critiqueAttemptsRef.current >= 3) return;
      if (composition.placements.some((candidate) => candidate.referenceLayoutId?.startsWith("template:"))) {
        return;
      }
      const repair = repairRenderedComposition({
        composition,
        critique,
        validate: (candidate, rect) =>
          evaluateCanvasRectInteraction({
            role: candidate.role,
            rect,
            cells: subjectCells,
          }).interaction.allowed &&
          cocoHeadlineClearsFixedObstacles(
            candidate.role,
            rect,
            fixedHeadlineObstacles
          ),
      });
      if (repair.changed) {
        critiqueAttemptsRef.current += 1;
        compositionRef.current = repair.composition;
        setComposition(repair.composition);
        setCandidates(repair.composition.placements);
        onComposition?.(repair.composition);
      }
    };
    const timer = window.setTimeout(() => {
      if (document.fonts?.ready) void document.fonts.ready.then(inspect);
      else inspect();
    }, 160);
    return () => {
      cancelled = true;
      window.clearTimeout(timer);
    };
  }, [
    commitEnabled,
    composition,
    enabled,
    fixedHeadlineObstacles,
    fixedHeadlineObstacleSignature,
    model,
    onComposition,
    subjectCells,
  ]);

  if (!debugVisible || candidates.length === 0) return null;
  return (
    <div
      data-nonexport="true"
      data-coco-debug-candidate-zones="true"
      className="pointer-events-none absolute inset-0"
      style={{ zIndex: 1210 }}
    >
      {composition && (
        <div
          data-coco-composition-director="true"
          data-coco-composition-score={composition.score.toFixed(2)}
          data-coco-composition-balance-penalty={composition.diagnostics.balancePenalty.toFixed(2)}
          data-coco-composition-alignment-score={composition.diagnostics.alignmentScore.toFixed(2)}
          data-coco-composition-grammar={composition.diagnostics.grammarId}
          data-coco-composition-guide-count={composition.diagnostics.guideCount}
          data-coco-composition-symmetry-score={composition.diagnostics.symmetryScore.toFixed(2)}
          data-coco-composition-subject-integration={composition.diagnostics.subjectIntegrationScore.toFixed(2)}
          data-coco-composition-assembly-score={composition.diagnostics.assemblyScore.toFixed(2)}
          data-coco-composition-lockups={composition.assembly.lockups.length}
          data-coco-reference-layout={composition.placements.find((candidate) => candidate.referenceLayoutId)?.referenceLayoutId}
          data-coco-composition-shared-guide-score={composition.diagnostics.sharedGuideScore.toFixed(2)}
          data-coco-render-critique={renderCritique?.passed ? "pass" : renderCritique ? "repair" : "pending"}
          data-coco-render-issues={renderCritique?.issues.length ?? 0}
          style={{
            position: "absolute",
            left: 6,
            top: 6,
            zIndex: 2,
            padding: "4px 7px",
            borderRadius: 5,
            background: "rgba(8, 47, 73, 0.88)",
            color: "rgb(186, 230, 253)",
            fontSize: 8,
            fontWeight: 800,
            letterSpacing: "0.04em",
            textTransform: "uppercase",
          }}
        >
          {composition.diagnostics.grammarId} · composition {composition.score.toFixed(0)} · balance -
          {composition.diagnostics.balancePenalty.toFixed(0)} · align +
          {composition.diagnostics.alignmentScore.toFixed(0)} · subject {composition.diagnostics.subjectIntegrationScore >= 0 ? "+" : ""}
          {composition.diagnostics.subjectIntegrationScore.toFixed(0)}
          {` · assembly ${composition.diagnostics.assemblyScore >= 0 ? "+" : ""}${composition.diagnostics.assemblyScore.toFixed(0)}`}
          {composition.placements.find((candidate) => candidate.referenceLayoutId)?.referenceLayoutId
            ? ` · ref ${composition.placements.find((candidate) => candidate.referenceLayoutId)?.referenceLayoutId}`
            : " · ref dynamic"}
          {renderCritique
            ? ` · render ${renderCritique.passed ? "pass" : `repair ${renderCritique.issues.length}`}`
            : " · render pending"}
        </div>
      )}
      {environmentCells.map((cell) => (
        <div
          key={`environment-${cell.row}-${cell.column}`}
          data-coco-environment-cell="true"
          data-coco-environment-complexity={cell.complexity.toFixed(3)}
          data-coco-environment-negative-space={cell.negativeSpace.toFixed(3)}
          data-coco-environment-readability={Math.max(
            cell.lightTextReadability,
            cell.darkTextReadability
          ).toFixed(3)}
          data-coco-environment-region={cell.relativeRegion}
          title={`${cell.relativeRegion} · negative space ${Math.round(
            cell.negativeSpace * 100
          )}% · complexity ${Math.round(cell.complexity * 100)}%`}
          style={{
            position: "absolute",
            left: `${cell.x}%`,
            top: `${cell.y}%`,
            width: `${cell.width}%`,
            height: `${cell.height}%`,
            background: `rgba(45, 212, 191, ${cell.negativeSpace * 0.14})`,
            border: `0.5px solid rgba(45, 212, 191, ${
              0.05 + cell.negativeSpace * 0.18
            })`,
            boxSizing: "border-box",
          }}
        />
      ))}
      {candidates.map((candidate) => {
        const color = COCO_CANDIDATE_COLORS[candidate.role];
        const lockup = composition?.assembly.lockups.find((candidateLockup) =>
          candidateLockup.roles.includes(candidate.role)
        );
        return (
          <div
            key={candidate.id}
            data-coco-candidate-role={candidate.role}
            data-coco-candidate-score={candidate.score.toFixed(1)}
            data-coco-subject-interaction={candidate.interactionMode ?? "background"}
            data-coco-subject-interaction-score={(candidate.interactionScore ?? 0).toFixed(1)}
            data-coco-discovered-zone={candidate.discoveredZoneId}
            data-coco-discovered-zone-kind={candidate.discoveredZoneKind}
            data-coco-lockup={lockup?.id}
            data-coco-lockup-guide={lockup?.guide}
            data-coco-copy-fits={candidate.capacity?.fits ? "true" : "false"}
            data-coco-copy-font-size={candidate.capacity?.fontSize ?? 0}
            data-coco-copy-lines={candidate.capacity?.lineCount ?? 0}
            data-coco-copy-occupancy={candidate.capacity?.occupancy.toFixed(3)}
            data-coco-reference-layout={candidate.referenceLayoutId}
            data-coco-reference-source={candidate.referenceSourceUrl}
            data-coco-reference-font={candidate.referenceFontFamily}
            style={{
              position: "absolute",
              left: `${candidate.rect.x}%`,
              top: `${candidate.rect.y}%`,
              width: `${candidate.rect.width}%`,
              height: `${candidate.rect.height}%`,
              border: `1.5px solid ${color}`,
              background: color.replace(/0\.95\)$/, "0.045)"),
              boxSizing: "border-box",
            }}
          >
            <span
              style={{
                position: "absolute",
                left: 2,
                top: 2,
                padding: "2px 5px",
                borderRadius: 4,
                background: "rgba(0,0,0,0.78)",
                color,
                fontSize: 8,
                fontWeight: 800,
                lineHeight: 1.15,
                textTransform: "uppercase",
                whiteSpace: "nowrap",
              }}
            >
              {candidate.role} {candidate.score.toFixed(0)} · overlap{" "}
              {Math.round(candidate.subjectOverlap * 100)}%
              {candidate.discoveredZoneKind ? ` · ${candidate.discoveredZoneKind}` : ""}
              {lockup ? ` · ${lockup.id}/${lockup.guide}` : ""}
              {` · ${candidate.interactionMode ?? "background"} ${
                (candidate.interactionScore ?? 0) >= 0 ? "+" : ""
              }${(candidate.interactionScore ?? 0).toFixed(0)}`}
              {candidate.capacity
                ? candidate.capacity.fits
                  ? ` · ${candidate.capacity.fontSize}px/${candidate.capacity.lineCount}L · breathe ${Math.round(
                      candidate.capacity.breathingRoom * 100
                    )}%`
                  : ` · NO FIT (${candidate.capacity.reason})`
                : ""}
            </span>
          </div>
        );
      })}
    </div>
  );
}

