const deferCanvasPlacement = React.useCallback(
  (work: () => void, opts?: { scrollDelay?: number }) => {
    const run = () => {
      work();
      window.setTimeout(scrollToArtboard, opts?.scrollDelay ?? 120);
    };

    if (typeof window === "undefined") {
      run();
      return;
    }

    window.requestAnimationFrame(() => {
      window.setTimeout(run, 0);
    });
  },
  [scrollToArtboard]
);

