const [replaceSceneBusy, setReplaceSceneBusy] = React.useState(false);

// Quick Edit and Scene Builder share the same background-layer replacement.
const replaceSceneFromFile = async (file: File) => {
  if (blockBasicArtworkChange()) return;
  setReplaceSceneBusy(true);
  try {
    const dataUrl = await downscaleDataUrlIfNeeded(await blobToDataURL(file), undefined, "image/jpeg");
    const store = useFlyerState.getState();
    const patches = {} as Record<Format, any>;
    for (const target of ["square", "story"] as const) {
      patches[target] = withCocoRecipeBackground({
        ...(store.session[target] ?? {}),
        portraits: store.portraits[target],
        emojis: store.emojis[target],
      }, { backgroundDataUrl: dataUrl });
    }
    store.setSession(current => ({ ...current, square: patches.square, story: patches.story }));
    for (const target of ["square", "story"] as const) {
      store.setPortraits(target, patches[target].portraits);
      store.setEmojis(target, patches[target].emojis);
    }
    setBgUploadUrl(dataUrl);
    setBgUrl(dataUrl);
    setBgFitMode(false);
    setBgScale(1);
    setBgRotate(0);
    setBgPosX(50);
    setBgPosY(50);
    store.setSessionDirty(current => ({ ...current, square: true, story: true }));
  } catch (error) {
    alert(error instanceof Error ? `Could not replace scene: ${error.message}` : "Could not replace scene. Please try another image.");
  } finally {
    setReplaceSceneBusy(false);
  }
};

