const setTitleSkewFromUser = (role: "headline" | "headline2", value: number) => {
  const skew = Math.max(-45, Math.min(45, Number(value) || 0));
  if (role === "headline") {
    setHeadSkew(skew);
    setTextFx((current) => ({ ...current, skewAxis: "y" }));
  } else {
    setHead2Skew(skew);
    setHead2Fx((current) => ({ ...current, skewAxis: "y" }));
  }
  const store = useFlyerState.getState();
  store.setSession((current) => {
    const variant = current[format] as any;
    const system = variant?.cocoCompositionSystem;
    const object = system?.compiledDocument?.objects?.find((item: any) => item.semanticRole === role);
    return { ...current, [format]: { ...variant,
      [role === "headline" ? "headSkew" : "head2Skew"]: skew,
      [role === "headline" ? "textFx" : "head2Fx"]: {
        ...variant?.[role === "headline" ? "textFx" : "head2Fx"], skewAxis: "y",
      },
      ...(object ? { cocoCompositionSystem: { ...system, compiledObjectOverrides: {
        ...system.compiledObjectOverrides,
        [object.id]: { ...system.compiledObjectOverrides?.[object.id], skew, skewAxis: "y" },
      } } } : {}),
    } };
  });
  store.setSessionDirty((current) => ({ ...current, [format]: true }));
};

