      // measured from the rendered glyph bounds so winning fonts and line
      // sizes cannot push its band back over the subheadline.
      const subtagY = pct(heroBottom - rootRect.top + COCO_CENTER_SUBTAG_HERO_GAP_PX);
      const subtagHeight = subtagNode ? pct(subtagNode.getBoundingClientRect().height) : 5;
      const complianceRingNode = root.querySelector<HTMLElement>(
        '[data-portrait-id="coco_compliance_circular_text"]'
      );
      const socialHandleNode = root.querySelector<HTMLElement>('[data-node="socialHandle"]');
      const complianceNode = root.querySelector<HTMLElement>('[data-node="compliance"]');
      const entryNode = root.querySelector<HTMLElement>('[data-node="price"]');
      if (!Number.isFinite(subtagY)) return;
      const roundedSubtagY = Math.round(subtagY * 100) / 100;
      setSubtagY((currentY) => Math.abs(currentY - roundedSubtagY) < 0.05 ? currentY : roundedSubtagY);
      const store = useFlyerState.getState();
      store.setSessionValue(format, "subtagY", roundedSubtagY);
      const currentPortraits = (store.portraits?.[format] ?? []) as any[];
      // Form-owned social rows keep their recipe positions, including during hydration.
      if (currentPortraits.some(item => String(item.id).startsWith("coco-form-social-"))) return;
