  const applyManualCocoTextColor = React.useCallback(
    (role: CocoZoneTextRole | "subtag", color: string) => {
      const nextColor = String(color || "").trim();
      if (!nextColor) return;
      const compiledSolidFill = role === "headline" && hasCocoCompiledCanvas(useFlyerState.getState().session?.[format])
        ? { gradient: false }
        : {};
      const concretePatch: Record<string, unknown> = {};
      switch (role) {
        case "headline":
          setTextFx((current) => ({ ...current, ...compiledSolidFill, color: nextColor, strokeWidth: 0 }));
          Object.assign(concretePatch, {
            headColor: nextColor,
            headStrokeWidth: 0,
            textFx: { ...compiledSolidFill, color: nextColor, strokeWidth: 0 },
          });
          break;
        case "headline2":
          setHead2Color(nextColor);
          setHead2Fx((current) => ({ ...current, color: nextColor, strokeWidth: 0 }));
          Object.assign(concretePatch, {
            head2Color: nextColor,
            head2Fx: { color: nextColor, strokeWidth: 0 },
          });
          break;
        case "details":
          setBodyColor(nextColor);
          Object.assign(concretePatch, { bodyColor: nextColor, detailsColor: nextColor });
          break;
        case "details2":
          setDetails2Color(nextColor);
          concretePatch.details2Color = nextColor;
          break;
        case "venue":
          setVenueColor(nextColor);
          concretePatch.venueColor = nextColor;
          break;
        case "presenter":
          setPresenterColor(nextColor);
          concretePatch.presenterColor = nextColor;
          break;
        case "leftRail":
          setLeftRailColor(nextColor);
          concretePatch.leftRailColor = nextColor;
          break;
        case "rightRail":
          setRightRailColor(nextColor);
          concretePatch.rightRailColor = nextColor;
          break;
        case "socialHandle":
          setSocialHandleColor(nextColor);
          concretePatch.socialHandleColor = nextColor;
          break;
        case "date":
          setDateColor(nextColor);
          concretePatch.dateColor = nextColor;
          break;
        case "price":
          setPriceColor(nextColor);
          concretePatch.priceColor = nextColor;
          break;
        case "compliance":
          setComplianceColor(nextColor);
          concretePatch.complianceColor = nextColor;
          break;
        case "subtag":
          setSubtagTextColor(nextColor);
          concretePatch.subtagTextColor = nextColor;
          break;
      }

      const store = useFlyerState.getState();
      const currentSession = (store.session?.[format] ?? {}) as Record<string, any>;
      const manualRoles = isCocoLayoutEditable
        ? {
            ...((currentSession.cocoManualTextColorRoles ?? {}) as Record<string, boolean>),
            [role]: true,
          }
        : currentSession.cocoManualTextColorRoles;
      const nextScrims = {
        ...((currentSession.cocoZoneContrastScrims ?? {}) as CocoZoneContrastScrimMap),
      };
      if (role !== "subtag") delete nextScrims[role];
      if (isCocoLayoutEditable && role !== "subtag") {
        setCocoZoneContrastScrims((current) => {
          if (!current[role]) return current;
          const next = { ...current };
          delete next[role];
          return next;
        });
      }
      const nextSession = {
        ...currentSession,
        ...concretePatch,
        ...(isCocoLayoutEditable
          ? {
              cocoManualTextColorRoles: manualRoles,
              cocoZoneContrastScrims: nextScrims,
            }
          : {}),
        textFx: {
          ...(currentSession.textFx ?? {}),
          ...((concretePatch.textFx as Record<string, unknown> | undefined) ?? {}),
        },
        head2Fx: {
          ...(currentSession.head2Fx ?? {}),
          ...((concretePatch.head2Fx as Record<string, unknown> | undefined) ?? {}),
        },
      };
      store.setSession((previous) => ({ ...previous, [format]: nextSession }));
      if (cocoNativeReferenceTemplateId && store.setCocoLayoutSession) {
        const currentLayout = (
          store.cocoLayoutSessions?.[format]?.[cocoCenterLayoutOptionId] ?? {}
        ) as Record<string, any>;
        store.setCocoLayoutSession(format, cocoCenterLayoutOptionId, {
          ...currentLayout,
          ...concretePatch,
          cocoManualTextColorRoles: manualRoles,
          cocoZoneContrastScrims: nextScrims,
          textFx: {
            ...(currentLayout.textFx ?? {}),
            ...((concretePatch.textFx as Record<string, unknown> | undefined) ?? {}),
          },
          head2Fx: {
            ...(currentLayout.head2Fx ?? {}),
            ...((concretePatch.head2Fx as Record<string, unknown> | undefined) ?? {}),
          },
        });
      }
    },
    [
      cocoCenterLayoutOptionId,
      cocoNativeReferenceTemplateId,
      format,
      isCocoLayoutEditable,
    ]
  );

