          const railHeadlineLine1 = railHeadlineSplit.primary || centerHeadlineLine1;
          const railHeadlineLine2 = railHeadlineSplit.secondary || centerHeadlineLine2;
          // Rail is the same two editable hero objects rotated 90 degrees.
