            const handleToRsvpGap = 0.55;
            const complianceToEntryGap = 6.72;
            const venueY = topY + presenterToVenueGap;
            const dateY = venueY + venueToDateGap;
            const djY = dateY + topToDjGap;
            const policyY = djY + djToPolicyGap;
            const hero2Y = heroY + heroLineGap;
            const descriptionY = textLeftHeadlineLines[1]
