  function getCocoLearningSummary(templateOverride?: TemplateSpec | null): CocoComposerConceptSummary | null {
    const storeSnapshot = useFlyerState.getState().exportDesign?.();
    const activeFormat = (storeSnapshot?.format || format) as Format;
    const sessionVariant = ((storeSnapshot?.session as any)?.[activeFormat] ?? {}) as Record<string, unknown>;
    const template = templateOverride ?? activeTemplate;
    return (
      ((sessionVariant as any).cocoConceptSummary as CocoComposerConceptSummary | undefined) ??
      ((template as any)?.formats?.[activeFormat]?.cocoConceptSummary as CocoComposerConceptSummary | undefined) ??
      ((template as any)?.base?.cocoConceptSummary as CocoComposerConceptSummary | undefined) ??
      ((template as any)?.cocoConceptSummary as CocoComposerConceptSummary | undefined) ??
      null
    );
  }

  function getCocoLearningSuggestion(
    templateOverride?: TemplateSpec | null,
    suggestionOverride?: CocoLearningSuggestion | null
  ): CocoLearningSuggestion | null {
    if (suggestionOverride) return suggestionOverride;
    return getCocoLearningSummary(templateOverride)?.winner?.learningSuggestion ?? null;
  }

  function buildCurrentCocoLearningSnapshot(
    templateOverride?: TemplateSpec | null,
    outcome = "unknown"
  ): CocoLearningDesignSnapshot {
    const storeSnapshot = useFlyerState.getState().exportDesign?.();
    const activeFormat = (storeSnapshot?.format || format) as Format;
    const sessionVariant = ((storeSnapshot?.session as any)?.[activeFormat] ?? {}) as Record<string, unknown>;
    const template = templateOverride ?? activeTemplate;
    const summary = getCocoLearningSummary(template);
    const moodProfile =
      ((sessionVariant as any).cocoMoodProfile as CocoMoodProfile | undefined) ??
      ((template as any)?.formats?.[activeFormat]?.cocoMoodProfile as CocoMoodProfile | undefined) ??
      ((template as any)?.base?.cocoMoodProfile as CocoMoodProfile | undefined) ??
      ((template as any)?.cocoMoodProfile as CocoMoodProfile | undefined) ??
      null;
    const activeSessionDirty = Boolean((storeSnapshot?.sessionDirty as any)?.[activeFormat]);
    const palette = ((sessionVariant as any).palette ?? (template as any)?.base?.palette ?? null) as
      | Record<string, unknown>
      | null;

    return {
      artDirectorScores: (summary?.winner?.score ?? null) as Record<string, unknown> | null,
      effects: {
        clarity: (sessionVariant as any).clarity ?? null,
        contrast: (sessionVariant as any).contrast ?? null,
        filmGrade: (sessionVariant as any).filmGrade ?? null,
        grade: (sessionVariant as any).grade ?? null,
        haze: (sessionVariant as any).haze ?? null,
        saturation: (sessionVariant as any).saturation ?? null,
        vignetteStrength: (sessionVariant as any).vignetteStrength ?? null,
      },
      eventType:
        String(
          (sessionVariant as any).cocoNightlifeStyle ??
            (template as any)?.cocoNightlifeStyle ??
            (template as any)?.style ??
            moodProfile?.primaryMood ??
            "general-nightlife"
        ) || "general-nightlife",
      exportCount: 0,
      imageMood: moodProfile?.primaryMood ?? null,
      layout: {
        format: activeFormat,
        layoutId: summary?.winner?.learningSuggestion?.layoutId ?? null,
        portraitScale: (sessionVariant as any).portraitScale ?? null,
        portraitX: (sessionVariant as any).portraitX ?? null,
        portraitY: (sessionVariant as any).portraitY ?? null,
        templateId: template?.id ?? templateId ?? null,
      },
      paid: Boolean(hasPaidAccess),
      palette,
      typography: {
        detailsFamily: (sessionVariant as any).detailsFamily ?? null,
        detailsSize: (sessionVariant as any).detailsSize ?? null,
        headlineFamily: (sessionVariant as any).headlineFamily ?? null,
        headlineScale: (sessionVariant as any).headMaxPx && (sessionVariant as any).headlineSize
          ? Number((sessionVariant as any).headlineSize) / Math.max(Number((sessionVariant as any).headMaxPx), 1)
          : null,
        headlineSize: (sessionVariant as any).headlineSize ?? (sessionVariant as any).headMaxPx ?? null,
        subheadlineFamily: (sessionVariant as any).head2Family ?? null,
        subheadlineSize: (sessionVariant as any).head2Size ?? null,
        venueFamily: (sessionVariant as any).venueFamily ?? null,
        venueSize: (sessionVariant as any).venueSize ?? null,
      },
      userFinalEdits: {
        modified: activeSessionDirty,
        outcome,
        paletteChanged: activeSessionDirty && Boolean(palette),
      },
    };
  }

  function recordCocoLearningOutcome(input: {
    outcome: string;
    suggestion?: CocoLearningSuggestion | null;
    template?: TemplateSpec | null;
    templateId?: string | null;
    userAction?: CocoLearningUserAction;
  }) {
    const suggestion = getCocoLearningSuggestion(input.template ?? null, input.suggestion ?? null);
    if (!suggestion) return null;
    const snapshot = buildCurrentCocoLearningSnapshot(input.template ?? null, input.outcome);
    const eventType = String(suggestion.nightlifeStyle ?? snapshot.eventType ?? "general-nightlife");
    const userAction = {
      ...(input.userAction ?? {}),
      modified:
        input.userAction?.modified ??
        Boolean((snapshot.userFinalEdits as Record<string, unknown> | null | undefined)?.modified),
    };
    const event = buildCocoLearningEvent({
      cocoSuggestion: {
        ...suggestion,
        nightlifeStyle: suggestion.nightlifeStyle ?? eventType,
      },
      eventType,
      finalDesignSnapshot: snapshot,
      sessionId: cocoLearningSessionIdRef.current,
      templateId: input.templateId ?? input.template?.id ?? templateId ?? "unknown-template",
      userAction,
    });
    const result = recordCocoLearningEvent(event);
    void trackClientEvent("coco_learning_event", {
      properties: {
        event_type: event.eventType,
        layout_id: event.cocoSuggestion.layoutId,
        learning_outcome: input.outcome,
        palette_id: event.cocoSuggestion.paletteId,
        saved: Boolean(event.userAction.saved),
        exported: Boolean(event.userAction.exported),
        accepted: Boolean(event.userAction.accepted),
        coco_suggestion: event.cocoSuggestion,
        design_snapshot: event.finalDesignSnapshot,
        modified: Boolean(event.userAction.modified),
        score: event.cocoSuggestion.score,
        success_score: scoreCocoLearningSuccess(event),
        template_id: event.templateId,
        typography_id: event.cocoSuggestion.typographyId,
      },
    });
    return result;
  }

