useEffect(() => {
  const cleanup = installKeyboardNudge({
    moveMode: () => moveMode,
    moveTarget: () => moveTarget,
    getPos: (t) => {
      switch (t) {
        case 'headline':  return { x: headX,     y: headY };
        case 'headline2': return { x: head2X,    y: head2Y };
        case 'details':   return { x: detailsX,  y: detailsY };
        case 'details2':  return { x: details2X, y: details2Y };
        case 'venue':     return { x: venueX,    y: venueY };
        case 'subtag':    return { x: subtagX,   y: subtagY };
        case 'presenter': return { x: presenterX, y: presenterY };
        case 'leftRail':  return { x: leftRailX,  y: leftRailY };
        case 'rightRail': return { x: rightRailX, y: rightRailY };
        case 'date':      return { x: dateX,      y: dateY };
        case 'time':      return { x: timeX,      y: timeY };
        case 'price':     return { x: priceX,     y: priceY };
        case 'qr':        return { x: qrX,        y: qrY };
        case 'portrait': {
          const selectedStorePortrait = selectedPortraitId
            ? (portraits?.[format] || []).find((p: any) => p.id === selectedPortraitId)
            : null;
          return selectedStorePortrait
            ? { x: Number(selectedStorePortrait.x ?? 50), y: Number(selectedStorePortrait.y ?? 50) }
            : { x: portraitX, y: portraitY };
        }
        case 'logo':      return { x: logoX,     y: logoY };
        case 'background':return { x: bgPosX,    y: bgPosY };
        default:          return null;
      }
    },
        getRotate: (t) => {
      switch (t) {
        case 'headline':  return headRotate;
        case 'headline2': return head2Rotate;
        case 'details':   return detailsRotate;
        case 'details2':  return details2Rotate;
        case 'venue':     return venueRotate;
        case 'subtag':    return subtagRotate;
        case 'presenter': return presenterRotation;
        case 'leftRail':  return leftRailRotation;
        case 'rightRail': return rightRailRotation;
        case 'date':      return dateRotation;
        case 'logo':      return logoRotate;
        default:          return null;
      }
    },
    setRotate: (t, deg) => {
      switch (t) {
        case 'headline':  setHeadRotate(deg);  break;
        case 'headline2': setHead2Rotate(deg); break;
        case 'details':   setDetailsRotate(deg); break;
        case 'details2':  setDetails2Rotate(deg); break;
        case 'venue':     setVenueRotate(deg); break;
        case 'subtag':    setSubtagRotate(deg); break;
        case 'presenter': setPresenterRotation(deg); break;
        case 'leftRail':  setLeftRailRotation(deg); break;
        case 'rightRail': setRightRailRotation(deg); break;
        case 'date':      setDateRotation(deg); break;
        case 'logo':      setLogoRotate(deg); break;
      }
    },

    setPos: (t, x, y) => {
      switch (t) {
        case 'headline':   setHeadX(x);     setHeadY(y);     break;
        case 'headline2':  setHead2X(x);    setHead2Y(y);    break;
        case 'details':    setDetailsX(x);  setDetailsY(y);  break;
        case 'details2':   setDetails2X(x); setDetails2Y(y); break;
        case 'venue':      setVenueX(x);    setVenueY(y);    break;
        case 'subtag':     setSubtagX(x);   setSubtagY(y);   break;
        case 'presenter':  setPresenterX(x); setPresenterY(y); break;
        case 'leftRail':   setLeftRailX(x);  setLeftRailY(y);  break;
	        case 'rightRail':  setRightRailX(x); setRightRailY(y); break;
	        case 'date':       onDateMoveRafSafe(x, y);           break;
	        case 'time':       onTimeMoveRafSafe(x, y);           break;
	        case 'price':      onPriceMoveRafSafe(x, y);          break;
	        case 'qr':         setQrX(x);        setQrY(y);        break;
        case 'portrait': {
          const selectedStorePortrait = selectedPortraitId
            ? (portraits?.[format] || []).find((p: any) => p.id === selectedPortraitId)
            : null;
          if (selectedStorePortrait) {
            if (selectedStorePortrait.locked) return;
            updatePortrait(format, selectedStorePortrait.id, { x, y });
            break;
          }
          if (portraitLocked) return;
          setPortraitX(x);
          setPortraitY(y);
          break;
        }
        case 'logo':       setLogoX(x);     setLogoY(y);     break;
        case 'background': setBgPosX(x);    setBgPosY(y);    break;
      }
    }
  });
  return cleanup;
}, [
  moveMode, moveTarget,
  headX, headY, head2X, head2Y,
  detailsX, detailsY, details2X, details2Y,
  venueX, venueY, subtagX, subtagY,
  presenterX, presenterY, leftRailX, leftRailY, rightRailX, rightRailY,
  dateX, dateY, timeX, timeY, priceX, priceY, qrX, qrY,
  presenterRotation, leftRailRotation, rightRailRotation, dateRotation,
  portraitX, portraitY, logoX, logoY,
  bgPosX, bgPosY,
	  selectedPortraitId, portraits, format, updatePortrait, portraitLocked, onDateMoveRafSafe, onTimeMoveRafSafe, onPriceMoveRafSafe
	]);
