function CocoSubjectSemanticMaskDebug({
  bounds,
  label = false,
}: {
  bounds: CocoSubjectBounds;
  label?: boolean;
}) {
  const regions = React.useMemo(
    () => buildSubjectSemanticRegions(bounds),
    [
      bounds.width,
      bounds.height,
      bounds.alpha.x,
      bounds.alpha.y,
      bounds.alpha.width,
      bounds.alpha.height,
      bounds.face?.x,
      bounds.face?.y,
      bounds.face?.width,
      bounds.face?.height,
      bounds.hands,
      bounds.props,
    ]
  );
  const [interactionMap, setInteractionMap] = React.useState<SubjectInteractionMap | null>(null);
  const [poseEvidence, setPoseEvidence] = React.useState<SubjectPoseEvidence | null>(null);

  React.useEffect(() => {
    if (!bounds.maskDataUrl) {
      setInteractionMap(null);
      setPoseEvidence(null);
      return;
    }
    let cancelled = false;
    const image = new Image();
    image.onload = () => {
      if (cancelled) return;
      const width = Math.max(1, image.naturalWidth || Number(bounds.maskWidth) || 1);
      const height = Math.max(1, image.naturalHeight || Number(bounds.maskHeight) || 1);
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const context = canvas.getContext("2d", { willReadFrequently: true });
      if (!context) return;
      context.clearRect(0, 0, width, height);
      context.drawImage(image, 0, 0, width, height);
      const rgba = context.getImageData(0, 0, width, height).data;
      const alpha = new Uint8ClampedArray(width * height);
      for (let index = 0; index < alpha.length; index += 1) {
        alpha[index] = rgba[index * 4 + 3] ?? 0;
      }
      if (!cancelled) {
        setPoseEvidence(
          analyzeSubjectPose({
            alpha,
            maskWidth: width,
            maskHeight: height,
            sourceWidth: bounds.width,
            sourceHeight: bounds.height,
            face: bounds.face,
            alphaThreshold: bounds.maskThreshold ?? 18,
          })
        );
        setInteractionMap(
          buildSubjectInteractionMap({
            alpha,
            width,
            height,
            regions,
            columns: 24,
            alphaThreshold: bounds.maskThreshold ?? 18,
          })
        );
      }
    };
    image.src = bounds.maskDataUrl;
    return () => {
      cancelled = true;
    };
  }, [
    bounds.maskDataUrl,
    bounds.maskHeight,
    bounds.maskThreshold,
    bounds.maskWidth,
    regions,
  ]);

  if (!bounds.maskDataUrl) return null;

  return (
    <div
      data-coco-debug-semantic-subject="true"
      data-coco-subject-body-lean={poseEvidence?.bodyLean}
      data-coco-subject-open-side={poseEvidence?.openSide}
      data-coco-subject-pose-confidence={poseEvidence?.confidence.toFixed(3)}
      style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
    >
      {regions.map((region, regionIndex) => {
        const rect = region.rectPct;
        const independentlyDetected = region.kind === "hands" || region.kind === "prop";
        const regionKey = [
          region.kind,
          rect.x.toFixed(3),
          rect.y.toFixed(3),
          rect.width.toFixed(3),
          rect.height.toFixed(3),
          regionIndex,
        ].join(":");
        return (
          <div
            key={regionKey}
            data-coco-subject-region={region.kind}
            data-coco-subject-protection={region.protection}
            style={{
              position: "absolute",
              inset: 0,
              background: SUBJECT_REGION_DEBUG_COLORS[region.kind],
              clipPath: `inset(${rect.y}% ${Math.max(0, 100 - rect.x - rect.width)}% ${Math.max(
                0,
                100 - rect.y - rect.height
              )}% ${rect.x}%)`,
              ...(independentlyDetected
                ? {}
                : {
                    maskImage: `url("${bounds.maskDataUrl}")`,
                    WebkitMaskImage: `url("${bounds.maskDataUrl}")`,
                    maskPosition: "center",
                    WebkitMaskPosition: "center",
                    maskRepeat: "no-repeat",
                    WebkitMaskRepeat: "no-repeat",
                    maskSize: "100% 100%",
                    WebkitMaskSize: "100% 100%",
                  }),
              mixBlendMode: "screen",
            }}
          />
        );
      })}
      {interactionMap?.cells.map((cell) => {
        const headline = scoreInteractionCellsForRole([cell], "headline");
        const utility = scoreInteractionCellsForRole([cell], "details");
        const visible = cell.subjectCoverage > 0.01;
        return (
          <div
            key={`interaction-${cell.row}-${cell.column}`}
            data-coco-interaction-cell="true"
            data-coco-interaction-region={cell.region}
            data-coco-interaction-coverage={cell.subjectCoverage.toFixed(3)}
            data-coco-interaction-protection={cell.protection.toFixed(2)}
            data-coco-interaction-x={cell.xPct}
            data-coco-interaction-y={cell.yPct}
            data-coco-interaction-width={cell.widthPct}
            data-coco-interaction-height={cell.heightPct}
            data-coco-headline-allowed={headline.allowed ? "true" : "false"}
            data-coco-utility-allowed={utility.allowed ? "true" : "false"}
            title={`${cell.region} · coverage ${Math.round(
              cell.subjectCoverage * 100
            )}% · protection ${cell.protection.toFixed(2)} · headline ${
              headline.allowed ? "allowed" : "blocked"
            } · details ${utility.allowed ? "allowed" : "blocked"}`}
            style={{
              position: "absolute",
              left: `${cell.xPct}%`,
              top: `${cell.yPct}%`,
              width: `${cell.widthPct}%`,
              height: `${cell.heightPct}%`,
              background: visible
                ? `rgba(255, 255, 255, ${Math.min(
                    0.34,
                    0.05 + cell.protection * cell.subjectCoverage * 0.3
                  )})`
                : "transparent",
              border: visible
                ? `0.5px solid ${
                    headline.allowed
                      ? "rgba(74, 222, 128, 0.72)"
                      : "rgba(248, 113, 113, 0.82)"
                  }`
                : "none",
              boxSizing: "border-box",
            }}
          />
        );
      })}
      {label && (
        <span
          style={{
            position: "absolute",
            left: 8,
            bottom: 8,
            padding: "3px 7px",
            borderRadius: 999,
            background: "rgba(4, 47, 46, 0.86)",
            color: "rgb(207, 250, 254)",
            fontSize: 10,
            fontWeight: 800,
            letterSpacing: "0.06em",
            lineHeight: 1.2,
            textTransform: "uppercase",
            whiteSpace: "nowrap",
          }}
        >
          Semantic subject · {bounds.maskSource ?? "unknown"} · {bounds.maskWidth ?? "?"}×
          {bounds.maskHeight ?? "?"}
          {poseEvidence
            ? ` · lean ${poseEvidence.bodyLean} · open ${poseEvidence.openSide} · ${Math.round(
                poseEvidence.confidence * 100
              )}%`
            : ""}
          {` · hands ${bounds.hands?.length ?? 0} · props ${bounds.props?.length ?? 0}`}
        </span>
      )}
    </div>
  );
}

