function getFixedCocoPortraitFooterZones(
  layoutId: CocoSubjectLayoutId | string | null | undefined,
  formatName: Format
): CocoFooterRecipeZoneMap | null {
  if (!isFixedCocoPortraitLayout(layoutId)) return null;
  const zones = cloneCocoFooterZoneMap(getSubjectRightFixedCocoFooterZones(formatName));
  return layoutId === "subject-left" ? mirrorCocoFixedFooterZoneMap(zones) : zones;
}

function getFixedCocoPortraitRecipeZones(
  layoutId: CocoSubjectLayoutId | string | null | undefined,
  formatName: Format
): CocoComposerZoneMap | null {
  if (!isFixedCocoPortraitLayout(layoutId)) return null;
  const artDirectorZones = getCocoArtDirectorCompositionZones(layoutId, formatName);
  if (artDirectorZones) return artDirectorZones;
  const footerZones = getSubjectRightFixedCocoFooterZones(formatName);
  const zones = cloneCocoZoneMap(
    formatName === "story"
      ? {
          subject: { x: 48, y: 9, width: 52, height: 86, align: "center" },
          headline: { x: 6, y: 20, width: 47.5, height: 18, align: "left" },
          script: { x: 6, y: 35, width: 47.5, height: 11, align: "left" },
          presenter: { x: 6, y: 5, width: 47.5, height: 7, align: "left" },
          leftInfo: { x: 6, y: 50.5, width: 47.5, height: 11.5, align: "left" },
          rightInfo: { x: 6, y: 64, width: 47.5, height: 10.5, align: "left" },
          date: { x: 84, y: 86, width: 12, height: 8, align: "center" },
          price: { x: 76, y: 86, width: 8, height: 8, align: "center" },
          venue: footerZones?.venue ?? { x: 6, y: 80, width: 36, height: 9, align: "left" },
          subtag: { x: 78, y: 94.5, width: 18, height: 4.5, align: "center" },
        }
      : {
          subject: { x: 63.2, y: 8.5, width: 36.8, height: 91.5, align: "center" },
          headline: { x: 5.8, y: 18, width: 56.8, height: 19.2, align: "left" },
          script: { x: 5.8, y: 36, width: 56.8, height: 14.6, align: "left" },
          presenter: { x: 5.8, y: 6.2, width: 56.8, height: 7.4, align: "center" },
          leftInfo: { x: 5.8, y: 52.5, width: 56.8, height: 14.4, align: "left" },
          rightInfo: { x: 5.8, y: 68.7, width: 56.8, height: 14.2, align: "left" },
          date: { x: 82, y: 85.5, width: 14.5, height: 10.5, align: "center" },
          price: { x: 67.2, y: 85.5, width: 14.2, height: 10.5, align: "center" },
          venue: footerZones?.venue ?? { x: 5.8, y: 84.8, width: 30.2, height: 10.2, align: "left" },
          subtag: { x: 83, y: 96.2, width: 13.5, height: 3.4, align: "center" },
        }
  );
  return layoutId === "subject-left" ? mirrorCocoFixedZoneMap(zones) : zones;
}

function getCocoPriceCircleGuideRects(zone: CocoRecipeRect, formatName: Format) {
  const heightToWidth = formatName === "story" ? 16 / 9 : 1;
  const diameterWidthPct =
    Math.min(zone.width, zone.height * heightToWidth) * COCO_UTILITY_ZONE_FILL_RATIO;
  const diameterHeightPct = diameterWidthPct / heightToWidth;
  const circle: CocoRecipeRect = {
    x: zone.x + (zone.width - diameterWidthPct) / 2,
    y: zone.y + (zone.height - diameterHeightPct) / 2,
    width: diameterWidthPct,
    height: diameterHeightPct,
    align: "center",
  };
  const innerWidthPct = diameterWidthPct * COCO_PRICE_BADGE_INNER_RATIO;
  const innerHeightPct = diameterHeightPct * COCO_PRICE_BADGE_INNER_RATIO;
  return {
    circle,
    inner: {
      x: circle.x + (circle.width - innerWidthPct) / 2,
      y: circle.y + (circle.height - innerHeightPct) / 2,
      width: innerWidthPct,
      height: innerHeightPct,
      align: "center" as const,
    },
  };
}

function clampComposerNumber(value: unknown, fallback: number, min: number, max: number) {
  const number = Number(value);
  if (!Number.isFinite(number)) return fallback;
  return Math.max(min, Math.min(max, number));
}

function clampComposerRange(value: number, min: number, max: number) {
  return clampComposerNumber(value, value, min, max);
}

function scaleCocoTypeSize(value: number, scale: number, min: number, max: number) {
  const base = Number.isFinite(value) ? value : min;
  const factor = clampComposerNumber(scale, 1, 0.55, 1.45);
  return Math.round(clampComposerNumber(base * factor, base, min, max));
}

type CocoFitTextRole =
  | "date"
  | "details"
  | "details2"
  | "headline"
  | "headline2"
  | "presenter"
  | "price"
  | "subtag"
  | "venue";

function cocoFitTextLines(text: string) {
  return String(text || "")
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map((line) => line.replace(/\s+/g, " ").trim())
    .filter(Boolean);
}

function cocoRoleWidthFactor(role: CocoFitTextRole, formatName: Format) {
  const story = formatName === "story";
  switch (role) {
    case "headline":
      return story ? 12.8 : 13.6;
    case "headline2":
      return story ? 8.8 : 8.2;
    case "presenter":
      return story ? 8.6 : 8.1;
    case "date":
    case "price":
      return story ? 8.8 : 8.4;
    case "details":
      return story ? 8.8 : 8.2;
    case "details2":
      return story ? 8.3 : 7.7;
    case "venue":
    case "subtag":
    default:
      return story ? 8.4 : 7.8;
  }
}

function cocoRoleHeightFactor(role: CocoFitTextRole, formatName: Format) {
  const story = formatName === "story";
  switch (role) {
    case "headline":
      return story ? 6.6 : 5.8;
    case "headline2":
      return story ? 4.8 : 4.4;
    case "date":
    case "price":
      return story ? 5.2 : 4.8;
    case "details":
      return story ? 4.8 : 4.25;
    case "details2":
      return story ? 4.55 : 4.05;
    case "presenter":
      return story ? 4.5 : 4.0;
    case "venue":
    case "subtag":
    default:
      return story ? 4.45 : 3.95;
  }
}

function cocoTypeFitCap(
  text: string,
  zone: CocoRecipeRect,
  formatName: Format,
  role: CocoFitTextRole,
  lineHeight = 1
) {
  const lines = cocoFitTextLines(text);
  if (!lines.length || !zone) return Number.POSITIVE_INFINITY;
  const lineCount = Math.max(1, lines.length);
  const longestLine = lines.reduce((longest, line) => Math.max(longest, line.length), 1);
  const safeLineHeight = clampComposerNumber(lineHeight, 1, 0.62, 1.35);
  const widthCap = (zone.width * cocoRoleWidthFactor(role, formatName)) / Math.max(4, longestLine);
  const heightCap = (zone.height * cocoRoleHeightFactor(role, formatName)) / Math.max(1, lineCount * safeLineHeight);
  const maxLines = role === "headline" ? 3 : role === "headline2" ? 2 : role === "presenter" ? 2 : 4;
  const lineOverflowPenalty = lineCount > maxLines ? Math.pow(0.88, lineCount - maxLines) : 1;
  return Math.max(1, Math.min(widthCap, heightCap) * lineOverflowPenalty);
}

function scaleCocoTypeSizeToFit(
  value: number,
  scale: number,
  min: number,
  max: number,
  fit: {
    formatName: Format;
    lineHeight?: number;
    role: CocoFitTextRole;
    text: string;
    zone: CocoRecipeRect;
  }
) {
  const readableMin = Math.max(min, COCO_MIN_READABLE_TEXT_SIZE);
  const readableMax = Math.max(max, readableMin);
  const base = Number.isFinite(value) ? Math.max(value, readableMin) : readableMin;
  const factor = clampComposerNumber(scale, 1, 0.55, 1.45);
  const scaled = base * factor;
  const fitCap = cocoTypeFitCap(fit.text, fit.zone, fit.formatName, fit.role, fit.lineHeight);
  return Math.round(clampComposerRange(Math.min(scaled, fitCap), readableMin, readableMax));
}

type CocoHeroImageFit = {
  bgPosX: number;
  bgPosY: number;
  bgScale: number;
  faceRect: CocoRecipeRect;
  heroRect: CocoRecipeRect;
};

function getCocoHeroCanvasSize(formatName: Format) {
  return formatName === "story"
    ? { width: 1080, height: 1920 }
    : { width: 1080, height: 1080 };
}

function solveCocoHeroPanPercent(
  canvasSize: number,
  drawnSize: number,
  sourceCoordinate: number,
  scaleFactor: number,
  targetCoordinate: number
) {
  const range = canvasSize - drawnSize;
  if (Math.abs(range) < 0.01) return 50;
  return clampComposerNumber(
    ((targetCoordinate - sourceCoordinate * scaleFactor) / range) * 100,
    50,
    0,
    100
  );
}

function rectFromCocoHeroFace(
  face: CocoHeroImageFace,
  dx: number,
  dy: number,
  scaleFactor: number,
  canvasWidth: number,
  canvasHeight: number
): CocoRecipeRect {
  return {
    x: ((dx + face.x * scaleFactor) / canvasWidth) * 100,
    y: ((dy + face.y * scaleFactor) / canvasHeight) * 100,
    width: (face.width * scaleFactor / canvasWidth) * 100,
    height: (face.height * scaleFactor / canvasHeight) * 100,
    align: "center",
  };
}

function padCocoFaceProtectionZone(face: CocoRecipeRect): CocoRecipeRect {
  // Protect recognition, not the whole portrait. Type may intentionally cross
  // hats, hair, clothing, arms, and torso.
  const padX = face.width * 0.12;
  const padY = face.height * 0.12;
  const x = Math.max(0, face.x - padX);
  const y = Math.max(0, face.y - padY);
  const right = Math.min(100, face.x + face.width + padX);
  const bottom = Math.min(100, face.y + face.height + padY);
  return {
    x,
    y,
    width: Math.max(1, right - x),
    height: Math.max(1, bottom - y),
    align: face.align ?? "center",
  };
}

function minCocoHeroScaleFactorForTarget(
  sourceSize: number,
  canvasSize: number,
  sourceCoordinate: number,
  targetCoordinate: number
) {
  const safeSourceSize = Math.max(1, sourceSize);
  const safeSourceCoordinate = clampComposerNumber(sourceCoordinate, safeSourceSize / 2, 1, safeSourceSize - 1);
  const safeTargetCoordinate = clampComposerNumber(targetCoordinate, canvasSize / 2, 0, canvasSize);
  const scaleToReachBefore = safeTargetCoordinate / safeSourceCoordinate;
  const scaleToReachAfter =
    (canvasSize - safeTargetCoordinate) /
    Math.max(1, safeSourceSize - safeSourceCoordinate);
  return Math.max(scaleToReachBefore, scaleToReachAfter);
}

function buildCocoHeroImageFit(
  face: CocoHeroImageFace | undefined,
  faceZone: CocoRecipeRect,
  subjectZone: CocoRecipeRect,
  formatName: Format
): CocoHeroImageFit | null {
  if (!face) return null;
  const imageWidth = Math.max(1, Number(face.imageWidth));
  const imageHeight = Math.max(1, Number(face.imageHeight));
  const faceWidth = Math.max(1, Number(face.width));
  const faceHeight = Math.max(1, Number(face.height));
  if (!Number.isFinite(imageWidth) || !Number.isFinite(imageHeight) || !Number.isFinite(faceWidth) || !Number.isFinite(faceHeight)) {
    return null;
  }

  const canvas = getCocoHeroCanvasSize(formatName);
  const coverScale = Math.max(canvas.width / imageWidth, canvas.height / imageHeight);
  const faceWidthAtCoverPct = (faceWidth * coverScale / canvas.width) * 100;
  const faceHeightAtCoverPct = (faceHeight * coverScale / canvas.height) * 100;
  const faceZoneCenterX = faceZone.x + faceZone.width / 2;
  const sideFaceZone = faceZoneCenterX < 35 || faceZoneCenterX > 65;
  // The target controls position; it is not a box the face must fill.
  const targetFaceWidthPct = formatName === "story" ? 12.5 : 14;
  const targetFaceHeightPct = formatName === "story" ? 8.5 : 14;
  const maxFaceWidthPct = formatName === "story" ? 15 : 18;
  const maxFaceHeightPct = formatName === "story" ? 10.5 : 18;
  const scaleForWidth = targetFaceWidthPct / Math.max(1, faceWidthAtCoverPct);
  const scaleForHeight = targetFaceHeightPct / Math.max(1, faceHeightAtCoverPct);
  const faceCenterX = face.x + faceWidth / 2;
  const faceCenterY = face.y + faceHeight / 2;
  const targetX = (faceZone.x + faceZone.width / 2) / 100 * canvas.width;
  const targetY = (faceZone.y + faceZone.height / 2) / 100 * canvas.height;
  const scaleForHorizontalReach =
    minCocoHeroScaleFactorForTarget(imageWidth, canvas.width, faceCenterX, targetX) / coverScale;
  const scaleForVerticalReach =
    minCocoHeroScaleFactorForTarget(imageHeight, canvas.height, faceCenterY, targetY) / coverScale;
  // bgScale is relative to the renderer's cover fit. Values below 1 expose
  // the canvas behind portrait images (the UI shows these as <100 scale), so
  // face-directed fitting may pan or zoom a background but never shrink it.
  const minBgScale = 1;
  const reachBoostX = sideFaceZone ? 1.04 : 1;
  const reachBoostY = sideFaceZone ? 1.02 : 1;
  const requestedBgScale = Math.max(
    minBgScale,
    scaleForWidth,
    scaleForHeight,
    scaleForHorizontalReach * reachBoostX,
    scaleForVerticalReach * reachBoostY
  );
  const maxBgScaleForFace = Math.min(
    maxFaceWidthPct / Math.max(1, faceWidthAtCoverPct),
    maxFaceHeightPct / Math.max(1, faceHeightAtCoverPct)
  );
  const bgScale = clampComposerNumber(
    Math.max(minBgScale, Math.min(requestedBgScale, maxBgScaleForFace)),
    1,
    minBgScale,
    sideFaceZone ? 2.35 : 1.75
  );
  const scaleFactor = coverScale * bgScale;
  const drawnWidth = imageWidth * scaleFactor;
  const drawnHeight = imageHeight * scaleFactor;
  const bgPosX = solveCocoHeroPanPercent(canvas.width, drawnWidth, faceCenterX, scaleFactor, targetX);
  const bgPosY = solveCocoHeroPanPercent(canvas.height, drawnHeight, faceCenterY, scaleFactor, targetY);
  const dx = (canvas.width - drawnWidth) * (bgPosX / 100);
  const dy = (canvas.height - drawnHeight) * (bgPosY / 100);
  const faceRect = rectFromCocoHeroFace(face, dx, dy, scaleFactor, canvas.width, canvas.height);
  const heroRect: CocoRecipeRect = {
    x: clampComposerNumber(faceRect.x - faceRect.width * 1.18, subjectZone.x, -20, 100),
    y: clampComposerNumber(faceRect.y - faceRect.height * 0.82, subjectZone.y, -20, 100),
    width: clampComposerNumber(faceRect.width * 3.35, subjectZone.width, 12, 120),
    height: clampComposerNumber(faceRect.height * 4.4, subjectZone.height, 18, 140),
    align: "center",
  };

  return {
    bgPosX,
    bgPosY,
    bgScale,
    faceRect,
    heroRect,
  };
}

function buildCocoRailBackgroundFit(
  imageSize: { width: number; height: number } | null,
  formatName: Format,
  current: { bgPosX: number; bgPosY: number; bgScale: number; fitMode: boolean },
  focalPoint: { x: number; y: number },
  requestedScale = 1.8
) {
  if (!imageSize) return null;
  const imageWidth = Math.max(1, Number(imageSize.width));
  const imageHeight = Math.max(1, Number(imageSize.height));
  if (![imageWidth, imageHeight].every(Number.isFinite)) return null;
  const canvas = formatName === "story" ? { width: 540, height: 960 } : { width: 540, height: 540 };
  const baseScale = current.fitMode
    ? Math.min(canvas.width / imageWidth, canvas.height / imageHeight)
    : Math.max(canvas.width / imageWidth, canvas.height / imageHeight);
  const currentScale = Math.max(0.01, Number(current.bgScale) || 1);
  const bgScale = clampComposerNumber(requestedScale, 1.8, 1, 2.35);
  const solveAxis = (
    canvasSize: number,
    sourceSize: number,
    position: number,
    focalPct: number
  ) => {
    const currentDrawn = sourceSize * baseScale * currentScale;
    const currentOffset = (canvasSize - currentDrawn) * (position / 100);
    const focalCanvas = clampComposerNumber(focalPct, 50, 0, 100) / 100 * canvasSize;
    // Preserve the exact source pixel already visible at the face focal point
    // while increasing scale. This avoids reinterpreting analysis coordinates
    // in a second image space.
    const focalSource = (focalCanvas - currentOffset) / (baseScale * currentScale);
    const nextDrawn = sourceSize * baseScale * bgScale;
    const nextOffset = focalCanvas - focalSource * baseScale * bgScale;
    const nextRange = canvasSize - nextDrawn;
    if (Math.abs(nextRange) < 0.01) return 50;
    return clampComposerNumber(nextOffset / nextRange * 100, 50, 0, 100);
  };
  return {
    bgScale,
    bgPosX: solveAxis(canvas.width, imageWidth, current.bgPosX, focalPoint.x),
    bgPosY: solveAxis(canvas.height, imageHeight, current.bgPosY, focalPoint.y),
  };
}

function buildCocoReanchoredBackgroundFit(
  imageSize: { width: number; height: number } | null,
  formatName: Format,
  current: { bgPosX: number; bgPosY: number; bgScale: number; fitMode: boolean },
  currentFocalPoint: { x: number; y: number },
  targetFocalPoint: { x: number; y: number },
  requestedScale = 1.8,
  lockRequestedScale = false
) {
  if (!imageSize) return null;
  const imageWidth = Math.max(1, Number(imageSize.width));
  const imageHeight = Math.max(1, Number(imageSize.height));
  if (![imageWidth, imageHeight].every(Number.isFinite)) return null;
  const canvas = formatName === "story" ? { width: 540, height: 960 } : { width: 540, height: 540 };
  const baseScale = current.fitMode
    ? Math.min(canvas.width / imageWidth, canvas.height / imageHeight)
    : Math.max(canvas.width / imageWidth, canvas.height / imageHeight);
  const currentScale = Math.max(0.01, Number(current.bgScale) || 1);
  const sourceFocalForAxis = (
    canvasSize: number,
    sourceSize: number,
    position: number,
    focalPct: number
  ) => {
    const currentDrawn = sourceSize * baseScale * currentScale;
    const currentOffset = (canvasSize - currentDrawn) * (position / 100);
    const focalCanvas = clampComposerNumber(focalPct, 50, 0, 100) / 100 * canvasSize;
    return (focalCanvas - currentOffset) / (baseScale * currentScale);
  };
  const sourceFocalX = sourceFocalForAxis(
    canvas.width,
    imageWidth,
    current.bgPosX,
    currentFocalPoint.x
  );
  const sourceFocalY = sourceFocalForAxis(
    canvas.height,
    imageHeight,
    current.bgPosY,
    currentFocalPoint.y
  );
  const targetX = clampComposerNumber(targetFocalPoint.x, 25, 0, 100) / 100 * canvas.width;
  const targetY = clampComposerNumber(targetFocalPoint.y, 20, 0, 100) / 100 * canvas.height;
  const scaleForHorizontalReach =
    minCocoHeroScaleFactorForTarget(imageWidth, canvas.width, sourceFocalX, targetX) / baseScale;
  const scaleForVerticalReach =
    minCocoHeroScaleFactorForTarget(imageHeight, canvas.height, sourceFocalY, targetY) / baseScale;
  const bgScale = clampComposerNumber(
    lockRequestedScale
      ? requestedScale
      : Math.max(requestedScale, scaleForHorizontalReach * 1.02, scaleForVerticalReach * 1.02),
    requestedScale,
    1,
    3
  );
  const solveTargetAxis = (
    canvasSize: number,
    sourceSize: number,
    sourceFocal: number,
    targetCanvas: number
  ) => {
    const nextDrawn = sourceSize * baseScale * bgScale;
    const nextOffset = targetCanvas - sourceFocal * baseScale * bgScale;
    const nextRange = canvasSize - nextDrawn;
    if (Math.abs(nextRange) < 0.01) return 50;
    return clampComposerNumber(nextOffset / nextRange * 100, 50, 0, 100);
  };
  return {
    bgScale,
    bgPosX: solveTargetAxis(canvas.width, imageWidth, sourceFocalX, targetX),
    bgPosY: solveTargetAxis(canvas.height, imageHeight, sourceFocalY, targetY),
  };
}

function normalizeCocoSubjectScaleBoost(value: unknown, fallback = 1) {
  return clampComposerNumber(value, fallback, 0.75, 1.45);
}

function normalizeCocoHeadlineSizeBoost(value: unknown, fallback = 0) {
  return clampComposerNumber(value, fallback, -12, 18);
}

function normalizeCocoSideScriptY(value: unknown): number | undefined {
  const number = Number(value);
  if (!Number.isFinite(number)) return undefined;
  return Math.max(0, Math.min(100, number));
}

function normalizeComposerRect(value: unknown, fallback: CocoRecipeRect): CocoRecipeRect {
  const rect = value as Partial<CocoRecipeRect> | undefined;
  return {
    x: clampComposerNumber(rect?.x, fallback.x, 0, 100),
    y: clampComposerNumber(rect?.y, fallback.y, 0, 100),
    width: clampComposerNumber(rect?.width, fallback.width, 1, 100),
    height: clampComposerNumber(rect?.height, fallback.height, 1, 100),
    align: rect?.align || fallback.align,
  };
}

function isRenderableComposerRect(value: unknown): value is CocoRecipeRect {
  const rect = value as Partial<CocoRecipeRect> | undefined;
  const x = Number(rect?.x);
  const y = Number(rect?.y);
  const width = Number(rect?.width);
  const height = Number(rect?.height);
  return (
    Number.isFinite(x) &&
    Number.isFinite(y) &&
    Number.isFinite(width) &&
    Number.isFinite(height) &&
    width > 0 &&
    height > 0
  );
}

function isCocoSubjectLayoutId(value: string): value is CocoSubjectLayoutId {
  return value === "subject-center" || value === "subject-left" || value === "subject-right";
}

function cocoTextAlignForSubjectLayout(layoutId: CocoSubjectLayoutId, fallback: Align): Align {
  if (layoutId === "subject-left") return "right";
  if (layoutId === "subject-right") return "left";
  return fallback;
}

type CocoLayoutTextScale = {
  fallback: number;
  min: number;
  max: number;
};

type CocoLayoutTypographyRecipe = {
  details: CocoLayoutTextScale;
  details2: CocoLayoutTextScale;
  venue: CocoLayoutTextScale;
  presenter: CocoLayoutTextScale;
  date: CocoLayoutTextScale;
  price: CocoLayoutTextScale;
  subtag: CocoLayoutTextScale;
  detailsLineHeight: number;
  details2LineHeight: number;
  venueLineHeight: number;
  detailsBold: boolean;
  details2Bold: boolean;
  venueBold: boolean;
  detailsTracking: number;
  details2LetterSpacing: number;
};

function getCocoLayoutTypographyRecipe(
  layoutId: CocoSubjectLayoutId,
  formatName: Format
): CocoLayoutTypographyRecipe {
  const story = formatName === "story";

  if (layoutId === "subject-center") {
    return {
      details: { fallback: story ? 16 : 15, min: 10, max: story ? 20 : 18 },
      details2: { fallback: 10, min: 10, max: story ? 13 : 12 },
      venue: { fallback: 10, min: 10, max: story ? 13 : 12 },
      presenter: { fallback: 11, min: 10, max: 16 },
      date: { fallback: 13, min: 10, max: 19 },
      price: { fallback: 15, min: 10, max: 22 },
      subtag: { fallback: 11, min: 10, max: 15 },
      detailsLineHeight: COCO_CENTER_DETAILS_LEADING,
      details2LineHeight: COCO_CENTER_DETAILS2_LEADING,
      venueLineHeight: COCO_CENTER_VENUE_LEADING,
      detailsBold: true,
      details2Bold: false,
      venueBold: true,
      detailsTracking: 0.015,
      details2LetterSpacing: 0.015,
    };
  }

  if (isFixedCocoPortraitLayout(layoutId)) {
    return {
      details: { fallback: story ? 12 : 11, min: 10, max: story ? 14 : 13 },
      details2: { fallback: 10, min: 10, max: 12 },
      venue: { fallback: 10, min: 10, max: story ? 12 : 11 },
      presenter: { fallback: 11, min: 10, max: 13 },
      date: { fallback: story ? 18 : 17, min: 10, max: story ? 24 : 22 },
      price: { fallback: story ? 15 : 14, min: 10, max: story ? 20 : 18 },
      subtag: { fallback: 10, min: 10, max: 11 },
      detailsLineHeight: 1.08,
      details2LineHeight: 1.08,
      venueLineHeight: 1,
      detailsBold: true,
      details2Bold: false,
      venueBold: true,
      detailsTracking: 0.08,
      details2LetterSpacing: 0.055,
    };
  }

  return {
    details: { fallback: story ? 15 : 14, min: 10, max: story ? 20 : 18 },
    details2: { fallback: 10, min: 10, max: story ? 14 : 13 },
    venue: { fallback: 10, min: 10, max: story ? 12 : 12 },
    presenter: { fallback: 12, min: 10, max: 18 },
    date: { fallback: 13, min: 10, max: 19 },
    price: { fallback: 15, min: 10, max: 22 },
    subtag: { fallback: 11, min: 10, max: 15 },
    detailsLineHeight: COCO_BODY_TEXT_LEADING,
    details2LineHeight: COCO_BODY_TEXT_LEADING,
    venueLineHeight: 0.7,
    detailsBold: true,
    details2Bold: false,
    venueBold: true,
    detailsTracking: 0.025,
    details2LetterSpacing: 0.015,
  };
}

function normalizeCocoPixelRect(value: unknown): CocoSubjectPixelRect | null {
  const rect = value as Partial<CocoSubjectPixelRect> | undefined;
  const x = Number(rect?.x);
  const y = Number(rect?.y);
  const width = Number(rect?.width);
  const height = Number(rect?.height);
  if (
    !Number.isFinite(x) ||
    !Number.isFinite(y) ||
    !Number.isFinite(width) ||
    !Number.isFinite(height) ||
    width <= 0 ||
    height <= 0
  ) {
    return null;
  }
  return { x, y, width, height };
}

function getCocoSubjectFullBounds(subjectBounds: CocoSubjectBounds | undefined): CocoSubjectPixelRect | null {
  return normalizeCocoPixelRect(subjectBounds?.alpha);
}

function getCocoSubjectCoreBounds(subjectBounds: CocoSubjectBounds | undefined): CocoSubjectPixelRect | null {
  const storedCore = normalizeCocoPixelRect((subjectBounds as any)?.core);
  if (storedCore) return storedCore;

  const full = getCocoSubjectFullBounds(subjectBounds);
  if (!full) return null;

  const horizontalInset = full.width * 0.18;
  return {
    x: full.x + horizontalInset,
    y: full.y,
    width: Math.max(1, full.width - horizontalInset * 2),
    height: full.height,
  };
}

function getCocoSubjectFaceBounds(subjectBounds: CocoSubjectBounds | undefined): CocoSubjectPixelRect | null {
  return normalizeCocoPixelRect((subjectBounds as any)?.face);
}

function mirrorCocoSideRect(rect: CocoRecipeRect): CocoRecipeRect {
  return {
    ...rect,
    x: Math.max(0, Math.min(100 - rect.width, 100 - rect.width - rect.x)),
    align: "center",
  };
}

function cocoSubjectFaceLayoutZone(
  layoutId: CocoSubjectLayoutId,
  baseSubjectZone: CocoRecipeRect,
  baseFaceZone: CocoRecipeRect,
  sideSubjectZone?: CocoRecipeRect,
  sideFaceZone?: CocoRecipeRect
): CocoRecipeRect {
  if (layoutId !== "subject-center" && sideFaceZone) {
    const target = layoutId === "subject-right" ? mirrorCocoSideRect(sideFaceZone) : { ...sideFaceZone };
    return {
      ...target,
      x: Math.max(0, Math.min(100 - target.width, target.x)),
      y: Math.max(0, Math.min(100 - target.height, target.y)),
      align: "center",
    };
  }

  const targetSubjectZone = cocoSubjectLayoutZone(layoutId, baseSubjectZone, sideSubjectZone);
  return {
    ...baseFaceZone,
    x: Math.max(0, Math.min(100 - baseFaceZone.width, baseFaceZone.x + targetSubjectZone.x - baseSubjectZone.x)),
    y: Math.max(0, Math.min(100 - baseFaceZone.height, baseFaceZone.y + targetSubjectZone.y - baseSubjectZone.y)),
    align: "center",
  };
}

function cocoSubjectBoundsStyle(
  rect: CocoSubjectPixelRect,
  subjectBounds: CocoSubjectBounds
): React.CSSProperties {
  const width = Math.max(1, Number(subjectBounds.width));
  const height = Math.max(1, Number(subjectBounds.height));
  return {
    position: "absolute",
    left: `${(rect.x / width) * 100}%`,
    top: `${(rect.y / height) * 100}%`,
    width: `${(rect.width / width) * 100}%`,
    height: `${(rect.height / height) * 100}%`,
    pointerEvents: "none",
  };
}

function cocoSubjectLayoutZone(
  layoutId: CocoSubjectLayoutId,
  base: CocoRecipeRect,
  sideBase?: CocoRecipeRect
): CocoRecipeRect {
  const side = sideBase ?? base;
  if (layoutId === "subject-left") return { ...side, x: 0, align: "center" };
  if (layoutId === "subject-right") {
    return { ...side, x: Math.max(0, 100 - side.width), align: "center" };
  }
  return { ...base, align: "center" };
}

function cocoTitleLayoutZones(
  layoutId: CocoSubjectLayoutId,
  base: Pick<CocoComposerZoneMap, "headline" | "script">,
  formatName: Format,
  tuning?: Pick<CocoHeadlineTuning, "sideScriptY">
): Pick<CocoComposerZoneMap, "headline" | "script"> {
  if (layoutId === "subject-center") {
    return {
      headline: { ...base.headline, align: base.headline.align || "center" },
      script: { ...base.script, align: base.script.align || "center" },
    };
  }

  const story = formatName === "story";
  const textX = layoutId === "subject-right" ? (story ? 6 : 5) : (story ? 39 : 40);
  const textWidth = story ? 56 : 55;
  const scriptY = normalizeCocoSideScriptY(tuning?.sideScriptY) ?? (story ? 39 : 43);

  return {
    headline: {
      x: textX,
      y: story ? 23 : 21,
      width: textWidth,
      height: story ? 18 : 26,
      align: "left",
    },
    script: {
      x: textX,
      y: scriptY,
      width: textWidth,
      height: story ? 10 : 15,
      align: "left",
    },
  };
}

function cocoFaceAnchoredTextZones(
  layoutId: CocoSubjectLayoutId,
  base: CocoComposerZoneMap,
  faceZone: CocoRecipeRect,
  formatName: Format,
  tuning?: Pick<CocoHeadlineTuning, "sideScriptY">
): CocoComposerZoneMap {
  const story = formatName === "story";
  const faceRight = faceZone.x + faceZone.width;
  const safeTop = story ? 4 : 5;
  const sideHeadlineY = clampComposerRange(faceZone.y + (story ? 4 : 1.7), story ? 19 : 21, story ? 34 : 32);
  const sideScriptY =
    normalizeCocoSideScriptY(tuning?.sideScriptY) ??
    clampComposerRange(sideHeadlineY + (story ? 15 : 15.8), story ? 34 : 36.8, story ? 50 : 48);
  if (layoutId === "subject-center") {
    const centerZones = buildCenterLayoutZones({
      face: { ...faceZone, align: faceZone.align ?? "center" },
      format: formatName,
      subject: { ...base.subject, align: base.subject.align ?? "center" },
    });

    return {
      ...base,
      subject: centerZones.subject,
      headline: centerZones.hero,
      script: centerZones.heroAccent,
      leftInfo: centerZones.detailsLeft,
      rightInfo: centerZones.detailsRight,
      presenter: centerZones.identity,
      date: centerZones.leftFact,
      price: centerZones.rightFact,
      venue: centerZones.venueBand,
      subtag: centerZones.socialRail,
    };
  }

  if (isFixedCocoPortraitLayout(layoutId)) {
    const fixedZones = getFixedCocoPortraitRecipeZones(layoutId, formatName);
    if (fixedZones) {
      return {
        ...base,
        ...fixedZones,
      };
    }
    if (layoutId !== "subject-right") {
      return { ...base };
    }

    if (story) {
      const headline: CocoRecipeRect = {
        x: 5,
        y: 24,
        width: 48,
        height: 17,
        align: "left",
      };
      const script: CocoRecipeRect = {
        x: 5,
        y: 38,
        width: 48,
        height: 9,
        align: "left",
      };
      const details: CocoRecipeRect = {
        x: 5,
        y: 53,
        width: 48,
        height: 11,
        align: "left",
      };
      return {
        ...base,
        headline,
        script,
        leftInfo: details,
        rightInfo: {
          x: 5,
          y: 66,
          width: 48,
          height: 10,
          align: "left",
        },
        presenter: {
          x: 24,
          y: 4,
          width: 52,
          height: 7,
          align: "center",
        },
        date: {
          x: 78,
          y: 86,
          width: 18,
          height: 9,
          align: "center",
        },
        price: {
          x: 5,
          y: 12,
          width: 18,
          height: 9,
          align: "center",
        },
        venue: {
          x: 5,
          y: 81,
          width: 52,
          height: 8,
          align: "left",
        },
        subtag: {
          x: 78,
          y: 94,
          width: 18,
          height: 5,
          align: "center",
        },
      };
    }

    const headline: CocoRecipeRect = {
      x: 4,
      y: 25,
      width: 49,
      height: 22,
      align: "left",
    };
    const script: CocoRecipeRect = {
      x: 4,
      y: 40,
      width: 49,
      height: 10,
      align: "left",
    };
    const details: CocoRecipeRect = {
      x: 4,
      y: 55,
      width: 49,
      height: 13,
      align: "left",
    };
    return {
      ...base,
      headline,
      script,
      leftInfo: details,
      rightInfo: {
        x: 4,
        y: 69,
        width: 49,
        height: 10,
        align: "left",
      },
      presenter: {
        x: 24,
        y: 4,
        width: 52,
        height: 7,
        align: "center",
      },
      date: {
        x: 82,
        y: 86,
        width: 15,
        height: 11,
        align: "center",
      },
      price: {
        x: 4,
        y: 6,
        width: 16,
        height: 11,
        align: "center",
      },
      venue: {
        x: 4,
        y: 82,
        width: 49,
        height: 10,
        align: "left",
      },
      subtag: {
        x: 82,
        y: 94,
        width: 15,
        height: 5,
        align: "center",
      },
    };
  }

  const sideX = Math.max(story ? 44 : 48, faceRight + (story ? 4 : 5));
  const availableWidth = Math.max(story ? 42 : 44, 96 - sideX);
  const sideWidth = Math.min(story ? 56 : 55, availableWidth);
  const headline: CocoRecipeRect = {
    x: sideX,
    y: sideHeadlineY,
    width: sideWidth,
    height: story ? 18 : 26,
    align: "left",
  };
  const script: CocoRecipeRect = {
    x: sideX,
    y: sideScriptY,
    width: sideWidth,
    height: story ? 10 : 15,
    align: "left",
  };
  const details: CocoRecipeRect = {
    x: sideX,
    y: clampComposerRange(script.y + (story ? 13 : 15), story ? 51 : 53, story ? 77 : 73),
    width: sideWidth,
    height: story ? 11 : 13,
    align: "left",
  };
  const venue: CocoRecipeRect = {
    x: sideX,
    y: story ? 88 : 86.5,
    width: Math.min(story ? 70 : 58, Math.max(sideWidth, 48)),
    height: story ? 7 : 7,
    align: "left",
  };
  const date: CocoRecipeRect = {
    x: story ? 6 : 7,
    y: story ? 85 : 86,
    width: story ? 20 : 16,
    height: story ? 10 : 10,
    align: "center",
  };
  const price: CocoRecipeRect = {
    x: story ? 76 : 78,
    y: safeTop,
    width: story ? 18 : 16,
    height: story ? 10 : 10,
    align: "center",
  };

  return {
    ...base,
    headline,
    script,
    leftInfo: details,
    rightInfo: {
      x: price.x,
      y: price.y + (story ? 11 : 12),
      width: price.width,
      height: story ? 16 : 16,
      align: "center",
    },
    presenter: {
      x: story ? 5 : 4,
      y: safeTop,
      width: story ? 58 : 54,
      height: story ? 7 : 7,
      align: "left",
    },
    date,
    price,
    venue,
    subtag: {
      x: story ? 7 : 8,
      y: story ? 92 : 91,
      width: story ? 13 : 12,
      height: story ? 6 : 7,
      align: "center",
    },
  };
}

function fitCocoSubjectBoundsToZone(
  subjectBounds: CocoSubjectBounds | undefined,
  zone: CocoRecipeRect,
  formatName: Format,
  scaleBoost = 1,
  faceZone?: CocoRecipeRect
): CocoRecipeAnchor | null {
  if (!subjectBounds) return null;
  const imageWidth = Number(subjectBounds.width);
  const imageHeight = Number(subjectBounds.height);
  const faceBounds = faceZone ? getCocoSubjectFaceBounds(subjectBounds) : null;
  const fitBounds = faceBounds ?? getCocoSubjectCoreBounds(subjectBounds) ?? getCocoSubjectFullBounds(subjectBounds);
  const fitX = Number(fitBounds?.x);
  const fitY = Number(fitBounds?.y);
  const fitWidth = Number(fitBounds?.width);
  const fitHeight = Number(fitBounds?.height);
  if (
    !Number.isFinite(imageWidth) ||
    !Number.isFinite(imageHeight) ||
    !Number.isFinite(fitX) ||
    !Number.isFinite(fitY) ||
    !Number.isFinite(fitWidth) ||
    !Number.isFinite(fitHeight) ||
    imageWidth <= 0 ||
    imageHeight <= 0 ||
    fitWidth <= 0 ||
    fitHeight <= 0
  ) {
    return null;
  }

  const canvasWidth = 540;
  const canvasHeight = formatName === "story" ? 960 : 540;
  const zoneLeft = (zone.x / 100) * canvasWidth;
  const zoneTop = (zone.y / 100) * canvasHeight;
  const zoneWidth = (zone.width / 100) * canvasWidth;
  const zoneHeight = (zone.height / 100) * canvasHeight;
  const zoneBottom = zoneTop + zoneHeight;
  const activeZone = faceBounds && faceZone ? faceZone : zone;
  const activeZoneLeft = (activeZone.x / 100) * canvasWidth;
  const activeZoneTop = (activeZone.y / 100) * canvasHeight;
  const activeZoneWidth = (activeZone.width / 100) * canvasWidth;
  const activeZoneHeight = (activeZone.height / 100) * canvasHeight;
  const scale = faceBounds && faceZone
    ? Math.min(activeZoneWidth / fitWidth, activeZoneHeight / fitHeight)
    : Math.max(zoneWidth / fitWidth, zoneHeight / fitHeight) *
      normalizeCocoSubjectScaleBoost(scaleBoost);
  const fitDrawWidth = fitWidth * scale;
  const fitDrawHeight = fitHeight * scale;
  const targetFitLeft = faceBounds && faceZone
    ? activeZoneLeft + (activeZoneWidth - fitDrawWidth) / 2
    : zoneLeft + (zoneWidth - fitDrawWidth) / 2;
  const targetFitTop = faceBounds && faceZone
    ? activeZoneTop + (activeZoneHeight - fitDrawHeight) / 2
    : zoneBottom - fitDrawHeight;
  const imageLeft = targetFitLeft - fitX * scale;
  const imageTop = targetFitTop - fitY * scale;

  // Where the real detected face actually lands on the canvas after this
  // fit, in the same coordinate space as `zone`/`faceZone`. This is the
  // face's TRUE position (derived from real detection), as opposed to
  // `faceZone`, which is only the template's ASSUMED target for where the
  // face should end up - the two can diverge, especially for layouts with
  // little safe space around a large/centered subject.
  const realFaceBounds = getCocoSubjectFaceBounds(subjectBounds);
  const detectedFaceZone: CocoRecipeRect | undefined = realFaceBounds
    ? {
        x: ((imageLeft + realFaceBounds.x * scale) / canvasWidth) * 100,
        y: ((imageTop + realFaceBounds.y * scale) / canvasHeight) * 100,
        width: ((realFaceBounds.width * scale) / canvasWidth) * 100,
        height: ((realFaceBounds.height * scale) / canvasHeight) * 100,
      }
    : undefined;

  return {
    x: (imageLeft + (imageWidth * scale) / 2) / canvasWidth * 100,
    y: (imageTop + (imageHeight * scale) / 2) / canvasHeight * 100,
    scale: clampComposerNumber(scale, scale, 0.05, 3),
    detectedFaceZone,
  };
}

function cocoRoleRect(recipe: TemplateSpec, roleId: string, fallback: CocoRecipeRect): CocoRecipeRect {
  const role = recipe.compositionRecipe?.roles?.find((item) => item.id === roleId);
  return normalizeComposerRect(role?.bounds, fallback);
}

function cocoMeasurementRect(
  recipe: TemplateSpec,
  key: string,
  fallback: CocoRecipeRect
): CocoRecipeRect {
  return normalizeComposerRect(recipe.measurementReference?.measurements?.[key], fallback);
}

function cocoMeasurementNumber(recipe: TemplateSpec, key: string, fallback: number): number {
  return clampComposerNumber(recipe.measurementReference?.measurements?.[key], fallback, 0, 1000);
}

function cocoSubjectScaleBoost(recipe: TemplateSpec, variant: Partial<TemplateBase>): number {
  return normalizeCocoSubjectScaleBoost(
    (variant as any).subjectScaleBoost ??
      cocoMeasurementNumber(recipe, "subjectScaleBoost", 1),
    1
  );
}

function cocoHeadlineTuning(recipe: TemplateSpec, variant: Partial<TemplateBase>): CocoHeadlineTuning {
  return {
    headlineSizeBoost: normalizeCocoHeadlineSizeBoost(
      (variant as any).headlineSizeBoost ??
        cocoMeasurementNumber(recipe, "headlineSizeBoost", 0),
      0
    ),
    sideScriptY: normalizeCocoSideScriptY(
      (variant as any).sideScriptY ??
        recipe.measurementReference?.measurements?.sideScriptY
    ),
  };
}

function buildCocoZoneMap(recipe: TemplateSpec, variant: Partial<TemplateBase>, formatName: Format): CocoComposerZoneMap {
  const defaults = formatName === "story" ? DEFAULT_COCO_STORY_ZONES : DEFAULT_COCO_SQUARE_ZONES;
  const textZones = (variant as any).textZones || {};
  return {
    subject: cocoRoleRect(recipe, "subjectPrimary", cocoMeasurementRect(recipe, "subjectVisibleRect", normalizeComposerRect((variant as any).subjectVisibleRect || textZones.centerSubject, defaults.subject))),
    headline: cocoRoleRect(recipe, "mainHeadline", cocoMeasurementRect(recipe, "mainTitleRect", normalizeComposerRect((variant as any).mainTitleRect || textZones.blockHeadline, defaults.headline))),
    script: cocoRoleRect(recipe, "scriptHeadline", cocoMeasurementRect(recipe, "scriptRect", normalizeComposerRect((variant as any).scriptRect || textZones.scriptTitle, defaults.script))),
    presenter: normalizeComposerRect(textZones.promoter, defaults.presenter),
    leftInfo: cocoRoleRect(recipe, "leftInfo", cocoMeasurementRect(recipe, "leftMetaRect", normalizeComposerRect((variant as any).leftMetaRect || textZones.leftDjLane, defaults.leftInfo))),
    rightInfo: cocoRoleRect(recipe, "rightInfo", cocoMeasurementRect(recipe, "rightMetaRect", normalizeComposerRect((variant as any).rightMetaRect || textZones.rightPriceLane, defaults.rightInfo))),
    date: cocoRoleRect(recipe, "date", normalizeComposerRect(textZones.dateBadge, defaults.date)),
    price: cocoRoleRect(recipe, "price", cocoMeasurementRect(recipe, "priceRect", normalizeComposerRect((variant as any).priceRect || textZones.rightPriceLane, defaults.price))),
    venue: cocoRoleRect(recipe, "venue", cocoMeasurementRect(recipe, "footerRect", normalizeComposerRect((variant as any).footerRect || textZones.footerInfo, defaults.venue))),
    subtag: normalizeComposerRect(textZones.ageBadge || textZones.subtag, defaults.subtag),
  };
}

type CocoTextReference = {
  templateId: string;
  label: string;
  variant: Partial<TemplateBase>;
  zones: CocoComposerZoneMap;
  score: number;
};

function cocoTemplatePositionRect(
  variant: Partial<TemplateBase>,
  xKey: keyof TemplateBase,
  yKey: keyof TemplateBase,
  width: unknown,
  height: unknown,
  fallback: CocoRecipeRect
): CocoRecipeRect {
  const x = (variant as any)[xKey];
  const y = (variant as any)[yKey];
  if (typeof x !== "number" || typeof y !== "number") return fallback;
  return normalizeComposerRect(
    {
      x,
      y,
      width: typeof width === "number" ? width : fallback.width,
      height: typeof height === "number" ? height : fallback.height,
      align: fallback.align,
    },
    fallback
  );
}

function cocoTemplateReferenceZones(
  recipe: TemplateSpec,
  variant: Partial<TemplateBase>,
  formatName: Format
): CocoComposerZoneMap {
  const zones = buildCocoZoneMap(recipe, variant, formatName);
  const textZones = (variant as any).textZones || {};
  const headlineSize = Number((variant as any).headlineSize ?? (variant as any).headMaxPx ?? (variant as any).headSize);
  const scriptSize = Number((variant as any).head2Size ?? (variant as any).head2SizePx);
  const detailsSize = Number((variant as any).detailsSize);
  const venueSize = Number((variant as any).venueSize);
  const dateSize = Number((variant as any).dateSize);
  const priceSize = Number((variant as any).priceSize);
  return {
    ...zones,
    headline: normalizeComposerRect(
      (variant as any).mainTitleRect ||
        textZones.blockHeadline ||
        textZones.mainTitle ||
        cocoTemplatePositionRect(
          variant,
          "headX",
          "headY",
          (variant as any).textColWidth,
          Number.isFinite(headlineSize) ? Math.max(8, headlineSize / (formatName === "story" ? 10 : 6)) : undefined,
          zones.headline
        ),
      zones.headline
    ),
    script: normalizeComposerRect(
      (variant as any).scriptRect ||
        textZones.scriptTitle ||
        textZones.headline2 ||
        cocoTemplatePositionRect(
          variant,
          "head2X",
          "head2Y",
          (variant as any).head2ColWidth,
          Number.isFinite(scriptSize) ? Math.max(6, scriptSize / (formatName === "story" ? 12 : 8)) : undefined,
          zones.script
        ),
      zones.script
    ),
    leftInfo: normalizeComposerRect(
      (variant as any).leftMetaRect ||
        textZones.leftDjLane ||
        textZones.details ||
        cocoTemplatePositionRect(
          variant,
          "detailsX",
          "detailsY",
          34,
          Number.isFinite(detailsSize) ? Math.max(7, detailsSize / 1.5) : undefined,
          zones.leftInfo
        ),
      zones.leftInfo
    ),
    venue: normalizeComposerRect(
      (variant as any).footerRect ||
        textZones.footerInfo ||
        textZones.footer ||
        textZones.venue ||
        cocoTemplatePositionRect(
          variant,
          "venueX",
          "venueY",
          48,
          Number.isFinite(venueSize) ? Math.max(5, venueSize / 1.5) : undefined,
          zones.venue
        ),
      zones.venue
    ),
    date: normalizeComposerRect(
      textZones.dateBadge ||
        textZones.date ||
        cocoTemplatePositionRect(
          variant,
          "dateX",
          "dateY",
          16,
          Number.isFinite(dateSize) ? Math.max(7, dateSize / 2) : undefined,
          zones.date
        ),
      zones.date
    ),
    price: normalizeComposerRect(
      (variant as any).priceRect ||
        textZones.price ||
        cocoTemplatePositionRect(
          variant,
          "priceX",
          "priceY",
          16,
          Number.isFinite(priceSize) ? Math.max(7, priceSize / 2) : undefined,
          zones.price
        ),
      zones.price
    ),
  };
}

function cocoRectCenter(rect: CocoRecipeRect) {
  return {
    x: rect.x + rect.width / 2,
    y: rect.y + rect.height / 2,
  };
}

function cocoReferenceSideScore(
  layoutId: CocoSubjectLayoutId,
  candidate: CocoComposerZoneMap,
  target: CocoComposerZoneMap
) {
  const candidateCenter = cocoRectCenter(candidate.headline);
  const targetCenter = cocoRectCenter(target.headline);
  if (layoutId === "subject-center") {
    const candidateBand =
      candidate.headline.width >= 60 &&
      candidateCenter.x >= 28 &&
      candidateCenter.x <= 72 &&
      candidateCenter.y >= 38;
    return candidateBand ? 34 : Math.max(0, 28 - Math.abs(candidateCenter.x - 50) * 0.8);
  }
  const targetLeft = targetCenter.x < 50;
  const candidateLeft = candidateCenter.x < 50;
  return targetLeft === candidateLeft ? 38 : -28;
}

function cocoReferenceFitScore(candidate: CocoComposerZoneMap, target: CocoComposerZoneMap) {
  const headlineCenter = cocoRectCenter(candidate.headline);
  const targetHeadlineCenter = cocoRectCenter(target.headline);
  const scriptCenter = cocoRectCenter(candidate.script);
  const targetScriptCenter = cocoRectCenter(target.script);
  const headlineDistance =
    Math.abs(headlineCenter.x - targetHeadlineCenter.x) +
    Math.abs(headlineCenter.y - targetHeadlineCenter.y);
  const scriptDistance =
    Math.abs(scriptCenter.x - targetScriptCenter.x) +
    Math.abs(scriptCenter.y - targetScriptCenter.y);
  const widthFit = Math.max(0, 18 - Math.abs(candidate.headline.width - target.headline.width) * 0.45);
  const stackFit = Math.max(0, 16 - scriptDistance * 0.24);
  const positionFit = Math.max(0, 24 - headlineDistance * 0.28);
  return widthFit + stackFit + positionFit;
}

function chooseCocoTextReference(
  layoutId: CocoSubjectLayoutId,
  formatName: Format,
  targetZones: CocoComposerZoneMap,
  sourceRecipeId?: string
): CocoTextReference | null {
  const candidates: CocoTextReference[] = [];
  for (const template of TEMPLATE_GALLERY) {
    if (!template || String(template.id || "").startsWith("__")) continue;
    const variant =
      template.formats?.[formatName] ??
      template.formats?.square ??
      template.base ??
      {};
    const hasLayoutSignal =
      !!(variant as any).mainTitleRect ||
      !!(variant as any).scriptRect ||
      !!(variant as any).textZones ||
      typeof (variant as any).headX === "number" ||
      typeof (variant as any).headY === "number";
    if (!hasLayoutSignal) continue;
    const candidateZones = cocoTemplateReferenceZones(template, variant, formatName);
    const sideScore = cocoReferenceSideScore(layoutId, candidateZones, targetZones);
    const fitScore = cocoReferenceFitScore(candidateZones, targetZones);
    const supportScore =
      (Number.isFinite((variant as any).detailsSize) ? 6 : 0) +
      (Number.isFinite((variant as any).dateSize) ? 4 : 0) +
      (Number.isFinite((variant as any).priceSize) ? 4 : 0) +
      (Number.isFinite((variant as any).head2Size ?? (variant as any).head2SizePx) ? 6 : 0);
    const sameRecipePenalty = template.id === sourceRecipeId ? 2 : 0;
    const score = sideScore + fitScore + supportScore - sameRecipePenalty;
    candidates.push({
      templateId: template.id,
      label: template.label,
      variant,
      zones: candidateZones,
      score,
    });
  }
  candidates.sort((a, b) => b.score - a.score);
  return candidates[0]?.score > 18 ? candidates[0] : null;
}

function cocoRectIntersectionRatio(a: CocoRecipeRect, b: CocoRecipeRect) {
  const left = Math.max(a.x, b.x);
  const top = Math.max(a.y, b.y);
  const right = Math.min(a.x + a.width, b.x + b.width);
  const bottom = Math.min(a.y + a.height, b.y + b.height);
  const width = Math.max(0, right - left);
  const height = Math.max(0, bottom - top);
  const area = Math.max(0.01, a.width * a.height);
  return (width * height) / area;
}

function chooseCocoCompositionHeadlineZone(
  compositionMap: CocoComposerStartupPayload["compositionMap"] | undefined,
  fallback: CocoRecipeRect,
  protectedZones: CocoRecipeRect[]
): CocoRecipeRect {
  const candidates = Array.isArray(compositionMap?.sceneImageAnalysis?.textOpportunityMap) &&
    compositionMap.sceneImageAnalysis.textOpportunityMap.length
    ? compositionMap.sceneImageAnalysis.textOpportunityMap
    : Array.isArray(compositionMap?.bestTextZones)
    ? compositionMap.bestTextZones
    : [];
  if (!candidates.length) return fallback;

  const fallbackCenterX = fallback.x + fallback.width / 2;
  const fallbackCenterY = fallback.y + fallback.height / 2;
  const ranked = candidates
    .map((candidate) => {
      const rect = normalizeComposerRect(candidate, fallback);
      const overlapPenalty = protectedZones.reduce(
        (max, zone) => Math.max(max, cocoRectIntersectionRatio(rect, zone)),
        0
      ) * 30;
      const centerX = rect.x + rect.width / 2;
      const centerY = rect.y + rect.height / 2;
      const templateAffinity =
        Math.max(0, 1 - (Math.abs(centerX - fallbackCenterX) + Math.abs(centerY - fallbackCenterY)) / 120) * 12;
      return {
        rect,
        score: Number(candidate.score ?? 0) + templateAffinity - overlapPenalty,
      };
    })
    .filter((item) => item.rect.width >= 24 && item.rect.height >= 12 && item.score >= 38)
    .sort((a, b) => b.score - a.score);

  return ranked[0]?.rect ?? fallback;
}

function chooseCocoCompositionPlan(
  compositionMap: CocoComposerStartupPayload["compositionMap"] | undefined,
  protectedZones: CocoRecipeRect[]
) {
  const plans = Array.isArray((compositionMap as any)?.compositionPlans)
    ? ((compositionMap as any).compositionPlans as any[])
    : [];
  if (!plans.length) return null;

  return plans
    .map((plan) => {
      const textColumn = normalizeComposerRect(plan?.textColumn, { x: 0, y: 0, width: 1, height: 1 });
      const overlapPenalty = protectedZones.reduce(
        (max, zone) => Math.max(max, cocoRectIntersectionRatio(textColumn, zone)),
        0
      ) * 40;
      return {
        plan,
        score: Number(plan?.score ?? 0) - overlapPenalty,
      };
    })
    .filter((item) => item.score >= 48)
    .sort((a, b) => b.score - a.score)[0]?.plan ?? null;
}

function sceneImageProtectionRects(
  compositionMap: CocoComposerStartupPayload["compositionMap"] | undefined,
  fallbackZones: CocoRecipeRect[]
): CocoRecipeRect[] {
  const protectionMap = Array.isArray(compositionMap?.sceneImageAnalysis?.protectionMap)
    ? compositionMap.sceneImageAnalysis.protectionMap
    : [];
  const mapped = protectionMap
    .map((zone) => normalizeComposerRect(zone, { x: 0, y: 0, width: 1, height: 1 }))
    .filter((zone) => zone.width > 0 && zone.height > 0);
  return mapped.length ? mapped : fallbackZones;
}

function applyCocoCompositionTextZones(
  zones: CocoComposerZoneMap,
  compositionMap: CocoComposerStartupPayload["compositionMap"] | undefined,
  protectedSubjectZone: CocoRecipeRect,
  formatName: Format
): CocoComposerZoneMap {
  const protectedZones = sceneImageProtectionRects(compositionMap, [protectedSubjectZone]);
  const plan = chooseCocoCompositionPlan(compositionMap, protectedZones);
  if (plan) {
    const alignment = plan.alignment === "right" || plan.alignment === "center" ? plan.alignment : "left";
    const metadata = normalizeComposerRect(plan.metadata, zones.leftInfo);
    const dateTime = normalizeComposerRect(plan.dateTime, zones.date);
    const details2Height = Math.max(4, Math.min(8, dateTime.y - (metadata.y + metadata.height) - 1));
    return {
      ...zones,
      headline: { ...normalizeComposerRect(plan.headline, zones.headline), align: alignment },
      script: { ...normalizeComposerRect(plan.accent, zones.script), align: alignment },
      leftInfo: { ...metadata, align: alignment },
      rightInfo: {
        x: metadata.x,
        y: Math.max(0, metadata.y + metadata.height + 1),
        width: metadata.width,
        height: details2Height,
        align: alignment,
      },
      date: { ...dateTime, align: alignment },
      venue: { ...normalizeComposerRect(plan.venue, zones.venue), align: alignment },
    };
  }

  const headline = chooseCocoCompositionHeadlineZone(
    compositionMap,
    zones.headline,
    protectedZones
  );
  if (
    Math.abs(headline.x - zones.headline.x) < 0.01 &&
    Math.abs(headline.y - zones.headline.y) < 0.01 &&
    Math.abs(headline.width - zones.headline.width) < 0.01
  ) {
    return zones;
  }

  const scriptHeight = formatName === "story" ? 8 : 10;
  const scriptTop = Math.max(0, Math.min(100 - scriptHeight, headline.y + headline.height * 0.62));
  const scriptInset = Math.min(8, headline.width * 0.14);
  return {
    ...zones,
    headline: {
      ...headline,
      align: headline.align || zones.headline.align || "center",
    },
    script: {
      x: Math.max(0, headline.x + scriptInset),
      y: scriptTop,
      width: Math.max(24, headline.width - scriptInset * 2),
      height: scriptHeight,
      align: headline.align || zones.script.align || "center",
    },
  };
}

function buildCocoSubjectFaceZone(
  recipe: TemplateSpec,
  variant: Partial<TemplateBase>,
  formatName: Format
): CocoRecipeRect {
  const fallback = formatName === "story" ? DEFAULT_COCO_STORY_FACE_ZONE : DEFAULT_COCO_SQUARE_FACE_ZONE;
  return normalizeComposerRect(
    (variant as any).subjectFaceRect ||
      recipe.measurementReference?.measurements?.subjectFaceRect,
    fallback
  );
}

function buildCocoSubjectSideZone(
  recipe: TemplateSpec,
  variant: Partial<TemplateBase>,
  formatName: Format
): CocoRecipeRect {
  const fallback = formatName === "story" ? DEFAULT_COCO_STORY_SIDE_SUBJECT_ZONE : DEFAULT_COCO_SQUARE_SIDE_SUBJECT_ZONE;
  return normalizeComposerRect(
    (variant as any).subjectSideVisibleRect ||
      recipe.measurementReference?.measurements?.subjectSideVisibleRect,
    fallback
  );
}

function buildCocoSubjectSideFaceZone(
  recipe: TemplateSpec,
  variant: Partial<TemplateBase>,
  formatName: Format
): CocoRecipeRect {
  const fallback = formatName === "story" ? DEFAULT_COCO_STORY_SIDE_FACE_ZONE : DEFAULT_COCO_SQUARE_SIDE_FACE_ZONE;
  return normalizeComposerRect(
    (variant as any).subjectSideFaceRect ||
      recipe.measurementReference?.measurements?.subjectSideFaceRect,
    fallback
  );
}


