function applyCocoPhotoPalette(
  base: CocoRefinedPalette,
  photoSignals: CocoPhotoSignal[] = []
): CocoRefinedPalette {
  const preferredSignals = [
    ...photoSignals.filter((signal) => signal.role === "background"),
    ...photoSignals.filter((signal) => signal.role !== "background"),
  ];
  const sampled = Array.from(new Set(
    preferredSignals.flatMap((signal) => signal.dominantHints ?? [])
      .map((hint) => String(hint || "").trim().toUpperCase())
      .filter((hint) => /^#[0-9A-F]{6}$/.test(hint))
  )).map((hex) => {
    const parsed = parseCocoTextColor(hex)!;
    const max = Math.max(parsed.r, parsed.g, parsed.b);
    const min = Math.min(parsed.r, parsed.g, parsed.b);
    const saturation = max > 0 ? (max - min) / max : 0;
    const luma = (0.2126 * parsed.r + 0.7152 * parsed.g + 0.0722 * parsed.b) / 255;
    return { ...parsed, hex, luma, saturation };
  });
  if (!sampled.length) return base;

  const colorful = [...sampled].sort((left, right) =>
    (right.saturation * 0.75 + (1 - Math.abs(right.luma - 0.5)) * 0.25) -
    (left.saturation * 0.75 + (1 - Math.abs(left.luma - 0.5)) * 0.25)
  );
  const dominant = colorful[0];
  const distance = (left: typeof dominant, right: typeof dominant) =>
    Math.hypot(left.r - right.r, left.g - right.g, left.b - right.b);
  const secondary = colorful.find((color) => color !== dominant && distance(color, dominant) > 88) || colorful[1] || dominant;
  const rgbToHex = (color: { r: number; g: number; b: number }) =>
    `#${[color.r, color.g, color.b]
      .map((channel) => Math.round(Math.max(0, Math.min(255, channel))).toString(16).padStart(2, "0"))
      .join("")}`.toUpperCase();
  const mix = (
    left: { r: number; g: number; b: number },
    right: { r: number; g: number; b: number },
    rightAmount: number
  ) => ({
    r: left.r + (right.r - left.r) * rightAmount,
    g: left.g + (right.g - left.g) * rightAmount,
    b: left.b + (right.b - left.b) * rightAmount,
  });
  const white = { r: 255, g: 255, b: 255 };
  const black = { r: 0, g: 0, b: 0 };
  const makeReadable = (color: { r: number; g: number; b: number }) => {
    let next = { ...color };
    for (let step = 0; step < 8; step += 1) {
      const luma = (0.2126 * next.r + 0.7152 * next.g + 0.0722 * next.b) / 255;
      if (luma >= 0.62) break;
      next = mix(next, white, 0.18);
    }
    return rgbToHex(next);
  };
  const primary = makeReadable(mix(dominant, parseCocoTextColor(base.palette.primary) || white, 0.2));
  const sampledSecondary = makeReadable(mix(secondary, parseCocoTextColor(base.palette.secondary) || white, 0.18));
  const complement = makeReadable(mix(
    { r: 255 - dominant.r, g: 255 - dominant.g, b: 255 - dominant.b },
    parseCocoTextColor(base.palette.accent) || white,
    0.22
  ));
  const neutral = rgbToHex(mix(white, dominant, 0.1));
  const dark = rgbToHex(mix(black, dominant, 0.28));

  return {
    palette: {
      bgFrom: dark,
      bgTo: rgbToHex(mix(black, secondary, 0.22)),
      primary,
      secondary: sampledSecondary,
      accent: complement,
      neutral,
    },
    headline: primary,
    subheadline: complement,
    presenter: sampledSecondary,
    details: neutral,
    details2: sampledSecondary,
    venue: neutral,
    utility: complement,
    subtag: neutral,
    headlineStroke: dark,
    headlineGlow: sampledSecondary,
  };
}

function getCocoComposerStyleTreatment(
  nightlifeStyle?: CocoNightlifeStyle | null,
  moodProfile?: CocoMoodProfile | null
): CocoComposerStyleTreatment {
  const treatments: Partial<Record<CocoNightlifeStyle, CocoComposerStyleTreatment>> = {
    afrobeats: {
      contrast: 1.08,
      grade: 0.46,
      haze: 0.22,
      saturation: 1.12,
      vibrance: 0.22,
      vignetteStrength: 0.52,
      warmth: 0.1,
    },
    "bottle-service": {
      clarity: 0.16,
      contrast: 1.12,
      grade: 0.56,
      haze: 0.08,
      saturation: 0.96,
      vibrance: 0.08,
      vignetteStrength: 0.7,
      warmth: 0.08,
    },
    brunch: {
      contrast: 1.02,
      exp: 1.04,
      grade: 0.28,
      haze: 0.12,
      saturation: 1.04,
      vibrance: 0.1,
      vignetteStrength: 0.36,
      warmth: 0.12,
    },
    edm: {
      clarity: 0.2,
      contrast: 1.18,
      grade: 0.58,
      haze: 0.26,
      leak: 0.16,
      saturation: 1.24,
      vibrance: 0.3,
      vignetteStrength: 0.64,
      warmth: -0.04,
    },
    "hip-hop": {
      clarity: 0.2,
      contrast: 1.18,
      grade: 0.48,
      grain: 0.18,
      haze: 0.1,
      saturation: 1.02,
      vibrance: 0.08,
      vignetteStrength: 0.66,
    },
    house: {
      contrast: 1.08,
      grade: 0.48,
      haze: 0.2,
      saturation: 1.14,
      vibrance: 0.2,
      vignetteStrength: 0.56,
    },
    "latin-night": {
      contrast: 1.08,
      grade: 0.44,
      haze: 0.18,
      saturation: 1.14,
      vibrance: 0.2,
      vignetteStrength: 0.5,
      warmth: 0.12,
    },
    "rnb-lounge": {
      contrast: 1.06,
      filmGrade: 0.62,
      grade: 0.5,
      haze: 0.2,
      saturation: 1.02,
      vibrance: 0.12,
      vignetteStrength: 0.68,
      warmth: 0.08,
    },
    rooftop: {
      contrast: 1.03,
      exp: 1.03,
      grade: 0.34,
      haze: 0.24,
      leak: 0.12,
      saturation: 1.06,
      vibrance: 0.16,
      vignetteStrength: 0.42,
      warmth: 0.14,
    },
    techno: {
      clarity: 0.24,
      contrast: 1.22,
      gamma: 0.96,
      grade: 0.62,
      grain: 0.2,
      haze: 0.08,
      saturation: 0.9,
      vibrance: 0.06,
      vignetteStrength: 0.72,
      warmth: -0.12,
    },
  };

  const base = { ...(treatments[nightlifeStyle ?? "general-nightlife"] ?? {}) };
  if (!moodProfile) return base;
  const energy = moodProfile.vector.energy;
  const elegance = moodProfile.vector.elegance;
  const exclusivity = moodProfile.vector.exclusivity;
  const underground = moodProfile.vector.underground;
  const summer = moodProfile.vector.summer;

  if (energy > 80) {
    base.contrast = Math.max(base.contrast ?? 1.08, 1.16);
    base.saturation = Math.max(base.saturation ?? 1.06, 1.18);
    base.vibrance = Math.max(base.vibrance ?? 0.12, 0.26);
    base.haze = Math.max(base.haze ?? 0.12, 0.2);
  }
  if (elegance > 78 || exclusivity > 78) {
    base.contrast = Math.max(base.contrast ?? 1.06, 1.1);
    base.grade = Math.max(base.grade ?? 0.42, 0.52);
    base.haze = Math.min(base.haze ?? 0.12, 0.12);
    base.saturation = Math.min(base.saturation ?? 1.02, 1.04);
    base.vignetteStrength = Math.max(base.vignetteStrength ?? 0.58, 0.68);
    base.vibrance = Math.min(base.vibrance ?? 0.12, 0.12);
  }
  if (underground > 72) {
    base.clarity = Math.max(base.clarity ?? 0.14, 0.22);
    base.contrast = Math.max(base.contrast ?? 1.1, 1.2);
    base.grain = Math.max(base.grain ?? 0.12, 0.18);
    base.vignetteStrength = Math.max(base.vignetteStrength ?? 0.58, 0.7);
  }
  if (summer > 72) {
    base.exp = Math.max(base.exp ?? 1, 1.03);
    base.haze = Math.max(base.haze ?? 0.1, 0.16);
    base.saturation = Math.max(base.saturation ?? 1.04, 1.08);
    base.vignetteStrength = Math.min(base.vignetteStrength ?? 0.46, 0.46);
    base.warmth = Math.max(base.warmth ?? 0, 0.08);
  }

  return base;
}

function parseCocoTextColor(value: unknown) {
  const source = String(value ?? "").trim();
  if (!source) return null;
  const lower = source.toLowerCase();
  if (lower === "transparent" || lower === "none") return null;
  if (lower === "black") return { r: 0, g: 0, b: 0, a: 1 };
  if (lower === "white") return { r: 255, g: 255, b: 255, a: 1 };

  const hexMatch = lower.match(/^#([0-9a-f]{3}|[0-9a-f]{4}|[0-9a-f]{6}|[0-9a-f]{8})$/i);
  if (hexMatch) {
    const raw = hexMatch[1];
    const expanded =
      raw.length === 3 || raw.length === 4
        ? raw
            .split("")
            .map((part) => part + part)
            .join("")
        : raw;
    return {
      r: Number.parseInt(expanded.slice(0, 2), 16),
      g: Number.parseInt(expanded.slice(2, 4), 16),
      b: Number.parseInt(expanded.slice(4, 6), 16),
      a: expanded.length >= 8 ? Number.parseInt(expanded.slice(6, 8), 16) / 255 : 1,
    };
  }

  const rgbMatch = lower.match(/^rgba?\(([^)]+)\)$/i);
  if (!rgbMatch) return null;
  const parts = rgbMatch[1].split(",").map((part) => part.trim());
  if (parts.length < 3) return null;
  const readChannel = (part: string) => {
    const number = Number.parseFloat(part);
    if (!Number.isFinite(number)) return 0;
    return part.endsWith("%") ? clampLighting01(number / 100) * 255 : Math.max(0, Math.min(255, number));
  };
  const alpha = parts[3] == null ? 1 : Math.max(0, Math.min(1, Number.parseFloat(parts[3])));
  return {
    r: readChannel(parts[0]),
    g: readChannel(parts[1]),
    b: readChannel(parts[2]),
    a: Number.isFinite(alpha) ? alpha : 1,
  };
}

function isCocoDarkTextColor(value: unknown) {
  const parsed = parseCocoTextColor(value);
  if (!parsed || parsed.a <= 0.2) return false;
  const luminance = (0.2126 * parsed.r + 0.7152 * parsed.g + 0.0722 * parsed.b) / 255;
  return luminance < 0.18;
}

function cocoReadableTextColor(value: unknown, fallback = "#ffffff") {
  const source = typeof value === "string" ? value.trim() : "";
  if (!source) return fallback;
  return isCocoDarkTextColor(source) ? fallback : source;
}

function balancedComposerHeadline(value: string) {
  const clean = String(value || "EVENT NAME")
    .replace(/\s+/g, " ")
    .trim();
  const words = clean.split(" ").filter(Boolean);
  if (words.length <= 1) return clean;
  if (clean.length <= 12 && words.length <= 2) return clean;
  const midpoint = Math.ceil(words.length / 2);
  return `${words.slice(0, midpoint).join(" ")}\n${words.slice(midpoint).join(" ")}`;
}

function chooseComposerIdentityHeadline(eventName: string, generatedHeadline: string) {
  const cleanEvent = String(eventName || "")
    .replace(/\s+/g, " ")
    .trim();
  const cleanGenerated = String(generatedHeadline || "")
    .replace(/\s+/g, " ")
    .trim();
  if (!cleanEvent) return cleanGenerated || "EVENT NAME";
  if (!cleanGenerated) return cleanEvent;

  const eventWords = cleanEvent.split(" ").filter(Boolean);
  const generatedWords = cleanGenerated.split(" ").filter(Boolean);
  if (eventWords.length >= 2 && generatedWords.length < eventWords.length) {
    const generatedLower = cleanGenerated.toLowerCase();
    const eventPrefix = eventWords.slice(0, generatedWords.length).join(" ").toLowerCase();
    if (generatedLower === eventPrefix) return cleanEvent;
  }

  return cleanGenerated;
}

function splitComposerEventTitle(value: string, templateScript: string) {
  const clean = String(value || "EVENT NAME")
    .replace(/\s+/g, " ")
    .trim();
  const words = clean.split(" ").filter(Boolean);
  const fallbackScript = String(templateScript || "")
    .replace(/\s+/g, " ")
    .trim();

  if (words.length === 2) {
    return {
      headline: words[0],
      script: words[1],
    };
  }

  if (fallbackScript && fallbackScript.toLowerCase() !== clean.toLowerCase()) {
    const scriptWords = fallbackScript.toLowerCase().split(" ").filter(Boolean);
    const remainingWords = words.filter((word, index) => {
      const phrase = words.slice(index, index + scriptWords.length).join(" ").toLowerCase();
      return phrase !== fallbackScript.toLowerCase();
    });
    return {
      headline: (remainingWords.length ? remainingWords : words).join(" "),
      script: fallbackScript,
    };
  }

  return {
    headline: clean,
    script: "",
  };
}

