function pickCocoSemanticCopyPatch(source: Record<string, any> | null | undefined) {
  if (!source) return {} as Record<string, any>;
  return Object.fromEntries(
    COCO_SEMANTIC_COPY_KEYS.flatMap((key) =>
      Object.prototype.hasOwnProperty.call(source, key) ? [[key, source[key]]] : []
    )
  ) as Record<string, any>;
}

function composerHeadlineSize(sourceSize: unknown, headline: string, zone: CocoRecipeRect, formatName: Format) {
  const lineCount = Math.max(1, headline.split("\n").length);
  const longestLine = headline
    .split("\n")
    .reduce((max, line) => Math.max(max, line.trim().length), 1);
  const base = clampComposerNumber(sourceSize, formatName === "story" ? 76 : 96, 48, formatName === "story" ? 104 : 118);
  const heightCap = (zone.height * (formatName === "story" ? 7.3 : 5.9)) / Math.max(1, lineCount);
  const widthCap = (zone.width * (formatName === "story" ? 9.2 : 8.2)) / Math.max(6, longestLine);
  return Math.round(clampComposerNumber(Math.min(base, heightCap, widthCap), base, 42, base));
}

function cocoLayoutHeadlineSize(sourceSize: unknown, headline: string, zone: CocoRecipeRect, formatName: Format) {
  const lineCount = Math.max(1, String(headline || "").split("\n").length);
  const longestLine = String(headline || "")
    .split("\n")
    .reduce((max, line) => Math.max(max, line.trim().length), 1);
  const base = clampComposerNumber(sourceSize, formatName === "story" ? 84 : 92, 42, formatName === "story" ? 112 : 128);
  const heightCap = (zone.height * (formatName === "story" ? 6.7 : 5.6)) / Math.max(1, lineCount);
  const widthCap = (zone.width * (formatName === "story" ? 12.4 : 13.2)) / Math.max(5, longestLine);
  return Math.round(clampComposerNumber(Math.min(base, heightCap, widthCap), base, 38, base));
}

function cocoLayoutScriptSize(sourceSize: unknown, script: string, zone: CocoRecipeRect, formatName: Format) {
  const longestLine = String(script || "")
    .split("\n")
    .reduce((max, line) => Math.max(max, line.trim().length), 1);
  const base = clampComposerNumber(sourceSize, formatName === "story" ? 38 : 34, 14, formatName === "story" ? 54 : 46);
  const heightCap = zone.height * (formatName === "story" ? 4.8 : 4.3);
  const widthCap = (zone.width * (formatName === "story" ? 8.9 : 8.1)) / Math.max(4, longestLine);
  return Math.round(clampComposerNumber(Math.min(base, heightCap, widthCap), base, 14, base));
}

function cocoLayoutSupportSize(
  sourceSize: unknown,
  text: string,
  zone: CocoRecipeRect,
  formatName: Format,
  fallback: number,
  min: number,
  max: number
) {
  const lines = String(text || "")
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .filter((line) => line.trim().length > 0);
  const lineCount = Math.max(1, lines.length);
  const longestLine = lines.reduce((longest, line) => Math.max(longest, line.trim().length), 1);
  const readableMin = Math.max(min, COCO_MIN_READABLE_TEXT_SIZE);
  const readableMax = Math.max(max, readableMin);
  const readableFallback = Math.max(fallback, readableMin);
  const base = clampComposerNumber(sourceSize, readableFallback, readableMin, readableMax);
  const heightCap = (zone.height * (formatName === "story" ? 5.6 : 4.8)) / Math.max(1, lineCount);
  const widthCap = (zone.width * (formatName === "story" ? 9.8 : 9.2)) / Math.max(4, longestLine);
  return Math.round(clampComposerNumber(Math.min(base, heightCap, widthCap), base, readableMin, base));
}

function compactCocoTextToMaxLines(text: string, maxLines: number) {
  const lineLimit = Math.max(1, Math.floor(maxLines));
  const lines = String(text || "")
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map((line) => line.replace(/\s+/g, " ").trim())
    .filter(Boolean);
  const longestExistingLine = lines.reduce((longest, line) => Math.max(longest, line.length), 0);
  if (lines.length <= lineLimit && longestExistingLine <= 24) return lines.join("\n");

  const words = lines.join(" ").split(" ").filter(Boolean);
  if (words.length <= lineLimit) return words.join("\n");

  const totalLength = words.reduce((sum, word) => sum + word.length, 0) + Math.max(0, words.length - 1);
  const idealLineLength = Math.ceil(totalLength / lineLimit);
  const packed: string[] = [];
  let current: string[] = [];
  let currentLength = 0;

  for (let index = 0; index < words.length; index += 1) {
    const word = words[index] ?? "";
    const remainingWords = words.length - index;
    const remainingLines = lineLimit - packed.length;
    const needsRoomForRemainingLines = remainingWords <= remainingLines;
    const nextLength = currentLength + (current.length ? 1 : 0) + word.length;
    if (
      current.length > 0 &&
      packed.length < lineLimit - 1 &&
      nextLength > idealLineLength &&
      !needsRoomForRemainingLines
    ) {
      packed.push(current.join(" "));
      current = [word];
      currentLength = word.length;
    } else {
      current.push(word);
      currentLength = nextLength;
    }
  }

  if (current.length) packed.push(current.join(" "));
  if (packed.length <= lineLimit) return packed.join("\n");
  return [...packed.slice(0, lineLimit - 1), packed.slice(lineLimit - 1).join(" ")].join("\n");
}

function compactCocoCenterSupportText(text: string) {
  const lines = String(text || "")
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map((line) => line.replace(/\s+/g, " ").trim())
    .filter(Boolean);

  if (lines.length > 1) {
    return compactCocoTextToMaxLines(lines.slice(0, 2).join("\n"), 2);
  }

  const words = lines.join(" ").split(" ").filter(Boolean).slice(0, 8);
  return compactCocoTextToMaxLines(words.join(" "), 2);
}

