    bgFitMode: false,
    bgPosX: formatRecipe.imageFit.positionX,
    bgPosY: formatRecipe.imageFit.positionY,
    bgScale: formatRecipe.imageFit.scale,
    bgRotate: 0,
    bgBlur: 0,
    hue: 0,
    contrast: 1.045,
    exp: 0.91,
    saturation: 0.96,
    vibrance: 0,
    clarity: 0,
    filmGrade: 0,
