function withCocoSubjectDecisionInTemplate<T extends TemplateSpec>(
  template: T,
  decision: CocoSubjectDecision
): T {
  const patchVariant = (variant: TemplateBase | undefined) =>
    variant
      ? ({
          ...variant,
          cocoSubjectDecision: decision,
        } as TemplateBase)
      : variant;
  return {
    ...template,
    ...(template.base ? { base: patchVariant(template.base) } : {}),
    ...(template.formats
      ? {
          formats: {
            ...template.formats,
            square: patchVariant(template.formats.square),
            story: patchVariant(template.formats.story),
          },
        }
      : {}),
  } as T;
}

async function buildPendingCocoDirectionCandidate(
  sourceComposer: CocoComposerStartupPayload,
  direction: CocoArtDirection
): Promise<PendingCocoDirectionCandidate> {
  const recipeSeed = buildCocoAuthoredRecipeSeed(direction.visualRecipeId);
  const referenceTemplateId = recipeSeed.id;
  if (!isCocoRecipeChoiceEligible(direction, sourceComposer, recipeSeed.formats)) {
    throw new CocoRecipeChoiceMismatch(`${direction.name} is not eligible without a subject.`);
  }

  const portableRecipeId = isCocoPortableRecipeId(direction.visualRecipeId)
    ? direction.visualRecipeId
    : null;
  const recipeSubjectDataUrl =
    sourceComposer.recipeSubjectDataUrl || sourceComposer.subjectDataUrl;
  const recipeSubjectBounds =
    sourceComposer.recipeSubjectBounds || sourceComposer.subjectBounds;
  const subjectAuthority = direction.subjectPolicy.mode === "none"
    ? {
        mode: "none" as const,
        offerImproveCutout: false,
        requiresRecipeSubjectConsent: false,
      }
    : direction.visualRecipeId
    ? resolveCocoRecipeSubjectAuthority({
        decision: sourceComposer.subjectDecision,
        visualRecipeId: direction.visualRecipeId,
        hasRecipeSubjectFallback: Boolean(portableRecipeId),
        hasUserSubject: Boolean(recipeSubjectDataUrl),
      })
    : {
        mode: "none" as const,
        offerImproveCutout: false,
        requiresRecipeSubjectConsent: false,
      };
  const recipeUsesUserSubject =
    Boolean(direction.visualRecipeId) && subjectAuthority.mode === "user";
  const uploadedPhotoBecomesRecipeCutout =
    recipeUsesUserSubject &&
    sourceComposer.subjectDecision?.source === "uploaded-photo";
  const composer: CocoComposerStartupPayload = {
    ...sourceComposer,
    creativeIntent:
      sourceComposer.creativeIntent ??
      resolveCocoCreativeIntent({
        eventDescription: sourceComposer.eventBrief.description,
        eventName: sourceComposer.eventName,
      }) ??
      undefined,
    layoutRecipeTemplateId: referenceTemplateId,
    selectedConceptDirectionId: direction.id,
    ...(direction.visualRecipeId
      ? {
          subjectDataUrl: recipeUsesUserSubject
            ? recipeSubjectDataUrl
            : undefined,
          subjectBounds: recipeUsesUserSubject
            ? recipeSubjectBounds
            : undefined,
          backgroundOnlyHero: recipeUsesUserSubject
            ? undefined
            : sourceComposer.backgroundOnlyHero,
        }
      : {}),
    ...(uploadedPhotoBecomesRecipeCutout && !sourceComposer.backgroundSelectionExplicit
      ? {
          // Recipe layouts own their atmosphere. Keeping the same opaque photo
          // behind its repositioned cutout would render the person twice.
          backgroundDataUrl: undefined,
          backgroundSrc: COCO_RUSH_NIGHT_AMBIENT_URL,
        }
      : {}),
    referenceCandidates: [],
    visualReferenceId: `recipe:${referenceTemplateId}`,
  };
  const generatedTemplate = portableRecipeId
    ? materializeCocoPortableRecipeTemplate({
        baseTemplate: recipeSeed,
        composer,
        project: await loadCocoPortableRecipeProject(portableRecipeId),
        recipeId: portableRecipeId,
      })
    : buildCocoComposerTemplate(composer);
  for (const format of ["square", "story"] as const) {
    if (generatedTemplate.formats?.[format]) {
      generatedTemplate.formats[format] = withCocoRecipeBackground(generatedTemplate.formats[format], composer);
    }
    if (getMaterializedCocoVisualRecipe(generatedTemplate.formats?.[format])?.id !== direction.visualRecipeId) {
      throw new Error(`Coco recipe ${referenceTemplateId} did not materialize its authored ${format} canvas.`);
    }
  }
  const template = generatedTemplate;
  if (sourceComposer.eventBrief.theme && (!cocoThemeAllowsRecipe(sourceComposer.eventBrief.theme, direction.visualRecipeId ?? '') || !cocoHeadlineMatches(direction.visualRecipeId ?? '', template.formats ?? {}, sourceComposer.eventName))) {
    throw new CocoRecipeChoiceMismatch('This design does not match the selected theme and headline structure.');
  }
  if (sourceComposer.eventBrief.theme) {
    // Check the real fonts before offering a title. Keep authored sizes instead
    // of quietly shrinking a long event name to squeeze it into a design.
    const context = document.createElement('canvas').getContext('2d');
    if (context) for (const format of ['square', 'story'] as const) {
      const v = template.formats?.[format] as any;
      const system = v?.cocoCompositionSystem;
      const fields = compiledPreviewFields(v);
      for (const o of system?.compiledDocument?.objects ?? []) {
        const override = system.compiledObjectOverrides?.[o.id];
        if (o.kind !== 'text' || !override?.cocoFormFields?.includes('eventName')) continue;
        const live = (key: string, fallback: unknown) => compiledObjectValue(system.compiledObjectOverrides, fields, o, key, fallback);
        const family = String(live('family', o.typography?.fontFamily ?? 'sans-serif'));
        const fontSize = Number(live('size', o.typography?.fontSizePx ?? 16));
        const cssFamily = family.includes(',') || /^["']/.test(family) ? family : JSON.stringify(family);
        const font = `${o.typography?.fontStyle ?? 'normal'} ${o.typography?.fontWeight ?? 400} ${fontSize}px ${cssFamily}`;
        await document.fonts.load(font, String(override.text));
        context.font = font;
        const tracking = Number(live('tracking', o.typography?.letterSpacingEm ?? 0)) * fontSize;
        const width = (text: string) => Math.max(...text.split('\n').map(line => {
          const value = o.typography?.textTransform === 'uppercase' ? line.toUpperCase() : line;
          const metrics = context.measureText(value);
          return Math.max(metrics.width, metrics.actualBoundingBoxLeft + metrics.actualBoundingBoxRight) + Math.max(0, value.length - 1) * tracking;
        }));
        const allowed = Math.max(Number(o.bounds?.width ?? 100) * 5.4, width(String(o.text ?? '')));
        if (width(String(override.text ?? '')) > allowed * 1.03) throw new CocoRecipeChoiceMismatch('The event name is too wide for this design at its original text size.', 'headline-width');
      }
    }
  }
  if (sourceComposer.fieldMappingVersion === 1) {
    if (!portableRecipeId || !cocoRecipeFormCapabilities(portableRecipeId, template.formats ?? {}).fields.length) {
      throw new Error('This direction does not yet support the guided event form.');
    }
    const issue = cocoRecipeDetailsIssue(template.formats ?? {});
    if (issue) throw new CocoRecipeChoiceMismatch(issue);
  }
  if (!isCocoRecipeChoiceEligible(direction, sourceComposer, template.formats)) {
    throw new CocoRecipeChoiceMismatch(`${direction.name} contains a subject and cannot be offered for this request.`);
  }
  const variant = template.formats?.square ?? template.base ?? {};
  const variantAny = variant as Record<string, any>;
  const palette = (variantAny.palette ?? {}) as Partial<Palette>;
  const colors = Array.from(
    new Set(
      [
        palette.secondary ?? palette.bgFrom,
        palette.bgTo,
        palette.primary ?? variantAny.headColor,
        palette.accent ?? variantAny.head2Color,
        palette.neutral ?? variantAny.bodyColor,
      ]
        .map((color) => String(color || "").trim())
        .filter(Boolean)
    )
  );

  return {
    colors,
    composer,
    description: COCO_DIRECTION_DESCRIPTIONS[direction.id] ?? direction.name,
    missingDetails: Array.from(new Set(["square", "story"].flatMap(format =>
      (template.formats?.[format as Format] as any)?.cocoFormMappingReport?.unplacedLabels ?? []
    ))) as string[],
    eventName: sourceComposer.eventName,
    // The same compiled renderer paints previews and the finished editor.
    personalizedPreview: {
      square: <CocoPersonalizedPreview variant={template.formats!.square!} format="square" eventName={composer.eventName} />,
      story: <CocoPersonalizedPreview variant={template.formats!.story!} format="story" eventName={composer.eventName} />,
    },
    generatedTemplate,
    headlineFont:
      String(variantAny.headlineFamily || variantAny.textFx?.fontFamily || "").trim() ||
      undefined,
    id: direction.id,
    name: direction.name,
    offerImproveCutout: subjectAuthority.offerImproveCutout,
    preview: selectedCocoRecipeBackground(composer) || getCocoRecipePreviewExports(direction.visualRecipeId)?.square || generatedTemplate.preview,
    recipePreview: getCocoRecipePreviewExports(direction.visualRecipeId),
    previewUsesRecipeSubject:
      subjectAuthority.mode === "recipe" ||
      (subjectAuthority.mode === "blocked" && Boolean(portableRecipeId)),
    requiresRecipeSubjectConsent: subjectAuthority.requiresRecipeSubjectConsent,
    requiresSubjectRetry: subjectAuthority.mode === "blocked",
    subjectQuality: sourceComposer.subjectDecision?.quality,
    template,
  };
}

function mergeStartupVariant(
  base: Partial<TemplateBase> | undefined,
  preview: string,
  overrides: Partial<TemplateBase>
): TemplateBase {
  const merged: TemplateBase = {
    ...(base ?? {}),
    backgroundUrl:
      typeof base?.backgroundUrl === "string" && base.backgroundUrl.trim().length > 0
        ? base.backgroundUrl
        : typeof (base as any)?.bgUrl === "string" && (base as any).bgUrl.trim().length > 0
        ? String((base as any).bgUrl)
        : preview,
    ...overrides,
  };

  const emojiList = overrides.emojiList ?? base?.emojiList;
  if (Array.isArray(emojiList)) {
    merged.emojiList = [...emojiList];
  }

  const emojis = overrides.emojis ?? base?.emojis;
  if (Array.isArray(emojis)) {
    merged.emojis = [...emojis];
  }

  return merged;
}

