React.useEffect(() => {
  if (!storageReady || showStartup || loadingStartup) return;
  if (isLiveDragging) return;
  syncHeadlineStyleToSession();
}, [isLiveDragging, loadingStartup, showStartup, storageReady, syncHeadlineStyleToSession]);

React.useEffect(() => {
  if (didInitCleanRef.current) return;
  didInitCleanRef.current = true;
  const store = useFlyerState.getState();
  store.setSession({ square: {}, story: {} });
  store.setSessionDirty({ square: false, story: false });
}, []);

const didApplyLadiesNightTestRef = React.useRef(false);
React.useEffect(() => {
  if (didApplyLadiesNightTestRef.current) return;
  if (typeof window === "undefined") return;

  const params = new URLSearchParams(window.location.search);
  const directLadiesNightTest =
    params.get("test") === "ladies-night" ||
    params.get("ladiesNightTest") === "1" ||
    params.get("template") === "ladies_night_center_hero" ||
    params.get("template") === "ladies_night_isolation_test";

  if (!directLadiesNightTest) return;

  const tpl = TEMPLATE_GALLERY.find((item) => item.id === "ladies_night_center_hero");
  if (!tpl) return;

  didApplyLadiesNightTestRef.current = true;
  const targetFormat: Format = params.get("format") === "square" ? "square" : "story";

  setLoadingStartup(false);
  setShowStartup(false);
  setFormat(targetFormat);
  applyTemplateFromGallery(tpl, {
    targetFormat,
    allowStarterPreview: true,
  });

  window.setTimeout(() => {
    const subjectId =
      targetFormat === "story"
        ? "ladies_night_subject_story"
        : "ladies_night_subject_square";
    const store = useFlyerState.getState();
    store.setSelectedPortraitId(subjectId);
    store.setMoveTarget("portrait");
    store.setSelectedPanel("portrait");
  }, 120);
}, [applyTemplateFromGallery]);

const didApplyDirectTemplateRef = React.useRef(false);
React.useEffect(() => {
  if (didApplyDirectTemplateRef.current) return;
  if (typeof window === "undefined") return;

  const params = new URLSearchParams(window.location.search);
  const directTemplateId =
    params.get("leftAlign") === "1"
      ? "square_center_hero_nightlife"
      : params.get("template") || "";

  if (
    !directTemplateId ||
    directTemplateId === "ladies_night_isolation_test" ||
    directTemplateId === "ladies_night_center_hero"
  ) return;

  const tpl = TEMPLATE_GALLERY.find((item) => item.id === directTemplateId);
  if (!tpl) return;

  didApplyDirectTemplateRef.current = true;
  const targetFormat: Format = params.get("format") === "story" ? "story" : "square";

  setLoadingStartup(false);
  setShowStartup(false);
  setFormat(targetFormat);
  applyTemplateFromGallery(tpl, {
    targetFormat,
    allowStarterPreview: true,
  });
}, [applyTemplateFromGallery]);


// keep this new state near the other useStates at the top of your component
const handleTemplateSelect = React.useCallback(
  (key: string, payload?: StartupSelectPayload) => {
    if (isStarterPlan && (key === "dj" || key === "promoter" || key === "artist")) {
      alert("DJ / Artist mode unlocks after login and plan selection.");
      return;
    }
    setLoadingStartup(true);
    setStartupBuildError(null);
    setStartupStudioMode(key === "dj" ? "dj" : null);
    setDjStartupFlowStage("design");
    if (!storageReadyRef.current) {
      pendingStartupSelectionRef.current = { key, payload };
      return;
    }

    runAfterNextPaint(async () => {
      let startupExpectedCenterLayoutOptionId: CocoCenterLayoutOptionId = "subject-center";
      let startupUsesPortableRecipe = false;
      try {
        if (
          key === "coco-composer" &&
          payload?.composer &&
          !payload.composer.selectedConceptDirectionId
        ) {
          const sourceComposer = payload.composer;
          const rankedDirections = selectCocoArtDirectionChoices({
            eventDescription: [
              payload.composer.eventBrief.description,
              payload.composer.eventBrief.subtitle,
              payload.composer.eventBrief.presenterName,
              payload.composer.eventBrief.djs,
              payload.composer.eventBrief.hosts,
              payload.composer.eventBrief.performers,
              payload.composer.eventBrief.additionalActs,
              payload.composer.eventBrief.musicPolicy,
              payload.composer.eventBrief.eventDetails,
              payload.composer.eventBrief.dressCode,
              ...payload.composer.eventBrief.experienceFeatures,
              payload.composer.eventBrief.mainPromotion,
              payload.composer.eventBrief.bottleSpecials,
              payload.composer.eventBrief.drinkSpecials,
              payload.composer.eventBrief.foodSpecials,
              payload.composer.eventBrief.hookahSpecials,
              payload.composer.eventBrief.additionalOffers,
            ]
              .filter(Boolean)
              .join(" · "),
            eventName: payload.composer.eventName,
            nightlifeStyle: payload.composer.styleDecision?.style,
          });
          // Keep the preferred directions first, then fill from the complete
          // library. Eligibility is a hard boundary, before ranking or builds.
          const allDirections = Array.from(new Map([...rankedDirections, ...COCO_ART_DIRECTIONS].map(direction => [direction.id, direction])).values());
          const eligibleDirections = allDirections.filter(direction => {
            const registered = TEMPLATE_GALLERY.find(template => (template as any).recipeId === direction.visualRecipeId);
            return isCocoRecipeChoiceEligible(direction, sourceComposer, registered?.formats);
          });
          const relevantDirections = diversifyCocoRecipeChoices(eligibleDirections.map((direction, index) => {
            const registered = TEMPLATE_GALLERY.find(template => (template as any).recipeId === direction.visualRecipeId);
            const cost = direction.visualRecipeId && sourceComposer.fieldMappingVersion === 1
              ? Math.max(...(["square", "story"] as const).map(format => {
                const source = registered?.formats?.[format];
                return source ? cocoFormRecipeCost(direction.visualRecipeId!, source, sourceComposer.eventName, sourceComposer.eventBrief) : 1000;
              }))
              : 0;
            return { direction, index, cost };
          }));
          const matchingDirections = sourceComposer.eventBrief.theme ? rankCocoMatchingDirections(COCO_ART_DIRECTIONS, sourceComposer, id => TEMPLATE_GALLERY.find(template => (template as any).recipeId === id)?.formats) : relevantDirections;
          cocoEventDraftRef.current = { ...sourceComposer.eventBrief };
          const queue = { composer: sourceComposer, remaining: matchingDirections, loading: true };
          pendingCocoDirectionQueueRef.current = queue;
          setCocoHasMoreDirections(false);
          setCocoLoadingMoreDirections(false);
          setCocoMoreDirectionsError(null);
          void buildCocoRecipeChoicePage(matchingDirections, direction => buildPendingCocoDirectionCandidate(sourceComposer, direction))
            .then(({ choices: candidates, remaining, mismatches, errors }) => {
              if (pendingCocoDirectionQueueRef.current !== queue) return;
              queue.remaining = remaining;
              queue.loading = false;
              setCocoHasMoreDirections(Boolean(remaining.length));
              if (!candidates.length) {
                // Expected fit/eligibility results belong beside the inputs.
                // Keep genuine build failures on the diagnostic error path.
                if (errors.length) throw errors[0];
                setStartupBuildError(cocoNoMatchingDesignsMessage(mismatches));
                setLoadingStartup(false);
                return;
              }
              setPendingCocoDirectionCandidates(candidates);
              setLoadingStartup(false);
              void trackClientEvent("coco_direction_choices_ready", {
                properties: {
                  candidate_ids: candidates.map((candidate) => candidate.id),
                  event_name_length: sourceComposer.eventName.length,
                  mobile: isMobileView,
                },
              });
            })
            .catch((error) => {
              if (pendingCocoDirectionQueueRef.current !== queue) return;
              queue.loading = false;
              const message =
                error instanceof Error
                  ? error.message
                  : "Could not build Coco's art directions.";
              console.error("Coco direction build failed", error);
              setStartupBuildError(message);
              setLoadingStartup(false);
            });
          return;
        }

        if (
          key === "coco-composer" &&
          payload?.composer?.selectedConceptDirectionId
        ) {
          const selectedDirection = getCocoArtDirection(
            payload.composer.selectedConceptDirectionId
          );
          if (selectedDirection?.visualRecipeId) {
            const registered = TEMPLATE_GALLERY.find(template => (template as any).recipeId === selectedDirection.visualRecipeId);
            if (!isCocoRecipeChoiceEligible(selectedDirection, payload.composer, registered?.formats)) {
              setStartupBuildError("Choose a design without a subject, or add a subject first.");
              setLoadingStartup(false);
              return;
            }
            const recipeSubjectDataUrl =
              payload.composer.recipeSubjectDataUrl ||
              payload.composer.subjectDataUrl;
            const subjectAuthority = selectedDirection.subjectPolicy.mode === "none"
              ? {
                  mode: "none" as const,
                  offerImproveCutout: false,
                  requiresRecipeSubjectConsent: false,
                }
              : resolveCocoRecipeSubjectAuthority({
                  decision: payload.composer.subjectDecision,
                  visualRecipeId: selectedDirection.visualRecipeId,
                  hasRecipeSubjectFallback: isCocoPortableRecipeId(
                    selectedDirection.visualRecipeId
                  ),
                  hasUserSubject: Boolean(recipeSubjectDataUrl),
                });
            if (subjectAuthority.mode === "blocked") {
              setStartupBuildError(
                subjectAuthority.requiresRecipeSubjectConsent
                  ? "Choose Try another photo or explicitly use the recipe subject."
                  : "This recipe needs a cleaner subject photo. Try another photo."
              );
              setLoadingStartup(false);
              return;
            }
          }
        }

        const startupFormat: Format = "square";
        // The startup reveal must wait for the layout requested by the chosen
        // direction. Center directions can legitimately open on Vertical
        // Rail/Text Left/Text Right; treating Layout 1 as the only completed
        // center state repeatedly replaced their authored geometry while the
        // cover was still mounted.
        const store = useFlyerState.getState();
        manualSceneBuilderPaletteRef.current = {};
        generatedSceneBuilderPaletteCycleRef.current = {};
        setGeneratedSceneBuilderPaletteStatus({});
        if (key === "coco-composer" && payload?.composer) {
          // Per-layout sessions belong to one generated flyer. Keeping them
          // across a new generation resurrects copy and geometry from an
          // earlier canvas because their keys are only format + layout ID.
          store.clearCocoLayoutSessions();
        }
        store.setSession((prev) => ({ ...prev, square: {}, story: {} }));
        store.setSessionDirty((prev) => ({ ...prev, square: false, story: false }));
        setFormat(startupFormat);

        if (key === "coco-composer" && payload?.composer) {
          setPortraitUrl(null);
          setBlendSubject(null);
          setBlendSubjectCutout(null);
          const selectedArtDirection = payload.composer.selectedConceptDirectionId
            ? getCocoArtDirection(payload.composer.selectedConceptDirectionId)
            : undefined;
          const selectedPortableRecipeId = isCocoPortableRecipeId(
            selectedArtDirection?.visualRecipeId
          )
            ? selectedArtDirection.visualRecipeId
            : null;
          startupUsesPortableRecipe = Boolean(selectedPortableRecipeId);
          const prebuilt = prebuiltCocoDirectionTemplateRef.current;
          const matchingPrebuilt =
            prebuilt?.composer.selectedConceptDirectionId ===
            payload.composer.selectedConceptDirectionId
              ? prebuilt
              : null;
          prebuiltCocoDirectionTemplateRef.current = null;
          if (!selectedArtDirection) {
            throw new Error("Select an authored Coco recipe before creating a flyer.");
          }
          const authoredCandidate = matchingPrebuilt ??
            await buildPendingCocoDirectionCandidate(payload.composer, selectedArtDirection);
          const generatedComposerTemplate = authoredCandidate.generatedTemplate;
          const composerTemplate = authoredCandidate.template;
          const squareVariant =
            composerTemplate.formats?.square ?? composerTemplate.base ?? {};
          const storyVariant =
            composerTemplate.formats?.story ??
            composerTemplate.formats?.square ??
            composerTemplate.base ??
            {};
          const startupSubjectLayoutId = (
            (squareVariant as any).cocoSubjectLayoutId === "subject-left" ||
            (squareVariant as any).cocoSubjectLayoutId === "subject-right"
              ? (squareVariant as any).cocoSubjectLayoutId
              : selectedArtDirection?.layoutByFormat.square.layoutId ?? "subject-center"
          ) as CocoSubjectLayoutId;
          const requestedCenterLayoutOption = (squareVariant as any).cocoCenterLayoutOptionId;
          const startupCenterLayoutOptionId: CocoCenterLayoutOptionId =
            requestedCenterLayoutOption === "subject-center-rail" ||
            requestedCenterLayoutOption === "subject-text-left" ||
            requestedCenterLayoutOption === "subject-text-right"
              ? requestedCenterLayoutOption
              : "subject-center";
          startupExpectedCenterLayoutOptionId = startupCenterLayoutOptionId;
          templatePaletteAnalysisRef.current += 1;
          store.setSession((prev) => ({
            ...prev,
            square: cloneTemplateSessionVariant(squareVariant),
            story: cloneTemplateSessionVariant(storyVariant),
          }));
          store.setSessionDirty((prev) => ({ ...prev, square: false, story: false }));
          setTemplateId(composerTemplate.id);
          setActiveTemplate(composerTemplate);
          cocoManualFitOverridesRef.current = {};
          cocoAppliedCompositionSignatureRef.current = "";
          setCocoDirectorZones({});
          setCocoDirectorZoneKey(null);
          setCocoReferenceLayoutId(null);
          setCocoSubjectLayoutId(startupSubjectLayoutId);
          if (startupSubjectLayoutId === "subject-center") {
            setCocoCenterLayoutOptionId(startupCenterLayoutOptionId);
          }
          applyTemplate(composerTemplate, { targetFormat: startupFormat, initialLoad: true });
          setCocoNativeReferenceTemplateId(
            selectedPortableRecipeId ? null : payload.composer.layoutRecipeTemplateId
          );
          setCocoVisualReferenceSearch({
            status: "ready",
            templateIds: [payload.composer.layoutRecipeTemplateId],
            visualIds: payload.composer.visualReferenceId
              ? [payload.composer.visualReferenceId]
              : [],
          });
          setCocoSubjectLayoutId(startupSubjectLayoutId);
          if (startupSubjectLayoutId === "subject-center") {
            setCocoCenterLayoutOptionId(startupCenterLayoutOptionId);
          }
          if (!selectedPortableRecipeId) {
            if (payload.composer.backgroundDataUrl) {
              setBgUploadUrl(payload.composer.backgroundDataUrl);
              setBgUrl(null);
            } else if (payload.composer.backgroundSrc) {
              applyStartupBackground(payload.composer.backgroundSrc);
            }
            // applyTemplate and the background source update are both queued in
            // this startup turn. Commit the analyzed variant's face-directed
            // transform explicitly so the live image cannot retain the previous
            // canvas's default 50/50 crop while its face rectangle comes from
            // the new image analysis. Portable recipes own this whole layer.
            setBgPosX(Number(squareVariant.bgPosX ?? 50));
            setBgPosY(Number(squareVariant.bgPosY ?? 50));
            setBgScale(Number(squareVariant.bgScale ?? 1));
            setBgFitMode(Boolean((squareVariant as any).bgFitMode ?? false));
            setBgRotate(Number(squareVariant.bgRotate ?? 0));
            void applyTemplateBackgroundPalette(
              composerTemplate,
              startupFormat,
              payload.composer.backgroundDataUrl || payload.composer.backgroundSrc
            );
          }
          void trackClientEvent("template_selected", {
            properties: {
              source: "startup",
              selection_type: "coco_composer",
              startup_key: key,
              template_id: composerTemplate.referenceTemplateId || composerTemplate.id,
              generated_template_id: composerTemplate.id,
              template_label: composerTemplate.label,
              coco_style: payload.composer.styleDecision?.style ?? null,
              coco_style_confidence: payload.composer.styleDecision?.confidence ?? null,
              coco_style_source: payload.composer.styleDecision?.source ?? null,
              coco_style_needs_user: payload.composer.styleDecision?.askUser ?? null,
              coco_direction_id: selectedArtDirection?.id ?? null,
              format: startupFormat,
              mobile: isMobileView,
              guest_mode: isGuestTrial,
              is_starter: isStarterPlan,
            },
          });
          recordCocoLearningOutcome({
            outcome: "concept_generated",
            suggestion: (generatedComposerTemplate as any).cocoConceptSummary?.winner?.learningSuggestion ?? null,
            template: generatedComposerTemplate,
            templateId: composerTemplate.id,
            userAction: {},
          });
          pendingCocoDirectionQueueRef.current = null;
          setPendingCocoDirectionCandidates([]);
        } else if (key === "dj" || key === "promoter" || key === "artist") {
          const startupTemplate = buildStartupCategoryTemplate(key);
          setTemplateId(startupTemplate.id);
          setActiveTemplate(startupTemplate);
          applyTemplate(startupTemplate, { targetFormat: startupFormat, initialLoad: true });

          if (key === "dj") {
            const startupBackground =
              payload?.startupBackgroundDataUrl ||
              payload?.startupBackgroundSrc ||
              DJ_STARTUP_BACKGROUNDS[0].src;
            applyStartupBackground(startupBackground);
            setTextSide("left");
            setHeadAlign("left");
            setAlign("left");
            setTextStyle("headline", startupFormat, { align: "left" });
            setHead2Align("left");
            setTextStyle("headline2", startupFormat, { align: "left" });
            setDetailsAlign("left");
            setDetails2Align("left");
            setVenueAlign("left");
            setSubtagAlign("left");
          }

          if (key === "promoter" || key === "artist") {
            setHeadAlign("center");
            setAlign("center");
            setTextStyle("headline", startupFormat, { align: "center" });
            setHead2Align("center");
            setTextStyle("headline2", startupFormat, { align: "center" });
            setDetailsAlign("center");
            setDetails2Align("center");
            setVenueAlign("center");
            setSubtagAlign("center");
          }
        } else {
          // ✅ Map each vibe to a real template index
          const vibeToTemplateId: Record<string, string> = {
            club: isStarterPlan ? "disco_mirrorball" : "miami2",
            tropical: isStarterPlan ? resolveStarterTemplateChoiceId(1) : "latin_street_tropical",
            luxury: isStarterPlan ? "new-york" : "atlanta",
            urban: "square_center_hero_nightlife",
          };

          const selectedTemplate = TEMPLATE_GALLERY.find((t) => t.id === key);
          const tplId = selectedTemplate?.id ?? vibeToTemplateId[key] ?? TEMPLATE_GALLERY[0]?.id;
          const tpl = selectedTemplate ?? TEMPLATE_GALLERY.find((t) => t.id === tplId);
          if (!tpl) throw new Error("Template not found for vibe: " + key);
          applyTemplateFromGallery(tpl, { targetFormat: startupFormat, allowStarterPreview: true });
          void trackClientEvent("template_selected", {
            properties: {
              source: "startup",
              selection_type: selectedTemplate ? "template_card" : "vibe",
              startup_key: key,
              template_id: tpl.id,
              template_label: tpl.label,
              format: startupFormat,
              mobile: isMobileView,
              guest_mode: isGuestTrial,
              is_starter: isStarterPlan,
            },
          });
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : "Could not load template.";
        console.error("Coco/template startup failed", error);
        setStartupBuildError(message);
        setLoadingStartup(false);
        return;
      }

      const revealAppliedTemplate = () => {
        setLoadingStartup(false);
        setShowStartup(false);
        scrollToArtboard();

        if (key === "coco-composer") {
          const store = useFlyerState.getState();
          setCocoEditorSurface("quick");
          setCocoMoreTools(false);
          setUiMode("design");
          store.setSelectedPanel(null);
          store.setMoveTarget(null);
          setMobileControlsOpen(false);
          return;
        }

        if (key === "dj") {
          setMobileControlsOpen(true);
          setMobileControlsTab("assets");
          useFlyerState.getState().setSelectedPanel(isStarterPlan ? "portrait" : "dj_branding");
          return;
        }

        if (useFlyerState.getState().selectedPanel == null) {
          useFlyerState.getState().setSelectedPanel("template");
        }
      };

      if (key === "coco-composer") {
        if (startupUsesPortableRecipe) {
          // Portable masters are already complete Square/Story compositions;
          // they deliberately do not participate in the generic center-layout
          // snapshot builder. Give React two frames to mount the authored
          // state, then reveal it without applying Layout 1 over the recipe.
          window.requestAnimationFrame(() => {
            window.requestAnimationFrame(revealAppliedTemplate);
          });
          return;
        }
        // A native reference first mounts with styling and object construction
        // only. Keep the startup cover in place until the verified, font-aware
        // Layout 1 mapper has committed its canonical v55 composition. The old
        // fixed 240 ms reveal exposed raw reference coordinates and made the
        // canvas look broken until the user clicked Layout 1 manually.
        let compositionChecks = 0;
        const revealWhenComposed = () => {
          const liveVariant = (useFlyerState.getState().session?.square ?? {}) as Record<string, any>;
          const liveLayoutId = String(liveVariant.cocoSubjectLayoutId ?? "");
          const liveCenterLayoutVersion = Number(liveVariant.cocoCenterLayoutVersion ?? 0);
          const liveCenterLayoutOptionId = String(liveVariant.cocoCenterLayoutOptionId ?? "");
          const liveCenterSnapshots = (
            liveVariant.cocoCenterLayoutSnapshots ?? {}
          ) as Partial<Record<CocoCenterLayoutOptionId, Record<string, any>>>;
          const expectedCenterSnapshot =
            liveCenterSnapshots[startupExpectedCenterLayoutOptionId] ?? null;
          const liveCenterGeometry = cocoLayoutLiveStateRef.current;
          const expectedCenterGeometryReady =
            startupExpectedCenterLayoutOptionId !== "subject-center-rail" ||
            !expectedCenterSnapshot
              ? true
              : Math.abs(
                  Number(liveCenterGeometry.headRotate ?? 0) -
                    Number(expectedCenterSnapshot.headRotate ?? 0)
                ) < 0.5 &&
                Math.abs(
                  Number(liveCenterGeometry.head2Rotate ?? 0) -
                    Number(expectedCenterSnapshot.head2Rotate ?? 0)
                ) < 0.5 &&
                Math.abs(
                  Number(liveCenterGeometry.headManualPx ?? 0) -
                    Number(expectedCenterSnapshot.headlineSize ?? expectedCenterSnapshot.headSize ?? 0)
                ) < 0.75 &&
                Math.abs(
                  Number(liveCenterGeometry.head2SizePx ?? 0) -
                    Number(expectedCenterSnapshot.head2Size ?? 0)
                ) < 0.75;
          const centerCompositionReady =
            liveLayoutId === "subject-center" &&
            liveCenterLayoutVersion >= 55 &&
            liveCenterLayoutOptionId === startupExpectedCenterLayoutOptionId &&
            Boolean(expectedCenterSnapshot) &&
            expectedCenterGeometryReady &&
            cocoSnapshotLayoutRafRef.current == null;
          // Side/split art directions arrive as complete generated
          // compositions. They do not use the center-only v55 snapshot
          // contract, so waiting for that marker would overwrite the chosen
          // crop, text column, and editable contrast assets with Layout 1.
          const sideCompositionReady =
            liveLayoutId === "subject-left" || liveLayoutId === "subject-right";
          const compositionReady = centerCompositionReady || sideCompositionReady;
          if (compositionReady) {
            revealAppliedTemplate();
            return;
          }

          if (
            liveLayoutId === "subject-center" &&
            (compositionChecks === 0 || compositionChecks % 10 === 0)
          ) {
            // Layout 1 owns the canonical snapshot build. Once that build is
            // complete, converge on the direction's requested option instead
            // of repeatedly undoing it with another Layout 1 application.
            const nextCenterOption =
              liveCenterLayoutVersion >= 55 && expectedCenterSnapshot
                ? startupExpectedCenterLayoutOptionId
                : "subject-center";
            const resetExpectedOption =
              nextCenterOption === startupExpectedCenterLayoutOptionId &&
              liveCenterLayoutOptionId === startupExpectedCenterLayoutOptionId &&
              !expectedCenterGeometryReady;
            applyCocoSubjectLayoutRef.current?.(
              nextCenterOption,
              resetExpectedOption ? { reset: true } : undefined
            );
          }
          compositionChecks += 1;
          if (compositionChecks >= 120) {
            setLoadingStartup(false);
            setStartupBuildError("Coco could not finish this layout. Please create the options again.");
            return;
          }
          window.setTimeout(revealWhenComposed, 50);
        };
        window.requestAnimationFrame(() => {
          window.requestAnimationFrame(revealWhenComposed);
        });
        return;
      }

      window.setTimeout(revealAppliedTemplate, 240);
    });

  },
  [
    applyStartupBackground,
    applyTemplate,
    applyTemplateBackgroundPalette,
    applyTemplateFromGallery,
    isGuestTrial,
    isMobileView,
    isStarterPlan,
    scrollToArtboard,
    setTextStyle,
  ]
);
// === /STARTUP SCREEN ===

React.useEffect(() => {
  if (!storageReady) return;
  const pending = pendingStartupSelectionRef.current;
  if (!pending) return;
  pendingStartupSelectionRef.current = null;
  handleTemplateSelect(pending.key, pending.payload);
}, [storageReady, handleTemplateSelect]);


