const applyCocoConversationGrade = (id: string) => {
  const preset = COCO_CONVERSATION_GRADES.find(g => g.id === id); if (!preset) return;
  const store = useFlyerState.getState();
  if (!cocoConversationOriginalGrades.current) cocoConversationOriginalGrades.current = Object.fromEntries((['square', 'story'] as const).map(f => [f, Object.fromEntries(COCO_GRADE_KEYS.map(key => [key, (store.session[f] as any)?.[key]]))]));
  const next = { ...store.session };
  for (const f of ['square', 'story'] as const) next[f] = { ...next[f], ...(preset.values ?? cocoConversationOriginalGrades.current[f]) };
  store.setSession(next); store.setSessionDirty(current => ({ ...current, square: true, story: true }));
  const v = next[format] as any;
  setExp(v.exp ?? 1); setContrast(v.contrast ?? 1.08); setSaturation(v.saturation ?? 1.1); setWarmth(v.warmth ?? .1); setTint(v.tint ?? 0); setGamma(v.gamma ?? 1); setGrain(v.grain ?? .15); setFilmGrade(v.filmGrade ?? .6); setVibrance(v.vibrance ?? .15);
  setCocoConversationGrade(id);
};
