const [cocoGuideSection, setCocoGuideSection] = React.useState<CocoGuideSection>('headline');
const [cocoGuideScope, setCocoGuideScope] = React.useState<'current' | 'both'>('current');
const [cocoGuideMessage, setCocoGuideMessage] = React.useState('');
const [cocoGuideHistory, setCocoGuideHistory] = React.useState<{ section: CocoGuideSection; before: Record<string, any>; after: Record<string, any> }[]>([]);
const [cocoFinishIssues, setCocoFinishIssues] = React.useState<CocoFinishIssue[] | null>(null);
const [cocoFinishAccepted, setCocoFinishAccepted] = React.useState<string[]>([]);
const cocoGuidePendingField = React.useRef<string | null>(null);
React.useEffect(() => {
  setCocoGuideHistory([]); setCocoGuideMessage(''); setCocoFinishIssues(null);
}, [activeCocoQuickVariant.cocoVisualRecipeId, showStartup]);
const focusCocoQuickField = (field: string) => {
  setCocoConversationRequest({ field, serial: Date.now() });
  const panel = document.querySelector<HTMLElement>('[data-testid="coco-quick-edit"]');
  const testId = field === 'eventName' ? 'coco-quick-event-name' : field === 'photos' ? 'coco-quick-replace-scene' : `coco-quick-brief-${field}`;
  const target = panel?.querySelector<HTMLElement>(`[data-testid="${CSS.escape(testId)}"], [data-testid="${CSS.escape(testId)}-line-1"]`);
  if (!target) return;
  for (let parent = target.parentElement; parent; parent = parent.parentElement) if (parent instanceof HTMLDetailsElement) parent.open = true;
  target.scrollIntoView({ behavior: 'smooth', block: 'center' }); target.focus({ preventScroll: true });
};
React.useEffect(() => {
  if (pendingFormat || fadeOut || !cocoGuidePendingField.current) return;
  const field = cocoGuidePendingField.current; cocoGuidePendingField.current = null;
  requestAnimationFrame(() => focusCocoQuickField(field));
}, [format, pendingFormat, fadeOut]);
const syncCocoGuidedNative = (v: Record<string, any>) => {
  const store = useFlyerState.getState();
  for (const target of ['square', 'story'] as const) {
    const assets = (store.session[target] as any)?.portraits;
    if (Array.isArray(assets) && assets !== store.portraits[target]) store.setPortraits(target, assets, { syncSession: false });
  }
  if (Number.isFinite(v.headManualPx)) { setHeadManualPx(v.headManualPx); setHeadMaxPx(v.headMaxPx ?? v.headManualPx); setHeadSizeAuto(Boolean(v.headSizeAuto)); }
  if (Number.isFinite(v.head2SizePx)) setHead2SizePx(v.head2SizePx);
  if (Number.isFinite(v.hue)) setHue(v.hue);
  if (v.palette) setPalette(v.palette);
};
const commitCocoGuidedAction = (section: CocoGuideSection, transform: (v: Record<string, any>, target: 'square' | 'story') => Record<string, any>, message: string) => {
  const store = useFlyerState.getState(), before = store.session;
  const targets = cocoGuideScope === 'both' ? ['square', 'story'] as const : [format];
  const after = { ...before };
  for (const target of targets) if (before[target]) after[target] = transform({ ...before[target], format: target }, target);
  store.setSession(after); store.setSessionDirty(current => ({ ...current, ...Object.fromEntries(targets.map(f => [f, true])) }));
  syncCocoGuidedNative(after[format]);
  setCocoGuideHistory(history => [...history, { section, before, after }]);
  setCocoGuideMessage(message);
};
const applyCocoConversationPalette = async (id: string, options: { mode?: PaletteBlend; strength?: number } = {}) => {
  const preset = COCO_TEXT_PALETTES.find(p => p.id === id);
  const current = useFlyerState.getState().session;
  const token = ++cocoPaletteRequest.current;
  setCocoPaletteBusy(true); setCocoPaletteError('');
  const targets = cocoGuideScope === 'both' ? ['square', 'story'] as const : [format];
  try {
    const prepared: Record<string, any> = {};
    for (const target of targets) {
      delete manualSceneBuilderPaletteRef.current[target];
      const source = current[target] as any;
      const colors = preset ? cocoConversationLinkedPalette(preset.id) : source.cocoCompositionSystem?.linkedPalette?.colors;
      if (!colors) continue;
      prepared[target] = await prepareCocoLinkedPalette(source, colors, { ...options, id });
    }
    if (token !== cocoPaletteRequest.current) return;
    commitCocoGuidedAction('details', (variant, target) => prepared[target] ? mergeCocoLinkedPalette(variant, prepared[target]) : variant, 'Palette colors updated.');
    if (prepared[format]?.palette) setPalette(prepared[format].palette);
  } catch { setCocoPaletteError('Could not prepare these colors. Your previous palette is kept.'); }
  finally { if (token === cocoPaletteRequest.current) setCocoPaletteBusy(false); }
};
const adjustCocoQuickSize = (field: string, id: string, value: number) => {
  const current = cocoQuickTextSizeOwners({ ...useFlyerState.getState().session[format], format }, field, cocoQuickFormCapabilities.bindings[field]).find((o: { id: string; size: number }) => o.id === id);
  if (!current || !Number.isFinite(value) || Math.abs(value - current.size) < .0001) return;
  const factor = value / current.size;
  commitCocoGuidedAction(field === 'eventName' ? 'headline' : 'details', (v, target) => {
    const owners = cocoQuickTextSizeOwners(v, field, cocoQuickFormCapabilities.bindings[field]);
    const owner = owners.find((o: { id: string; size: number }) => o.id === id) ?? (owners.length === 1 ? owners[0] : undefined);
    return owner ? cocoGuidedStyle(v, owner.id, 'size', target === format ? value : owner.size * factor) : v;
  }, cocoGuideScope === 'both' ? 'Size adjusted proportionally in Square and Story.' : `Size updated in ${format === 'square' ? 'Square' : 'Story'}.`);
};
const enlargeCocoGuideSection = (section: CocoGuideSection = cocoGuideSection) => {
  commitCocoGuidedAction(section, v => {
    const fields = section === 'headline' ? ['eventName'] : cocoQuickFormCapabilities.fields;
    let next = v;
    for (const field of fields) for (const owner of cocoQuickTextSizeOwners(v, field, cocoQuickFormCapabilities.bindings[field])) next = cocoGuidedStyle(next, owner.id, 'size', Math.round(owner.size * 1.1 * 10) / 10);
    return next;
  }, 'Text is 10% larger. Check the preview; you can undo this adjustment.');
};
const undoCocoGuide = () => {
  const last = cocoGuideHistory.at(-1); if (!last) return;
  const store = useFlyerState.getState();
  const next = cocoGuidedUndo(store.session, last.before, last.after);
  store.setSession(next); store.setSessionDirty(current => ({ ...current, square: true, story: true })); syncCocoGuidedNative(next[format]);
  setCocoGuideHistory(history => history.slice(0, -1)); setCocoGuideMessage('Last adjustment undone.');
};
const resetCocoGuideSection = () => {
  const store = useFlyerState.getState(), before = store.session;
  let after = before;
  for (const action of [...cocoGuideHistory].reverse()) if (action.section === cocoGuideSection) after = cocoGuidedUndo(after, action.before, action.after);
  if (cocoGuideScope === 'current') after = { ...before, [format]: after[format] };
  store.setSession(after); store.setSessionDirty(current => ({ ...current, square: true, story: true })); syncCocoGuidedNative(after[format]);
  setCocoGuideHistory(history => [...history, { section: cocoGuideSection, before, after }]);
  setCocoGuideMessage('This section’s size and color adjustments were reset. Your wording is kept.');
};

const activeCocoQuickBrief = (activeCocoQuickVariant.cocoEventBrief ?? {}) as Partial<CocoComposerEventBrief>;
