// New selections share one palette contract. Legacy documents without the
// collection marker retain their saved colors and rendering behavior.
const coreHeadlineColors = React.useMemo(() => mapHeadlinePalette(palette), [palette]);
const applyCoreHeadlinePalette = React.useCallback((id: HeadlinePresetId) => {
  const c = coreHeadlineColors;
  setHeadGlassPaletteLinked(false);
  setHeadPure3dPaletteLinked(false);
  setHeadGoldBlockPaletteLinked(false);
  setHeadDashStrokePaletteLinked(false);
  setHeadKineticPaletteLinked(false);
  setHeadGlassPrimaryColor(c.face); setHeadGlassSecondaryColor(c.depth);
  setHeadGlassHighlightColor(c.highlight); setHeadGlassEdgeColor(c.edge);
  setHeadPure3dFaceColor(c.face); setHeadPure3dEdgeColor(c.edge); setHeadPure3dShadowColor(c.shadow);
  setHeadGoldBlockLightColor(c.light); setHeadGoldBlockMidColor(c.face); setHeadGoldBlockDarkColor(c.dark);
  setHeadGoldBlockHighlightColor(c.highlight); setHeadGoldBlockAmberColor(c.edge); setHeadGoldBlockBurnColor(c.shadow);
  setHeadGoldBlockStrokeColor(c.dark);
  setHeadDashStrokeColors(c.stroke);
  setHeadKineticTextColor(c.face); setHeadKineticTopColor(c.edge); setHeadKineticBottomColor(c.depth);
  setHeadRushDotColor(c.face); setHeadRushContrastColor(c.highlight);
  setHeadGlitchRedColor(c.face); setHeadGlitchMagentaColor(c.depth);
  setHeadGlitchBlueColor(c.edge); setHeadGlitchYellowColor(c.highlight);
  setHeadExtrudeColor(c.depth);
  setTextFx(previous => ({ ...previous,
    color: id === 'outline' ? 'transparent' : c.face,
    gradFrom: id === 'metal' ? c.light : c.face,
    gradMid: id === 'metal' ? c.face : c.depth,
    gradTo: id === 'metal' ? c.dark : c.edge,
    strokeColor: id === 'outline' ? c.face : c.highlight,
    glowColor: c.edge, shadowColor: c.shadow,
  }));
}, [coreHeadlineColors]);
React.useEffect(() => {
  if (headPremiumPreset) applyCoreHeadlinePalette(headPremiumPreset);
}, [headPremiumPreset, applyCoreHeadlinePalette]);

const applyPremiumHeadlinePreset = (id: HeadlinePresetId, variant?: 'tube') => {
  clearInactiveHeadlinePresetRenderState();
  switch (id) {
    case 'clean': case 'outline':
      resetHeadlinePresetStyles();
      setTextFx(previous => ({ ...previous, gradient: false, italic: false,
        tracking: -.02, strokeWidth: id === 'outline' ? 1.5 : 0,
        color: id === 'outline' ? 'transparent' : coreHeadlineColors.face,
      }));
      break;
    case 'glass':
      if (isMobileView) applyHeadlineAcrylicGlassPreset(); else applyHeadlineGlassPreset();
      break;
    case 'metal':
      applyHeadlineGoldBlockPreset();
      setHeadGoldBlockStrokeWidth(1.2); setHeadGoldBlockTexture(.08);
      setHeadGoldBlockRoughness(.12); setHeadGoldBlockBevel(.5);
      setHeadMetalBlur(0); setHeadGoldBlockShine(.75); setHeadGoldBlockShadow(.32);
      setHeadExtrudeDepth(0); setHeadExtrudeDistance(0);
      break;
    case '3d':
      applyHeadlinePure3dPreset(); setHeadPure3dFrame(.48); setHeadExtrudeDepth(14);
      break;
    case 'neon':
      if (variant === 'tube') applyHeadlineGlitchPreset(); else applyHeadlineNeonGlowPreset();
      setHeadGlitchGlow(variant === 'tube' ? 12 : 10);
      setHeadGlitchNoise(0); setHeadGlitchRgbSplit(variant === 'tube' ? 9 : 2);
      break;
    case 'stroke':
      applyHeadlineDashStrokePreset();
      setTextFx(previous => ({ ...previous, glow: 4 }));
      break;
    case 'halftone':
      applyHeadlineRushHalftonePreset();
      setHeadRushDotSize(3.2); setHeadRushDotSpacing(5.5); setHeadRushShadowOffset(0);
      setTextFx(previous => ({ ...previous, glow: 0, tracking: -.025 }));
      break;
    case 'kinetic':
      applyHeadlineKineticPreset(); setHeadKineticSliceOffsetX(12);
      setHeadKineticSliceOffsetY(1); setHeadKineticShadowOpacity(.32);
      break;
  }
  // Material selection should not replace the user's chosen letterforms.
  setHeadlineFamily(headlineFamily);
  setTextStyle('headline', format, { family: headlineFamily });
  setHeadSkew(0); setHeadRotate(0);
  setHeadPremiumPreset(id);
  applyCoreHeadlinePalette(id);
};

const mobilePanelClass = React.useCallback(
  (tab: "design" | "assets", panel: string | string[]) => {
    if (!mobileVisibleCreatorPanels) return "";
    const visibleSet = tab === "design" ? mobileVisibleCreatorPanels.design : mobileVisibleCreatorPanels.assets;
    const keys = Array.isArray(panel) ? panel : [panel];
    return keys.some((key) => visibleSet.has(key)) ? "" : "hidden";
  },
  [mobileVisibleCreatorPanels]
);
