const recordMove = React.useCallback(
  (move: {
    kind:
      | "icon"
      | "emoji"
      | "portrait"
      | "headline"
      | "headline2"
      | "details"
      | "details2"
      | "venue"
      | "subtag"
      | "presenter"
      | "leftRail"
      | "rightRail"
      | "socialHandle"
      | "date"
      | "time"
      | "price"
      | "compliance"
      | "qr"
      | "logo"
      | "background";
    id: string;
    x: number;
    y: number;
  }) => {
    if (isCocoLayoutEditable) {
      cocoLayoutDirtyRef.current[format] = true;
      const overrides = cocoRailManualOverridesRef.current[format];
      if (move.kind === "socialHandle") overrides.handle = true;
      if (move.kind === "leftRail") overrides.rsvp = true;
      if (move.kind === "compliance") overrides.compliance = true;
      if (move.kind === "price") overrides.price = true;
      setCocoLayoutDirtyByFormat((current) =>
        current[format] ? current : { ...current, [format]: true }
      );
    }
    setLastMoveStack((prev) => {
      const next = [...prev, move];
      return next.length > 3 ? next.slice(-3) : next;
    });
  },
  [cocoCenterLayoutOptionId, format, isCocoLayoutEditable]
);

const undoAssetPosition = React.useCallback(() => {
  if (!lastMoveStack.length) return;
  const lastMovePos = lastMoveStack[lastMoveStack.length - 1];
  switch (lastMovePos.kind) {
    case "icon":
      updateIcon(lastMovePos.id, { x: lastMovePos.x, y: lastMovePos.y });
      break;
    case "emoji":
      updateEmoji(format, lastMovePos.id, {
        x: lastMovePos.x,
        y: lastMovePos.y,
      });
      break;
    case "portrait":
      updatePortrait(format, lastMovePos.id, {
        x: lastMovePos.x,
        y: lastMovePos.y,
      });
      break;
    case "headline":
      setHeadX(lastMovePos.x);
      setHeadY(lastMovePos.y);
      break;
    case "headline2":
      setHead2X(lastMovePos.x);
      setHead2Y(lastMovePos.y);
      break;
    case "details":
      setDetailsX(lastMovePos.x);
      setDetailsY(lastMovePos.y);
      break;
    case "details2":
      setDetails2X(lastMovePos.x);
      setDetails2Y(lastMovePos.y);
      break;
    case "venue":
      setVenueX(lastMovePos.x);
      setVenueY(lastMovePos.y);
      break;
    case "subtag":
      setSubtagX(lastMovePos.x);
      setSubtagY(lastMovePos.y);
      break;
    case "presenter":
      setPresenterX(lastMovePos.x);
      setPresenterY(lastMovePos.y);
      break;
    case "leftRail":
      setLeftRailX(lastMovePos.x);
      setLeftRailY(lastMovePos.y);
      break;
    case "rightRail":
      setRightRailX(lastMovePos.x);
      setRightRailY(lastMovePos.y);
      break;
	    case "date":
	      onDateMoveRafSafe(lastMovePos.x, lastMovePos.y);
	      break;
	    case "time":
	      onTimeMoveRafSafe(lastMovePos.x, lastMovePos.y);
	      break;
	    case "price":
	      onPriceMoveRafSafe(lastMovePos.x, lastMovePos.y);
	      break;
    case "compliance":
      setComplianceX(lastMovePos.x);
      setComplianceY(lastMovePos.y);
      useFlyerState.getState().setSessionValue(format, "complianceX", lastMovePos.x);
      useFlyerState.getState().setSessionValue(format, "complianceY", lastMovePos.y);
      break;
    case "qr":
      setQrX(lastMovePos.x);
      setQrY(lastMovePos.y);
      break;
    case "logo":
      setLogoX(lastMovePos.x);
      setLogoY(lastMovePos.y);
      break;
    case "background":
      setBgX(lastMovePos.x);
      setBgY(lastMovePos.y);
      setBgPosX(lastMovePos.x);
      setBgPosY(lastMovePos.y);
      break;
  }
  setLastMoveStack((prev) => prev.slice(0, -1));
  if (isMobileView && activeAssetControls) {
    // Keep asset float open after undo to avoid control flicker/closure.
    showMobileFloat("asset");
  }
}, [
  lastMoveStack,
  format,
  isMobileView,
  activeAssetControls,
  showMobileFloat,
  updateIcon,
  updateEmoji,
  updatePortrait,
  setHeadX,
  setHeadY,
  setHead2X,
  setHead2Y,
  setDetailsX,
  setDetailsY,
  setDetails2X,
  setDetails2Y,
  setVenueX,
  setVenueY,
  setSubtagX,
  setSubtagY,
  setLogoX,
  setLogoY,
	  setBgX,
	  setBgY,
	  setBgPosX,
	  setBgPosY,
	  onDateMoveRafSafe,
	  onTimeMoveRafSafe,
	  onPriceMoveRafSafe,
	]);

