type CanvasHorizontalAlignment = "left" | "center" | "right";

const alignCanvasObjectHorizontally = (alignment: CanvasHorizontalAlignment) => {
  const store = useFlyerState.getState();
  const rawActive =
    resolveCoordinateReaderTarget(store.moveTarget, store.selectedPanel) ??
    store.selectedPanel ??
    null;
  const active =
    rawActive === "head2"
      ? "headline2"
      : rawActive === "social"
        ? "socialHandle"
        : rawActive;

  if (!active) {
    alert("❌ Nothing selected");
    return;
  }

  if (active === "background") {
    setBgPosX(alignment === "left" ? 0 : alignment === "right" ? 100 : 50);
    return;
  }

  const root = canvasRefs.root;
  if (!root) {
    alert("❌ Canvas root not found");
    return;
  }

  // Compiled text owns its position independently of the legacy coordinate
  // setters. Align its painted text and persist the same override used by drag.
  const compiledPanel = active === "headline2" ? "head2" : active;
  const compiledObject = activeCompiledLayerObjects.find((object: any) =>
    object.kind === "text" && object.id === activeCompiledTextLayerDescriptor?.id &&
    (object.binding?.moveTarget === active || object.binding?.panel === compiledPanel))
    ?? (["headline", "headline2"].includes(active)
      ? activeCompiledLayerObjects.find((object: any) => object.kind === "text" && object.binding?.panel === compiledPanel)
      : undefined);
  if (compiledObject) {
    const owner = Array.from(root.querySelectorAll<HTMLElement>("[data-coco-compiled-object]"))
      .find(node => node.dataset.cocoCompiledObject === compiledObject.id);
    if (!owner) return;
    const canvasRect = root.getBoundingClientRect();
    if (!canvasRect.width) return;
    const rects: DOMRect[] = [];
    const walker = document.createTreeWalker(owner, NodeFilter.SHOW_TEXT);
    while (walker.nextNode()) {
      const node = walker.currentNode;
      if (!node.textContent?.trim() || node.parentElement?.closest("svg")) continue;
      const range = document.createRange(); range.selectNodeContents(node);
      rects.push(...Array.from(range.getClientRects()).filter(rect => rect.width > 0));
    }
    const box = owner.getBoundingClientRect();
    const left = rects.length ? Math.min(...rects.map(rect => rect.left)) : box.left;
    const right = rects.length ? Math.max(...rects.map(rect => rect.right)) : box.right;
    const target = alignment === "left" ? canvasRect.left + 10
      : alignment === "right" ? canvasRect.right - 10 : canvasRect.left + canvasRect.width / 2;
    const visible = alignment === "left" ? left : alignment === "right" ? right : (left + right) / 2;
    const delta = (target - visible) / canvasRect.width * 100;
    const composition = (store.session?.[format] as any)?.cocoCompositionSystem ?? activeCompiledLayerSystem;
    const prior = composition.compiledObjectOverrides?.[compiledObject.id] ?? {};
    const xKey = compiledObject.binding?.x;
    const currentX = Number(prior.x ?? (store.session?.[format] as any)?.[xKey] ?? compiledObject.binding?.initial?.x ?? compiledObject.bounds.x);
    persistCocoActionSessionPatch({
      ...(xKey ? { [xKey]: currentX + delta } : {}),
      cocoCompositionSystem: { ...composition, compiledObjectOverrides: {
        ...composition.compiledObjectOverrides,
        [compiledObject.id]: { ...prior, x: currentX + delta, left: parseFloat(owner.style.left) + delta },
      } },
    });
    return;
  }

  let element: HTMLElement | null = null;
  let currentX: number | null = null;
  let applyX: ((nextX: number) => void) | null = null;

  const selectedLayer = getSelectedPortraitLayer();
  const portraitElement = selectedLayer
    ? Array.from(root.querySelectorAll<HTMLElement>("[data-portrait-id]")).find(
        (node) => node.dataset.portraitId === String(selectedLayer.id)
      ) ?? null
    : null;

  if (active === "icon") {
    const emojiList = Array.isArray(emojis) ? emojis : emojis?.[format] || [];
    const selectedEmoji = selectedEmojiId
      ? emojiList.find((emoji: any) => emoji.id === selectedEmojiId)
      : null;

    if (selectedLayer && portraitElement) {
      element =
        portraitElement.querySelector<HTMLElement>("[data-hit-bounds='true']") ??
        portraitElement;
      currentX = Number(selectedLayer.x ?? 50);
      applyX = (nextX) =>
        store.updatePortrait(format, selectedLayer.id, {
          x: clamp100(nextX),
          y: selectedLayer.y ?? 50,
        });
    } else if (selectedEmoji) {
      element = Array.from(root.querySelectorAll<HTMLElement>("[data-emoji-id]")).find(
        (node) => node.dataset.emojiId === String(selectedEmoji.id)
      ) ?? null;
      currentX = Number(selectedEmoji.x ?? 50);
      applyX = (nextX) =>
        store.updateEmoji(format, selectedEmoji.id, { x: clamp100(nextX) });
    }
  } else if (active === "portrait" || active === "logo") {
    if (selectedLayer && portraitElement) {
      element =
        portraitElement.querySelector<HTMLElement>("[data-hit-bounds='true']") ??
        portraitElement;
      currentX = Number(selectedLayer.x ?? 50);
      applyX = (nextX) =>
        store.updatePortrait(format, selectedLayer.id, {
          x: active === "portrait" ? clampVirtual(nextX) : clamp100(nextX),
          y: selectedLayer.y ?? 50,
        });
    } else {
      element = active === "portrait" ? canvasRefs.portrait : canvasRefs.logo;
      currentX = active === "portrait" ? portraitX : logoX;
      applyX = active === "portrait" ? setPortraitX : setLogoX;
    }
  } else {
    const nodeKey = active === "socialHandle" ? "socialHandle" : active;
    element =
      (canvasRefs[nodeKey as keyof typeof canvasRefs] as HTMLElement | null) ??
      root.querySelector<HTMLElement>(`[data-node="${nodeKey}"]`) ??
      null;

    const bindings: Record<string, { x: number; set: (nextX: number) => void }> = {
      headline: {
        x: headX,
        set: (nextX) => onHeadMoveRafSafe(nextX, headY),
      },
      headline2: {
        x: head2X,
        set: (nextX) => onHead2MoveRafSafe(nextX, head2Y),
      },
      details: { x: detailsX, set: (nextX) => onDetailsMoveRafSafe(nextX, detailsY) },
      details2: { x: details2X, set: (nextX) => onDetails2MoveRafSafe(nextX, details2Y) },
      venue: { x: venueX, set: (nextX) => onVenueMoveRafSafe(nextX, venueY) },
      subtag: { x: subtagX, set: (nextX) => onSubtagMoveRafSafe(nextX, subtagY) },
      presenter: {
        x: presenterX,
        set: (nextX) => {
          setCocoManualPositionValue("presenter", "x", nextX);
          store.setSessionValue(format, "presenterX", nextX);
        },
      },
      leftRail: {
        x: leftRailX,
        set: (nextX) => {
          setLeftRailX(nextX);
          store.setSessionValue(format, "leftRailX", nextX);
        },
      },
      rightRail: {
        x: rightRailX,
        set: (nextX) => {
          setRightRailX(nextX);
          store.setSessionValue(format, "rightRailX", nextX);
        },
      },
      socialHandle: {
        x: socialHandleX,
        set: (nextX) => {
          setSocialHandleX(nextX);
          store.setSessionValue(format, "cocoSocialHandleX" as any, nextX);
        },
      },
      date: { x: dateX, set: setDateXFromUser },
      time: { x: timeX, set: setTimeXFromUser },
      price: { x: priceX, set: setPriceXFromUser },
      compliance: {
        x: complianceX,
        set: (nextX) => {
          setCocoManualPositionValue("compliance", "x", nextX);
          store.setSessionValue(format, "complianceX", nextX);
        },
      },
      qr: { x: qrX, set: setQrX },
    };
    const binding = bindings[active];
    if (binding) {
      currentX = binding.x;
      applyX = binding.set;
    }
  }

  if (!element || currentX == null || !applyX) {
    alert(`❌ Could not align selected object: ${active}`);
    return;
  }

  const canvasRect = root.getBoundingClientRect();
  const objectRect = element.getBoundingClientRect();
  if (canvasRect.width <= 0 || objectRect.width <= 0) return;

  // Align the visible object bounds, not its CSS anchor. This remains correct
  // for centered assets, translated labels, rotated rails, and fixed-width text.
  const edgeInsetPx = 10;
  const targetX =
    alignment === "left"
      ? canvasRect.left + edgeInsetPx
      : alignment === "right"
        ? canvasRect.right - edgeInsetPx
        : canvasRect.left + canvasRect.width / 2;
  const visibleX =
    alignment === "left"
      ? objectRect.left
      : alignment === "right"
        ? objectRect.right
        : objectRect.left + objectRect.width / 2;
  const nextX = currentX + ((targetX - visibleX) / canvasRect.width) * 100;

  applyX(nextX);
};

