{/* UI: HEADLINE (END) */}



{/* UI: HEADLINE 2 (BEGIN) */}
<div
  id="head2-panel"
  className={clsx("relative rounded-xl transition", editorPanelClass("copy"), mobilePanelClass("design", "head2"))}
>
  <Collapsible
    title="Sub Headline"
    storageKey="p:head2"
    isOpen={selectedPanel === "head2"}
    onToggle={() =>
      useFlyerState
        .getState()
        .setSelectedPanel(selectedPanel === "head2" ? null : "head2")
    }
    panelClassName={
      selectedPanel === "head2" ? "ring-1 ring-inset ring-[#00FFF0]/70" : undefined
    }
    right={
      <div className="flex items-center gap-3 text-[11px]">
        {/* ENABLE */}
        <Chip
          small
          active={headline2Enabled[format]}
          onClick={() => {
            const enabled = !headline2Enabled[format];
            const store = useFlyerState.getState();
            const variant = store.session?.[format] as any;
            const objects = variant?.cocoCompositionSystem?.compiledDocument?.objects;
            const missing = Array.isArray(objects) && !objects.some((object: any) =>
              object.kind === "text" && (object.semanticRole === "headline2" || object.binding?.text === "head2line"));
            if (enabled && missing && !variant?.cocoNativeSubheadlineInitialized) {
              // A template without this layer has no authored text box to restore.
              // Initialize one explicit left-anchored box; alignment is inside it.
              const text = head2.trim() || "SUB HEADLINE";
              setHead2(text); setHead2X(5); setHead2Y(30);
              setHead2Align("center"); setHead2ColWidth(90);
              setHead2SizePx(36); setHead2Rotate(0); setHead2Skew(0);
              markCocoManualFitOverride("headline2");
              store.setSession((current) => ({ ...current, [format]: {
                ...current[format], head2: text, head2line: text,
                head2X: 5, head2Y: 30, head2Align: "center", head2ColWidth: 90,
                head2Size: 36, head2SizePx: 36, head2Rotate: 0, head2Skew: 0,
                head2Enabled: true, cocoNativeSubheadlineInitialized: true,
              } }));
            }
            setHeadline2Enabled(format, enabled);
            if (enabled) { store.setSelectedPanel("head2"); store.setMoveTarget("headline2"); }
          }}
        >
          {headline2Enabled[format] ? "On" : "Off"}
        </Chip>

        <span className="opacity-80">Align</span>

	        <Chip
	          small
	          active={selectedTextAlignment("headline2", head2Align) === "left"}
	          onClick={() => applyTextLayerAlignment("headline2", "left")}
	        >
	          L
	        </Chip>

	        <Chip
	          small
	          active={selectedTextAlignment("headline2", head2Align) === "center"}
	          onClick={() => applyTextLayerAlignment("headline2", "center")}
	        >
	          C
	        </Chip>

	        <Chip
	          small
	          active={selectedTextAlignment("headline2", head2Align) === "right"}
	          onClick={() => applyTextLayerAlignment("headline2", "right")}
	        >
	          R
	        </Chip>
      </div>
    }
  >
    {/* ⭐ NEON ACTIVE WRAPPER (FUCHSIA) */}
    <div className="p-0">
      <div className="mt-2">
        <FontPicker
          label="Font"
          value={head2Family}
	          options={HEADLINE2_FONTS_LOCAL}
	          onChange={(v) => {
	            const nextFamily = v;
	            setHead2Family(nextFamily);
            if (nextFamily === "Whimsical SVG") setHead2Fx(previous => ({ ...previous, uppercase: false, gradient: false }));
	            setTextStyle("headline2", format, { family: nextFamily });
	            setSessionValue(format, "head2Family", nextFamily);
          }}
          disabled={!headline2Enabled[format]}
        />
      </div>

      <PngGlyphPicker selected={head2Family} disabled={!headline2Enabled[format]} onSelect={(family) => {
        setHead2Family(family);
        setTextStyle("headline2", format, { family });
        setSessionValue(format, "head2Family", family);
        setHead2Fx(v => ({ ...v, gradient: false }));
      }} />
      {/* TEXT FIELD */}
      <textarea
        value={fineTuneTextValue("head2line", head2)}
        onChange={(e) => editFineTuneText("head2line", e.target.value, setHead2)}
        rows={2}
        disabled={!headline2Enabled[format]}
        className="w-full rounded p-2 bg-[#17171b] text-white border border-neutral-700 disabled:opacity-50"
        placeholder="Optional sub-headline"
      />

      {/* GRID 1 */}
      <div className="grid grid-cols-2 gap-3 mt-2">
        <Stepper
          label="Opacity"
          value={head2Alpha}
          setValue={setHead2Alpha}
          min={0}
          max={1}
          step={0.05}
          digits={2}
        />

        <Stepper
          label="Spacing"
          value={head2Fx.tracking}
          setValue={(n) => setHead2Fx((v) => ({ ...v, tracking: n }))}
          min={-1}
          max={0.15}
          step={0.01}
          digits={2}
        />

        <Stepper
          label="Rotate"
          value={head2Rotate}
          setValue={(n) => setHead2Rotate(normDeg(n))}
          min={-360}
          max={360}
          step={1}
        />
        <Stepper
          label="Skew"
          value={head2Skew}
          setValue={(value) => setTitleSkewFromUser("headline2", value)}
          min={-45}
          max={45}
          step={1}
        />
      </div>

      {/* GRID 2 */}
      <div className="grid grid-cols-2 gap-3 mt-2">
        <Stepper
          label="Size"
          value={head2SizePx}
          setValue={setHead2SizeFromUser}
          min={24}
          max={300}
          step={2}
        />

        <Stepper
          label="Leading"
          value={head2LineHeight}
          setValue={(v) => {
            markCocoManualFitOverride("headline2");
            setHead2LineHeight(v);
            const store = useFlyerState.getState();
            store.setSession((current) => ({ ...current, [format]: {
              ...current[format], head2LineHeight: v, head2X, head2Y,
            } }));
            store.setSessionDirty((current) => ({ ...current, [format]: true }));
          }}
          min={0.2}
          max={1.3}
          step={0.02}
          digits={2}
        />
      </div>

      {/* TOGGLES */}
      <div className="flex flex-wrap items-center gap-2 mt-2">
        <Chip small active={head2Fx.uppercase} onClick={() => setHead2Fx((v) => ({ ...v, uppercase: !v.uppercase }))}>Upper</Chip>
        <Chip small active={head2Fx.bold} onClick={() => setHead2Fx((v) => ({ ...v, bold: !v.bold }))}>Bold</Chip>
        <Chip small active={head2Fx.italic} onClick={() => setHead2Fx((v) => ({ ...v, italic: !v.italic }))}>Italic</Chip>
        <Chip small active={head2Shadow} onClick={() => setHead2Shadow(!head2Shadow)}>Shadow</Chip>
        <Chip
          small
          active={head2Fx.strokeWidth > 0}
          onClick={() =>
            setHead2Fx((v) => ({ ...v, strokeWidth: v.strokeWidth > 0 ? 0 : Math.max(1, v.strokeWidth || 1) }))
          }
        >
          Stroke
        </Chip>
      </div>

      <div className="mt-2 flex items-center gap-3">
          <span className="w-[110px] shrink-0 text-xs opacity-70">Shadow</span>
        <Stepper
          className="flex-1"
          value={head2ShadowStrength}
          setValue={setHead2ShadowStrength}
          min={0}
          max={8}
          step={0.1}
          digits={1}
        />
      </div>

      <div className="mt-2 flex items-center gap-3">
          <span className="w-[110px] shrink-0 text-xs opacity-70">Outline</span>
        <Stepper
          className="flex-1"
          value={head2Fx.strokeWidth}
          setValue={(n) => setHead2Fx((v) => ({ ...v, strokeWidth: n }))}
          min={0}
          max={8}
          step={0.1}
          digits={1}
        />
      </div>

      <div className="flex items-end mt-2 flex-wrap w-full">
        <div className="ml-auto flex flex-wrap items-center gap-3 justify-end text-[11px]">
          <span className="opacity-80">Fill</span>
          <ColorDot
            title="Fill color"
            value={head2Color}
            allowNone
            noneTitle="No fill"
            onChange={(c) => {
              applyManualCocoTextColor("headline2", c);
            }}
          />
          <span className="opacity-80">Stroke</span>
          <ColorDot
            title="Stroke color"
            value={head2Fx.strokeColor}
            onChange={(c) => {
              const next = { ...head2Fx, strokeColor: c };
              setHead2Fx(next);
              setSessionValue(format, "head2Fx", next);
            }}
          />
        </div>
      </div>
    </div>
  </Collapsible>
</div>
{/* UI: HEADLINE 2 (END) */}

